def _load_dotenv_file(path):
    env_path = os.path.abspath(str(path or ""))
    if not os.path.isfile(env_path):
        return False
    try:
        with open(env_path, "r", encoding="utf-8") as f:
            for raw_line in f:
                line = raw_line.strip()
                if not line or line.startswith("#") or "=" not in line:
                    continue
                key, value = line.split("=", 1)
                key = key.strip()
                if not key or key in os.environ:
                    continue
                value = value.strip()
                if len(value) >= 2 and value[0] == value[-1] and value[0] in ("'", '"'):
                    value = value[1:-1]
                os.environ[key] = value
        return True
    except Exception as e:
        print(json.dumps({
            "event": "aicanvas_env_load_failed",
            "path": env_path,
            "error": str(e),
        }, ensure_ascii=False), file=sys.stderr)
        return False

_load_dotenv_file(os.path.join(CURRENT_DIR, ".env"))

def _json_log(event, **fields):
    payload = {"event": str(event or "aicanvas_event")}
    payload.update(fields)
    try:
        print(json.dumps(payload, ensure_ascii=False), file=sys.stderr)
    except Exception:
        pass

