def _comic_model(id, name=None, provider="api-gateway", description="", **extra):
    model_id = str(id or "").strip()
    item = {
        "id": model_id,
        "name": str(name or model_id),
        "provider": provider,
        "description": description,
    }
    item.update(extra)
    return item


def _comic_video_model(id, name=None, provider="api-gateway", description="", **extra):
    defaults = {
        "input_mode": "reference_to_video",
        "requires_start_frame": False,
        "supports_end_frame": False,
        "requires_end_frame": False,
        "supports_reference_images": True,
        "max_reference_images": 7,
        "supports_duration_control": True,
        "label": "通用视频",
    }
    defaults.update(extra)
    return _comic_model(id, name, provider, description, **defaults)


