def _extend_comic_catalog_with_api_gateway_ids(kind, model_ids):
    def _catalog_key(value):
        return str(value or "").strip().lower()

    existing = {
        _catalog_key(model.get("id"))
        for model in COMIC_LOCAL_MODEL_CATALOG.get(kind, [])
        if isinstance(model, dict)
    }
    for model_id in model_ids:
        model_key = _catalog_key(model_id)
        if not model_key or model_key in existing:
            continue
        existing.add(model_key)
        if kind == "video":
            COMIC_LOCAL_MODEL_CATALOG[kind].append(
                _comic_video_model(
                    model_id,
                    model_id,
                    "api-gateway",
                    "API Gateway 视频模型，使用同一个服务地址和密钥，通过 model 字段切换。",
                )
            )
        else:
            COMIC_LOCAL_MODEL_CATALOG[kind].append(
                _comic_model(
                    model_id,
                    model_id,
                    "api-gateway",
                    "API Gateway 文本模型，使用同一个服务地址和密钥，通过 model 字段切换。",
                )
            )


_extend_comic_catalog_with_api_gateway_ids("llm", COMIC_API_GATEWAY_REMOTE_TEXT_MODELS)
_extend_comic_catalog_with_api_gateway_ids("video", COMIC_API_GATEWAY_REMOTE_VIDEO_MODELS)

