def _normalize_comic_model_id(value):
    return COMIC_READINESS_SERVICE.normalize_model_id(value)


def _is_official_ark_seedance_video_model(model_id):
    raw = str(model_id or "").strip()
    if not raw:
        return False
    normalized = raw
    try:
        normalized = _lk888_normalize_video_model(_apply_model_remap(raw))
    except Exception:
        normalized = raw
    return normalized in COMIC_OFFICIAL_ARK_SEEDANCE_VIDEO_MODEL_IDS


def _comic_video_model_param_caps(model_id):
    model_id = str(model_id or "").strip()
    if not model_id:
        return {}
    caps = {}
    try:
        raw_caps = _load_json_file(os.path.join(CURRENT_DIR, "model_capabilities.json")) or {}
        item = raw_caps.get(model_id) if isinstance(raw_caps, dict) else None
        if isinstance(item, dict):
            caps.update({
                key: item.get(key)
                for key in ("ratios", "resolutions", "quality", "durations")
                if item.get(key) not in (None, "")
            })
    except Exception:
        pass
    try:
        lk_caps = _lk888_video_caps_for_model(_lk888_normalize_video_model(_apply_model_remap(model_id)))
        if isinstance(lk_caps, dict):
            for key in ("ratios", "resolutions", "durations"):
                if not caps.get(key) and lk_caps.get(key):
                    caps[key] = lk_caps.get(key)
    except Exception:
        pass
    if model_id == "doubao-seedance-2-0-mini-260615":
        caps["supports_resolution_control"] = False
    elif caps.get("resolutions") or caps.get("quality"):
        caps["supports_resolution_control"] = True
    return {key: value for key, value in caps.items() if value not in (None, "", [])}


def _lk888_video_model_detail(model_id, api_gateway_cfg=None):
    model_id = _lk888_normalize_video_model(_apply_model_remap(str(model_id or "").strip()))
    if not model_id:
        return model_id, {}
    cfg = api_gateway_cfg if isinstance(api_gateway_cfg, dict) else _get_api_gateway_config()
    base = str(cfg.get("apiUrl") or "").strip()
    key = str(cfg.get("apiKey") or "").strip()
    if not base or not key:
        return model_id, {}
    cached = _APIMART_DETAIL_CACHE.get((base, model_id))
    if cached is not None:
        return model_id, cached if isinstance(cached, dict) else {}
    try:
        detail = _apimart_json_request(base, key, "/v1/skills/models/" + urllib.parse.quote(model_id, safe=""), None, 30)
    except Exception:
        detail = {}
    _APIMART_DETAIL_CACHE[(base, model_id)] = detail
    return model_id, detail if isinstance(detail, dict) else {}


def _lk888_upload_param_limit(pdef):
    desc = str((pdef or {}).get("description") or "")
    match = re.search(r"upload\s+(\d+)\s*[-~]\s*(\d+)", desc, re.IGNORECASE)
    if match:
        return int(match.group(2))
    match = re.search(r"upload\s+(\d+)\s+image", desc, re.IGNORECASE)
    if match:
        return int(match.group(1))
    match = re.search(r"(?:最多|max)\s*(\d+)", desc, re.IGNORECASE)
    if match:
        return int(match.group(1))
    match = re.search(r"up to\s*(\d+)", desc, re.IGNORECASE)
    if match:
        return int(match.group(1))
    return 0


def _lk888_video_schema_reference_limit(model_id):
    if _lk888_normalize_video_model(_apply_model_remap(str(model_id or "").strip())) == "sora-2":
        return 2
    _, detail = _lk888_video_model_detail(model_id)
    limits = []
    for pdef in detail.get("params") or []:
        if not isinstance(pdef, dict) or str(pdef.get("type") or "").lower() != "upload":
            continue
        name_label = " ".join(str(pdef.get(key) or "").lower() for key in ("name", "label"))
        text = " ".join([name_label, str(pdef.get("description") or "").lower()])
        if any(token in name_label for token in ("video", "audio", "sound", "voice", "clip", "视频", "音频", "声音")):
            continue
        if any(token in text for token in ("image", "reference", "图片", "参考")):
            limits.append(_lk888_upload_param_limit(pdef) or 1)
    return max(limits) if limits else 0


def _lk888_required_extra_inputs_for_storyboard_video(model_id):
    _, detail = _lk888_video_model_detail(model_id)
    fields = []
    for pdef in detail.get("params") or []:
        if not isinstance(pdef, dict) or not pdef.get("required"):
            continue
        name = str(pdef.get("name") or "").strip()
        if not name:
            continue
        ptype = str(pdef.get("type") or "").lower()
        name_label = " ".join(str(pdef.get(key) or "").lower() for key in ("name", "label"))
        lowered = name.lower()
        if ptype == "upload" and any(token in name_label for token in ("video", "audio", "sound", "voice", "clip", "视频", "音频", "声音")):
            fields.append(name)
        elif any(token in lowered for token in ("script_name", "script_content", "clips")):
            fields.append(name)
    return fields


def _coerce_lk888_video_params_to_schema(model, params, payload, api_gateway_cfg=None):
    params = dict(params if isinstance(params, dict) else {})
    _, detail = _lk888_video_model_detail(model, api_gateway_cfg)
    ratio_field = ""
    ratio_aliases = ("aspectRatio", "aspect_ratio", "ratio", "aspectratio", "aspect")
    for pdef in detail.get("params") or []:
        if not isinstance(pdef, dict):
            continue
        name = str(pdef.get("name") or "")
        if not name or str(pdef.get("type") or "").lower() == "upload":
            continue
        ptype = str(pdef.get("type") or "").lower()
        opts = [opt.get("value") for opt in (pdef.get("options") or []) if isinstance(opt, dict)]
        current = params.get(name)
        if name.lower() in {"ratio", "aspect_ratio", "aspectratio", "aspect"}:
            ratio_field = ratio_field or name
            if current in (None, "", [], {}):
                current = _first_non_empty(
                    *(params.get(key) for key in ratio_aliases),
                    *(payload.get(key) for key in ratio_aliases),
                )
        if opts and current not in (None, "", [], {}) and str(current) in {str(opt) for opt in opts}:
            params[name] = current
            continue
        value = _aic_param_value(name, ptype, opts, payload)
        if value not in (None, ""):
            params[name] = value
            continue
        if pdef.get("required") and opts and params.get(name) in (None, "", [], {}):
            flagged = next((opt.get("value") for opt in pdef.get("options") or [] if isinstance(opt, dict) and opt.get("default")), None)
            params[name] = flagged if flagged not in (None, "") else opts[0]
    if ratio_field:
        ratio_value = _first_non_empty(
            params.get(ratio_field),
            *(params.get(key) for key in ratio_aliases),
            *(payload.get(key) for key in ratio_aliases),
        )
        for key in ratio_aliases:
            if key != ratio_field:
                params.pop(key, None)
        if ratio_value not in (None, "", [], {}):
            params[ratio_field] = ratio_value
    return params


def _enrich_comic_video_model_param_caps(catalog):
    if not isinstance(catalog, dict):
        return catalog
    models = []
    for item in catalog.get("models") or []:
        if not isinstance(item, dict):
            models.append(item)
            continue
        updated = dict(item)
        caps = _comic_video_model_param_caps(updated.get("id"))
        schema_ref_limit = _lk888_video_schema_reference_limit(updated.get("id"))
        extra_required = _lk888_required_extra_inputs_for_storyboard_video(updated.get("id"))
        official_seedance_limit = (
            COMIC_OFFICIAL_ARK_SEEDANCE_REFERENCE_LIMIT
            if _is_official_ark_seedance_video_model(updated.get("id"))
            else 0
        )
        if official_seedance_limit:
            updated["max_reference_images"] = official_seedance_limit
            updated["supports_reference_images"] = True
            caps["max_reference_images"] = official_seedance_limit
        elif schema_ref_limit:
            updated["max_reference_images"] = schema_ref_limit
            updated["supports_reference_images"] = True
            caps["max_reference_images"] = schema_ref_limit
        elif str(updated.get("provider") or "") == "api-gateway":
            updated["supports_reference_images"] = False
            updated["max_reference_images"] = 0
        if extra_required:
            updated["supports_storyboard_keyframes_video"] = False
            updated["storyboard_video_unsupported_required_fields"] = extra_required
        else:
            updated["supports_storyboard_keyframes_video"] = bool(updated.get("max_reference_images"))
        updated["supports_multiframe_references"] = int(updated.get("max_reference_images") or 0) >= COMIC_MULTIFRAME_VIDEO_MIN_REFERENCE_IMAGES and not extra_required
        if caps:
            updated_caps = dict(updated.get("capabilities") or {})
            updated_caps.update(caps)
            updated["capabilities"] = updated_caps
            for key, value in caps.items():
                updated.setdefault(key, value)
        models.append(updated)
    out = dict(catalog)
    out["models"] = models
    return out


def _build_comic_model_catalog_response(kind, upstream_payload=None):
    catalog = COMIC_READINESS_SERVICE.build_model_catalog_response(kind, upstream_payload)
    if str(kind or "").strip().lower() == "video":
        catalog = _enrich_comic_video_model_param_caps(catalog)
    return catalog


def _merge_local_comic_models_into_catalog(catalog, kind):
    kind = str(kind or "").strip().lower()
    if kind not in COMIC_LOCAL_MODEL_CATALOG or not isinstance(catalog, dict):
        return catalog
    local_catalog = _build_comic_model_catalog_response("audio")
    if kind != "audio":
        local_catalog = _build_comic_model_catalog_response(kind)
    models = list(catalog.get("models") or [])
    local_by_id = {
        str(item.get("id") or "").strip(): item
        for item in local_catalog.get("models") or []
        if isinstance(item, dict) and str(item.get("id") or "").strip()
    }
    seen = set()
    merged_models = []
    override_fields = COMIC_LOCAL_OVERRIDE_FIELDS.get(kind, set())
    for item in models:
        if not isinstance(item, dict):
            continue
        mid = str(item.get("id") or "").strip()
        if not mid:
            continue
        local_item = local_by_id.get(mid)
        updated = dict(item)
        if local_item:
            for key, value in local_item.items():
                if key in override_fields and value not in ("", None):
                    updated[key] = value
                elif updated.get(key) in ("", None) and value not in ("", None):
                    updated[key] = value
        merged_models.append(updated)
        seen.add(mid)
    for item in local_catalog.get("models") or []:
        mid = str(item.get("id") or "").strip()
        if mid and mid not in seen:
            merged_models.append(item)
            seen.add(mid)
    merged = dict(catalog)
    merged["models"] = merged_models
    merged["localWorkflowModelsIncluded"] = kind == "audio"
    merged["localModelMetadataIncluded"] = True
    if not merged.get("defaultModelId") and local_catalog.get("defaultModelId"):
        merged["defaultModelId"] = local_catalog.get("defaultModelId")
    if not merged.get("default_model") and local_catalog.get("default_model"):
        merged["default_model"] = local_catalog.get("default_model")
    return merged


def _comic_price_model_type(kind):
    kind = str(kind or "").strip().lower()
    if kind == "audio":
        return "tts"
    return kind


def _priced_comic_model_ids(kind):
    price_type = _comic_price_model_type(kind)
    try:
        prices = _fetch_platform_model_prices()
    except Exception:
        prices = []
    ids = set()
    for item in prices or []:
        if not isinstance(item, dict):
            continue
        if str(item.get("model_type") or "").strip().lower() != price_type:
            continue
        model_id = str(item.get("model_id") or "").strip()
        if model_id:
            ids.add(model_id)
    return ids


def _filter_priced_comic_model_catalog(catalog, kind):
    if not isinstance(catalog, dict):
        return catalog
    kind = str(kind or "").strip().lower()
    if kind == "llm":
        lk888_llm_ids = {COMIC_DEFAULT_LLM_MODEL, "gpt-5.4-mini", "gemini-3.1-pro-preview"}
        default_model = COMIC_DEFAULT_LLM_MODEL
        models = []
        for item in catalog.get("models") or []:
            if not isinstance(item, dict):
                continue
            model_id = str(item.get("id") or "").strip()
            if model_id not in lk888_llm_ids:
                continue
            updated = dict(item)
            updated["provider"] = "ai"
            updated["is_default"] = model_id == default_model
            models.append(updated)
        if not models:
            models = [
                {
                    "id": COMIC_DEFAULT_LLM_MODEL,
                    "name": "Grok 4-20",
                    "provider": "ai",
                    "description": "LK888 语言模型，适合提示词优化、剧本整理和常规创作辅助。",
                    "is_default": True,
                },
                {
                    "id": "gpt-5.4-mini",
                    "name": "GPT-5.4 mini",
                    "provider": "ai",
                    "description": "LK888 语言模型，适合提示词优化、剧本整理和常规创作辅助。",
                    "is_default": False,
                },
                {
                    "id": "gemini-3.1-pro-preview",
                    "name": "Gemini 3.1 Pro",
                    "provider": "ai",
                    "description": "LK888 语言模型，适合长上下文分析和复杂创意推理。",
                    "is_default": False,
                },
            ]
        models.sort(key=lambda item: 0 if str(item.get("id") or "").strip() == default_model else 1)
        updated_catalog = dict(catalog)
        updated_catalog["models"] = models
        updated_catalog["provider"] = "ai"
        updated_catalog["defaultModelId"] = default_model
        updated_catalog["default_model"] = default_model
        updated_catalog["pricedOnly"] = True
        return updated_catalog
    priced_ids = _priced_comic_model_ids(kind)
    if kind == "video":
        priced_ids = set(priced_ids)
        priced_ids.add(COMIC_DEFAULT_VIDEO_MODEL)
        priced_ids.update(COMIC_LK888_MULTI_REF_VIDEO_MODEL_IDS)
        priced_ids.update(str(model.get("id") or "") for model in COMIC_LK888_MULTI_REF_VIDEO_MODELS)
        priced_ids.update(str(model.get("id") or "") for model in COMIC_OFFICIAL_ARK_VIDEO_MODELS)
    if not priced_ids:
        return catalog
    default_model = COMIC_DEFAULT_MODEL_BY_KIND.get(kind) or ""
    models = []
    for item in catalog.get("models") or []:
        if not isinstance(item, dict):
            continue
        model_id = str(item.get("id") or "").strip()
        if model_id not in priced_ids:
            continue
        updated = dict(item)
        updated["is_default"] = model_id == default_model
        models.append(updated)
    if default_model not in {str(item.get("id") or "").strip() for item in models} and models:
        default_model = str(models[0].get("id") or "").strip()
        for item in models:
            item["is_default"] = str(item.get("id") or "").strip() == default_model
    models.sort(key=lambda item: 0 if str(item.get("id") or "").strip() == default_model else 1)
    updated_catalog = dict(catalog)
    updated_catalog["models"] = models
    if default_model:
        updated_catalog["defaultModelId"] = default_model
        updated_catalog["default_model"] = default_model
    updated_catalog["pricedOnly"] = True
    return updated_catalog


def _build_comic_model_readiness_response(payload, upstream_catalogs=None):
    return COMIC_READINESS_SERVICE.build_model_readiness_response(
        payload,
        upstream_catalogs,
    )


def _comic_local_catalog_has_model(kind, model_id):
    model_id = _normalize_comic_model_id(model_id)
    if kind not in COMIC_LOCAL_MODEL_CATALOG or not model_id:
        return False
    catalog = _build_comic_model_catalog_response(kind)
    ids = {
        _normalize_comic_model_id(item.get("id"))
        for item in catalog.get("models") or []
        if isinstance(item, dict)
    }
    return model_id in ids


def _merge_local_comic_readiness(readiness, payload):
    if not isinstance(readiness, dict) or not isinstance(payload, dict):
        return readiness
    checks = readiness.get("checks")
    if not isinstance(checks, list):
        return readiness
    changed = False
    for check in checks:
        if not isinstance(check, dict) or check.get("ok") is not False:
            continue
        code = str(check.get("code") or "").strip()
        kind = COMIC_READINESS_MODEL_FIELDS.get(code) or _normalize_comic_model_kind(code)
        model_id = _normalize_comic_model_id(
            check.get("model")
            or payload.get(code)
            or payload.get(kind)
            or payload.get(f"{kind}_model")
        )
        if _comic_local_catalog_has_model(kind, model_id):
            check["ok"] = True
            check["message"] = ""
            check["source"] = "local-catalog"
            changed = True
    if changed:
        readiness["ready"] = not any(
            isinstance(check, dict) and check.get("ok") is False
            for check in checks
        )
    return readiness


def _allow_comic_analysis_readiness_without_media_models(readiness):
    if not isinstance(readiness, dict):
        return readiness
    checks = readiness.get("checks")
    if not isinstance(checks, list):
        return readiness
    for check in checks:
        if not isinstance(check, dict) or check.get("ok") is not False:
            continue
        code = str(check.get("code") or "").strip()
        if code in {"image_model", "video_model"}:
            check["ok"] = True
            check["non_blocking_for_analysis"] = True
            check["message"] = check.get("message") or "该模型只影响后续生成，不阻断剧本分析"
    readiness["ready"] = not any(
        isinstance(check, dict) and check.get("ok") is False
        for check in checks
    )
    readiness["analysisOnly"] = True
    return readiness


