def _join_versioned_api_path(base_url, path):
    base = str(base_url or "").strip().rstrip("/")
    clean = "/" + str(path or "").strip().lstrip("/")
    if not base:
        return clean
    for version in ("/v1", "/v2"):
        if base.endswith(version) and clean.startswith(version + "/"):
            return base + clean[len(version):]
    return base + clean


def _url_origin(value):
    try:
        parsed = urllib.parse.urlsplit(str(value or ""))
        if not parsed.scheme or not parsed.netloc:
            return ""
        return f"{parsed.scheme.lower()}://{parsed.netloc.lower()}"
    except Exception:
        return ""


def _url_path(value):
    try:
        return urllib.parse.urlsplit(str(value or "")).path or ""
    except Exception:
        return ""


def _is_managed_gateway_api_url(api_url, gateway_cfg):
    base_url = str((gateway_cfg or {}).get("apiUrl") or "").strip().rstrip("/")
    target_url = str(api_url or "").strip().rstrip("/")
    if not base_url or not target_url:
        return False
    if target_url == base_url or target_url.startswith(base_url + "/"):
        return True
    return bool(_url_origin(base_url) and _url_origin(base_url) == _url_origin(target_url))


def _is_legacy_model_provider_api_url(api_url):
    try:
        parsed = urllib.parse.urlsplit(str(api_url or ""))
        host = parsed.netloc.lower()
    except Exception:
        host = ""
    if not host:
        return False
    return any(
        marker in host
        for marker in (
            "api.ppio.com",
            "api.ppinfra.com",
            "ppio.com",
            "grsai",
            "runninghub.cn",
            "runninghub",
        )
    )


def _resolve_proxy_api_key(api_url, api_key):
    api_gateway_cfg = _get_api_gateway_config()
    raw_key = str(api_key or "").strip()
    use_api_gateway = (
        raw_key == API_KEY_PLACEHOLDER
        or raw_key == "__AICANVAS_GPT_BEST__"
        or _is_managed_gateway_api_url(api_url, api_gateway_cfg)
        or _is_legacy_model_provider_api_url(api_url)
    )
    if use_api_gateway:
        return str(api_gateway_cfg.get("apiKey") or "").strip(), True, api_gateway_cfg
    return raw_key, False, api_gateway_cfg


def _first_text(value):
    if isinstance(value, str):
        return value
    if isinstance(value, list):
        parts = [_first_text(item) for item in value]
        return "\n".join(part for part in parts if part)
    if isinstance(value, dict):
        for key in ("text", "content", "prompt"):
            if isinstance(value.get(key), str) and value.get(key).strip():
                return value.get(key)
        if isinstance(value.get("parts"), list):
            return _first_text(value.get("parts"))
    return ""


