def _strip_legacy_model_prefix(model):
    text = str(model or "").strip()
    for prefix in ("openai/", "apimart/", "grsai/", "ppio/"):
        if text.lower().startswith(prefix):
            return text[len(prefix):].strip()
    return text


def _pick_api_gateway_model(requested_model, allowed_models, fallback_model):
    normalized = _strip_legacy_model_prefix(requested_model)
    if normalized in allowed_models:
        return normalized
    fallback = _strip_legacy_model_prefix(fallback_model)
    if fallback in allowed_models:
        return fallback
    return next(iter(allowed_models), normalized or fallback)


def _normalize_api_gateway_chat_payload(data, api_gateway_cfg):
    payload = dict(data or {})
    model = str(api_gateway_cfg.get("llmModel") or "").strip()
    requested_model = str(payload.get("model") or "").strip()
    payload["model"] = _pick_api_gateway_model(
        requested_model,
        API_GATEWAY_TEXT_MODEL_IDS,
        model or "gpt-5.4-mini",
    )
    payload["stream"] = bool(payload.get("stream") is True)
    if isinstance(payload.get("messages"), list) and payload["messages"]:
        return payload

    messages = []
    system_instruction = payload.get("system_instruction")
    system_text = _first_text(system_instruction)
    if system_text:
        messages.append({"role": "system", "content": system_text})

    contents = payload.get("contents")
    if isinstance(contents, list):
        for item in contents:
            if not isinstance(item, dict):
                continue
            role = "assistant" if str(item.get("role") or "").lower() == "model" else "user"
            content = _first_text(item.get("parts") or item.get("content") or item)
            if content:
                messages.append({"role": role, "content": content})

    if not messages:
        prompt = _first_text(payload.get("prompt") or payload.get("input") or payload.get("content"))
        if prompt:
            messages.append({"role": "user", "content": prompt})
    if not messages:
        messages.append({"role": "user", "content": ""})

    keep_keys = ("temperature", "top_p", "max_tokens", "presence_penalty", "frequency_penalty")
    normalized = {
        key: payload[key]
        for key in keep_keys
        if key in payload and payload[key] is not None
    }
    normalized["model"] = payload.get("model") or model or "gpt-5.4-mini"
    normalized["stream"] = payload["stream"]
    normalized["messages"] = messages
    return normalized


def _normalize_aspect_ratio_value(value):
    text = str(value or "").strip().replace("：", ":").replace("／", "/").replace("×", "x")
    if not text or text.lower() in ("auto", "adaptive") or text in ("自适应", "自动", "适应"):
        return ""
    m = re.match(r"^\s*(\d+(?:\.\d+)?)\s*[:/xX]\s*(\d+(?:\.\d+)?)\s*$", text)
    if not m:
        return ""
    a = float(m.group(1))
    b = float(m.group(2))
    if a <= 0 or b <= 0:
        return ""
    choices = (("16:9", 16 / 9), ("9:16", 9 / 16), ("1:1", 1), ("4:3", 4 / 3), ("3:4", 3 / 4), ("21:9", 21 / 9))
    return min(choices, key=lambda item: abs(item[1] - a / b))[0]


def _looks_like_ratio(value):
    return bool(_normalize_aspect_ratio_value(value))


def _video_ratio_from_dimensions(data):
    data = data if isinstance(data, dict) else {}
    for width_key, height_key in (("selectedVideoWidth", "selectedVideoHeight"),):
        try:
            width = float(data.get(width_key) or 0)
            height = float(data.get(height_key) or 0)
        except (TypeError, ValueError):
            continue
        if width > 0 and height > 0:
            return _normalize_aspect_ratio_value(f"{width}:{height}")
    return ""


def _normalize_ratio_key(payload):
    if _normalize_aspect_ratio_value(payload.get("aspect_ratio")):
        payload["aspect_ratio"] = _normalize_aspect_ratio_value(payload.get("aspect_ratio"))
    if "aspect_ratio" not in payload or not _normalize_aspect_ratio_value(payload.get("aspect_ratio")):
        for key in ("aspectRatio", "ratio", "aspect"):
            ratio = _normalize_aspect_ratio_value(payload.get(key))
            if ratio:
                payload["aspect_ratio"] = ratio
                break
    if ("aspect_ratio" not in payload or not _normalize_aspect_ratio_value(payload.get("aspect_ratio"))) and _looks_like_ratio(payload.get("size")):
        payload["aspect_ratio"] = _normalize_aspect_ratio_value(payload.get("size"))
    if "aspect_ratio" not in payload or not _normalize_aspect_ratio_value(payload.get("aspect_ratio")):
        ratio = _video_ratio_from_dimensions(payload)
        if ratio:
            payload["aspect_ratio"] = ratio
    if payload.get("aspect_ratio") not in (None, ""):
        payload["ratio"] = payload.get("aspect_ratio")
        payload["aspectRatio"] = payload.get("aspect_ratio")


def _collapse_alias_group(payload, keys, preferred=None):
    payload = dict(payload if isinstance(payload, dict) else {})
    keys = tuple(keys or ())
    if not keys:
        return payload
    preferred = tuple(preferred or keys)
    chosen_key = ""
    chosen_value = None
    for key in preferred:
        value = payload.get(key)
        if value in (None, "", [], {}):
            continue
        chosen_key = key
        chosen_value = value
        break
    if not chosen_key:
        return payload
    for key in keys:
        if key != chosen_key:
            payload.pop(key, None)
    payload[chosen_key] = chosen_value
    return payload


def _collapse_video_ratio_aliases(payload):
    return _collapse_alias_group(payload, ("aspectRatio", "aspect_ratio", "ratio", "aspectratio"), preferred=("aspectRatio", "aspect_ratio", "ratio", "aspectratio"))


def _looks_like_video_resolution(value):
    text = str(value or "").strip().lower()
    if not text:
        return False
    return bool(re.match(r"^\d{3,4}\s*p?$", text)) or text in ("2k", "4k")


def _video_resolution_label(value):
    text = str(value or "").strip()
    if not _looks_like_video_resolution(text):
        return ""
    return (text + "p") if re.match(r"^\d{3,4}$", text) else text


def _video_resolution_from_dimensions(data):
    data = data if isinstance(data, dict) else {}
    for width_key, height_key in (("selectedVideoWidth", "selectedVideoHeight"), ("videoWidth", "videoHeight")):
        try:
            width = float(data.get(width_key) or 0)
            height = float(data.get(height_key) or 0)
        except (TypeError, ValueError):
            continue
        if width <= 0 or height <= 0:
            continue
        short_side = min(width, height)
        tiers = (480, 540, 720, 1080, 1440, 2160)
        return f"{min(tiers, key=lambda tier: abs(tier - short_side))}p"
    return ""



def _video_resolution_from_quality(value):
    text = str(value or "").strip().lower()
    return {
        "standard": "720p",
        "normal": "720p",
        "medium": "720p",
        "hd": "1080p",
        "high": "1080p",
        "full_hd": "1080p",
        "fullhd": "1080p",
        "ultra": "1080p",
        "uhd": "1080p",
        "超清": "1080p",
        "高清": "1080p",
        "标准": "720p",
    }.get(text, "")

def _normalize_video_size_keys(payload):
    payload = payload if isinstance(payload, dict) else {}
    if payload.get("resolution") in (None, ""):
        value = _video_resolution_from_quality(payload.get("quality") or payload.get("definition") or payload.get("clarity"))
        if value:
            payload["resolution"] = value
    if payload.get("resolution") in (None, ""):
        for key in (
            "videoResolution",
            "video_resolution",
            "selectedVideoResolution",
            "selectedResolution",
            "selectedSize",
            "videoSize",
            "definition",
            "clarity",
            "imageSize",
            "image_size",
        ):
            value = _video_resolution_label(payload.get(key))
            if value:
                payload["resolution"] = value
                break
    if payload.get("resolution") in (None, "") and _looks_like_video_resolution(payload.get("size")):
        payload["resolution"] = _video_resolution_label(payload.get("size"))
    if payload.get("resolution") in (None, ""):
        value = _video_resolution_from_dimensions(payload)
        if value:
            payload["resolution"] = value
    if payload.get("resolution") not in (None, "") and payload.get("videoSize") in (None, ""):
        payload["videoSize"] = payload.get("resolution")
    return payload


def _clean_media_url(value):
    text = str(value or "").strip()
    if not text:
        return ""
    if text.lower() in ("undefined", "null", "none", "false", "0", "about:blank"):
        return ""
    if re.match(r"^https?://", text, flags=re.IGNORECASE):
        return text
    if text.startswith(("/uploads/", "/assets/", "/output/", "/data/")):
        return text
    if text.startswith(("uploads/", "output/", "data/uploads/", "data/assets/")):
        return text
    return ""


def _media_url_from_value(value):
    if isinstance(value, str):
        return _clean_media_url(value)
    if isinstance(value, dict):
        for key in (
            "media_url",
            "mediaUrl",
            "thumbnail_url",
            "thumbnailUrl",
            "reference_image",
            "referenceImage",
            "url",
            "src",
            "image_url",
            "imageUrl",
            "audio_url",
            "audioUrl",
            "video_url",
            "videoUrl",
        ):
            candidate = value.get(key)
            if isinstance(candidate, dict):
                candidate = candidate.get("url") or candidate.get("src")
            url = _clean_media_url(candidate)
            if url:
                return url
        for key in ("reference_urls", "reference_images", "referenceImages", "image_urls", "reference_image_urls"):
            values = value.get(key)
            if isinstance(values, list):
                for candidate in values:
                    url = _media_url_from_value(candidate)
                    if url:
                        return url
    return ""


def _extend_url_list(items, value):
    if isinstance(value, list):
        for item in value:
            url = _media_url_from_value(item)
            if url:
                items.append(url)
        return
    url = _media_url_from_value(value)
    if url:
        items.append(url)
        return


def _looks_like_video_ref_url(value):
    text = str(value or "").strip().lower()
    if not text:
        return False
    text = text.split("?", 1)[0].split("#", 1)[0]
    return text.endswith(tuple(STATIC_VIDEO_CACHE_EXTS)) or "/video" in text


def _dedupe_urls(values):
    seen = set()
    result = []
    for value in values:
        text = str(value or "").strip()
        if not text or text in seen:
            continue
        seen.add(text)
        result.append(text)
    return result


def _aic_collect_audio_refs(data):
    refs = []
    data = data if isinstance(data, dict) else {}
    for key in (
        "reference_audio",
        "referenceAudio",
        "reference_audio_url",
        "referenceAudioUrl",
        "voice_audio",
        "voiceAudio",
        "voice_audio_url",
        "voiceAudioUrl",
        "subject_audio",
        "subjectAudio",
        "subject_audio_url",
        "subjectAudioUrl",
        "voice_url",
        "voiceUrl",
        "audio_url",
        "audioUrl",
    ):
        _extend_url_list(refs, data.get(key))
    for key in ("reference_audio_urls", "audio_urls", "audioUrls", "voice_audio_urls", "voiceAudioUrls", "subject_audio_urls", "subjectAudioUrls", "audios", "audioRefs", "referenceAudioRefs", "voiceAudioRefs"):
        _extend_url_list(refs, data.get(key))
    return _dedupe_urls(refs)

def _aic_collect_voice_resource_ids(data):
    ids = []
    data = data if isinstance(data, dict) else {}
    scalar_keys = (
        "voiceId", "voice_id", "ttsVoice", "tts_voice", "speakerId", "speaker_id",
        "resourceId", "resource_id", "voiceResourceId", "voice_resource_id",
        "cloneVoiceId", "clone_voice_id", "clone_voice", "voiceCloneId",
    )
    for key in scalar_keys:
        value = str(data.get(key) or "").strip()
        if value and value.lower() not in ("undefined", "null", "none", "false", "0"):
            ids.append(value)
    for list_key in ("audioRefs", "referenceAudioRefs", "voiceAudioRefs", "audios"):
        values = data.get(list_key)
        if isinstance(values, list):
            for item in values:
                if not isinstance(item, dict):
                    continue
                for key in scalar_keys:
                    value = str(item.get(key) or "").strip()
                    if value and value.lower() not in ("undefined", "null", "none", "false", "0"):
                        ids.append(value)
    return _dedupe_urls(ids)


def _merge_voice_resource_into_params(params, voice_ids):
    params = dict(params if isinstance(params, dict) else {})
    ids = _dedupe_urls(voice_ids)
    if not ids:
        return params
    voice_id = ids[0]
    for key in ("voiceId", "voice_id", "ttsVoice", "speaker", "speakerId", "speaker_id", "resourceId", "resource_id", "voiceResourceId", "voice_resource_id", "cloneVoiceId", "clone_voice_id"):
        params.setdefault(key, voice_id)
    params["voice_resource_ids"] = ids
    return params



CANVAS_REFERENCE_IMAGE_ALIAS_KEYS = (
    "images",
    "image_urls",
    "imageUrls",
    "reference_image_urls",
    "referenceImageUrls",
    "reference_images",
    "referenceImages",
    "subject_reference_images",
    "additional_reference_images",
    "inputUrls",
)


def _sync_canvas_reference_image_aliases(data):
    data = data if isinstance(data, dict) else {}
    refs = []
    for key in CANVAS_REFERENCE_IMAGE_ALIAS_KEYS:
        _extend_url_list(refs, data.get(key))
    _extend_url_list(refs, data.get("image_with_roles"))
    refs = _dedupe_urls(refs)
    if not refs:
        return data
    for key in CANVAS_REFERENCE_IMAGE_ALIAS_KEYS:
        data[key] = _merge_unique_list(data.get(key), refs)
    data.setdefault("image_url", refs[0])
    data.setdefault("imageUrl", refs[0])
    return data


def _adapt_api_gateway_image_payload(data, api_gateway_cfg):
    payload = _sync_canvas_reference_image_aliases(dict(data or {}))
    image_model = str(api_gateway_cfg.get("imageModel") or "gpt-image-2").strip()
    requested_model = str(payload.get("model") or "").strip()
    requested_model = _apply_model_remap(requested_model)
    payload["model"] = _pick_api_gateway_model(
        requested_model,
        API_GATEWAY_IMAGE_MODEL_IDS,
        image_model or "gpt-image-2",
    )
    if "n" not in payload and payload.get("batchSize"):
        payload["n"] = payload.get("batchSize")
    _normalize_ratio_key(payload)

    refs = []
    for key in (
        "urls",
        "image_urls",
        "imageUrls",
        "reference_image_urls",
        "referenceImageUrls",
        "reference_images",
        "referenceImages",
        "images",
        "inputUrls",
    ):
        _extend_url_list(refs, payload.get(key))
    refs = _dedupe_urls(refs)
    if refs:
        payload["image_urls"] = refs
        payload["reference_image_urls"] = refs
        payload["image_url"] = refs[0]
        payload["image"] = refs if len(refs) > 1 else refs[0]
    payload.pop("shutProgress", None)
    return payload


def _extract_proxy_task_id(data):
    if not isinstance(data, dict):
        return ""
    for key in ("taskId", "task_id", "id", "jobId", "job_id", "requestId", "request_id"):
        value = str(data.get(key) or "").strip()
        if value:
            return value
    return ""


def _lk888_normalize_video_model(model):
    name = str(model or "").strip()
    if name.startswith("apimart/"):
        name = name[len("apimart/"):]
    aliases = {
        "kling-video-v3": "kling-v3-video",
        "vidu/viduq3-mix_reference2video": "viduq3-cankaosheng",
        "vidu/viduq3-turbo_img2video": "viduq3",
        "vidu/viduq3-turbo_reference2video": "viduq3-cankaosheng",
    }
    return aliases.get(name, name)


def _lk888_video_duration(value, allowed=("5", "10", "15")):
    text = str(value or "5").strip()
    if text.endswith(".0"):
        text = text[:-2]
    return text if text in allowed else _lk888_pick_numeric_option(text, allowed, allowed[0])


def _lk888_video_ratio(value):
    text = _normalize_aspect_ratio_value(value) or "16:9"
    return text if text in ("16:9", "9:16", "1:1") else "16:9"


def _lk888_video_caps_for_model(model):
    name = str(model or "").strip()
    low = name.lower()
    family_caps = {}
    if low.startswith("viduq3"):
        family_caps = {"ratios": ["16:9", "9:16", "4:3", "3:4", "1:1"], "resolutions": ["540p", "720p", "1080p"], "durations": {"min": 4, "max": 16, "options": ["4", "8", "12", "16"]}}
    elif low.startswith("wan2.") or low.startswith("wanx"):
        family_caps = {"ratios": ["16:9", "9:16", "1:1", "4:3", "3:4"], "resolutions": ["720P", "1080P"], "durations": {"options": ["3", "6", "9", "12", "15"]}}
    remap = _load_model_remap()
    candidates = []
    entry = remap.get(name)
    if isinstance(entry, dict):
        candidates.append(entry)
    for item in remap.values():
        if isinstance(item, dict) and str(item.get("replacement") or "").strip() == name:
            candidates.append(item)
    for item in candidates:
        caps = item.get("caps")
        if isinstance(caps, dict):
            merged = dict(caps)
            for key, value in family_caps.items():
                if not merged.get(key):
                    merged[key] = value
            if low.startswith("viduq3") and family_caps.get("durations"):
                merged["durations"] = family_caps["durations"]
            return merged
    return family_caps


def _lk888_pick_option(value, options, default=""):
    opts = [str(o).strip() for o in (options or []) if str(o).strip()]
    text = str(value or "").strip()
    aliases = {"自适应": "auto", "自动": "auto", "适应": "auto"}
    text = aliases.get(text, text)
    if not opts:
        return default or ("16:9" if text.lower() in ("auto", "adaptive") else text)
    for opt in opts:
        if opt == text or opt.lower() == text.lower():
            return opt
    if text.lower() in ("auto", "adaptive"):
        for preferred in ("16:9", "adaptive", "auto"):
            for opt in opts:
                if opt.lower() == preferred.lower():
                    return opt
    return default or opts[0]


def _lk888_pick_numeric_option(value, options, default=""):
    opts = [str(o).strip() for o in (options or []) if str(o).strip()]
    if not opts:
        return value
    text = str(value or "").strip()
    for opt in opts:
        if opt == text or opt.lower() == text.lower():
            return opt
    try:
        import re as _re
        target = float(_re.sub(r"[^0-9.]", "", text) or 0)
        if target > 0:
            return min(opts, key=lambda opt: abs(float(_re.sub(r"[^0-9.]", "", opt) or 0) - target))
    except Exception:
        pass
    return default or opts[0]


def _lk888_normalize_video_params(model, params):
    out = dict(params or {})
    caps = _lk888_video_caps_for_model(model)
    ratios = caps.get("ratios") or []
    resolutions = caps.get("resolutions") or []
    durations = (caps.get("durations") or {}).get("options") if isinstance(caps.get("durations"), dict) else []
    for key in ("aspect_ratio", "ratio", "aspectRatio"):
        if key in out and out.get(key) not in (None, ""):
            out[key] = _lk888_pick_option(out.get(key), ratios, "16:9" if ratios else "")
    for key in ("resolution", "size", "videoSize"):
        if key in out and out.get(key) not in (None, ""):
            out[key] = _lk888_pick_numeric_option(out.get(key), resolutions, resolutions[0] if resolutions else "")
    if "duration" in out and out.get("duration") not in (None, ""):
        out["duration"] = _lk888_pick_numeric_option(out.get("duration"), durations, durations[0] if durations else "")
    return out


def _is_kling_video_reference_model(model):
    model = str(model or "").strip().lower()
    return model in {"kling-v3-omni-videoref"}


def _has_video_reference_param(params):
    if not isinstance(params, dict):
        return False
    for key, value in params.items():
        if value in (None, "", [], {}):
            continue
        lowered = str(key or "").lower()
        if "video" in lowered and "audio" not in lowered:
            return True
    return False


def _merge_kling_video_refs_into_params(params, model, video_refs, api_gateway_cfg, prompt, image_refs, payload):
    params = dict(params if isinstance(params, dict) else {})
    refs = _dedupe_urls(video_refs)
    if not refs or not _is_kling_video_reference_model(model):
        return params

    base = str(api_gateway_cfg.get("apiUrl") or "").strip()
    key = str(api_gateway_cfg.get("apiKey") or "").strip()
    try:
        dynamic_params = _apimart_media_params(base, key, model, prompt, image_refs, payload) if base and key else {}
    except Exception:
        dynamic_params = {}
    if isinstance(dynamic_params, dict):
        for k, v in dynamic_params.items():
            if v not in (None, "", [], {}) and k not in params:
                params[k] = v

    if not _has_video_reference_param(params):
        params["video"] = refs[0]
    params.setdefault("video_url", refs[0])
    params.setdefault("reference_video", refs[0])
    return params


def _merge_audio_refs_into_params(params, audio_refs):
    params = dict(params if isinstance(params, dict) else {})
    refs = _dedupe_urls(audio_refs)
    if not refs:
        return params
    params["reference_audio_urls"] = _merge_unique_list(params.get("reference_audio_urls"), refs)
    params["audio_urls"] = _merge_unique_list(params.get("audio_urls"), refs)
    params["audioUrls"] = _merge_unique_list(params.get("audioUrls"), refs)
    params["voice_audio_urls"] = _merge_unique_list(params.get("voice_audio_urls"), refs)
    params["voiceAudioUrls"] = _merge_unique_list(params.get("voiceAudioUrls"), refs)
    params["subject_audio_urls"] = _merge_unique_list(params.get("subject_audio_urls"), refs)
    params["subjectAudioUrls"] = _merge_unique_list(params.get("subjectAudioUrls"), refs)
    params["audios"] = _merge_unique_list(params.get("audios"), refs)
    params.setdefault("audio_url", refs[0])
    params.setdefault("audioUrl", refs[0])
    params.setdefault("reference_audio", refs[0])
    params.setdefault("reference_audio_url", refs[0])
    params.setdefault("referenceAudioUrl", refs[0])
    params.setdefault("voice_audio_url", refs[0])
    params.setdefault("voiceAudioUrl", refs[0])
    params.setdefault("subject_audio_url", refs[0])
    params.setdefault("subjectAudioUrl", refs[0])
    params.setdefault("reference_audio_role", "reference_audio")
    params.setdefault("audio_reference_mode", "reference_audio")
    params.setdefault("lip_sync_required", True)
    params.setdefault("generate_audio", True)
    params.setdefault("with_audio", True)
    params.setdefault("sound", "on")
    return params


def _merge_subject_voice_into_params(params, payload):
    params = dict(params if isinstance(params, dict) else {})
    payload = payload if isinstance(payload, dict) else {}
    voice = str(
        payload.get("voice")
        or payload.get("voiceName")
        or payload.get("ttsVoice")
        or ""
    ).strip()
    voices = payload.get("subject_voice_names")
    if not voice and isinstance(voices, list) and voices:
        voice = str(voices[0] or "").strip()
    if voice:
        params.setdefault("voice", voice)
        params.setdefault("voice_name", voice)
        params.setdefault("tts_voice", voice)
    for src, dst in (
        ("generate_audio", "generate_audio"),
        ("with_audio", "with_audio"),
        ("sound", "sound"),
        ("audio", "audio"),
        ("require_subject_voice_audio", "require_subject_voice_audio"),
        ("strictSubjectVoice", "strictSubjectVoice"),
        ("voiceConsistencyRequired", "voiceConsistencyRequired"),
        ("subject_voice_mode", "subject_voice_mode"),
        ("require_audio_reference", "require_audio_reference"),
        ("requireAudioReference", "requireAudioReference"),
        ("audioReferenceMode", "audioReferenceMode"),
        ("lipSyncRequired", "lipSyncRequired"),
        ("lip_sync_required", "lip_sync_required"),
        ("mouthSyncRequired", "mouthSyncRequired"),
    ):
        if payload.get(src) not in (None, "") and dst not in params:
            params[dst] = payload.get(src)
    return params


def _adapt_api_gateway_video_payload(data, api_gateway_cfg):
    payload = _sync_canvas_reference_image_aliases(dict(data or {}))
    video_model = str(api_gateway_cfg.get("videoModel") or COMIC_DEFAULT_VIDEO_MODEL).strip()
    requested_model = str(payload.get("model") or "").strip()
    requested_model = _lk888_normalize_video_model(_apply_model_remap(requested_model))
    # ponytail: for video, do not silently swap unknown models to an arbitrary fallback.
    payload["model"] = requested_model or _lk888_normalize_video_model(video_model or COMIC_DEFAULT_VIDEO_MODEL)
    _normalize_ratio_key(payload)
    _normalize_video_size_keys(payload)

    refs = []
    for key in ("images", "image_urls", "imageUrls", "inputUrls", "reference_image_urls", "referenceImageUrls", "reference_images", "referenceImages"):
        _extend_url_list(refs, payload.get(key))
    for key in ("first", "first_frame", "firstFrameUrl", "last", "last_frame", "lastFrameUrl", "storyboard_image", "storyboardImage", "end_frame_image", "endFrameImage", "imageUrl", "image_url"):
        _extend_url_list(refs, payload.get(key))
    _extend_url_list(refs, payload.get("image_with_roles"))
    refs = _dedupe_urls(refs)
    video_refs = _dedupe_urls(_apimart_collect_video_refs(payload))
    if not video_refs:
        video_refs = [r for r in refs if _looks_like_video_ref_url(r)]
    refs = [r for r in refs if not _looks_like_video_ref_url(r)]
    refs = [_apimart_publicize_ref(r) for r in refs]
    refs = [r for r in refs if r]
    limited_keyframe_refs = [_apimart_publicize_ref(r) for r in _dedupe_urls(payload.get("_keyframes_limited_video_refs") or [])]
    limited_keyframe_refs = [r for r in limited_keyframe_refs if r]
    if limited_keyframe_refs:
        refs = limited_keyframe_refs
    video_refs = [_apimart_publicize_ref(r) for r in video_refs]
    video_refs = [r for r in video_refs if r]
    if refs:
        payload["images"] = refs
    audio_refs = [r for r in (_apimart_publicize_ref(v) for v in _aic_collect_audio_refs(payload)) if r]

    model = str(payload.get("model") or "")
    if model.startswith("kling-"):
        params = {
            "duration": _lk888_video_duration(payload.get("duration")),
            "prompt": str(payload.get("prompt") or "").strip(),
        }
        if model == "kling-v2-6":
            params["sound"] = str(payload.get("sound") or "off").strip() or "off"
            params["aspect_ratio"] = _lk888_video_ratio(payload.get("aspect_ratio"))
            params["ratio"] = params["aspect_ratio"]
            params["aspectRatio"] = params["aspect_ratio"]
            if payload.get("negative_prompt"):
                params["negative_prompt"] = str(payload.get("negative_prompt") or "").strip()
        else:
            params["mode"] = str(payload.get("mode") or "std").strip() or "std"
            if model != "kling-v3-omni-shouweizhen":
                params["aspect_ratio"] = _lk888_video_ratio(payload.get("aspect_ratio"))
                params["ratio"] = params["aspect_ratio"]
                params["aspectRatio"] = params["aspect_ratio"]
        if payload.get("resolution") not in (None, ""):
            params["resolution"] = payload.get("resolution")
        if refs:
            params["images"] = refs[:7]
        params = _merge_kling_video_refs_into_params(
            params, model, video_refs, api_gateway_cfg, params["prompt"], refs, payload
        )
        params = _merge_audio_refs_into_params(params, audio_refs)
        if model == "kling-avatar-image2video" and audio_refs:
            # ponytail: LK888 digital-human variants have used both generic and explicit audio field names.
            params.setdefault("sound_file", audio_refs[0])
            params.setdefault("soundFile", audio_refs[0])
            params.setdefault("audio", audio_refs[0])
            params.setdefault("audio_file", audio_refs[0])
            params.setdefault("audioFile", audio_refs[0])
            params.setdefault("reference_audio_file", audio_refs[0])
            if refs:
                params.setdefault("image", refs[0])
                params.setdefault("image_url", refs[0])
                params.setdefault("input_image", refs[0])
            params.setdefault("lip_sync_required", True)
            params.setdefault("audio_reference_mode", "digital_human")
        params = _merge_subject_voice_into_params(params, payload)
        params = _lk888_normalize_video_params(model, params)
        params = _collapse_video_ratio_aliases(params)
        params = _coerce_lk888_video_params_to_schema(model, params, payload, api_gateway_cfg)
        return {"model": model, "prompt": params["prompt"], "params": params, "count": 1}

    base = str(api_gateway_cfg.get("apiUrl") or "").strip()
    key = str(api_gateway_cfg.get("apiKey") or "").strip()
    prompt = str(payload.get("prompt") or "").strip()
    refs = [_apimart_publicize_ref(r) for r in refs]
    refs = [r for r in refs if r]
    try:
        params = _apimart_media_params(base, key, model, prompt, refs, payload) if base and key else {}
    except Exception:
        params = {}
    if not isinstance(params, dict):
        params = {}
    # ponytail: LK888 video endpoints expect provider-specific fields under params, not flat APIMart/OpenAI fields.
    for src, dst in (
        ("duration", "duration"),
        ("resolution", "resolution"),
        ("videoSize", "resolution"),
        ("videoResolution", "resolution"),
        ("video_resolution", "resolution"),
        ("selectedVideoResolution", "resolution"),
        ("selectedResolution", "resolution"),
        ("selectedSize", "resolution"),
        ("quality", "quality"),
        ("mode", "mode"),
    ):
        if payload.get(src) not in (None, "") and dst not in params:
            params[dst] = payload.get(src)
    ratio_value = _first_non_empty(payload.get("aspectRatio"), payload.get("aspect_ratio"), payload.get("ratio"))
    if ratio_value not in (None, "") and not any(key in params for key in ("aspectRatio", "aspect_ratio", "ratio")):
        params["aspectRatio"] = ratio_value
    if limited_keyframe_refs:
        for key, value in list(params.items()):
            lowered = str(key or "").lower()
            if lowered in {"inputurls", "input_urls", "first", "last"} or "image" in lowered or "frame" in lowered:
                if _dedupe_urls(value):
                    params.pop(key, None)
        params_refs = []
        for value in params.values():
            _extend_url_list(params_refs, value)
        if not (set(_dedupe_urls(params_refs)) & set(limited_keyframe_refs)):
            params["images"] = limited_keyframe_refs
    else:
        params_refs = []
        for value in params.values():
            _extend_url_list(params_refs, value)
        if refs and not any(k.lower() in ("image", "images", "image_url", "image_urls", "first_frame", "last_frame") for k in params) and not (set(_dedupe_urls(params_refs)) & set(refs)):
            params["images"] = refs
    params = _merge_audio_refs_into_params(params, audio_refs)
    params = _merge_subject_voice_into_params(params, payload)
    params = _lk888_normalize_video_params(model, params)
    params = _collapse_video_ratio_aliases(params)
    params = _coerce_lk888_video_params_to_schema(model, params, payload, api_gateway_cfg)
    return {"model": model, "prompt": prompt, "params": params, "count": 1}



# ===== APIMART-PROXY-PATCH: APIMart 媒体协议适配 (2026-06-11) =====
# APIMart 不支持 OpenAI 风格媒体接口; 统一走 POST /v1/media/generate (任务式)
# + GET /v1/skills/task-status 轮询。图片在代理内阻塞轮询后按 OpenAI 形状返回;
# 视频创建返回 {"task_id"}, 前端的 /v2/videos/generations/{id} 轮询被翻译成 task-status。
_APIMART_CATALOG_CACHE = {}
_APIMART_DETAIL_CACHE = {}


def _is_apimart_gateway_base(base_url):
    # APIMART-KILLED: apimart.ai is dead; always return False so media goes through OpenAI-compat path (lk888)
    return False


def _assert_apimart_api_key(key):
    text = str(key or "").strip()
    field_names = {
        "reference_image_urls", "referenceImageUrls", "image_urls", "imageUrls",
        "inputUrls", "images", "reference_images", "referenceImages",
        "subject_reference_images", "additional_reference_images",
        "character_reference_images", "scene_reference_images",
        "prop_reference_images", "strict_reference_image_urls",
    }
    if not text or text in field_names or len(text) < 16:
        raise RuntimeError("LK888 网关密钥异常，已在本地拦截，未提交上游")
    return text


def _apimart_json_request(base, key, path, payload=None, timeout=60):
    key = _assert_apimart_api_key(key)
    url = base.rstrip("/") + path
    headers = {"Authorization": "Bearer " + key, "Content-Type": "application/json", "User-Agent": "Mozilla/5.0"}
    body = json.dumps(payload).encode("utf-8") if payload is not None else None
    req = urllib.request.Request(url, data=body, headers=headers, method="POST" if payload is not None else "GET")
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return json.loads(resp.read().decode("utf-8", "replace"))


def _apimart_catalog(base, key, media_type):
    cache_key = (base, media_type)
    cached = _APIMART_CATALOG_CACHE.get(cache_key)
    if cached:
        return cached
    names = set()
    try:
        data = _apimart_json_request(base, key, "/v1/skills/models?type=" + media_type, None, 30)
        names = {str(item.get("name") or "") for item in (data.get("models") or []) if isinstance(item, dict)}
    except Exception:
        names = set()
    if names:
        _APIMART_CATALOG_CACHE[cache_key] = names
    return names


def _apimart_collect_refs(data):
    refs = []
    for k in ("urls", "image_urls", "imageUrls", "reference_image_urls", "referenceImageUrls", "reference_images", "referenceImages", "images", "inputUrls",
              "first", "first_frame", "firstFrameUrl", "imageUrl", "image_url"):
        _extend_url_list(refs, (data or {}).get(k))
    _extend_url_list(refs, (data or {}).get("image_with_roles"))
    return _dedupe_urls(refs)


def _apimart_publicize_ref(ref):
    # APIMART-REF-PUBLICIZE: 网关只接受可公开访问的图片 URL, 把 data: URI 落地成公网 URL
    ref = str(ref or '').strip()
    if not ref:
        return ref
    # AIC-HTTPS-FIX: 网关拒绝 http:// 图片链接，把本机媒体host的 http 升级为 https
    if ref.startswith('http://'):
        try:
            _pb = (os.environ.get('AIC_MEDIA_UPLOAD_PUBLIC_BASE', '') or '').strip()
            _bh = urllib.parse.urlsplit(_pb).netloc.lower() if _pb else ''
            if _bh and urllib.parse.urlsplit(ref).netloc.lower() == _bh:
                ref = 'https://' + ref[len('http://'):]
        except Exception:
            pass
        return ref
    if not ref.startswith('data:'):
        return ref
    import base64 as _b64, re as _re, os as _os, time as _time
    m = _re.match(r'data:([^;,]+)?(;base64)?,(.*)$', ref, _re.S)
    if not m:
        return ref
    mime = (m.group(1) or 'image/png').strip()
    body = m.group(3)
    try:
        raw = _b64.b64decode(body) if m.group(2) else urllib.parse.unquote_to_bytes(body)
    except Exception:
        return ref
    updir = _os.environ.get('AIC_MEDIA_UPLOAD_DIR', '').strip()
    pubbase = _os.environ.get('AIC_MEDIA_UPLOAD_PUBLIC_BASE', '').strip().rstrip('/')
    if not updir or not pubbase:
        return ref
    try:
        _os.makedirs(updir, exist_ok=True)
        ext = {'image/png':'png','image/jpeg':'jpg','image/jpg':'jpg','image/webp':'webp','image/gif':'gif'}.get(mime, 'png')
        name = 'aicref_%s_%s.%s' % (_time.strftime('%Y%m%d%H%M%S'), _os.urandom(5).hex(), ext)
        with open(_os.path.join(updir, name), 'wb') as fh:
            fh.write(raw)
        return pubbase + '/' + name
    except Exception:
        return ref


def _aic_ratio_label(data):
    # APIMART-PARAM-PASSTHROUGH: 从前端 data 取比例标签 (兼容多种字段名)
    for k in ("aspect_ratio", "aspectRatio", "ratio", "resolvedRatioLabel", "aspect"):
        v = str((data or {}).get(k) or "").strip()
        if v:
            return v
    return ""


def _aic_ratio_to_pixel(ratio_label, pixel_opts):
    import re as _re
    try:
        a, b = _re.split(r"[:：/xX×]", str(ratio_label).strip())[:2]
        target = float(a) / float(b)
    except Exception:
        return ""
    best, bestdiff = "", 1e9
    for opt in pixel_opts:
        mm = _re.match(r"(\d+)\s*[x×X]\s*(\d+)", str(opt))
        if not mm:
            continue
        r = int(mm.group(1)) / int(mm.group(2))
        d = abs(r - target)
        if d < bestdiff:
            bestdiff, best = d, opt
    return best


def _aic_match_option(value, opts):
    # 把值规范化到合法选项: 精确 / 忽略大小写 / 字符串化
    sval = str(value).strip()
    if not opts:
        return sval
    for o in opts:
        if str(o) == sval:
            return o
    low = sval.lower()
    for o in opts:
        if str(o).lower() == low:
            return o
    return ""


def _aic_param_value(name, ptype, opts, data):
    # 为单个 schema 参数从前端 data 解析出合法值; 解析不到返回 ""
    import re as _re
    low = str(name).lower()
    d = data or {}
    pixel_opts = [o for o in opts if _re.match(r"\d+\s*[x×X]\s*\d+", str(o))]
    # 比例 / 尺寸类
    if low in ("size", "ratio", "aspect_ratio", "aspect", "image_size", "resolution_ratio", "aspectratio", "videosize", "video_size", "videoresolution", "video_resolution"):
        rl = _aic_ratio_label(d)
        if pixel_opts:  # 选项是像素 -> 比例映射到最接近像素
            px = _aic_ratio_to_pixel(rl, pixel_opts) if rl else ""
            return px or ""
        if rl:  # 选项是比例标签
            m = _aic_match_option(rl, opts)
            if m:
                return m
        # size 也可能前端直接给了像素/标签
        direct = ""
        for k in ("videoSize", "video_size", "videoResolution", "video_resolution", "selectedVideoResolution", "selectedResolution", "selectedSize", "resolution", "imageSize", "image_size", "size"):
            direct = str(d.get(k) or "").strip()
            if direct:
                break
        direct = _video_resolution_label(direct) or direct or _video_resolution_from_dimensions(d)
        return _aic_match_option(direct, opts) if direct else ""
    # 分辨率/清晰度
    if low in ("resolution", "definition", "clarity", "imagesize", "videosize", "video_size", "videoresolution", "video_resolution"):
        for k in ("resolution", "videoSize", "video_size", "videoResolution", "video_resolution", "selectedVideoResolution", "selectedResolution", "selectedSize", "imageSize", "image_size", "definition", "clarity", "quality", "hd", "size", "rhVideoResolution"):
            raw = str(d.get(k) or "").strip()
            for v in (_video_resolution_label(raw), raw):
                if not v:
                    continue
                m = _aic_match_option(v, opts)
                if m:
                    return m
        v = _video_resolution_from_dimensions(d)
        if v:
            m = _aic_match_option(v, opts)
            if m:
                return m
        return ""
    # 画质(高清)
    if low in ("quality", "hd"):
        for k in ("quality", "hd", "clarity", "definition"):
            v = str(d.get(k) or "").strip()
            if v:
                m = _aic_match_option(v, opts)
                if m:
                    return m
        # 前端传 hd/highQuality 布尔 -> 取最高档(非 auto)
        if d.get("hd") in (True, "true", 1, "1") or d.get("highQuality") in (True, "true", 1, "1"):
            for cand in ("high", "1080p", "4k", "2k"):
                m = _aic_match_option(cand, opts)
                if m:
                    return m
        return ""
    # 时长
    if low in ("audio_duration", "duration", "seconds", "video_duration"):
        for k in ("duration", "seconds", "video_duration", "audio_duration"):
            v = d.get(k)
            if v not in (None, ""):
                sv = str(int(v)) if isinstance(v, (int, float)) else str(v).strip()
                m = _aic_match_option(sv, opts) if opts else sv
                if m:
                    return m
                if opts:  # 选最接近的数字档
                    try:
                        tv = float(sv)
                        cand = min(opts, key=lambda o: abs(float(_re.sub(r"[^0-9.]", "", str(o)) or 0) - tv))
                        return cand
                    except Exception:
                        pass
        return ""
    # 音频开关
    if low in ("generate_audio", "audio", "sound", "with_audio"):
        for k in ("audio", "generate_audio", "sound", "with_audio"):
            if k in d:
                b = d.get(k)
                sv = "true" if b in (True, "true", 1, "1", "yes") else "false"
                m = _aic_match_option(sv, opts) if opts else sv
                return m or sv
        return ""
    if low in ("orientation", "frame_orientation"):
        ratio = _normalize_aspect_ratio_value(_aic_ratio_label(d))
        if ratio == "9:16":
            return _aic_match_option("portrait", opts) or "portrait"
        if ratio == "16:9":
            return _aic_match_option("landscape", opts) or "landscape"
        return ""
    # 兜底: 同名直取
    v = d.get(name)
    if v not in (None, ""):
        return _aic_match_option(v, opts) if opts else str(v)
    return ""


def _apimart_collect_video_refs(data):
    out = []
    def _add(v):
        if v is None: return
        if isinstance(v, str):
            s = v.strip()
            if s: out.append(s)
        elif isinstance(v, dict):
            for kk in ("videoUrl","video_url","remoteUrl","url","localUrl","src","value"):
                u = v.get(kk)
                if isinstance(u, str) and u.strip():
                    out.append(u.strip()); break
        elif isinstance(v, (list, tuple)):
            for it in v: _add(it)
    d = data or {}
    for k in ("video","video_urls","videoUrls","videos","videoUrl","video_url",
              "sourceVideo","source_video","sourceVideoUrl","clips",
              "reference_video","referenceVideo","reference_video_url","referenceVideoUrl",
              "reference_video_urls","referenceVideoUrls","referenceVideos","reference_videos",
              "inputUrls","input_urls","inputs","references"):
        _add(d.get(k))
    vids = [u for u in out if (u.lower().split("?")[0].endswith((".mp4",".mov",".webm",".m4v")) or "/video" in u.lower())]
    return _dedupe_urls(vids)


def _aic_is_video_upload(lowered, pdef):
    label = str(pdef.get("label") or "").lower()
    if "video" in label: return True
    if "image" in label: return False
    desc = str(pdef.get("description") or "").lower()
    return ("video" in lowered) or ("clip" in lowered) or ("video" in desc)


def _aic_is_audio_upload(lowered, pdef):
    label = str(pdef.get("label") or "").lower()
    desc = str(pdef.get("description") or "").lower()
    text = " ".join([lowered, label, desc])
    if "video" in text or "image" in text or "图片" in text or "视频" in text:
        return False
    return any(token in text for token in ("audio", "voice", "sound", "音频", "声音", "音色", "配音"))


def _apimart_media_params(base, key, model, prompt, refs, data=None):
    detail = _APIMART_DETAIL_CACHE.get((base, model))
    if detail is None:
        try:
            detail = _apimart_json_request(base, key, "/v1/skills/models/" + urllib.parse.quote(model, safe=""), None, 30)
            _APIMART_DETAIL_CACHE[(base, model)] = detail
        except Exception:
            detail = {}
    params = {}
    param_defs = detail.get("params") if isinstance(detail, dict) else []
    video_refs = [r for r in (_apimart_publicize_ref(v) for v in _apimart_collect_video_refs(data)) if r]
    audio_refs = [r for r in (_apimart_publicize_ref(v) for v in _aic_collect_audio_refs(data)) if r]
    for pdef in (param_defs or []):
        if not isinstance(pdef, dict):
            continue
        name = str(pdef.get("name") or "")
        if not name:
            continue
        lowered = name.lower()
        ptype = str(pdef.get("type") or "").lower()
        desc = str(pdef.get("description") or "")
        is_audio_upload = ptype == "upload" and _aic_is_audio_upload(lowered, pdef)
        is_video_upload = ptype == "upload" and _aic_is_video_upload(lowered, pdef)
        if lowered == "prompt":
            params[name] = prompt
        elif is_audio_upload:
            if audio_refs:
                if lowered.endswith("s") or (u"最多" in desc) or (u"数组" in desc):
                    params[name] = audio_refs
                else:
                    params[name] = audio_refs[0]
        elif is_video_upload:
            if video_refs:
                params[name] = video_refs[0]
        elif ptype == "upload" and refs and not _aic_is_video_upload(lowered, pdef):
            if _lk888_normalize_video_model(_apply_model_remap(d.get("model"))) == "sora-2" and lowered == "input_reference":
                params[name] = refs[:2]
                continue
            single_upload = re.search(r"upload\s+1\s+image|1\s*张|单张", desc, re.IGNORECASE) and not re.search(r"1\s*[-~]\s*[2-9]", desc)
            if not single_upload and (lowered.endswith("s") or (u"最多" in desc)):
                params[name] = refs
            else:
                params[name] = refs[0]
        else:
            # APIMART-PARAM-PASSTHROUGH: 透传前端选择的 比例/尺寸/分辨率/画质/时长/音频
            _opts = [o.get("value") for o in (pdef.get("options") or []) if isinstance(o, dict)]
            _val = _aic_param_value(name, ptype, _opts, data)
            if _val not in (None, ""):
                params[name] = _val
    # AIC-REQUIRED-DEFAULTS: 重映射模型的替身可能带画布UI未提供的必填项,
    # 必填 select 仍为空时补一个合理默认(标注default -> auto -> 中间档), 避免网关 400 参数验证失败
    for pdef in (param_defs or []):
        if not isinstance(pdef, dict) or not pdef.get("required"):
            continue
        rname = str(pdef.get("name") or "")
        if not rname or params.get(rname) not in (None, ""):
            continue
        if str(pdef.get("type") or "").lower() in ("textarea", "text", "upload"):
            continue
        ropts = [o.get("value") for o in (pdef.get("options") or []) if isinstance(o, dict)]
        if not ropts:
            continue
        flagged = next((o.get("value") for o in pdef.get("options")
                        if isinstance(o, dict) and o.get("default")), None)
        if flagged not in (None, ""):
            params[rname] = flagged
        elif str(pdef.get("type") or "").lower() in {"switch", "boolean", "bool"}:
            off_value = next((o for o in ropts if str(o).strip().lower() in {"false", "0", "off", "no"}), None)
            params[rname] = off_value if off_value not in (None, "") else ropts[0]
        elif "auto" in [str(o).lower() for o in ropts]:
            params[rname] = next(o for o in ropts if str(o).lower() == "auto")
        else:
            params[rname] = ropts[len(ropts) // 2]
    params = _collapse_video_ratio_aliases(params)
    return params


_MODEL_REMAP_CACHE = {"data": None}
def _load_model_remap():
    if _MODEL_REMAP_CACHE["data"] is None:
        try:
            import os, json as _json
            p = os.path.join(os.path.dirname(os.path.abspath(__file__)), "model_remap.json")
            with open(p, "r", encoding="utf-8") as f:
                _MODEL_REMAP_CACHE["data"] = _json.load(f) or {}
        except Exception:
            _MODEL_REMAP_CACHE["data"] = {}
    return _MODEL_REMAP_CACHE["data"]

def _apply_model_remap(model):
    """死模型id→网关活替身id；无替身或未知则原样返回。"""
    m = str(model or "").strip()
    if not m:
        return m
    if m in ("doubao-seedance-2-0-260128", "doubao-seedance-2-0-fast-260128", "doubao-seedance-2-0-mini-260615"):
        return m
    entry = _load_model_remap().get(m)
    if isinstance(entry, dict):
        rep = str(entry.get("replacement") or "").strip()
        if rep and rep.lower() not in ("no_replacement", "none", "null"):
            return rep
    return m




# ===== APIMART-PROXY-PATCH: APIMart 媒体协议适配 (2026-06-11) =====
# APIMart 不支持 OpenAI 风格媒体接口; 统一走 POST /v1/media/generate (任务式)
# + GET /v1/skills/task-status 轮询。图片在代理内阻塞轮询后按 OpenAI 形状返回;
# 视频创建返回 {"task_id"}, 前端的 /v2/videos/generations/{id} 轮询被翻译成 task-status。
_APIMART_CATALOG_CACHE = {}
_APIMART_DETAIL_CACHE = {}


def _is_apimart_gateway_base(base_url):
    try:
        host = urllib.parse.urlsplit(str(base_url or "")).netloc.lower()
    except Exception:
        host = ""
    return False


def _apimart_json_request(base, key, path, payload=None, timeout=60):
    key = _assert_apimart_api_key(key)
    url = base.rstrip("/") + path
    headers = {"Authorization": "Bearer " + key, "Content-Type": "application/json", "User-Agent": "Mozilla/5.0"}
    body = json.dumps(payload).encode("utf-8") if payload is not None else None
    req = urllib.request.Request(url, data=body, headers=headers, method="POST" if payload is not None else "GET")
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            return json.loads(resp.read().decode("utf-8", "replace"))
    except urllib.error.HTTPError as e:
        detail = e.read().decode("utf-8", "replace")[:1000]
        raise RuntimeError("Gateway HTTP %s %s: %s" % (e.code, path, detail))


def _apimart_catalog(base, key, media_type):
    cache_key = (base, media_type)
    cached = _APIMART_CATALOG_CACHE.get(cache_key)
    if cached:
        return cached
    names = set()
    try:
        data = _apimart_json_request(base, key, "/v1/skills/models?type=" + media_type, None, 30)
        names = {str(item.get("name") or "") for item in (data.get("models") or []) if isinstance(item, dict)}
    except Exception:
        names = set()
    if names:
        _APIMART_CATALOG_CACHE[cache_key] = names
    return names


def _apimart_collect_refs(data):
    refs = []
    for k in ("urls", "image_urls", "imageUrls", "reference_image_urls", "referenceImageUrls", "reference_images", "referenceImages", "images", "inputUrls",
              "first", "first_frame", "firstFrameUrl", "imageUrl", "image_url"):
        _extend_url_list(refs, (data or {}).get(k))
    _extend_url_list(refs, (data or {}).get("image_with_roles"))
    return _dedupe_urls(refs)


def _apimart_publicize_ref(ref):
    # APIMART-REF-PUBLICIZE: ??/????????? URL???/??/data ??????????
    ref = str(ref or '').strip()
    if not ref:
        return ref
    import base64 as _b64, re as _re, os as _os, time as _time, glob as _glob
    updir = (_os.environ.get('AIC_MEDIA_UPLOAD_DIR', '').strip() or '/root/canvas-refimg')
    pubbase = (_os.environ.get('AIC_MEDIA_UPLOAD_PUBLIC_BASE', '').strip().rstrip('/') or 'https://manju.eknowhub.cn/refimg')

    def _save_public(raw, mime='image/png'):
        _os.makedirs(updir, exist_ok=True)
        ext = {'image/png':'png','image/jpeg':'jpg','image/jpg':'jpg','image/webp':'webp','image/gif':'gif'}.get((mime or '').split(';', 1)[0].lower(), '')
        if not ext:
            ext = (_os.path.splitext(urllib.parse.urlsplit(ref).path)[1] or '.png').lstrip('.')[:8]
        name = 'aicref_%s_%s.%s' % (_time.strftime('%Y%m%d%H%M%S'), _os.urandom(5).hex(), ext or 'png')
        with open(_os.path.join(updir, name), 'wb') as fh:
            fh.write(raw)
        return pubbase + '/' + name

    def _account_virtual_fallback(req_path):
        rel = ''
        roots = []
        if req_path.startswith('/output/'):
            rel = req_path[len('/output/'):].lstrip('/')
            roots = [_os.path.join(BASE_DIR, 'accounts', '*', 'output')]
        elif req_path.startswith('/data/uploads/'):
            rel = req_path[len('/data/uploads/'):].lstrip('/')
            roots = [_os.path.join(BASE_DIR, 'accounts', '*', 'data', 'uploads')]
        if not rel:
            return ''
        matches = []
        for root in roots:
            matches.extend(_glob.glob(_os.path.join(root, rel)))
        files = [path for path in matches if _os.path.isfile(path)]
        if not files:
            return ''
        files.sort(key=lambda path: _os.path.getmtime(path), reverse=True)
        return _os.path.abspath(files[0])

    if ref.startswith('data:'):
        m = _re.match(r'data:([^;,]+)?(;base64)?,(.*)$', ref, _re.S)
        if not m:
            return ref
        try:
            raw = _b64.b64decode(m.group(3)) if m.group(2) else urllib.parse.unquote_to_bytes(m.group(3))
            return _save_public(raw, (m.group(1) or 'image/png').strip())
        except Exception:
            return ref

    if ref.startswith(('/uploads/', 'uploads/', '/output/', 'output/', '/data/uploads/', 'data/uploads/')):
        try:
            req_path = '/' + ref.lstrip('/')
            local_path = _resolve_local_virtual_path(req_path)
            if not local_path and req_path.startswith('/uploads/'):
                local_path = _os.path.abspath(_os.path.join(_current_uploads_dir(), req_path[len('/uploads/'):]))
            if not local_path and req_path.startswith('/output/'):
                local_path = _os.path.abspath(_os.path.join(_current_output_dir(), req_path[len('/output/'):]))
            if not local_path and req_path.startswith('/data/uploads/'):
                local_path = _os.path.abspath(_os.path.join(_current_uploads_dir(), req_path[len('/data/uploads/'):]))
            if (not local_path or not _os.path.isfile(local_path)) and req_path.startswith(('/output/', '/data/uploads/')):
                local_path = _account_virtual_fallback(req_path)
            if local_path and _os.path.isfile(local_path):
                mime = mimetypes.guess_type(local_path)[0] or 'image/png'
                with open(local_path, 'rb') as fh:
                    return _save_public(fh.read(), mime)
            if req_path.startswith(_PLATFORM_MEDIA_PROXY_PREFIXES):
                candidates = _platform_media_candidate_urls(req_path)
                for candidate in candidates:
                    try:
                        request = urllib.request.Request(candidate, headers={"User-Agent": "Mozilla/5.0"}, method="HEAD")
                        with urllib.request.urlopen(request, timeout=5) as response:
                            if int(getattr(response, "status", 200) or 200) < 400:
                                return candidate
                    except Exception:
                        continue
                if candidates:
                    return candidates[0]
        except Exception:
            return ref
        return ref

    if ref.startswith('http://') or ref.startswith('https://'):
        try:
            pb_host = urllib.parse.urlsplit(pubbase).netloc.lower()
            parsed = urllib.parse.urlsplit(ref)
            host = parsed.netloc.lower()
            if pb_host and host == pb_host:
                return ref
            local_hosts = {'120.26.194.174', '120.26.194.174:8777', '127.0.0.1', '127.0.0.1:8777', 'localhost', 'localhost:8777'}
            if host in local_hosts:
                req_path = urllib.parse.unquote(parsed.path).replace('\\', '/')
                local_path = _resolve_local_virtual_path(req_path)
                if not local_path and req_path.startswith('/output/'):
                    local_path = _os.path.abspath(_os.path.join(_current_output_dir(), req_path[len('/output/'):]))
                if not local_path and req_path.startswith('/data/uploads/'):
                    local_path = _os.path.abspath(_os.path.join(_current_uploads_dir(), req_path[len('/data/uploads/'):]))
                if (not local_path or not _os.path.isfile(local_path)) and req_path.startswith(('/output/', '/data/uploads/')):
                    local_path = _account_virtual_fallback(req_path)
                if local_path and _os.path.isfile(local_path):
                    mime = mimetypes.guess_type(local_path)[0] or 'image/png'
                    with open(local_path, 'rb') as fh:
                        return _save_public(fh.read(), mime)
            if 'apimart' in host:
                req = urllib.request.Request(ref, headers={"User-Agent": "Mozilla/5.0"})
                with urllib.request.urlopen(req, timeout=30) as resp:
                    return _save_public(resp.read(), resp.headers.get('Content-Type') or 'image/png')
        except Exception:
            return ref
        return ref

    return ref

def _aic_ratio_label(data):
    # APIMART-PARAM-PASSTHROUGH: 从前端 data 取比例标签 (兼容多种字段名)
    for k in ("aspect_ratio", "aspectRatio", "ratio", "resolvedRatioLabel", "aspect"):
        v = str((data or {}).get(k) or "").strip()
        if v:
            return v
    return ""


def _aic_ratio_to_pixel(ratio_label, pixel_opts):
    import re as _re
    try:
        a, b = _re.split(r"[:：/xX×]", str(ratio_label).strip())[:2]
        target = float(a) / float(b)
    except Exception:
        return ""
    best, bestdiff = "", 1e9
    for opt in pixel_opts:
        mm = _re.match(r"(\d+)\s*[x×X]\s*(\d+)", str(opt))
        if not mm:
            continue
        r = int(mm.group(1)) / int(mm.group(2))
        d = abs(r - target)
        if d < bestdiff:
            bestdiff, best = d, opt
    return best


def _aic_match_option(value, opts):
    # 把值规范化到合法选项: 精确 / 忽略大小写 / 字符串化
    sval = str(value).strip()
    if not opts:
        return sval
    for o in opts:
        if str(o) == sval:
            return o
    low = sval.lower()
    for o in opts:
        if str(o).lower() == low:
            return o
    return ""


def _aic_param_value(name, ptype, opts, data):
    # 为单个 schema 参数从前端 data 解析出合法值; 解析不到返回 ""
    import re as _re
    low = str(name).lower()
    d = data or {}
    pixel_opts = [o for o in opts if _re.match(r"\d+\s*[x×X]\s*\d+", str(o))]
    # 比例 / 尺寸类
    if low in ("size", "ratio", "aspect_ratio", "aspect", "image_size", "resolution_ratio", "aspectratio", "videosize", "video_size", "videoresolution", "video_resolution"):
        rl = _aic_ratio_label(d)
        if pixel_opts:  # 选项是像素 -> 比例映射到最接近像素
            px = _aic_ratio_to_pixel(rl, pixel_opts) if rl else ""
            return px or ""
        if rl:  # 选项是比例标签
            m = _aic_match_option(rl, opts)
            if m:
                return m
        # size 也可能前端直接给了像素/标签
        direct = ""
        for k in ("videoSize", "video_size", "videoResolution", "video_resolution", "selectedVideoResolution", "selectedResolution", "selectedSize", "resolution", "imageSize", "image_size", "size"):
            direct = str(d.get(k) or "").strip()
            if direct:
                break
        direct = _video_resolution_label(direct) or direct or _video_resolution_from_dimensions(d)
        return _aic_match_option(direct, opts) if direct else ""
    # 分辨率/清晰度
    if low in ("resolution", "definition", "clarity", "imagesize", "videosize", "video_size", "videoresolution", "video_resolution"):
        for k in ("resolution", "videoSize", "video_size", "videoResolution", "video_resolution", "selectedVideoResolution", "selectedResolution", "selectedSize", "imageSize", "image_size", "definition", "clarity", "quality", "hd", "size", "rhVideoResolution"):
            raw = str(d.get(k) or "").strip()
            for v in (_video_resolution_label(raw), raw):
                if not v:
                    continue
                m = _aic_match_option(v, opts)
                if m:
                    return m
        v = _video_resolution_from_dimensions(d)
        if v:
            m = _aic_match_option(v, opts)
            if m:
                return m
        return ""
    # 画质(高清)
    if low in ("quality", "hd"):
        for k in ("quality", "hd", "clarity", "definition"):
            v = str(d.get(k) or "").strip()
            if v:
                m = _aic_match_option(v, opts)
                if m:
                    return m
        # 前端传 hd/highQuality 布尔 -> 取最高档(非 auto)
        if d.get("hd") in (True, "true", 1, "1") or d.get("highQuality") in (True, "true", 1, "1"):
            for cand in ("high", "1080p", "4k", "2k"):
                m = _aic_match_option(cand, opts)
                if m:
                    return m
        return ""
    # 时长
    if low in ("audio_duration", "duration", "seconds", "video_duration"):
        for k in ("duration", "seconds", "video_duration", "audio_duration"):
            v = d.get(k)
            if v not in (None, ""):
                sv = str(int(v)) if isinstance(v, (int, float)) else str(v).strip()
                m = _aic_match_option(sv, opts) if opts else sv
                if m:
                    return m
                if opts:  # 选最接近的数字档
                    try:
                        tv = float(sv)
                        cand = min(opts, key=lambda o: abs(float(_re.sub(r"[^0-9.]", "", str(o)) or 0) - tv))
                        return cand
                    except Exception:
                        pass
        return ""
    # 音频开关
    if low in ("generate_audio", "audio", "sound", "with_audio"):
        for k in ("audio", "generate_audio", "sound", "with_audio"):
            if k in d:
                b = d.get(k)
                sv = "true" if b in (True, "true", 1, "1", "yes") else "false"
                m = _aic_match_option(sv, opts) if opts else sv
                return m or sv
        return ""
    if low in ("orientation", "frame_orientation"):
        ratio = _normalize_aspect_ratio_value(_aic_ratio_label(d))
        if ratio == "9:16":
            return _aic_match_option("portrait", opts) or "portrait"
        if ratio == "16:9":
            return _aic_match_option("landscape", opts) or "landscape"
        return ""
    # 兜底: 同名直取
    v = d.get(name)
    if v not in (None, ""):
        return _aic_match_option(v, opts) if opts else str(v)
    return ""


def _apimart_collect_video_refs(data):
    out = []
    def _add(v):
        if v is None: return
        if isinstance(v, str):
            s = v.strip()
            if s: out.append(s)
        elif isinstance(v, dict):
            for kk in ("videoUrl","video_url","remoteUrl","url","localUrl","src","value"):
                u = v.get(kk)
                if isinstance(u, str) and u.strip():
                    out.append(u.strip()); break
        elif isinstance(v, (list, tuple)):
            for it in v: _add(it)
    d = data or {}
    for k in ("video","video_urls","videoUrls","videos","videoUrl","video_url",
              "sourceVideo","source_video","sourceVideoUrl","clips",
              "reference_video","referenceVideo","reference_video_url","referenceVideoUrl",
              "reference_video_urls","referenceVideoUrls","referenceVideos","reference_videos",
              "inputUrls","input_urls","inputs","references"):
        _add(d.get(k))
    vids = [u for u in out if (u.lower().split("?")[0].endswith((".mp4",".mov",".webm",".m4v")) or "/video" in u.lower())]
    return _dedupe_urls(vids)


def _aic_is_video_upload(lowered, pdef):
    label = str(pdef.get("label") or "").lower()
    if "video" in label: return True
    if "image" in label: return False
    desc = str(pdef.get("description") or "").lower()
    return ("video" in lowered) or ("clip" in lowered) or ("video" in desc)


def _apimart_media_params(base, key, model, prompt, refs, data=None):
    detail = _APIMART_DETAIL_CACHE.get((base, model))
    if detail is None:
        try:
            detail = _apimart_json_request(base, key, "/v1/skills/models/" + urllib.parse.quote(model, safe=""), None, 30)
            _APIMART_DETAIL_CACHE[(base, model)] = detail
        except Exception:
            detail = {}
    params = {}
    param_defs = detail.get("params") if isinstance(detail, dict) else []
    video_refs = [r for r in (_apimart_publicize_ref(v) for v in _apimart_collect_video_refs(data)) if r]
    audio_refs = [r for r in (_apimart_publicize_ref(v) for v in _aic_collect_audio_refs(data)) if r]
    for pdef in (param_defs or []):
        if not isinstance(pdef, dict):
            continue
        name = str(pdef.get("name") or "")
        if not name:
            continue
        lowered = name.lower()
        ptype = str(pdef.get("type") or "").lower()
        desc = str(pdef.get("description") or "")
        is_audio_upload = ptype == "upload" and _aic_is_audio_upload(lowered, pdef)
        is_video_upload = ptype == "upload" and _aic_is_video_upload(lowered, pdef)
        if lowered == "prompt":
            params[name] = prompt
        elif is_audio_upload:
            if audio_refs:
                if lowered.endswith("s") or (u"最多" in desc) or (u"数组" in desc):
                    params[name] = audio_refs
                else:
                    params[name] = audio_refs[0]
        elif is_video_upload:
            if video_refs:
                params[name] = video_refs[0]
        elif ptype == "upload" and refs and not _aic_is_video_upload(lowered, pdef):
            if _lk888_normalize_video_model(_apply_model_remap(d.get("model"))) == "sora-2" and lowered == "input_reference":
                params[name] = refs[:2]
                continue
            single_upload = re.search(r"upload\s+1\s+image|1\s*张|单张", desc, re.IGNORECASE) and not re.search(r"1\s*[-~]\s*[2-9]", desc)
            if not single_upload and (lowered.endswith("s") or (u"最多" in desc)):
                params[name] = refs
            else:
                params[name] = refs[0]
        else:
            # APIMART-PARAM-PASSTHROUGH: 透传前端选择的 比例/尺寸/分辨率/画质/时长/音频
            _opts = [o.get("value") for o in (pdef.get("options") or []) if isinstance(o, dict)]
            _val = _aic_param_value(name, ptype, _opts, data)
            if _val not in (None, ""):
                params[name] = _val
    # AIC-REQUIRED-DEFAULTS: 重映射模型的替身可能带画布UI未提供的必填项,
    # 必填 select 仍为空时补一个合理默认(标注default -> auto -> 中间档), 避免网关 400 参数验证失败
    for pdef in (param_defs or []):
        if not isinstance(pdef, dict) or not pdef.get("required"):
            continue
        rname = str(pdef.get("name") or "")
        if not rname or params.get(rname) not in (None, ""):
            continue
        if str(pdef.get("type") or "").lower() in ("textarea", "text", "upload"):
            continue
        ropts = [o.get("value") for o in (pdef.get("options") or []) if isinstance(o, dict)]
        if not ropts:
            continue
        flagged = next((o.get("value") for o in pdef.get("options")
                        if isinstance(o, dict) and o.get("default")), None)
        if flagged not in (None, ""):
            params[rname] = flagged
        elif str(pdef.get("type") or "").lower() in {"switch", "boolean", "bool"}:
            off_value = next((o for o in ropts if str(o).strip().lower() in {"false", "0", "off", "no"}), None)
            params[rname] = off_value if off_value not in (None, "") else ropts[0]
        elif "auto" in [str(o).lower() for o in ropts]:
            params[rname] = next(o for o in ropts if str(o).lower() == "auto")
        else:
            params[rname] = ropts[len(ropts) // 2]
    return params


_MODEL_REMAP_CACHE = {"data": None}
def _load_model_remap():
    if _MODEL_REMAP_CACHE["data"] is None:
        try:
            import os, json as _json
            p = os.path.join(os.path.dirname(os.path.abspath(__file__)), "model_remap.json")
            with open(p, "r", encoding="utf-8") as f:
                _MODEL_REMAP_CACHE["data"] = _json.load(f) or {}
        except Exception:
            _MODEL_REMAP_CACHE["data"] = {}
    return _MODEL_REMAP_CACHE["data"]

def _apply_model_remap(model):
    """死模型id→网关活替身id；无替身或未知则原样返回。"""
    m = str(model or "").strip()
    if not m:
        return m
    if m in ("doubao-seedance-2-0-260128", "doubao-seedance-2-0-fast-260128", "doubao-seedance-2-0-mini-260615"):
        return m
    entry = _load_model_remap().get(m)
    if isinstance(entry, dict):
        rep = str(entry.get("replacement") or "").strip()
        if rep and rep.lower() not in ("no_replacement", "none", "null"):
            return rep
    return m


def _classify_apimart_media(api_url, data, api_gateway_cfg):
    path = _url_path(api_url).lower()
    payload = dict(data or {})
    task_id = _extract_proxy_task_id(payload)
    m = re.search(r"/v[12]/videos/generations/([^/?]+)", path, flags=re.IGNORECASE)
    if m:
        task_id = task_id or urllib.parse.unquote(m.group(1))
    is_video = bool(re.search(r"/v[12]/videos/generations(?:/|$)", path) or "videos/generations" in path)
    is_image = bool(
        re.search(r"/v1/draw/(?:completions|nano-banana)(?:$|[/?])", path)
        or re.search(r"/v1/images/generations(?:/|$)", path)
        or "images/generations" in path
        or "/v3/seedream-" in path
    )
    base = str(api_gateway_cfg.get("apiUrl") or "")
    key = str(api_gateway_cfg.get("apiKey") or "")
    if is_video:
        if task_id and not payload.get("prompt"):
            payload["__apimart_task_id"] = task_id
            return "video_query", payload, "GET"
        catalog = _apimart_catalog(base, key, "video")
        model = str(payload.get("model") or "").strip()
        model = _apply_model_remap(model)
        # CATALOG-FALLBACK-FIX: 网关列表接口偶尔返回空; catalog 为空时必须保留用户所选模型, 不可强制回退
        if not model:
            model = str(api_gateway_cfg.get("videoModel") or "").strip()
        elif catalog and model not in catalog:
            _fb = str(api_gateway_cfg.get("videoModel") or "").strip()
            if _fb and _fb in catalog:
                model = _fb
        payload["model"] = model
        return "video_create", payload, "POST"
    if is_image:
        catalog = _apimart_catalog(base, key, "image")
        model = str(payload.get("model") or "").strip()
        model = _apply_model_remap(model)
        # CATALOG-FALLBACK-FIX
        if not model:
            model = str(api_gateway_cfg.get("imageModel") or "gpt-image-2").strip()
        elif catalog and model not in catalog:
            _fb = str(api_gateway_cfg.get("imageModel") or "gpt-image-2").strip()
            if _fb and _fb in catalog:
                model = _fb
        payload["model"] = model
        return "image", payload, "POST"
    _aud_model = str(payload.get("model") or "").strip()
    if _aud_model:
        _aud_remap = _apply_model_remap(_aud_model)
        try:
            _aud_cat = _apimart_catalog(base, key, "audio")
        except Exception:
            _aud_cat = set()
        if _aud_cat and (_aud_remap in _aud_cat or _aud_model in _aud_cat):
            payload["model"] = _aud_remap
            return "audio", payload, "POST"
    return None, payload, "POST"


def _handle_proxy_task_get(handler):
    # APIMART-TASK-PROXY: 前端用 /api/v2/proxy/task?apiUrl=.../v1/tasks/{id} 轮询视频, 但网关实为 /v1/skills/task-status
    try:
        from urllib.parse import urlparse as _up, parse_qs as _pq, unquote as _uq
        q = _pq(_up(handler.path).query)
        api_url = _uq((q.get('apiUrl') or [''])[0])
        task_id = (q.get('task_id') or q.get('id') or [''])[0]
        if not task_id:
            mm = re.search(r'/v[12]/tasks/([^/?]+)', api_url)
            task_id = mm.group(1) if mm else ''
        if not task_id:
            mm = re.search(r'[?&]task_id=([^&]+)', api_url)
            task_id = mm.group(1) if mm else ''
        if not task_id:
            _json_err(handler, 400, 'missing task_id'); return True
        # ARK-NATIVE-PATCH: 方舟 task_id 形如 cgt-... 走方舟轮询
        if str(task_id).startswith(ARK_TASK_ID_PREFIX):
            try:
                info = _ark_task_status(task_id)
                _json_ok(handler, _ark_status_envelope(task_id, info))
            except Exception as e:
                _json_err(handler, 502, 'ark task proxy error: %s' % str(e)[:200])
            return True
        cfg = _get_api_gateway_config()
        base = str(cfg.get('apiUrl') or '').strip()
        key = str(cfg.get('apiKey') or '').strip()
        info = _apimart_task_status(base, key, task_id)
        p2 = info.get('data') if isinstance(info.get('data'), dict) else {}
        try:
            url = str(_extract_ai_result_url(info) or '').strip()
        except Exception:
            url = str(info.get('result_url') or p2.get('output') or p2.get('result_url') or info.get('video_url') or '').strip()
        state = str(info.get('state') or '').lower()
        err = info.get('error') or info.get('fail_reason')
        is_final = bool(info.get('is_final')) or bool(url)
        if url:
            out = {'status':'COMPLETED','task_status':'COMPLETED','state':'success','is_final':True,'progress':info.get('progress') or '100','output':url,'url':url,'video_url':url,'videoUrl':url,'fileUrl':url,'results':[{'url':url,'video_url':url,'videoUrl':url}],'task_id':str(task_id)}
        elif is_final or state in ('failed','error') or err:
            msg = str(err or info.get('status') or 'generation failed')
            out = {'status':'FAILED','task_status':'FAILED','state':'failed','is_final':True,'failReason':msg,'failure_reason':msg,'error':msg,'task_id':str(task_id)}
        else:
            out = {'status':'RUNNING','task_status':'RUNNING','state':'running','is_final':False,'progress':info.get('progress') or '','task_id':str(task_id)}
        _json_ok(handler, out)
    except Exception as e:
        err_text = str(e or "").lower()
        if isinstance(e, (TimeoutError, socket.timeout)) or "timed out" in err_text or "timeout" in err_text:
            _json_ok(
                handler,
                {
                    "status": "RUNNING",
                    "task_status": "RUNNING",
                    "state": "running",
                    "is_final": False,
                    "progress": "",
                    "task_id": str(task_id or ""),
                    "warning": "upstream timeout, retry later",
                },
            )
        else:
            _json_err(handler, 502, 'task proxy error: %s' % str(e)[:200])
    return True


def _apimart_task_status(base, key, task_id):
    return _apimart_json_request(
        base, key,
        "/v1/skills/task-status?task_id=" + urllib.parse.quote(str(task_id), safe=""),
        None, 30)


def _apimart_status_envelope(task_id, info):
    payload = info.get("data") if isinstance(info.get("data"), dict) else {}
    try:
        url = str(_extract_ai_result_url(info) or "").strip()
    except Exception:
        url = str(info.get("result_url") or payload.get("output") or payload.get("result_url") or "").strip()
    raw_status = str(info.get("status") or "")
    final = bool(info.get("is_final")) or bool(url)
    if url:
        status = "SUCCESS"
    elif final:
        status = "FAILURE"
    elif raw_status in (u"等待中", u"排队中", ""):
        status = "NOT_START"
    else:
        status = "RUNNING"
    fail_reason = ""
    if status == "FAILURE":
        fail_reason = str(info.get("error") or "") or raw_status or u"生成失败"
    return {
        "task_id": str(task_id),
        "status": status,
        "progress": info.get("progress"),
        "data": {"output": url},
        "url": url,
        "video_url": url,
        "fail_reason": fail_reason,
    }


def _api_gateway_image_task_result(task_id, api_gateway_cfg, api_key, timeout_sec=280):
    base = str(api_gateway_cfg.get("apiUrl") or "").strip()
    key = str(api_key or api_gateway_cfg.get("apiKey") or "").strip()
    deadline = time.time() + float(timeout_sec or 280)
    last_status = ""
    while time.time() < deadline:
        envelope = _apimart_status_envelope(task_id, _apimart_task_status(base, key, task_id))
        last_status = str(envelope.get("status") or "")
        if last_status == "SUCCESS":
            url = str(envelope.get("url") or "").strip()
            return {
                "created": int(time.time()),
                "data": [{"url": url}],
                "images": [url],
                "url": url,
                "task_id": str(task_id),
                "status": "succeeded",
            }
        if last_status == "FAILURE":
            raise RuntimeError(envelope.get("fail_reason") or "generation failed")
        time.sleep(5)
    raise RuntimeError("Gateway image task timeout (%ss, last=%s)" % (timeout_sec, last_status or "unknown"))


# ===== ARK-NATIVE-PATCH 开始 (2026-06-28) =====
# All three Seedance 2.0 official models use Ark native API.
# Keep reference image/video/audio input; do not fall back to old first/last-frame route.
ARK_NATIVE_MODELS = {
    "doubao-seedance-2-0-260128",
    "doubao-seedance-2-0-fast-260128",
    "doubao-seedance-2-0-mini-260615",
}
ARK_BASE_URL = "https://ark.cn-beijing.volces.com/api/v3"
ARK_TASK_ID_PREFIX = "cgt-"


def _ark_api_key():
    return (os.environ.get("ARK_API_KEY") or "").strip()


def _ark_should_route(model):
    return str(model or "").strip() in ARK_NATIVE_MODELS


def _ark_ratio_from_data(data):
    d = data if isinstance(data, dict) else {}
    for key in ("ratio", "aspect_ratio", "aspectRatio"):
        v = _normalize_aspect_ratio_value(d.get(key))
        if v:
            return v
    for key in ("videoSize", "size"):
        v = _normalize_aspect_ratio_value(d.get(key))
        if _looks_like_ratio(v):
            return v
    v = _video_ratio_from_dimensions(d)
    if v:
        return v
    try:
        w = float(d.get("width"))
        h = float(d.get("height"))
    except (TypeError, ValueError):
        return ""
    if w <= 0 or h <= 0:
        return ""
    return _normalize_aspect_ratio_value(f"{w}:{h}")


def _ark_json_request(path, payload=None, method=None, timeout=60):
    key = _ark_api_key()
    if not key:
        raise RuntimeError("ARK_API_KEY not configured")
    url = ARK_BASE_URL + path
    headers = {"Authorization": "Bearer " + key, "Content-Type": "application/json", "User-Agent": "Mozilla/5.0"}
    body = json.dumps(payload).encode("utf-8") if payload is not None else None
    m = method or ("POST" if body is not None else "GET")
    req = urllib.request.Request(url, data=body, headers=headers, method=m)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            return json.loads(resp.read().decode("utf-8", "replace"))
    except urllib.error.HTTPError as e:
        try:
            err_body = e.read().decode("utf-8", "replace")
        except Exception:
            err_body = ""
        raise RuntimeError("ark %s %s: %s" % (e.code, e.reason, err_body[:300]))


def _ark_publicize_audio_ref(ref):
    ref = str(ref or "").strip()
    if not ref:
        return ""
    try:
        return _apimart_publicize_ref(ref) or ref
    except Exception:
        return ref


def _ark_build_content(prompt, data):
    """Build Ark official content[] with text plus reference image/video/audio items."""
    content = []
    if prompt:
        content.append({"type": "text", "text": prompt})
    refs = []
    for key in (
        "images",
        "image_urls",
        "imageUrls",
        "inputUrls",
        "reference_image_urls",
        "referenceImageUrls",
        "action_flow_images",
        "actionFlowImages",
        "character_reference_images",
        "scene_reference_images",
        "prop_reference_images",
        "subject_reference_images",
        "additional_reference_images",
        "strict_reference_image_urls",
    ):
        _extend_url_list(refs, (data or {}).get(key))
    _extend_url_list(refs, (data or {}).get("image_with_roles"))
    for key in ("first", "first_frame", "firstFrameUrl", "last", "last_frame", "lastFrameUrl", "imageUrl", "image_url"):
        _extend_url_list(refs, (data or {}).get(key))
    public_refs = []
    for ref in _dedupe_urls(refs):
        public_ref = _apimart_publicize_ref(ref)
        if public_ref and public_ref not in public_refs:
            public_refs.append(public_ref)
    for ref in public_refs[:9]:
        content.append({"type": "image_url", "image_url": {"url": ref}, "role": "reference_image"})

    seen_video_refs = set()
    for key in ("reference_video", "referenceVideo", "reference_video_url", "referenceVideoUrl", "video_url", "videoUrl"):
        url = _media_url_from_value((data or {}).get(key))
        if url and url not in seen_video_refs:
            seen_video_refs.add(url)
            content.append({"type": "video_url", "video_url": {"url": url}, "role": "reference_video"})
    for key in ("reference_video_urls", "video_urls", "videos"):
        for value in (data or {}).get(key) or []:
            url = _media_url_from_value(value)
            if url and url not in seen_video_refs:
                seen_video_refs.add(url)
                content.append({"type": "video_url", "video_url": {"url": url}, "role": "reference_video"})

    audio_refs = []
    for key in ("reference_audio", "referenceAudio", "reference_audio_url", "referenceAudioUrl", "audio_url", "audioUrl", "voiceAudioUrl", "voice_audio_url", "subjectAudioUrl", "subject_audio_url"):
        _extend_url_list(audio_refs, (data or {}).get(key))
    for key in ("reference_audio_urls", "audio_urls", "voice_audio_urls", "subject_audio_urls", "audios"):
        for value in (data or {}).get(key) or []:
            _extend_url_list(audio_refs, value)
    seen_audio_refs = set()
    for ref in _dedupe_urls(audio_refs):
        url = _ark_publicize_audio_ref(ref)
        if url and url not in seen_audio_refs:
            seen_audio_refs.add(url)
            content.append({"type": "audio_url", "audio_url": {"url": url}, "role": "reference_audio"})
    return content

def _ark_build_create_payload(data):
    d = _normalize_video_size_keys(dict(data or {}))
    _normalize_ratio_key(d)
    model = str(d.get("model") or "").strip()
    prompt = str(d.get("prompt") or "").strip()
    payload = {"model": model, "content": _ark_build_content(prompt, d)}
    has_reference_media = any(
        isinstance(item, dict) and item.get("type") in {"image_url", "video_url"}
        for item in payload.get("content", [])
    )
    # 顶层可选参数（方舟原生 schema）
    ratio = _ark_ratio_from_data(d)
    if ratio:
        payload["ratio"] = ratio
    resolution = str(d.get("resolution") or d.get("imageSize") or "").strip()
    if resolution and not (model == "doubao-seedance-2-0-mini-260615" and has_reference_media):
        payload["resolution"] = resolution
    for src in ("duration", "video_duration", "seconds"):
        v = d.get(src)
        if v not in (None, ""):
            try:
                payload["duration"] = int(v); break
            except (TypeError, ValueError):
                pass
    if payload.get("duration") not in range(5, 16):
        payload["duration"] = 5
    if "generate_audio" in d:
        payload["generate_audio"] = bool(d.get("generate_audio"))
    elif _aic_collect_audio_refs(d):
        payload["generate_audio"] = True
    if "watermark" in d:
        payload["watermark"] = bool(d.get("watermark"))
    if "seed" in d:
        try:
            payload["seed"] = int(d.get("seed"))
        except (TypeError, ValueError):
            pass
    return payload


def _ark_create_video(data):
    payload = _ark_build_create_payload(data)
    try:
        resp = _ark_json_request("/contents/generations/tasks", payload, "POST", 60)
    except RuntimeError as exc:
        has_ref = any(
            isinstance(item, dict) and item.get("type") in {"image_url", "video_url"}
            for item in payload.get("content", [])
        )
        if payload.get("ratio") and has_ref and "ratio" in str(exc).lower():
            # ponytail: older Ark r2v routes rejected ratio+reference; keep that path as a one-shot fallback.
            fallback_payload = dict(payload)
            fallback_payload.pop("ratio", None)
            resp = _ark_json_request("/contents/generations/tasks", fallback_payload, "POST", 60)
        else:
            raise
    task_id = str(resp.get("id") or "").strip()
    if not task_id:
        raise RuntimeError("ark no task id: %s" % str(resp)[:200])
    return task_id


def _ark_task_status(task_id):
    return _ark_json_request("/contents/generations/tasks/" + urllib.parse.quote(str(task_id), safe=""), None, "GET", 30)


def _ark_extract_video_url(info):
    if isinstance(info, dict):
        for key in ("video_url", "videoUrl", "audio_url", "audioUrl", "result_url", "output", "url", "fileUrl", "file_url", "media_url", "download_url"):
            value = info.get(key)
            if isinstance(value, str) and value.strip():
                return value.strip()
        for key in ("content", "data", "result", "results", "outputs"):
            value = _ark_extract_video_url(info.get(key))
            if value:
                return value
    if isinstance(info, list):
        for item in info:
            value = _ark_extract_video_url(item)
            if value:
                return value
    return ""


def _ark_status_value(info):
    if not isinstance(info, dict):
        return ""
    for key in ("status", "state", "task_status"):
        value = str(info.get(key) or "").strip().lower()
        if value:
            return value
    data = info.get("data") if isinstance(info.get("data"), dict) else {}
    return str(data.get("status") or data.get("state") or "").strip().lower()


def _ark_status_envelope(task_id, info):
    """翻译方舟返回到现有前端 envelope 形状（兼容 apimart 那套）。"""
    info = info or {}
    raw_status = _ark_status_value(info)
    url = _ark_extract_video_url(info)
    if raw_status in ("succeeded", "success", "completed", "complete", "done") or url:
        status = "SUCCESS"
    elif raw_status in ("failed", "failure", "error", "expired", "cancelled", "canceled"):
        status = "FAILURE"
    elif raw_status in ("queued", ""):
        status = "NOT_START"
    else:
        status = "RUNNING"
    fail_reason = ""
    if status == "FAILURE":
        err = info.get("error") or {}
        fail_reason = str((err or {}).get("message") if isinstance(err, dict) else err) or raw_status or u"生成失败"
    return {
        "task_id": str(task_id),
        "status": status,
        "progress": "100" if status == "SUCCESS" else "",
        "data": {"output": url},
        "url": url,
        "video_url": url,
        "fail_reason": fail_reason,
    }


def _ark_task_envelope_for_proxy(task_id):
    """供 /api/v2/proxy/task GET 入口使用，输出与 _handle_proxy_task_get 同形状。"""
    info = _ark_task_status(task_id)
    raw_status = _ark_status_value(info)
    url = _ark_extract_video_url(info)
    if url or raw_status in ("succeeded", "success", "completed", "complete", "done"):
        return {
            "status": "COMPLETED", "task_status": "COMPLETED", "state": "success",
            "is_final": True, "progress": "100",
            "output": url, "url": url, "video_url": url, "videoUrl": url, "fileUrl": url,
            "results": [{"url": url, "video_url": url, "videoUrl": url}],
            "task_id": str(task_id),
        }
    if raw_status in ("failed", "failure", "error", "expired", "cancelled", "canceled"):
        err = info.get("error") or {}
        msg = str((err or {}).get("message") if isinstance(err, dict) else err) or raw_status or "generation failed"
        return {
            "status": "FAILED", "task_status": "FAILED", "state": "failed",
            "is_final": True, "failReason": msg, "failure_reason": msg, "error": msg,
            "task_id": str(task_id),
        }
    return {
        "status": "RUNNING", "task_status": "RUNNING", "state": "running",
        "is_final": False, "progress": "", "task_id": str(task_id),
    }
# ===== ARK-NATIVE-PATCH 结束 =====


# ===== PANORAMA-360-PATCH 开始 =====
PANORAMA_GENERATE_PATH = "/api/v2/panorama/generate"


def _handle_panorama_generate(handler, path):
    """POST /api/v2/panorama/generate
    body: {"prompt": "<场景描述>", "image_url": "<可选参考图URL>"}
    用图像模型 + 2:1/equirectangular 提示词生成360全景图,
    轮询到完成后返回 {"success":true,"url":"http...png"}。
    复用画布会话鉴权 (同 chat-stream)。
    """
    if path != PANORAMA_GENERATE_PATH:
        return False

    user_id = _assistant_resolve_user_id(handler)
    if user_id <= 0:
        _json_err(handler, 401, u"请先从平台进入画布")
        return True

    try:
        data = json.loads(_read_body(handler) or b"{}")
    except Exception:
        data = {}
    if not isinstance(data, dict):
        data = {}

    user_prompt = str(data.get("prompt") or "").strip()
    if not user_prompt:
        _json_err(handler, 400, u"缺少场景描述 prompt")
        return True
    image_url = str(data.get("image_url") or "").strip()

    # AIC-PANO-HIRES: 强等距全景提示词(gemini 对此跟随更好)
    prompt = (
        "A 360 degree equirectangular VR panorama photo, full spherical projection, "
        "2:1 aspect ratio, the horizon is a straight horizontal line across the vertical center, "
        "seamless wrap so the left and right edges connect continuously, monoscopic 360 photosphere. "
        "Scene all around the viewer: " + user_prompt +
        ". Equirectangular projection, immersive surroundings in every direction, ultra high detail, no text, no watermark"
    )

    cfg = _get_api_gateway_config()
    base = str(cfg.get("apiUrl") or "").strip()
    key = str(cfg.get("apiKey") or "").strip()
    if not base or not key:
        _json_err(handler, 502, u"全景生成失败: 网关未配置")
        return True

    model = "gemini-3-pro-image-preview"  # AIC-PANO-HIRES: 4K 真等距全景
    refs = []
    if image_url:
        refs = [_apimart_publicize_ref(image_url)]
        refs = [r for r in refs if r]

    try:
        params = _apimart_media_params(
            base, key, model, prompt, refs, {"ratio": "2:1", "quality": "high"}
        )
    except Exception:
        params = {}
    if not isinstance(params, dict):
        params = {}
    # AIC-IMG2PANO: 强制把参考图塞进 images (图生图真正生效; 不依赖隐式路由)
    if refs:
        params["images"] = refs
    # AIC-PANO-HIRES: gemini 4K + 21:9(最接近且>2:1, 留全360°), 去掉 gpt 的 size
    params.pop("size", None)
    params["imageSize"] = "2K"  # AIC-PANO-LIGHT: 4K太吃内存, 2K够清晰
    params["aspectRatio"] = "21:9"

    try:
        payload = {"model": model, "prompt": prompt, "params": params, "count": 1}
        created = _apimart_json_request(base, key, "/v1/media/generate", payload, 60)
        if str(created.get("code")) != "200":
            raise RuntimeError(str(created.get("msg") or created)[:300])
        info0 = created.get("data") if isinstance(created.get("data"), dict) else {}
        task_id = info0.get("task_id") or created.get("task_id")
        if not task_id:
            raise RuntimeError("no task_id: %s" % str(created)[:200])
    except Exception as e:
        _json_err(handler, 502, u"全景生成失败: %s" % str(e)[:300])
        return True

    try:
        for _ in range(25):
            time.sleep(5)
            envelope = _apimart_status_envelope(
                task_id, _apimart_task_status(base, key, task_id)
            )
            if envelope.get("status") == "SUCCESS" and envelope.get("url"):
                _img_url = envelope["url"]
                _data_uri = None
                try:
                    import urllib.request as _ur, base64 as _b64
                    _rq = _ur.Request(_img_url, headers={"User-Agent": "Mozilla/5.0"})
                    with _ur.urlopen(_rq, timeout=60) as _rp:
                        _raw = _rp.read(); _ct = _rp.headers.get("Content-Type") or "image/png"
                    # AIC-IMG2PANO: gpt-image-2 最宽只给 16:9, 中心裁成真 2:1 等距全景 (PIL 已装)
                    try:
                        import io as _io
                        from PIL import Image as _PImage
                        _im = _PImage.open(_io.BytesIO(_raw))
                        if _im.mode not in ("RGB", "L"):
                            _im = _im.convert("RGB")
                        _w, _h = _im.size
                        # AIC-PANO-HIRES: 统一成 2:1(宽上限4096), 缩放不裁宽 -> 保住完整360°避免接缝
                        # AIC-PANO-LIGHT: 上限3072 + JPEG(防大图OOM)
                        _ow = min(_w, 3072) if _w >= 2 else _w
                        _im = _im.resize((_ow, max(1, _ow // 2)))
                        if _im.mode not in ("RGB", "L"):
                            _im = _im.convert("RGB")
                        _ob = _io.BytesIO(); _im.save(_ob, format="JPEG", quality=88, optimize=True)
                        _raw = _ob.getvalue(); _ct = "image/jpeg"
                    except Exception:
                        pass
                    _data_uri = "data:" + _ct + ";base64," + _b64.b64encode(_raw).decode("ascii")
                except Exception:
                    _data_uri = None
                _json_ok(handler, {"success": True, "url": _img_url, "dataUri": _data_uri})
                return True
            if envelope.get("status") == "FAILURE":
                raise RuntimeError(envelope.get("fail_reason") or u"生成失败")
        raise RuntimeError(u"轮询超时 (125s)")
    except Exception as e:
        _json_err(handler, 502, u"全景生成失败: %s" % str(e)[:300])
        return True
# ===== PANORAMA-360-PATCH 结束 =====


def _handle_apimart_media_proxy(handler, kind, data, api_gateway_cfg, api_key, billing_ctx):
    base = str(api_gateway_cfg.get("apiUrl") or "").strip()
    key = str(api_key or api_gateway_cfg.get("apiKey") or "").strip()
    try:
        if kind == "video_query":
            task_id = str(data.get("__apimart_task_id") or "")
            info = _apimart_task_status(base, key, task_id)
            _json_ok(handler, _apimart_status_envelope(task_id, info))
            return
        model = str(data.get("model") or "").strip()
        prompt = str(data.get("prompt") or "").strip()
        refs = _apimart_collect_refs(data)
        refs = [_apimart_publicize_ref(r) for r in refs]
        refs = [r for r in refs if r]
        params = _apimart_media_params(base, key, model, prompt, refs, data)
        payload = {"model": model, "prompt": prompt, "params": params}
        if kind == "image":
            payload["count"] = 1
        try:
            print(json.dumps({"event":"apimart_media_submit","kind":kind,"model":model,"param_keys":list(params.keys()),"images":params.get("images") or params.get("image") or params.get("input_image") or params.get("image_url")}, ensure_ascii=False), flush=True)
        except Exception:
            pass
        created = _apimart_json_request(base, key, "/v1/media/generate", payload, 60)
        if str(created.get("code")) != "200":
            raise RuntimeError(str(created.get("msg") or created)[:300])
    except Exception as e:
        _refund_canvas_model_call(billing_ctx, u"云灵AI漫剧画布媒体生成失败退款：%s" % str(e)[:120])
        _json_err(handler, 502, "Gateway media proxy error: %s" % str(e)[:300])
        return
    try:
        info = created.get("data") if isinstance(created.get("data"), dict) else {}
        task_id = info.get("task_id") or created.get("task_id")
        if not task_id:
            raise RuntimeError("Gateway no task_id: %s" % str(created)[:200])
        if kind == "video_create":
            _json_ok(handler, {"task_id": str(task_id), "status": "submitted", "source": "gateway"})
            return
        deadline = time.time() + 280
        while time.time() < deadline:
            time.sleep(5)
            envelope = _apimart_status_envelope(task_id, _apimart_task_status(base, key, task_id))
            if envelope["status"] == "SUCCESS":
                _json_ok(handler, {"created": int(time.time()), "data": [{"url": envelope["url"]}], "task_id": str(task_id)})
                return
            if envelope["status"] == "FAILURE":
                raise RuntimeError(envelope.get("fail_reason") or u"生成失败")
        raise RuntimeError("Gateway image task timeout (280s)")
    except Exception as e:
        _refund_canvas_model_call(billing_ctx, u"云灵AI漫剧画布媒体生成失败退款：%s" % str(e)[:120])
        _json_err(handler, 502, "Gateway media proxy error: %s" % str(e)[:300])
# ===== APIMART-PROXY-PATCH 结束 =====


def _prepare_api_gateway_media_proxy(api_url, data, api_gateway_cfg):
    base_url = str(api_gateway_cfg.get("apiUrl") or "").strip().rstrip("/")
    original_path = _url_path(api_url)
    path_lower = original_path.lower()
    task_id = _extract_proxy_task_id(data)
    match = re.search(r"/v[12]/videos/generations/([^/?]+)", original_path, flags=re.IGNORECASE)
    if match:
        task_id = task_id or urllib.parse.unquote(match.group(1))

    is_video_endpoint = bool(
        re.search(r"/v[12]/videos/generations(?:/|$)", path_lower)
        or "videos/generations" in path_lower
    )
    is_image_endpoint = bool(
        re.search(r"/v1/draw/(?:completions|nano-banana)(?:$|[/?])", path_lower)
        or re.search(r"/v1/images/generations(?:/|$)", path_lower)
        or "images/generations" in path_lower
        or "/v3/seedream-" in path_lower
    )

    if is_video_endpoint:
        if task_id and not data.get("prompt"):
            return (
                _join_versioned_api_path(base_url, f"/v2/videos/generations/{urllib.parse.quote(task_id, safe='')}"),
                "GET",
                {},
            )
        return (
            _join_versioned_api_path(base_url, "/v1/media/generate"),
            "POST",
            _adapt_api_gateway_video_payload(data, api_gateway_cfg),
        )

    if is_image_endpoint:
        return (
            _join_versioned_api_path(base_url, "/v1/media/generate"),
            "POST",
            _adapt_api_gateway_image_payload(data, api_gateway_cfg),
        )

    return api_url, "POST", data


def _request_server_port(handler):
    try:
        return int(handler.server.server_address[1])
    except Exception:
        return int(PORT)


def _request_host_origin(handler):
    host = str(handler.headers.get("Host", "") or "").strip()
    if not host:
        return ""
    proto = str(handler.headers.get("X-Forwarded-Proto", "") or "").split(",", 1)[0].strip().lower()
    if proto not in ("http", "https"):
        proto = "http"
    return _normalize_origin(f"{proto}://{host}")


def _local_allowed_origins(handler):
    port = _request_server_port(handler)
    # AIC_PUBLIC_CANVAS_ORIGINS: allow the deployed Yunling Canvas page to load its own config APIs.
    return {
        f"http://127.0.0.1:{port}",
        f"http://localhost:{port}",
        f"http://[::1]:{port}",
        "http://120.26.194.174",
        "https://120.26.194.174",
        "http://120.26.194.174:8777",
        "https://120.26.194.174:8777",
    }


def _is_allowed_origin(handler, origin):
    normalized = _normalize_origin(origin)
    if not normalized:
        return False
    return normalized in _local_allowed_origins(handler) or normalized in ALLOWED_ORIGINS


def _allowed_cors_origin(handler):
    origin = handler.headers.get("Origin", "")
    normalized = _normalize_origin(origin)
    if normalized and _is_allowed_origin(handler, normalized):
        return normalized
    return ""


def _send_cors_origin_header(handler):
    origin = _allowed_cors_origin(handler)
    if not origin:
        return
    handler.send_header("Access-Control-Allow-Origin", origin)
    handler.send_header("Vary", "Origin")


def _client_is_loopback(handler):
    try:
        host = str(handler.client_address[0] or "").strip()
    except Exception:
        return False
    if host in ("localhost",):
        return True
    try:
        return ipaddress.ip_address(host).is_loopback
    except Exception:
        return False


def _request_has_valid_local_token(handler):
    if not LOCAL_ACCESS_TOKEN:
        return False
    token = str(handler.headers.get("X-AIC-Local-Token", "") or "").strip()
    auth = str(handler.headers.get("Authorization", "") or "").strip()
    if not token and auth.lower().startswith("bearer "):
        token = auth[7:].strip()
    return bool(token) and hmac.compare_digest(token, LOCAL_ACCESS_TOKEN)


def _b64url_encode(raw):
    return base64.urlsafe_b64encode(raw).rstrip(b"=").decode("ascii")


def _b64url_decode(value):
    text = str(value or "")
    padding = "=" * (-len(text) % 4)
    return base64.urlsafe_b64decode((text + padding).encode("ascii"))


def _parse_cookie_header(handler):
    raw = str(handler.headers.get("Cookie", "") or "")
    cookies = {}
    for part in raw.split(";"):
        if "=" not in part:
            continue
        name, value = part.split("=", 1)
        name = name.strip()
        if name:
            cookies[name] = urllib.parse.unquote(value.strip())
    return cookies


def _sign_canvas_session_payload(payload):
    body = _b64url_encode(
        json.dumps(payload, ensure_ascii=False, separators=(",", ":"), sort_keys=True).encode("utf-8")
    )
    sig = hmac.new(
        AICANVAS_SESSION_SECRET.encode("utf-8"),
        body.encode("ascii"),
        hashlib.sha256,
    ).digest()
    return f"{body}.{_b64url_encode(sig)}"


def _decode_canvas_session_token(token):
    raw = str(token or "").strip()
    if "." not in raw:
        return None
    body, sig = raw.rsplit(".", 1)
    expected_sig = _b64url_encode(
        hmac.new(
            AICANVAS_SESSION_SECRET.encode("utf-8"),
            body.encode("ascii"),
            hashlib.sha256,
        ).digest()
    )
    if not hmac.compare_digest(sig, expected_sig):
        return None
    try:
        payload = json.loads(_b64url_decode(body).decode("utf-8"))
    except Exception:
        return None
    try:
        if int(payload.get("exp") or 0) < int(time.time()):
            return None
    except Exception:
        return None
    return payload if isinstance(payload, dict) else None


def _store_platform_session_token(token, exp, session_id=None):
    token = str(token or "").strip()
    if not token:
        return ""
    try:
        expires_at = int(exp)
    except Exception:
        expires_at = int(time.time()) + int(AICANVAS_SESSION_TTL_SECONDS)
    session_id = str(session_id or "").strip() or secrets.token_urlsafe(24)
    now = int(time.time())
    with _platform_session_tokens_lock:
        for key, item in list(_platform_session_tokens.items()):
            try:
                if int(item.get("exp") or 0) <= now:
                    _platform_session_tokens.pop(key, None)
            except Exception:
                _platform_session_tokens.pop(key, None)
        _platform_session_tokens[session_id] = {"token": token, "exp": expires_at}
    return session_id


def _load_platform_session_token(session_id):
    session_id = str(session_id or "").strip()
    if not session_id:
        return ""
    now = int(time.time())
    with _platform_session_tokens_lock:
        item = _platform_session_tokens.get(session_id)
        if not isinstance(item, dict):
            return ""
        try:
            if int(item.get("exp") or 0) <= now:
                _platform_session_tokens.pop(session_id, None)
                return ""
        except Exception:
            _platform_session_tokens.pop(session_id, None)
            return ""
        return str(item.get("token") or "").strip()


def _make_canvas_session_token(user):
    user = user if isinstance(user, dict) else {}
    user_id = user.get("user_id") or user.get("id")
    now = int(time.time())
    session_ttl = int(AICANVAS_SESSION_TTL_SECONDS)
    if str(user.get("auth_source") or "").strip() == "matrix_sso":
        session_ttl = int(AICANVAS_MATRIX_SESSION_TTL_SECONDS)
    payload = {
        "user_id": int(user_id),
        "nickname": str(user.get("nickname") or user.get("username") or user.get("phone") or ""),
        "avatar": str(user.get("avatar") or ""),
        "iat": now,
        "exp": now + session_ttl,
    }
    platform_session_id = str(user.get("platform_session_id") or "").strip()
    if platform_session_id:
        payload["platform_session_id"] = platform_session_id
    if user.get("local_password_login"):
        payload["local_password_login"] = True
        payload["username"] = str(user.get("username") or payload["nickname"] or "")
    if str(user.get("auth_source") or "").strip() == "matrix_sso":
        payload["auth_source"] = "matrix_sso"
        payload["matrix_org_id"] = str(user.get("matrix_org_id") or "")[:128]
    return _sign_canvas_session_payload(payload)


def _session_cookie_header(token="", clear=False, max_age=None):
    if clear:
        return f"{AICANVAS_SESSION_COOKIE}=; Path=/; Max-Age=0; HttpOnly; SameSite=Lax"
    cookie_max_age = int(max_age or AICANVAS_SESSION_TTL_SECONDS)
    return (
        f"{AICANVAS_SESSION_COOKIE}={urllib.parse.quote(str(token or ''))}; "
        f"Path=/; Max-Age={cookie_max_age}; HttpOnly; SameSite=Lax"
    )


class _MatrixSsoExchangeError(RuntimeError):
    def __init__(self, code, status=401):
        self.code = str(code or "matrix_sso_exchange_failed")
        self.status = int(status or 401)
        super().__init__(self.code)


def _consume_matrix_sso_ticket(ticket_id, expires_at, now_ts=None):
    current = int(time.time() if now_ts is None else now_ts)
    ticket_id = str(ticket_id or "").strip()
    with _matrix_sso_replay_lock:
        for existing_id, existing_expiry in list(_matrix_sso_consumed_tickets.items()):
            if int(existing_expiry or 0) <= current:
                _matrix_sso_consumed_tickets.pop(existing_id, None)
        if ticket_id in _matrix_sso_consumed_tickets:
            return False
        _matrix_sso_consumed_tickets[ticket_id] = int(expires_at)
    return True


def _exchange_matrix_sso_ticket(ticket, now_ts=None):
    if not AICANVAS_MATRIX_SSO_ENABLED:
        raise _MatrixSsoExchangeError("matrix_sso_disabled", 503)
    if len(AICANVAS_MATRIX_SSO_SECRET.encode("utf-8")) < 32:
        raise _MatrixSsoExchangeError("matrix_sso_secret_missing", 503)
    try:
        claims = verify_matrix_sso_ticket(
            ticket,
            secret=AICANVAS_MATRIX_SSO_SECRET,
            issuer=AICANVAS_MATRIX_SSO_ISSUER,
            audience=AICANVAS_MATRIX_SSO_AUDIENCE,
            now=now_ts,
            max_ttl_seconds=AICANVAS_MATRIX_SSO_MAX_TTL_SECONDS,
        )
    except MatrixSsoError as exc:
        raise _MatrixSsoExchangeError(exc.code, 401) from exc
    if not _consume_matrix_sso_ticket(claims.get("jti"), claims.get("exp"), now_ts=now_ts):
        raise _MatrixSsoExchangeError("matrix_sso_ticket_replayed", 409)
    user = {
        "user_id": int(claims["user_id"]),
        "id": int(claims["user_id"]),
        "nickname": str(claims.get("name") or ""),
        "avatar": "",
        "auth_source": "matrix_sso",
        "matrix_org_id": str(claims.get("org_id") or ""),
    }
    token = _make_canvas_session_token(user)
    payload = _canvas_session_login_payload({}, token, user)
    payload.update({
        "source": "matrix_sso",
        "expires_in": int(AICANVAS_MATRIX_SESSION_TTL_SECONDS),
    })
    return token, payload, user


def _canvas_session_cookie_token(cookies):
    cookies = cookies if isinstance(cookies, dict) else {}
    return cookies.get(AICANVAS_SESSION_COOKIE) or cookies.get(AICANVAS_LEGACY_SESSION_COOKIE)


def _canvas_session_request_token(handler):
    headers = getattr(handler, "headers", {})
    bearer = _bearer_token_from_authorization(headers.get("Authorization"))
    cookies = _parse_cookie_header(handler)
    for token in (_canvas_session_cookie_token(cookies), bearer):  # cookie优先，bearer兜底
        if isinstance(_decode_canvas_session_token(token), dict):
            return token
    return ""


def _get_canvas_session_payload(handler):
    return _decode_canvas_session_token(_canvas_session_request_token(handler))


def _canvas_session_bearer_payload(handler):
    headers = getattr(handler, "headers", {})
    bearer = _bearer_token_from_authorization(headers.get("Authorization"))
    payload = _decode_canvas_session_token(bearer)
    return payload if isinstance(payload, dict) else None


def _bearer_token_from_authorization(value):
    value = str(value or "").strip()
    if not value.lower().startswith("bearer "):
        return ""
    return value.split(" ", 1)[1].strip()


def _local_password_login_session_payload(handler):
    headers = getattr(handler, "headers", {})
    bearer = _bearer_token_from_authorization(headers.get("Authorization"))
    cookies = _parse_cookie_header(handler)
    for token in (_canvas_session_cookie_token(cookies), bearer):
        payload = _decode_canvas_session_token(token)
        if isinstance(payload, dict) and payload.get("local_password_login"):
            return payload
    return None


def _has_local_password_login_session(handler):
    return bool(_local_password_login_session_payload(handler))


def _platform_url(path):
    base = AICANVAS_PLATFORM_API_BASE
    if not base:
        return ""
    return f"{base}/{str(path or '').lstrip('/')}"


def _parse_platform_json(raw):
    text = raw.decode("utf-8", errors="ignore") if isinstance(raw, (bytes, bytearray)) else str(raw or "")
    if not text:
        return {}
    try:
        return json.loads(text)
    except Exception:
        return {"raw": text}


def _is_file_descriptor_exhaustion_error(error):
    text = repr(error)
    lowered = text.lower()
    return (
        "too many open files" in lowered
        or "oserror(24" in lowered
        or "errno 24" in lowered
    )


def _platform_json_request(path, payload=None, method="POST", include_internal_secret=True, timeout=30):
    url = _platform_url(path)
    if not url:
        return 500, {"detail": "AICANVAS_PLATFORM_API_BASE is not configured"}
    headers = {
        "Content-Type": "application/json",
        "User-Agent": "Yunling-AI-CanvasPro/1.0",
        "Connection": "close",
    }
    if include_internal_secret and AICANVAS_INTERNAL_SECRET:
        headers["X-AICanvas-Internal-Secret"] = AICANVAS_INTERNAL_SECRET
    data = None
    if payload is not None:
        data = json.dumps(payload, ensure_ascii=False).encode("utf-8")
    req = urllib.request.Request(url, data=data, headers=headers, method=method)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            return int(resp.status), _parse_platform_json(resp.read())
    except urllib.error.HTTPError as e:
        return int(e.code), _parse_platform_json(e.read())
    except Exception as e:
        if _is_file_descriptor_exhaustion_error(e):
            _json_log(
                "platform_json_request_fd_exhausted",
                path=str(path or ""),
                method=str(method or "POST").upper(),
                timeout=timeout,
            )
            return 503, {
                "code": "platform_fd_exhausted",
                "detail": "远程平台连接资源耗尽，视频生成暂时不可用；请稍后重试，如连续出现需重启远程漫剧服务并检查句柄泄漏。",
            }
        _json_log(
            "platform_json_request_failed",
            path=str(path or ""),
            method=str(method or "POST").upper(),
            error=repr(e)[:300],
        )
        return 502, {"detail": f"平台服务调用失败：{repr(e)}"}


def _platform_error_message(data, fallback="平台服务调用失败"):
    if isinstance(data, dict):
        detail = data.get("detail") or data.get("error") or data.get("message")
        if isinstance(detail, list) and detail:
            return str(detail[0])
        if detail:
            return str(detail)
    return fallback


def _send_json_with_headers(handler, code, data, extra_headers=None):
    body = json.dumps(data, ensure_ascii=False, indent=2).encode()
    handler.send_response(int(code))
    handler.send_header("Content-Type", "application/json; charset=utf-8")
    handler.send_header("Content-Length", str(len(body)))
    _send_cors_origin_header(handler)
    for name, value in (extra_headers or {}).items():
        handler.send_header(str(name), str(value))
    handler.end_headers()
    try:
        handler.wfile.write(body)
    except (BrokenPipeError, ConnectionResetError):
        pass


_PLATFORM_PROXY_HOP_BY_HOP_HEADERS = {
    "connection",
    "keep-alive",
    "proxy-authenticate",
    "proxy-authorization",
    "te",
    "trailer",
    "transfer-encoding",
    "upgrade",
}


def _is_comic_generation_api_path(path):
    route_path = str(path or "").split("?", 1)[0]
    generation_patterns = (
        r"/api/v1/comic-drama/generate-script",
        r"/api/v1/comic-drama/projects/\d+/characters/[^/]+/generate-views",
        r"/api/v1/comic-drama/projects/\d+/scenes/[^/]+/generate-image",
        r"/api/v1/comic-drama/projects/\d+/props/[^/]+/generate-image",
        r"/api/v1/comic-drama/storyboards/\d+/(generate-image|generate-video|prepare-dialogue-audio)",
        r"/api/v1/comic-drama/projects/\d+/batch-generate",
    )
    return any(re.fullmatch(pattern, route_path) for pattern in generation_patterns)


def _platform_api_proxy_target(path):
    if path == "/api/v1":
        return "/"
    if not str(path or "").startswith("/api/v1/"):
        return ""
    if _is_comic_generation_api_path(path):
        return ""
    return path[len("/api/v1"):]


_PLATFORM_MEDIA_PROXY_PREFIXES = ("/uploads/", "/video_output/")


def _platform_media_proxy_target(path):
    try:
        raw_path = urllib.parse.urlsplit(str(path or "")).path
        decoded_path = urllib.parse.unquote(raw_path).replace("\\", "/")
    except Exception:
        return ""
    if not any(decoded_path.startswith(prefix) for prefix in _PLATFORM_MEDIA_PROXY_PREFIXES):
        return ""
    normalized = os.path.normpath(decoded_path).replace("\\", "/")
    if not normalized.startswith("/"):
        normalized = "/" + normalized
    if normalized != decoded_path:
        return ""
    return decoded_path


def _platform_media_url(path):
    base = AICANVAS_PLATFORM_MEDIA_BASE or AICANVAS_PLATFORM_WEB_URL
    if not base:
        return ""
    return f"{base}/{str(path or '').lstrip('/')}"


def _platform_media_candidate_urls(path):
    seen = set()
    urls = []
    for base in (
        AICANVAS_PLATFORM_MEDIA_BASE,
        "https://manju.eknowhub.cn",
        AICANVAS_PLATFORM_WEB_URL,
        "https://gongju.eknowhub.cn",
    ):
        base = str(base or "").strip().rstrip("/")
        if not base or base in seen:
            continue
        seen.add(base)
        urls.append(f"{base}/{str(path or '').lstrip('/')}")
    return urls


def _platform_api_proxy_headers(handler, prefer_canvas_bearer=False):
    headers = {
        "User-Agent": "Yunling-AIHB-PlatformProxy/1.0",
    }
    for name in ("Content-Type", "Accept", "Accept-Language"):
        value = handler.headers.get(name)
        if value:
            headers[name] = value
    authorization = handler.headers.get("Authorization")
    bearer = _bearer_token_from_authorization(authorization)
    if authorization and not isinstance(_decode_canvas_session_token(bearer), dict):
        headers["Authorization"] = authorization
    else:
        session_token = _assistant_session_platform_token(handler, prefer_bearer=prefer_canvas_bearer)
        if session_token:
            headers["Authorization"] = f"Bearer {session_token}"
    return headers


def _has_platform_proxy_authorization(handler):
    return bool(_platform_api_proxy_headers(handler).get("Authorization"))


def _has_platform_session_authorization(handler):
    headers = getattr(handler, "headers", {})
    if not headers.get("Cookie", ""):
        return False
    cookies = _parse_cookie_header(handler)
    token = _canvas_session_cookie_token(cookies)
    if not token:
        return False
    session = _decode_canvas_session_token(token)
    return bool(session and session.get("platform_session_id"))


def _platform_authorization_user_id(handler):
    headers = getattr(handler, "headers", {})
    bearer = _bearer_token_from_authorization(headers.get("Authorization"))
    if not bearer or isinstance(_decode_canvas_session_token(bearer), dict):
        return 0
    status, payload = _fetch_platform_json_for_current_request(handler, "/user/info", "GET")
    if int(status or 0) != 200 or not isinstance(payload, dict):
        return 0
    candidates = [payload.get("data"), payload.get("user"), payload]
    for candidate in candidates:
        if isinstance(candidate, dict) and isinstance(candidate.get("user"), dict):
            candidates.append(candidate.get("user"))
        if not isinstance(candidate, dict):
            continue
        try:
            user_id = int(candidate.get("user_id") or candidate.get("id") or 0)
        except Exception:
            user_id = 0
        if user_id > 0:
            return user_id
    return 0


def _query_int(handler, name, default):
    try:
        query = urllib.parse.urlsplit(getattr(handler, "path", "") or "").query
        values = urllib.parse.parse_qs(query, keep_blank_values=True).get(name)
        if not values:
            return int(default)
        return max(1, int(str(values[0]).strip()))
    except Exception:
        return int(default)


_AGENT_COMIC_RUNTIMES = {}
_AGENT_COMIC_RUNTIMES_LOCK = threading.Lock()


def _agent_comic_runtime_state(scope=None):
    scope = _sanitize_account_scope(scope if scope is not None else _get_agent_runtime_scope())
    if not scope:
        return None
    with _AGENT_COMIC_RUNTIMES_LOCK:
        return _AGENT_COMIC_RUNTIMES.setdefault(scope, {"projects": {}, "tasks": {}, "ai_tasks": {}, "assets": {}, "asset_usages": [], "next_project_id": 1, "next_asset_id": 1, "loaded": False, "load_lock": threading.Lock()})


class _AgentScopedDict(dict):
    def __init__(self, key):
        super().__init__()
        self._key = key
        self._default = {}

    def _mapping(self):
        state = _agent_comic_runtime_state()
        return state[self._key] if state is not None else self._default

    def __getitem__(self, key): return self._mapping()[key]
    def __setitem__(self, key, value): self._mapping()[key] = value
    def __delitem__(self, key): del self._mapping()[key]
    def __contains__(self, key): return key in self._mapping()
    def __iter__(self): return iter(self._mapping())
    def __len__(self): return len(self._mapping())
    def get(self, key, default=None): return self._mapping().get(key, default)
    def items(self): return self._mapping().items()
    def keys(self): return self._mapping().keys()
    def values(self): return self._mapping().values()
    def clear(self): self._mapping().clear()
    def pop(self, key, *default): return self._mapping().pop(key, *default)
    def setdefault(self, key, default=None): return self._mapping().setdefault(key, default)
    def update(self, *args, **kwargs): return self._mapping().update(*args, **kwargs)
    def copy(self): return dict(self._mapping())


class _AgentScopedList(list):
    def __init__(self, key):
        super().__init__()
        self._key = key
        self._default = []

    def _items(self):
        state = _agent_comic_runtime_state()
        return state[self._key] if state is not None else self._default

    def __iter__(self): return iter(self._items())
    def __len__(self): return len(self._items())
    def __getitem__(self, index): return self._items()[index]
    def append(self, value): self._items().append(value)
    def clear(self): self._items().clear()
    def extend(self, values): self._items().extend(values)


def _current_local_comic_state_path():
    agent_paths = _agent_storage_paths(_get_agent_runtime_scope())
    return os.path.join(agent_paths["rootDir"], "agent_projects_local.json") if agent_paths else LOCAL_COMIC_STATE_PATH


def _local_comic_counter(name, default):
    state = _agent_comic_runtime_state()
    return int(state[name] if state is not None else default)


def _set_local_comic_counter(name, value):
    state = _agent_comic_runtime_state()
    if state is not None:
        state[name] = int(value)
        return True
    return False


def _take_local_comic_project_id():
    global LOCAL_COMIC_PROJECT_NEXT_ID
    project_id = _local_comic_counter("next_project_id", LOCAL_COMIC_PROJECT_NEXT_ID)
    if not _set_local_comic_counter("next_project_id", project_id + 1):
        LOCAL_COMIC_PROJECT_NEXT_ID = project_id + 1
    return project_id


LOCAL_COMIC_PROJECTS = _AgentScopedDict("projects")
LOCAL_COMIC_PROJECT_NEXT_ID = 1
LOCAL_COMIC_TASKS = _AgentScopedDict("tasks")
AI_COMIC_TASKS = _AgentScopedDict("ai_tasks")
AI_COMIC_TASK_REFRESH_LOCK = threading.Lock()
AI_COMIC_TASK_REFRESH_IN_FLIGHT = set()
AI_COMIC_PROJECT_TASK_REFRESH_IN_FLIGHT = set()
LOCAL_COMIC_ASSETS = _AgentScopedDict("assets")
LOCAL_COMIC_ASSET_NEXT_ID = 1
LOCAL_COMIC_ASSET_USAGES = _AgentScopedList("asset_usages")
LOCAL_COMIC_STATE_SAVE_LOCK = threading.Lock()
LOCAL_COMIC_STATE_SAVE_SCHEDULE_LOCK = threading.Lock()
LOCAL_COMIC_STATE_SAVE_DIRTY = False
LOCAL_COMIC_STATE_SAVE_THREAD = None
LOCAL_COMIC_ANALYSIS_LOCK = threading.Lock()
LOCAL_AIC_SUBJECTS_PATH = os.environ.get(
    "AICANVAS_SUBJECTS_PATH",
    os.path.join(CURRENT_DIR, "user", "aic_subjects.json"),
)
LOCAL_COMIC_STATE_PATH = os.environ.get(
    "AICANVAS_LOCAL_COMIC_STATE_PATH",
    os.path.join(CURRENT_DIR, "user", "comic_projects_local.json"),
)


def _save_local_comic_state():
    path = os.path.abspath(str(_current_local_comic_state_path() or ""))
    if not path:
        return False
    try:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with LOCAL_COMIC_STATE_SAVE_LOCK:
            payload = {
                "projects": {str(project_id): project for project_id, project in LOCAL_COMIC_PROJECTS.items()},
                "next_project_id": _local_comic_counter("next_project_id", LOCAL_COMIC_PROJECT_NEXT_ID),
                "tasks": {str(task_id): task for task_id, task in LOCAL_COMIC_TASKS.items()},
                "assets": {str(asset_id): asset for asset_id, asset in LOCAL_COMIC_ASSETS.items()},
                "next_asset_id": _local_comic_counter("next_asset_id", LOCAL_COMIC_ASSET_NEXT_ID),
                "asset_usages": list(LOCAL_COMIC_ASSET_USAGES),
            }
            with tempfile.NamedTemporaryFile(
                "w",
                encoding="utf-8",
                dir=os.path.dirname(path),
                prefix=f"{os.path.basename(path)}.",
                suffix=".tmp",
                delete=False,
            ) as file:
                json.dump(payload, file, ensure_ascii=False, indent=2)
                tmp_path = file.name
            os.replace(tmp_path, path)
        return True
    except Exception as error:
        _json_log("local_comic_state_save_failed", path=path, error=str(error))
        return False


def _save_local_comic_state_deferred():
    global LOCAL_COMIC_STATE_SAVE_DIRTY, LOCAL_COMIC_STATE_SAVE_THREAD

    def worker():
        global LOCAL_COMIC_STATE_SAVE_DIRTY, LOCAL_COMIC_STATE_SAVE_THREAD
        while True:
            with LOCAL_COMIC_STATE_SAVE_SCHEDULE_LOCK:
                LOCAL_COMIC_STATE_SAVE_DIRTY = False
            _save_local_comic_state()
            with LOCAL_COMIC_STATE_SAVE_SCHEDULE_LOCK:
                if not LOCAL_COMIC_STATE_SAVE_DIRTY:
                    LOCAL_COMIC_STATE_SAVE_THREAD = None
                    return

    with LOCAL_COMIC_STATE_SAVE_SCHEDULE_LOCK:
        LOCAL_COMIC_STATE_SAVE_DIRTY = True
        if LOCAL_COMIC_STATE_SAVE_THREAD and LOCAL_COMIC_STATE_SAVE_THREAD.is_alive():
            return True
        LOCAL_COMIC_STATE_SAVE_THREAD = threading.Thread(
            target=worker,
            daemon=True,
            name="LocalComicStateSave",
        )
        LOCAL_COMIC_STATE_SAVE_THREAD.start()
    return True



def _aic_subjects_path():
    override = str(os.environ.get("AICANVAS_SUBJECTS_PATH", "") or "").strip()
    if override:
        return os.path.abspath(override)
    return os.path.join(_current_user_dir(), "aic_subjects.json")


def _read_aic_subjects_from_path(path):
    path = os.path.abspath(str(path or ""))
    if not path or not os.path.exists(path):
        return []
    try:
        with open(path, "r", encoding="utf-8-sig") as fh:
            payload = json.load(fh)
    except Exception:
        return []
    if isinstance(payload, dict) and isinstance(payload.get("subjects"), list):
        items = payload.get("subjects") or []
    elif isinstance(payload, list):
        items = payload
    elif isinstance(payload, dict) and isinstance(payload.get("subject"), dict):
        items = [payload.get("subject")]
    else:
        items = []
    return [item for item in items if isinstance(item, dict)]


def _aic_subject_source_paths(include_accounts=True):
    paths = []
    seen = set()

    def _add(path):
        path = os.path.abspath(str(path or ""))
        if not path or path in seen:
            return
        seen.add(path)
        paths.append(path)

    _add(_aic_subjects_path())
    _add(LOCAL_AIC_SUBJECTS_PATH)
    if include_accounts:
        accounts_dir = os.path.join(CURRENT_DIR, "accounts")
        try:
            for account_name in os.listdir(accounts_dir):
                account_dir = os.path.join(accounts_dir, account_name)
                if not os.path.isdir(account_dir):
                    continue
                _add(os.path.join(account_dir, "user", "aic_subjects.json"))
                _add(os.path.join(account_dir, "data", "aic_subjects", "subjects.json"))
        except Exception:
            pass
    return paths


def _aic_sync_subjects_to_current_scope(subjects):
    if not _get_request_account_scope():
        return 0
    if not subjects:
        return 0
    try:
        existing = _load_aic_subjects()
        existing_keys = set()
        for item in existing:
            if not isinstance(item, dict):
                continue
            name = str(item.get("name") or "").strip().lower()
            sid = str(item.get("id") or item.get("subjectId") or "").strip()
            image = str(item.get("mainImage") or item.get("image") or item.get("img") or "").strip()
            existing_keys.add(sid or f"{name}|{image}")
        changed = 0
        for subject in subjects:
            if not isinstance(subject, dict):
                continue
            name = str(subject.get("name") or "").strip().lower()
            sid = str(subject.get("id") or subject.get("subjectId") or "").strip()
            image = str(subject.get("mainImage") or subject.get("image") or subject.get("img") or "").strip()
            key = sid or f"{name}|{image}"
            if key in existing_keys:
                continue
            item = dict(subject)
            item.setdefault("syncedFromSubjectFallback", True)
            existing.append(item)
            existing_keys.add(key)
            changed += 1
        if changed and _save_aic_subjects(existing):
            try:
                _ensure_aic_subject_file_manager_assets(existing)
            except Exception:
                pass
            _json_log("aic_subject_scope_synced", scope=_get_request_account_scope(), count=changed)
            return changed
    except Exception as error:
        try:
            _json_log("aic_subject_scope_sync_failed", scope=_get_request_account_scope(), error=repr(error))
        except Exception:
            pass
    return 0


def _load_aic_subjects_for_prompt(wanted_tokens=None):
    wanted_tokens = [str(value or "").strip() for value in (wanted_tokens or []) if str(value or "").strip()]

    def _collect(paths):
        items = []
        seen = set()
        for path in paths:
            for subject in _read_aic_subjects_from_path(path):
                if not isinstance(subject, dict):
                    continue
                name = str(subject.get("name") or "").strip()
                if wanted_tokens and not _subject_prompt_token_matches(name, wanted_tokens):
                    continue
                sid = str(subject.get("id") or subject.get("subjectId") or "").strip()
                main_image = str(subject.get("mainImage") or subject.get("image") or subject.get("img") or "").strip()
                key = sid or f"{name}|{main_image}"
                if key in seen:
                    continue
                seen.add(key)
                items.append(subject)
        return items

    if _get_request_account_scope():
        scoped = _collect([_aic_subjects_path()])
        if scoped or not wanted_tokens:
            return scoped
        fallback = _collect(_aic_subject_source_paths(include_accounts=True))
        _aic_sync_subjects_to_current_scope(fallback)
        return fallback
    return _collect(_aic_subject_source_paths(include_accounts=False))


def _load_aic_subjects():
    path = os.path.abspath(str(_aic_subjects_path() or ""))
    items = _read_aic_subjects_from_path(path)
    if items:
        return items
    legacy_path = os.path.abspath(str(LOCAL_AIC_SUBJECTS_PATH or ""))
    if path and legacy_path and path != legacy_path and not os.path.exists(path) and os.path.exists(legacy_path):
        legacy_items = _read_aic_subjects_from_path(legacy_path)
        if legacy_items:
            _save_aic_subjects(legacy_items)
            return legacy_items
    return []


def _save_aic_subjects(subjects):
    path = os.path.abspath(str(_aic_subjects_path() or ""))
    if not path:
        return False
    try:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with tempfile.NamedTemporaryFile(
            "w",
            encoding="utf-8",
            dir=os.path.dirname(path),
            prefix=f"{os.path.basename(path)}.",
            suffix=".tmp",
            delete=False,
        ) as fh:
            json.dump({"subjects": subjects}, fh, ensure_ascii=False, indent=2)
            tmp_path = fh.name
        os.replace(tmp_path, path)
        return True
    except Exception as error:
        _json_log("aic_subjects_save_failed", error=repr(error))
        return False


def _aic_subject_file_asset_id(subject):
    source = str((subject or {}).get("id") or (subject or {}).get("name") or "subject").strip()
    source = re.sub(r"[^a-zA-Z0-9_-]+", "-", source).strip("-_").lower()
    if not source:
        source = "subject"
    return f"aic-subject-{source[:70]}"


def _aic_url_file_name(url, fallback):
    try:
        parsed = urllib.parse.urlparse(str(url or ""))
        name = os.path.basename(parsed.path or "")
    except Exception:
        name = ""
    if not name:
        name = fallback
    if "." not in os.path.basename(name):
        name = f"{name}.png"
    return name[:140]


def _aic_subject_image_urls(subject):
    urls = []
    for value in [subject.get("mainImage"), *(subject.get("angleImages") or [])]:
        url = str(value or "").strip()
        if url and url not in urls:
            urls.append(url)
    return urls


def _save_aic_subject_file_manager_asset(subject, *, touch=True):
    if not isinstance(subject, dict):
        return ""
    urls = _aic_subject_image_urls(subject)
    if not urls:
        return ""
    try:
        _ensure_current_storage_dirs()
        assets_dir = _current_assets_dir()
        os.makedirs(assets_dir, exist_ok=True)
        asset_id = _aic_subject_file_asset_id(subject)
        path = os.path.join(assets_dir, f"{asset_id}.json")
        existing = _read_json_file(path, {}) if os.path.exists(path) else {}
        now_ms = int(time.time() * 1000)
        created_at = int(existing.get("createdAt") or subject.get("createdAt") or now_ms)
        updated_at = int(now_ms if touch else (existing.get("updatedAt") or subject.get("updatedAt") or now_ms))
        name = str(subject.get("name") or "").strip() or "subject"
        description = str(subject.get("description") or "").strip()
        tags = [str(tag).strip() for tag in (subject.get("tags") or []) if str(tag or "").strip()]
        search_tags = []
        for tag in ["\u4e3b\u4f53\u56fe", "\u4e3b\u4f53\u5e93", name, *tags]:
            if tag and tag not in search_tags:
                search_tags.append(tag)
        nodes = []
        items = []
        for index, url in enumerate(urls):
            label = "\u4e3b\u56fe" if index == 0 else "\u89c6\u89d2\u56fe%d" % index
            file_name = _aic_url_file_name(url, f"{asset_id}-{index + 1}.png")
            node_id = f"source-image-{asset_id}-{index + 1}"
            node_name = f"{name}-{label}"
            node = {
                "id": node_id,
                "type": "source-image",
                "name": node_name,
                "x": index * 24,
                "y": index * 24,
                "width": 288,
                "height": 288,
                "src": url,
                "imageUrl": url,
                "sourceUrl": url,
                "thumbUrl": url,
                "localPath": "",
                "originalLocalPath": "",
                "displayLocalPath": "",
                "thumbLocalPath": "",
                "sourceId": "",
                "thumbId": "",
                "fileName": file_name,
                "needsAutoResize": True,
            }
            nodes.append(node)
            items.append({"type": "image", "url": url, "name": node_name, "fileName": file_name})
        asset = {
            "id": asset_id,
            "kind": "generation-history",
            "mediaKind": "image",
            "projectId": "default_v2_project",
            "canvasId": "aic-subjects",
            "sourceNodeId": str(subject.get("sourceNodeId") or ""),
            "resultFingerprint": f"aic-subject:{subject.get('id') or name}",
            "name": f"\u4e3b\u4f53\u56fe - {name}",
            "category": "\u4e3b\u4f53\u5e93",
            "coverUrl": urls[0],
            "coverType": "image",
            "items": items,
            "nodes": nodes,
            "edges": [],
            "model": str(subject.get("imageModel") or "gpt-image-2"),
            "provider": "openai",
            "prompt": description or f"\u4e3b\u4f53\u56fe {name}",
            "aspectRatio": str(subject.get("aspectRatio") or "\u81ea\u9002\u5e94"),
            "imageSize": str(subject.get("imageSize") or "original"),
            "sourceIndex": 0,
            "createdAt": created_at,
            "updatedAt": updated_at,
            "metaKey": asset_id,
            "tags": search_tags,
            "metadata": {
                "source": "aic-subject",
                "subjectId": str(subject.get("id") or ""),
                "subjectName": name,
                "voice": str(subject.get("voice") or ""),
                "voiceAudioUrl": str(subject.get("voiceAudioUrl") or ""),
                "referenceImageCount": len(urls),
            },
        }
        _write_json_file(path, asset)
        return asset_id
    except Exception as error:
        _json_log("aic_subject_file_asset_save_failed", error=repr(error), subject=str(subject.get("name") or ""))
        return ""


def _ensure_aic_subject_file_manager_assets(subjects):
    if not isinstance(subjects, list):
        return 0
    created = 0
    for subject in subjects:
        if not isinstance(subject, dict):
            continue
        try:
            asset_id = _aic_subject_file_asset_id(subject)
            path = os.path.join(_current_assets_dir(), f"{asset_id}.json")
            if os.path.exists(path):
                continue
            if _save_aic_subject_file_manager_asset(subject, touch=False):
                created += 1
        except Exception:
            continue
    return created


def _delete_aic_subject_file_manager_asset(subject):
    if not isinstance(subject, dict):
        return []
    removed = []
    try:
        asset_id = _aic_subject_file_asset_id(subject)
        path = os.path.join(_current_assets_dir(), f"{asset_id}.json")
        if os.path.exists(path):
            os.remove(path)
            removed.append(path)
    except Exception as error:
        _json_log("aic_subject_file_asset_delete_failed", error=repr(error), subject=str(subject.get("name") or ""))
    return removed


def _delete_aic_subject_local_asset(subject):
    if not isinstance(subject, dict):
        return []
    name = str(subject.get("name") or "").strip()
    source_key = f"aic-subject:{name}" if name else ""
    removed = []
    for asset_id, asset in list(LOCAL_COMIC_ASSETS.items()):
        if not isinstance(asset, dict) or str(asset.get("source") or "") != "aic-subject":
            continue
        asset_data = asset.get("asset_data") if isinstance(asset.get("asset_data"), dict) else {}
        if (source_key and asset.get("source_key") == source_key) or (name and str(asset_data.get("name") or "") == name):
            LOCAL_COMIC_ASSETS.pop(asset_id, None)
            removed.append(asset_id)
    if removed:
        _save_local_comic_state()
    return removed


def _delete_aic_subject(subject_id="", name=""):
    subject_id = str(subject_id or "").strip()
    name = str(name or "").strip()
    if not subject_id and not name:
        return None, "missing_id_or_name"
    subjects = _load_aic_subjects()
    kept = []
    deleted = []
    for item in subjects:
        if not isinstance(item, dict):
            continue
        id_match = bool(subject_id and str(item.get("id") or "") == subject_id)
        name_match = bool(name and str(item.get("name") or "") == name)
        if id_match or name_match:
            deleted.append(item)
        else:
            kept.append(item)
    if not deleted:
        return None, "not_found"
    if not _save_aic_subjects(kept):
        return None, "save_failed"
    removed_files = []
    removed_assets = []
    for item in deleted:
        removed_files.extend(_delete_aic_subject_file_manager_asset(item))
        removed_assets.extend(_delete_aic_subject_local_asset(item))
    return {
        "deleted": deleted,
        "subjects": kept,
        "removedFileAssets": removed_files,
        "removedLocalAssets": removed_assets,
    }, ""


def _aic_looks_like_image_url(value):
    value = str(value or "").strip()
    if not value:
        return False
    lowered = value.lower().split("?", 1)[0].split("#", 1)[0]
    if lowered.endswith((".png", ".jpg", ".jpeg", ".webp", ".gif", ".bmp", ".avif")):
        return True
    if "/refimg/" in lowered or "/public-uploads/" in lowered or "/uploads/" in lowered or "/output/" in lowered:
        return True
    if lowered.startswith("blob:"):
        return True
    return False


def _aic_subject_public_image(subject):
    if not isinstance(subject, dict):
        return ""
    candidates = [subject.get("mainImage"), subject.get("image"), subject.get("img")]
    candidates.extend(subject.get("angleImages") or [])
    for value in candidates:
        value = str(value or "").strip()
        if value and _aic_looks_like_image_url(value):
            return value
    return ""


def _aic_subject_audio_url(subject):
    if not isinstance(subject, dict):
        return ""
    for key in (
        "voiceAudioUrl",
        "audioUrl",
        "audio_url",
        "voiceUrl",
        "voice_url",
        "referenceAudioUrl",
        "reference_audio_url",
    ):
        value = str(subject.get(key) or "").strip()
        if value and value.lower() not in ("undefined", "null", "none", "false", "0"):
            return value
    return ""


def _normalize_aic_subject_voice_fields(subject):
    subject = dict(subject if isinstance(subject, dict) else {})
    voice = str(subject.get("voice") or subject.get("voiceName") or subject.get("ttsVoice") or "").strip()
    voice_name = str(subject.get("voiceName") or voice).strip()
    tts_voice = str(subject.get("ttsVoice") or subject.get("tts_voice") or subject.get("voiceId") or "").strip()
    audio = _aic_subject_audio_url(subject)
    if not voice:
        voice = "无配音" if not audio else "上传音色"
    if not voice_name:
        voice_name = voice
    if voice in ("无配音", "none", "None", "NONE"):
        status = "none"
        voice_type = "none"
        provider = "none"
        model = "无配音"
        tts_voice = ""
    elif audio:
        status = "ready"
        voice_type = str(subject.get("voiceType") or "uploaded_audio").strip()
        provider = str(subject.get("voiceProvider") or "uploaded-audio").strip()
        model = str(subject.get("voiceModel") or "上传音频克隆").strip()
        if not tts_voice and model == _AIC_TEXT_VOICE_MODEL:
            tts_voice = _aic_pick_text_voice(subject.get("voiceDescription") or voice)
    else:
        status = str(subject.get("voiceStatus") or "text_only").strip()
        voice_type = str(subject.get("voiceType") or "text_note").strip()
        provider = str(subject.get("voiceProvider") or "preset-note").strip()
        model = str(subject.get("voiceModel") or "文本音色备注").strip()
    subject.update(
        {
            "voice": voice,
            "voiceName": voice_name,
            "ttsVoice": tts_voice or voice,
            "voiceAudioUrl": audio,
            "audioUrl": audio,
            "voiceUrl": audio,
            "referenceAudioUrl": audio,
            "voiceStatus": status,
            "voiceType": voice_type,
            "voiceProvider": provider,
            "voiceModel": model,
            "voiceDescription": str(subject.get("voiceDescription") or subject.get("voice_description") or voice).strip(),
        }
    )
    return subject


def _upsert_aic_subject_asset(subject):
    global LOCAL_COMIC_ASSET_NEXT_ID
    if not isinstance(subject, dict):
        return
    name = str(subject.get("name") or "主体").strip() or "主体"
    image_url = _aic_subject_public_image(subject)
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()
    source_key = f"aic-subject:{name}"
    existing = None
    for asset in LOCAL_COMIC_ASSETS.values():
        if isinstance(asset, dict) and asset.get("source_key") == source_key:
            existing = asset
            break
    asset_id = int(existing.get("id")) if existing else int(LOCAL_COMIC_ASSET_NEXT_ID or 1)
    if not existing:
        LOCAL_COMIC_ASSET_NEXT_ID = asset_id + 1
    refs = [str(u).strip() for u in [image_url, *(subject.get("angleImages") or [])] if str(u or "").strip()]
    asset_data = {
        "name": name,
        "description": str(subject.get("description") or ""),
        "image_url": image_url,
        "thumbnail_url": image_url,
        "reference_images": refs,
        "voice": str(subject.get("voice") or ""),
        "voiceName": str(subject.get("voiceName") or ""),
        "ttsVoice": str(subject.get("ttsVoice") or ""),
        "voiceAudioUrl": str(subject.get("voiceAudioUrl") or ""),
        "audioUrl": str(subject.get("audioUrl") or ""),
        "voiceUrl": str(subject.get("voiceUrl") or ""),
        "referenceAudioUrl": str(subject.get("referenceAudioUrl") or ""),
        "voiceStatus": str(subject.get("voiceStatus") or ""),
        "voiceType": str(subject.get("voiceType") or ""),
        "voiceProvider": str(subject.get("voiceProvider") or ""),
        "voiceModel": str(subject.get("voiceModel") or ""),
        "voiceDescription": str(subject.get("voiceDescription") or ""),
        "tags": subject.get("tags") if isinstance(subject.get("tags"), list) else [],
    }
    asset = {
        "id": asset_id,
        "asset_type": "character",
        "name": name,
        "description": asset_data["description"],
        "thumbnail_url": image_url,
        "asset_data": asset_data,
        "category": "character",
        "status": "active",
        "source": "aic-subject",
        "source_key": source_key,
        "usage_count": int((existing or {}).get("usage_count") or 0),
        "is_favorite": bool((existing or {}).get("is_favorite")),
        "created_at": str((existing or {}).get("created_at") or now),
        "updated_at": now,
    }
    scope = _get_request_account_scope()
    if scope:
        asset["account_scope"] = scope
    LOCAL_COMIC_ASSETS[asset_id] = asset
    _save_local_comic_state()


def _aic_subject_download_ext(data, mime, url):
    head = bytes(data or b"")[:16]
    if head.startswith(b"\x89PNG\r\n\x1a\n"):
        return "png", "image/png"
    if head.startswith(b"\xff\xd8\xff"):
        return "jpg", "image/jpeg"
    if head.startswith(b"RIFF") and head[8:12] == b"WEBP":
        return "webp", "image/webp"
    if head.startswith((b"GIF87a", b"GIF89a")):
        return "gif", "image/gif"
    mime = str(mime or "").split(";", 1)[0].strip().lower()
    if mime == "image/png":
        return "png", mime
    if mime in {"image/jpeg", "image/jpg"}:
        return "jpg", "image/jpeg"
    if mime == "image/webp":
        return "webp", mime
    if mime == "image/gif":
        return "gif", mime
    try:
        ext = os.path.splitext(urllib.parse.urlsplit(str(url or "")).path)[1].lstrip(".").lower()
    except Exception:
        ext = ""
    if ext in {"png", "jpg", "jpeg", "webp", "gif"}:
        return ("jpg" if ext == "jpeg" else ext), mimetypes.guess_type("x." + ext)[0] or "image/jpeg"
    return "jpg", "image/jpeg"


def _aic_subject_download_bytes(image_url):
    raw = str(image_url or "").strip()
    if not raw:
        raise ValueError("missing_image_url")
    max_bytes = 30 * 1024 * 1024
    if raw.startswith("data:"):
        match = re.match(r"^data:([^;,]+)?;base64,(.*)$", raw, re.DOTALL)
        if not match:
            raise ValueError("invalid_data_image")
        mime = (match.group(1) or "image/png").strip().lower()
        if not mime.startswith("image/"):
            raise ValueError("not_image")
        data = base64.b64decode(match.group(2))
        if len(data) > max_bytes:
            raise ValueError("image_too_large")
        return data, mime

    local_lookup = raw
    try:
        parsed = urllib.parse.urlsplit(raw)
        if parsed.scheme in {"http", "https"}:
            local_lookup = parsed.path or raw
    except Exception:
        local_lookup = raw
    local_path = _resolve_local_virtual_path(local_lookup)
    if local_path and os.path.isfile(local_path):
        if os.path.getsize(local_path) > max_bytes:
            raise ValueError("image_too_large")
        with open(local_path, "rb") as file:
            data = file.read()
        return data, mimetypes.guess_type(local_path)[0] or "image/jpeg"

    if not (raw.startswith("http://") or raw.startswith("https://")):
        raise ValueError("unsupported_image_url")
    request = urllib.request.Request(raw, headers={"User-Agent": "Mozilla/5.0"})
    with urllib.request.urlopen(request, timeout=45) as response:
        mime = str(response.headers.get("Content-Type") or "").split(";", 1)[0].strip().lower()
        if mime and not (mime.startswith("image/") or mime == "application/octet-stream"):
            raise ValueError("not_image")
        chunks = []
        total = 0
        while True:
            chunk = response.read(1024 * 256)
            if not chunk:
                break
            chunks.append(chunk)
            total += len(chunk)
            if total > max_bytes:
                raise ValueError("image_too_large")
        return b"".join(chunks), mime or "image/jpeg"


def _upsert_aic_subject_download_local_asset(name, public_url, source_url, file_asset_id):
    global LOCAL_COMIC_ASSET_NEXT_ID
    name = str(name or "主体下载图").strip() or "主体下载图"
    public_url = str(public_url or "").strip()
    if not public_url:
        return 0
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()
    source_key = f"aic-subject-download:{hashlib.sha1(public_url.encode('utf-8')).hexdigest()[:16]}"
    existing = None
    for asset in LOCAL_COMIC_ASSETS.values():
        if isinstance(asset, dict) and asset.get("source_key") == source_key:
            existing = asset
            break
    asset_id = int(existing.get("id")) if existing else int(LOCAL_COMIC_ASSET_NEXT_ID or 1)
    if not existing:
        LOCAL_COMIC_ASSET_NEXT_ID = asset_id + 1
    asset = {
        "id": asset_id,
        "asset_type": "character",
        "name": name,
        "description": "主体库单张下载图，已保存到文件管理",
        "thumbnail_url": public_url,
        "asset_data": {
            "name": name,
            "image_url": public_url,
            "thumbnail_url": public_url,
            "reference_images": [public_url],
            "source_url": str(source_url or ""),
            "file_asset_id": str(file_asset_id or ""),
        },
        "tags": ["主体图", "主体库", "下载"],
        "category": "主体库下载",
        "source": "aic-subject-download",
        "source_key": source_key,
        "status": "active",
        "usage_count": int((existing or {}).get("usage_count") or 0),
        "is_favorite": bool((existing or {}).get("is_favorite")),
        "created_at": str((existing or {}).get("created_at") or now),
        "updated_at": now,
    }
    scope = _get_request_account_scope()
    if scope:
        asset["account_scope"] = scope
    LOCAL_COMIC_ASSETS[asset_id] = asset
    _save_local_comic_state()
    return asset_id


def _handle_aic_subject_image_download_request(handler, path, method):
    parsed_path = urllib.parse.urlparse(str(path or ""))
    if parsed_path.path != "/api/v2/aic-subject-image-download":
        return False
    if str(method or "").upper() != "POST":
        _send_json_with_headers(handler, 405, {"ok": False, "error": "method_not_allowed"})
        return True
    payload = _read_json_body_object(handler)
    image_url = str(payload.get("imageUrl") or payload.get("url") or "").strip()
    subject_name = str(payload.get("subjectName") or payload.get("name") or "主体图片").strip() or "主体图片"
    try:
        data, mime = _aic_subject_download_bytes(image_url)
        ext, mime = _aic_subject_download_ext(data, mime, image_url)
        safe_name = re.sub(r"[^0-9A-Za-z\u4e00-\u9fff_-]+", "-", subject_name).strip("-_") or "subject"
        digest = hashlib.sha1((image_url + str(len(data))).encode("utf-8") + data[:4096]).hexdigest()[:14]
        file_name = f"{safe_name[:42]}-{digest}.{ext}"
        rel_dir = "subject-downloads"
        abs_dir = os.path.join(_current_assets_dir(), rel_dir)
        os.makedirs(abs_dir, exist_ok=True)
        abs_path = os.path.abspath(os.path.join(abs_dir, file_name))
        if not _is_path_inside(abs_path, _current_assets_dir()):
            raise ValueError("invalid_save_path")
        if not os.path.exists(abs_path):
            with open(abs_path, "wb") as file:
                file.write(data)
        public_url = "/data/assets/" + urllib.parse.quote(f"{rel_dir}/{file_name}")
        subject_asset = {
            "id": f"download-{digest}",
            "name": f"{subject_name} 下载图",
            "description": "主体库单张下载图，已保存到文件管理",
            "mainImage": public_url,
            "angleImages": [],
            "createdAt": int(time.time() * 1000),
            "updatedAt": int(time.time() * 1000),
            "tags": ["主体库下载"],
        }
        file_asset_id = _save_aic_subject_file_manager_asset(subject_asset, touch=True)
        local_asset_id = _upsert_aic_subject_download_local_asset(subject_asset["name"], public_url, image_url, file_asset_id)
        _json_log("aic_subject_image_download_saved", file=file_name, file_asset_id=file_asset_id, local_asset_id=local_asset_id)
        _send_json_with_headers(handler, 200, {
            "ok": True,
            "url": public_url,
            "fileName": file_name,
            "mime": mime,
            "fileAssetId": file_asset_id,
            "localAssetId": local_asset_id,
            "asset": {
                "id": file_asset_id,
                "name": subject_asset["name"],
                "category": "主体库下载",
                "coverUrl": public_url,
                "url": public_url,
            },
        })
    except Exception as error:
        _json_log("aic_subject_image_download_failed", error=repr(error), url=image_url[:180])
        _send_json_with_headers(handler, 400, {"ok": False, "error": str(error) or "save_failed"})
    return True



def _safe_aic_whiteboard_board(raw):
    text = str(raw or "default_v2_project").strip() or "default_v2_project"
    text = re.sub(r"[^a-zA-Z0-9_.-]+", "_", text).strip("._-")
    return (text[:120] or "default_v2_project")


def _aic_whiteboard_file(board):
    _ensure_current_storage_dirs()
    base = os.path.join(_current_data_dir(), "aic_whiteboard")
    os.makedirs(base, exist_ok=True)
    return os.path.join(base, _safe_aic_whiteboard_board(board) + ".json")


_AIC_VIDEO_THUMB_CACHE = {}


def _aic_media_local_key(value):
    text = str(value or "").strip()
    if not text:
        return ""
    try:
        parsed = urllib.parse.urlsplit(text)
        if parsed.scheme and parsed.path:
            text = parsed.path
    except Exception:
        pass
    try:
        text = urllib.parse.unquote(text)
    except Exception:
        pass
    text = text.split("?", 1)[0].split("#", 1)[0].replace("\\", "/").lstrip("/")
    marker = "output/"
    idx = text.find(marker)
    if idx >= 0:
        return text[idx:]
    return text


def _aic_is_image_thumb_url(value):
    text = str(value or "").strip().lower()
    if not text:
        return False
    text = text.split("?", 1)[0].split("#", 1)[0]
    return text.endswith((".jpg", ".jpeg", ".png", ".webp", ".gif"))


def _aic_find_video_thumb_url(video_ref, preferred_assets_dir=None):
    target = _aic_media_local_key(video_ref)
    if not target:
        return ""
    preferred_assets_dir = os.path.abspath(str(preferred_assets_dir or "")) if preferred_assets_dir else ""
    cache_key = ("aic-video-thumb", preferred_assets_dir, target)
    if cache_key in _AIC_VIDEO_THUMB_CACHE:
        return _AIC_VIDEO_THUMB_CACHE[cache_key]
    target_name = os.path.basename(target)
    found = ""

    def _walk(value):
        nonlocal found
        if found:
            return
        if isinstance(value, dict):
            refs = [
                value.get("localPath"),
                value.get("originalLocalPath"),
                value.get("displayLocalPath"),
                value.get("src"),
                value.get("videoUrl"),
                value.get("sourceUrl"),
            ]
            names = [str(value.get("name") or ""), str(value.get("fileName") or "")]
            matched = any(_aic_media_local_key(item) == target for item in refs if item)
            if not matched and target_name:
                matched = any(os.path.basename(_aic_media_local_key(item)) == target_name for item in refs if item)
                matched = matched or any(name == target_name for name in names)
            if matched:
                for key in ("thumbUrl", "videoThumbSrc", "thumbSrc", "coverUrl", "posterUrl"):
                    candidate = str(value.get(key) or "").strip()
                    if _aic_is_image_thumb_url(candidate):
                        found = candidate
                        return
            for item in value.values():
                _walk(item)
        elif isinstance(value, list):
            for item in value:
                _walk(item)

    def _asset_dirs():
        dirs = []
        for path in (
            preferred_assets_dir,
            _current_assets_dir(),
            os.path.join(os.path.dirname(os.path.abspath(__file__)), "data", "assets"),
        ):
            if path and os.path.isdir(path) and path not in dirs:
                dirs.append(path)
        accounts_root = os.path.join(os.path.dirname(os.path.abspath(__file__)), "accounts")
        try:
            for account in os.listdir(accounts_root):
                path = os.path.join(accounts_root, account, "data", "assets")
                if os.path.isdir(path) and path not in dirs:
                    dirs.append(path)
        except Exception:
            pass
        return dirs

    try:
        for assets_dir in _asset_dirs():
            history_files = []
            for name in os.listdir(assets_dir):
                if name.startswith("gen-history-") and name.endswith(".json"):
                    path = os.path.join(assets_dir, name)
                    history_files.append((os.path.getmtime(path), path))
            history_files.sort(reverse=True)
            for _, path in history_files[:250]:
                try:
                    data = _load_json_file(path)
                except Exception:
                    data = None
                _walk(data)
                if found:
                    break
            if found:
                break
    except Exception:
        found = ""
    _AIC_VIDEO_THUMB_CACHE[cache_key] = found
    return found


def _normalize_aic_whiteboard_video_thumbs(snapshot, preferred_assets_dir=None):
    if not isinstance(snapshot, dict):
        return False
    nodes = snapshot.get("nodes")
    if isinstance(nodes, dict):
        values = list(nodes.values())
    elif isinstance(nodes, list):
        values = nodes
    else:
        values = []
    changed = False
    for node in values:
        if not isinstance(node, dict) or str(node.get("type") or "") not in ("source-video", "ai-video"):
            continue
        nested_thumb = ""
        for item in node.get("videos") or []:
            if not isinstance(item, dict):
                continue
            candidate = str(item.get("thumbUrl") or item.get("videoThumbSrc") or item.get("posterUrl") or "").strip()
            if _aic_is_image_thumb_url(candidate):
                nested_thumb = candidate
                break
        video_ref = (
            node.get("videoUrl")
            or node.get("src")
            or node.get("sourceUrl")
            or node.get("localPath")
            or node.get("originalLocalPath")
        )
        thumb = nested_thumb or _aic_find_video_thumb_url(video_ref, preferred_assets_dir)
        if not thumb:
            continue
        for key in ("thumbUrl", "videoThumbSrc", "imageUrl"):
            current = node.get(key)
            if not current or _looks_like_video_ref_url(current):
                node[key] = thumb
                changed = True
        thumb_local = thumb.lstrip("/") if thumb.startswith("/") else thumb
        if not node.get("thumbLocalPath") or _looks_like_video_ref_url(node.get("thumbLocalPath")):
            node["thumbLocalPath"] = thumb_local
            changed = True
        if not node.get("posterUrl"):
            node["posterUrl"] = thumb
            changed = True
    return changed


def _aic_whiteboard_node_count(snapshot):
    if not isinstance(snapshot, dict):
        return 0
    nodes = snapshot.get("nodes")
    if isinstance(nodes, list):
        return len(nodes)
    if isinstance(nodes, dict):
        return len(nodes)
    return 0


def _load_aic_whiteboard_doc(board):
    safe_board = _safe_aic_whiteboard_board(board)
    path = _aic_whiteboard_file(safe_board)
    data = _load_json_file(path)
    if not isinstance(data, dict) or not data:
        return {"board": safe_board, "updatedAt": 0, "snapshot": None}
    snapshot = data.get("snapshot") if isinstance(data.get("snapshot"), dict) else None
    preferred_assets_dir = os.path.join(os.path.dirname(os.path.dirname(path)), "assets")
    if _normalize_aic_whiteboard_video_thumbs(snapshot, preferred_assets_dir):
        data["snapshot"] = snapshot
        try:
            _atomic_write_json(path, data)
        except Exception:
            pass
    try:
        updated_at = int(data.get("updatedAt") or 0)
    except Exception:
        updated_at = 0
    return {"board": safe_board, "updatedAt": updated_at, "snapshot": snapshot}


def _handle_aic_whiteboard_request(handler, path, method):
    parsed = urllib.parse.urlparse(str(getattr(handler, "path", path) or ""))
    if parsed.path != "/api/v2/aic-whiteboard":
        return False
    method = str(method or "").upper()
    query = urllib.parse.parse_qs(parsed.query or "")
    if method == "GET":
        board = _safe_aic_whiteboard_board((query.get("board") or [""])[0])
        doc = _load_aic_whiteboard_doc(board)
        _send_json_with_headers(handler, 200, {"ok": True, **doc})
        return True
    if method != "POST":
        _send_json_with_headers(handler, 405, {"ok": False, "error": "method_not_allowed"})
        return True
    try:
        payload = json.loads((_read_body(handler, max_bytes=30 * 1024 * 1024) or b"{}").decode("utf-8", "ignore"))
    except ValueError:
        _send_json_with_headers(handler, 413, {"ok": False, "error": "request_too_large"})
        return True
    except Exception:
        _send_json_with_headers(handler, 400, {"ok": False, "error": "invalid_json"})
        return True
    if not isinstance(payload, dict):
        payload = {}
    board = _safe_aic_whiteboard_board(payload.get("board") or (query.get("board") or [""])[0])
    snapshot = payload.get("snapshot") if isinstance(payload.get("snapshot"), dict) else None
    try:
        incoming_ts = int(payload.get("updatedAt") or 0)
    except Exception:
        incoming_ts = 0
    current = _load_aic_whiteboard_doc(board)
    current_ts = int(current.get("updatedAt") or 0)
    if current_ts > incoming_ts > 0:
        _send_json_with_headers(handler, 200, {"ok": True, "stale": True, **current})
        return True
    if incoming_ts <= 0:
        incoming_ts = int(time.time() * 1000)
    snapshot = snapshot or {"nodes": {}, "edges": {}, "assets": {}}
    if _aic_whiteboard_node_count(snapshot) == 0 and _aic_whiteboard_node_count(current.get("snapshot")) > 0:
        _send_json_with_headers(handler, 200, {"ok": True, "stale": True, "emptyRejected": True, **current})
        return True
    preferred_assets_dir = os.path.join(os.path.dirname(os.path.dirname(_aic_whiteboard_file(board))), "assets")
    _normalize_aic_whiteboard_video_thumbs(snapshot, preferred_assets_dir)
    doc = {"board": board, "updatedAt": incoming_ts, "snapshot": snapshot}
    _atomic_write_json(_aic_whiteboard_file(board), doc)
    _send_json_with_headers(handler, 200, {"ok": True, "stale": False, **doc})
    return True

def _handle_aic_subjects_request(handler, path, method):
    parsed_subject_path = urllib.parse.urlparse(str(path or ""))
    if parsed_subject_path.path != "/api/v2/aic-subjects":
        return False
    method = str(method or "").upper()
    if method == "GET":
        subjects = _load_aic_subjects()
        normalized_subjects = []
        changed = False
        for subject in subjects:
            if not isinstance(subject, dict):
                continue
            item = dict(subject)
            voice_fields = _normalize_aic_subject_voice_fields(item)
            for key in (
                "voice",
                "voiceName",
                "ttsVoice",
                "voiceAudioUrl",
                "audioUrl",
                "voiceUrl",
                "referenceAudioUrl",
                "voiceStatus",
                "voiceType",
                "voiceProvider",
                "voiceModel",
                "voiceDescription",
            ):
                value = voice_fields.get(key, "")
                if item.get(key) != value:
                    item[key] = value
                    changed = True
            normalized_subjects.append(item)
        subjects = normalized_subjects
        if changed:
            _save_aic_subjects(subjects)
        synced_assets = _ensure_aic_subject_file_manager_assets(subjects)
        _send_json_with_headers(handler, 200, {"ok": True, "subjects": subjects, "fileAssetsSynced": synced_assets})
        return True
    if method == "DELETE":
        query = urllib.parse.parse_qs(parsed_subject_path.query or "")
        payload = _read_json_body_object(handler)
        subject = payload.get("subject") if isinstance(payload.get("subject"), dict) else {}
        subject_id = _first_non_empty(payload.get("id"), payload.get("subjectId"), subject.get("id"), (query.get("id") or [""])[0], (query.get("subjectId") or [""])[0])
        name = _first_non_empty(payload.get("name"), payload.get("subjectName"), subject.get("name"), (query.get("name") or [""])[0], (query.get("subjectName") or [""])[0])
        result, error = _delete_aic_subject(subject_id, name)
        if error:
            status = 404 if error == "not_found" else 400 if error == "missing_id_or_name" else 500
            _send_json_with_headers(handler, status, {"ok": False, "error": error})
            return True
        _json_log("aic_subject_deleted", id=str(subject_id or ""), name=str(name or ""), deleted_count=len(result.get("deleted") or []), removed_file_assets=len(result.get("removedFileAssets") or []), removed_local_assets=len(result.get("removedLocalAssets") or []))
        _send_json_with_headers(handler, 200, {"ok": True, **result})
        return True
    if method != "POST":
        _send_json_with_headers(handler, 405, {"ok": False, "error": "method_not_allowed"})
        return True
    payload = _read_json_body_object(handler)
    if str(payload.get("op") or payload.get("action") or "").strip().lower() in {"delete", "remove"}:
        subject = payload.get("subject") if isinstance(payload.get("subject"), dict) else {}
        result, error = _delete_aic_subject(_first_non_empty(payload.get("id"), payload.get("subjectId"), subject.get("id")), _first_non_empty(payload.get("name"), payload.get("subjectName"), subject.get("name")))
        if error:
            status = 404 if error == "not_found" else 400 if error == "missing_id_or_name" else 500
            _send_json_with_headers(handler, status, {"ok": False, "error": error})
            return True
        _send_json_with_headers(handler, 200, {"ok": True, **result})
        return True
    subject = payload.get("subject") if isinstance(payload.get("subject"), dict) else payload
    if not isinstance(subject, dict):
        _send_json_with_headers(handler, 400, {"ok": False, "error": "invalid_subject"})
        return True
    name = str(subject.get("name") or "").strip()
    main_image = _aic_subject_public_image(subject)
    if not name or not main_image:
        _send_json_with_headers(handler, 400, {"ok": False, "error": "missing_name_or_image"})
        return True
    now_ms = int(time.time() * 1000)
    normalized = {
        "id": str(subject.get("id") or f"subj-{now_ms}"),
        "name": name[:80],
        "description": str(subject.get("description") or "").strip(),
        "tags": subject.get("tags") if isinstance(subject.get("tags"), list) else [],
        "mainImage": main_image,
        "angleImages": [str(u).strip() for u in (subject.get("angleImages") or []) if str(u or "").strip()],
        "sourceNodeId": str(subject.get("sourceNodeId") or ""),
        "createdAt": int(subject.get("createdAt") or now_ms),
        "updatedAt": now_ms,
    }
    voice_fields = _normalize_aic_subject_voice_fields(subject)
    for key in (
        "voice",
        "voiceName",
        "ttsVoice",
        "voiceAudioUrl",
        "audioUrl",
        "voiceUrl",
        "referenceAudioUrl",
        "voiceStatus",
        "voiceType",
        "voiceProvider",
        "voiceModel",
        "voiceDescription",
    ):
        normalized[key] = voice_fields.get(key, "")
    subjects = _load_aic_subjects()
    replaced = False
    for idx, item in enumerate(subjects):
        if str(item.get("id") or "") == normalized["id"] or str(item.get("name") or "") == normalized["name"]:
            normalized["createdAt"] = item.get("createdAt") or normalized["createdAt"]
            subjects[idx] = normalized
            replaced = True
            break
    if not replaced:
        subjects.insert(0, normalized)
    subjects = subjects[:500]
    if not _save_aic_subjects(subjects):
        _send_json_with_headers(handler, 500, {"ok": False, "error": "save_failed"})
        return True
    _upsert_aic_subject_asset(normalized)
    file_asset_id = _save_aic_subject_file_manager_asset(normalized, touch=True)
    _json_log("aic_subject_saved", name=normalized["name"], has_image=bool(normalized["mainImage"]), angle_count=len(normalized["angleImages"]), file_asset_id=file_asset_id)
    _send_json_with_headers(handler, 200, {"ok": True, "subject": normalized, "subjects": subjects, "fileAssetId": file_asset_id})
    return True


_AIC_TEXT_VOICE_MODEL = "gemini-2.5-pro-preview-tts"
_AIC_GEMINI_TTS_VOICES = {
    "achernar",
    "achird",
    "algenib",
    "algieba",
    "alnilam",
    "aoede",
    "autonoe",
    "callirrhoe",
    "charon",
    "despina",
    "enceladus",
    "erinome",
    "fenrir",
    "gacrux",
    "iapetus",
    "kore",
    "laomedeia",
    "leda",
    "orus",
    "puck",
    "pulcherrima",
    "rasalgethi",
    "sadachbia",
    "sadaltager",
    "schedar",
    "sulafat",
    "umbriel",
    "vindemiatrix",
    "zephyr",
    "zubenelgenubi",
}


def _aic_pick_text_voice(description):
    text = str(description or "").strip()
    lowered = text.lower()
    for voice in _AIC_GEMINI_TTS_VOICES:
        if voice in lowered:
            return "iapetus" if voice == "iapetu" else voice
    if any(mark in text for mark in ("\u7537", "\u6210\u719f", "\u4f4e\u6c89", "\u78c1\u6027", "\u5927\u53d4", "\u53d4", "\u7237")) or re.search(r"father|male|man|deep", text, re.I):
        return "fenrir"
    if any(mark in text for mark in ("\u65c1\u767d", "\u6c89\u7a33", "\u7a33\u91cd", "\u53d9\u8ff0", "\u64ad\u97f3")) or re.search(r"narrat|calm", text, re.I):
        return "charon"
    if any(mark in text for mark in ("\u5c11\u5973", "\u6d3b\u6cfc", "\u53ef\u7231", "\u5e74\u8f7b", "\u6e05\u4eae", "\u751c")) or re.search(r"girl|young|cute", text, re.I):
        return "autonoe"
    return "aoede"


def _aic_text_voice_candidates(description):
    primary = _aic_pick_text_voice(description)
    fallback_map = {
        "autonoe": ["autonoe", "kore", "puck", "aoede"],
        "aoede": ["aoede", "kore", "charon"],
        "fenrir": ["fenrir", "iapetus", "charon"],
        "charon": ["charon", "aoede", "fenrir"],
    }
    candidates = []
    for voice in fallback_map.get(primary, [primary, "aoede", "charon"]):
        voice = "iapetus" if voice == "iapetu" else str(voice or "").strip().lower()
        if voice and voice not in candidates:
            candidates.append(voice)
    return candidates or ["aoede"]


def _aic_voice_model_for_request(model):
    requested = str(model or "").strip()
    if not requested or requested in {"doubao-tts-2.0", "speech-2.8"}:
        return _AIC_TEXT_VOICE_MODEL
    return requested


def _handle_aic_voice_request(handler, path, method):
    if str(path or "").split("?", 1)[0] != "/api/v2/aic-voice/generate":
        return False
    if str(method or "").upper() != "POST":
        _send_json_with_headers(handler, 405, {"ok": False, "error": "method_not_allowed"})
        return True
    payload = _read_json_body_object(handler)
    description = str(payload.get("description") or payload.get("voiceDescription") or "").strip()
    sample_text = str(payload.get("sampleText") or payload.get("text") or "").strip()
    model = _aic_voice_model_for_request(payload.get("model"))
    if not description:
        _send_json_with_headers(handler, 400, {"ok": False, "error": "缺少音色描述"})
        return True
    if not sample_text:
        sample_text = "这是一段主体音色试听，用于确认角色声音。"
    tts_prompt = f"{description}\n\n{sample_text}"
    candidates = _aic_text_voice_candidates(description)
    errors = []
    pending_status = None
    for tts_voice in candidates:
        billing_ctx = None
        params = {
            "text": sample_text,
            "input_text": sample_text,
            "voice": tts_voice,
            "voice_name": tts_voice,
            "voiceName": tts_voice,
            "speaker": tts_voice,
            "voice_description": description,
            "style_prompt": description,
            "format": "wav",
            "source": "aic-subject-ai-voice",
        }
        try:
            billing_ctx = _charge_canvas_model_call(handler, "tts", model, {**params, "prompt": tts_prompt})
            if billing_ctx is None:
                return True
            result = AI_API_SERVICE.submit_media_task(model, tts_prompt, params=params, count=1)
            task_id = str(result.get("task_id") or "").strip()
            if not task_id:
                raise RuntimeError("平台没有返回音频任务ID")
            last_status = {}
            for _ in range(24):
                time.sleep(2)
                last_status = AI_API_SERVICE.get_task_status(task_id)
                audio_url = str(_extract_ai_result_url(last_status) or "").strip()
                if audio_url:
                    _send_json_with_headers(
                        handler,
                        200,
                        {
                            "ok": True,
                            "audioUrl": audio_url,
                            "taskId": task_id,
                            "model": model,
                            "provider": "lk888-ai-audio",
                            "ttsVoice": tts_voice,
                            "voiceName": tts_voice,
                            "voiceCandidates": candidates,
                            "description": description,
                            "sampleText": sample_text,
                        },
                    )
                    return True
                state = str(last_status.get("state") or last_status.get("status") or "").strip().lower()
                if state in ("failed", "failure", "error", "cancelled", "canceled"):
                    raise RuntimeError(last_status.get("error") or last_status.get("error_message") or "AI音色生成失败")
            pending_status = {"taskId": task_id, "ttsVoice": tts_voice, "lastStatus": last_status}
            errors.append(f"{tts_voice}: pending")
        except Exception as error:
            _refund_canvas_model_call(billing_ctx, f"AI音色生成失败退款：{tts_voice}")
            safe_error = AiApiService.sanitize_error(str(error))
            errors.append(f"{tts_voice}: {safe_error}")
            _json_log("aic_voice_generate_attempt_failed", model=model, tts_voice=tts_voice, error=AiApiService.sanitize_error(repr(error)))
    if pending_status:
        _send_json_with_headers(
            handler,
            202,
            {
                "ok": False,
                "pending": True,
                "error": "AI音色任务仍在生成，暂时没有返回真实音频",
                "taskId": pending_status.get("taskId"),
                "model": model,
                "provider": "lk888-ai-audio",
                "ttsVoice": pending_status.get("ttsVoice"),
                "voiceName": pending_status.get("ttsVoice"),
                "voiceCandidates": candidates,
                "lastStatus": pending_status.get("lastStatus"),
                "attemptErrors": errors,
            },
        )
        return True
    _json_log("aic_voice_generate_failed", model=model, error="; ".join(errors))
    _send_json_with_headers(
        handler,
        502,
        {
            "ok": False,
            "error": "AI音色生成失败：" + "；".join(errors),
            "model": model,
            "provider": "lk888-ai-audio",
            "ttsVoice": candidates[0],
            "voiceName": candidates[0],
            "voiceCandidates": candidates,
        },
    )
    return True


