def _aic_audio_requested_model(model):
    return str(model or "").strip() or "speech-2.8"


def _aic_audio_model_for_request(model):
    requested = _aic_audio_requested_model(model)
    if requested in _AIC_AUDIO_TEXT_FALLBACK_MODELS:
        return _AIC_TEXT_VOICE_MODEL
    return requested


def _aic_audio_text_from_payload(payload):
    payload = payload if isinstance(payload, dict) else {}
    for key in ("text", "sampleText", "prompt", "description", "lyrics"):
        value = payload.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
    values = payload.get("textInputs")
    if isinstance(values, list):
        joined = '\n'.join(str(item or "").strip() for item in values if str(item or "").strip()).strip()
        if joined:
            return joined
    return ""


def _handle_aic_audio_request(handler, path, method):
    if str(path or "").split("?", 1)[0] != "/api/v2/aic-audio/generate":
        return False
    if str(method or "").upper() != "POST":
        _send_json_with_headers(handler, 405, {"ok": False, "error": "method_not_allowed"})
        return True
    payload = _read_json_body_object(handler)
    requested_model = _aic_audio_requested_model(payload.get("model") or payload.get("audioWorkflowKey"))
    model = _aic_audio_model_for_request(requested_model)
    prompt = _aic_audio_text_from_payload(payload)
    if not prompt:
        _send_json_with_headers(handler, 400, {"ok": False, "error": "缺少音频生成文本"})
        return True
    label = _AIC_AUDIO_MODEL_LABELS.get(requested_model, _AIC_AUDIO_MODEL_LABELS.get(model, model))
    source_params = payload.get("params") if isinstance(payload.get("params"), dict) else {}
    params = dict(source_params)
    audio_refs = _dedupe_urls(_aic_collect_audio_refs(payload) + _aic_collect_audio_refs(source_params))
    voice_resource_ids = _dedupe_urls(_aic_collect_voice_resource_ids(payload) + _aic_collect_voice_resource_ids(source_params))
    params.update({
        "text": str(payload.get("text") or prompt),
        "input_text": str(payload.get("sampleText") or payload.get("text") or prompt),
        "prompt": prompt,
        "description": str(payload.get("description") or prompt),
        "format": str(params.get("format") or "mp3"),
        "source": "canvas-audio-node",
        "audioWorkflowKey": requested_model,
        "actualModel": model,
        "audioWorkflowLabel": label,
    })
    if audio_refs:
        params = _merge_audio_refs_into_params(params, audio_refs)
    if voice_resource_ids:
        params = _merge_voice_resource_into_params(params, voice_resource_ids)
    if requested_model in _AIC_AUDIO_CLONE_MODELS:
        if not voice_resource_ids:
            reason = f"{label} \u9700\u8981\u5148\u9009\u62e9\u6216\u751f\u6210\u4e00\u4e2a\u514b\u9686\u97f3\u8272ID\uff1b\u666e\u901a\u97f3\u9891URL\u5df2\u4fdd\u5b58\u4e3a\u53c2\u8003\uff0c\u4f46\u4e0d\u80fd\u76f4\u63a5\u5f53\u4f5c\u8be5\u6a21\u578b\u7684\u514b\u9686\u97f3\u8272\u8d44\u6e90\u3002"
            _send_json_with_headers(handler, 400, {"ok": False, "error": reason, "model": requested_model, "actualModel": model, "modelLabel": label, "provider": "lk888-ai-audio", "needsVoiceResourceId": True, "hasAudioReference": bool(audio_refs)})
            return True
        params.update({"clone_text": prompt, "target_text": prompt, "voice_text": prompt, "audioRefCount": len(audio_refs), "voiceResourceId": voice_resource_ids[0]})
    elif requested_model in _AIC_AUDIO_TEXT_MODELS:
        description = str(payload.get("description") or payload.get("voiceDescription") or prompt).strip()
        candidates = _aic_text_voice_candidates(description)
        voice = str(payload.get("voice") or params.get("voice") or (candidates[0] if candidates else "")).strip()
        if voice:
            params.update({"voice": voice, "voice_name": voice, "voiceName": voice, "speaker": voice, "voice_description": description, "style_prompt": description})
    elif requested_model in _AIC_AUDIO_MUSIC_MODELS:
        params.setdefault("lyrics", prompt)
        params.setdefault("style", str(payload.get("style") or payload.get("description") or ""))
    billing_ctx = None
    try:
        billing_ctx = _charge_canvas_model_call(handler, "tts", model, {**params, "prompt": prompt})
        if billing_ctx is None:
            return True
        result = AI_API_SERVICE.submit_media_task(model, prompt, params=params, count=1)
        task_id = str(result.get("task_id") or result.get("id") or "").strip()
        if not task_id:
            raise RuntimeError("\u5e73\u53f0\u6ca1\u6709\u8fd4\u56de\u97f3\u9891\u4efb\u52a1ID")
        last_status = {}
        for _ in range(30):
            time.sleep(2)
            last_status = AI_API_SERVICE.get_task_status(task_id)
            audio_url = str(_extract_ai_result_url(last_status) or "").strip()
            if audio_url:
                _send_json_with_headers(handler, 200, {"ok": True, "audioUrl": audio_url, "taskId": task_id, "model": requested_model, "actualModel": model, "modelLabel": label, "provider": "lk888-ai-audio", "prompt": prompt})
                return True
            state = str(last_status.get("state") or last_status.get("status") or "").strip().lower()
            if state in ("failed", "failure", "error", "cancelled", "canceled"):
                raise RuntimeError(last_status.get("error") or last_status.get("error_message") or "LK888??????")
        _send_json_with_headers(handler, 202, {"ok": False, "pending": True, "error": "???????????????????", "taskId": task_id, "model": requested_model, "actualModel": model, "modelLabel": label, "provider": "lk888-ai-audio", "lastStatus": last_status})
        return True
    except Exception as error:
        _refund_canvas_model_call(billing_ctx, "LK888音频生成失败退款")
        safe_error = AiApiService.sanitize_error(str(error))
        _json_log("aic_audio_generate_failed", model=model, error=safe_error)
        _send_json_with_headers(handler, 502, {"ok": False, "error": "LK888\u97f3\u9891\u751f\u6210\u5931\u8d25\uff1a" + safe_error, "model": requested_model, "actualModel": model, "modelLabel": label, "provider": "lk888-ai-audio"})
        return True


