# ===== SUBJECT-VIDEO-REFERENCE-GUARD 开始 (2026-07-01) =====
# 服务器兜底：提示词出现 @主体名 时，自动把主体库里的图片/角度图/声音带入生成请求。
# 这样即使前端提及解析漏掉，视频模型也不会只看到文字而胡乱生成人物。
def _aic_known_subject_names_for_prompt_scope():
    names = []
    seen = set()
    try:
        paths = [_aic_subjects_path()] if _get_request_account_scope() else _aic_subject_source_paths(include_accounts=False)
        if _get_request_account_scope():
            paths = [*paths, *_aic_subject_source_paths(include_accounts=True)]
        for path in paths:
            for subject in _read_aic_subjects_from_path(path):
                name = str((subject or {}).get("name") or "").strip()
                key = name.lower()
                if name and key not in seen:
                    seen.add(key)
                    names.append(name)
    except Exception:
        pass
    names.sort(key=len, reverse=True)
    return names


def _subject_name_tokens_from_prompt(prompt):
    text = str(prompt or "")
    names = []
    known_names = _aic_known_subject_names_for_prompt_scope()
    for match in re.finditer(r'@([^\s@]+)', text):
        raw_name = str(match.group(1) or "").strip()
        if not raw_name:
            continue
        name = raw_name
        for subject_name in known_names:
            if _subject_prompt_token_matches(subject_name, [raw_name]):
                name = subject_name
                break
        if name and name not in names:
            names.append(name)
    return names


def _subject_prompt_token_matches(subject_name, wanted_tokens):
    subject = str(subject_name or "").strip().lower()
    if not subject:
        return False
    for token in wanted_tokens or []:
        text = str(token or "").strip().lower()
        if text == subject:
            return True
        if not text.startswith(subject):
            continue
        suffix = text[len(subject):]
        if not suffix:
            return True
        last = subject[-1]
        first = suffix[0]
        if (
            last.isascii()
            and (last.isalnum() or last == "_")
            and first.isascii()
            and (first.isalnum() or first == "_")
        ):
            continue
        return True
    return False


def _aic_url_seems_fetchable(url, timeout=6):
    url = str(url or '').strip()
    if not (url.startswith('http://') or url.startswith('https://')):
        return False
    try:
        req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"}, method="HEAD")
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            status = getattr(resp, 'status', 200)
            ctype = str(resp.headers.get('Content-Type') or '').lower()
            if 200 <= int(status) < 400 and (not ctype or ctype.startswith('image/') or 'octet-stream' in ctype):
                return True
    except Exception:
        pass
    try:
        req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            status = getattr(resp, 'status', 200)
            ctype = str(resp.headers.get('Content-Type') or '').lower()
            return 200 <= int(status) < 400 and (ctype.startswith('image/') or 'octet-stream' in ctype)
    except Exception:
        return False


def _aic_subject_model_note(subject):
    if not isinstance(subject, dict):
        return ''
    name = str(subject.get('name') or '').strip()
    description = str(subject.get('description') or '').strip()
    voice = str(subject.get('voice') or '').strip()
    tags = [str(t or '').strip() for t in (subject.get('tags') or []) if str(t or '').strip()]
    parts = []
    if name:
        parts.append('\u4e3b\u4f53\u540d\u79f0\uff1a' + name)
    if description:
        parts.append('\u4e3b\u4f53\u63cf\u8ff0\uff1a' + description)
    elif tags:
        parts.append('\u4e3b\u4f53\u6807\u7b7e\uff1a' + '\u3001'.join(tags[:6]))
    if voice:
        parts.append('\u4e3b\u4f53\u97f3\u8272\uff1a' + voice)
    if not parts:
        return ''
    return '\uff1b'.join(parts)


def _aic_empty_subject_ref_bundle():
    return {"images": [], "audios": [], "voices": [], "tts_voices": [], "subjects": [], "notes": [], "missing_audio_voices": []}


def _aic_merge_subject_ref_bundle(target, source):
    target = target if isinstance(target, dict) else _aic_empty_subject_ref_bundle()
    source = source if isinstance(source, dict) else {}
    for key in ("images", "audios", "voices", "tts_voices", "subjects", "notes", "missing_audio_voices"):
        existing = target.setdefault(key, [])
        for value in source.get(key) or []:
            text = str(value or "").strip()
            if text and text not in existing:
                existing.append(text)
    return target


def _aic_subject_ref_bundle_from_subjects(subjects, wanted_tokens=None, wanted_ids=None):
    result = _aic_empty_subject_ref_bundle()
    wanted_ids = {str(value or "").strip() for value in (wanted_ids or []) if str(value or "").strip()}
    wanted_tokens = [str(value or "").strip() for value in (wanted_tokens or []) if str(value or "").strip()]
    for subject in subjects or []:
        if not isinstance(subject, dict):
            continue
        subject_name = str(subject.get("name") or "").strip()
        subject_id = str(subject.get("id") or subject.get("subjectId") or "").strip()
        if wanted_tokens or wanted_ids:
            name_ok = bool(wanted_tokens and _subject_prompt_token_matches(subject_name, wanted_tokens))
            id_ok = bool(wanted_ids and subject_id and subject_id in wanted_ids)
            if not (name_ok or id_ok):
                continue
        if subject_name and subject_name not in result["subjects"]:
            result["subjects"].append(subject_name)
        raw_images = []
        for value in [subject.get("mainImage") or subject.get("image") or subject.get("img"), *(subject.get("angleImages") or subject.get("imgs") or [])]:
            url = str(value or "").strip()
            if url and url not in raw_images:
                raw_images.append(url)
        usable_images = []
        for url in raw_images:
            public_url = str(_apimart_publicize_ref(url) or "").strip()
            if public_url and public_url not in usable_images and _aic_url_seems_fetchable(public_url):
                usable_images.append(public_url)
        if not usable_images:
            usable_images = raw_images
        for url in usable_images:
            if url and url not in result["images"]:
                result["images"].append(url)
        audio = _aic_subject_audio_url(subject)
        if audio and audio not in result["audios"]:
            result["audios"].append(audio)
        voice = str(subject.get("voice") or subject.get("voiceName") or subject.get("ttsVoice") or "").strip()
        tts_voice = str(subject.get("ttsVoice") or subject.get("tts_voice") or "").strip()
        if voice and voice not in ("无配音", "none", "None", "NONE"):
            if audio and voice not in result["voices"]:
                result["voices"].append(voice)
            elif not audio:
                missing = subject_name or voice
                if missing and missing not in result["missing_audio_voices"]:
                    result["missing_audio_voices"].append(missing)
        if audio and tts_voice and tts_voice not in result["tts_voices"]:
            result["tts_voices"].append(tts_voice)
        note = _aic_subject_model_note(subject)
        if note and note not in result["notes"]:
            result["notes"].append(note)
    return result


def _aic_load_subjects_by_names_or_ids(names=None, ids=None):
    names = [str(value or "").strip() for value in (names or []) if str(value or "").strip()]
    ids = {str(value or "").strip() for value in (ids or []) if str(value or "").strip()}

    def _collect(paths):
        items = []
        seen = set()
        for path in paths:
            for subject in _read_aic_subjects_from_path(path):
                name = str(subject.get("name") or "").strip()
                sid = str(subject.get("id") or subject.get("subjectId") or "").strip()
                if names or ids:
                    name_ok = bool(names and _subject_prompt_token_matches(name, names))
                    id_ok = bool(ids and sid and sid in ids)
                    if not (name_ok or id_ok):
                        continue
                key = sid or f"{name}|{subject.get('mainImage') or ''}"
                if key in seen:
                    continue
                seen.add(key)
                items.append(subject)
        return items

    if _get_request_account_scope():
        scoped = _collect([_aic_subjects_path()])
        if scoped or (not names and not ids):
            return scoped
        fallback = _collect(_aic_subject_source_paths(include_accounts=True))
        _aic_sync_subjects_to_current_scope(fallback)
        return fallback
    return _collect(_aic_subject_source_paths(include_accounts=False))


def _aic_collect_subject_payload_refs(value, subjects, names, ids):
    if value is None:
        return
    if isinstance(value, dict):
        if value.get("subject") is not None and len(value) <= 3:
            _aic_collect_subject_payload_refs(value.get("subject"), subjects, names, ids)
            return
        if value.get("id") or value.get("subjectId") or value.get("name") or value.get("mainImage") or value.get("image") or value.get("img"):
            subjects.append(value)
            name = str(value.get("name") or "").strip()
            sid = str(value.get("id") or value.get("subjectId") or "").strip()
            if name:
                names.append(name)
            if sid:
                ids.append(sid)
        return
    if isinstance(value, (list, tuple)):
        for item in value:
            _aic_collect_subject_payload_refs(item, subjects, names, ids)
        return
    text = str(value or "").strip()
    if text:
        names.append(text)


def _aic_subject_payload_mentions(data):
    data = data if isinstance(data, dict) else {}
    subjects, names, ids = [], [], []
    for key in ("subject", "aic_subject"):
        _aic_collect_subject_payload_refs(data.get(key), subjects, names, ids)
    for key in ("subjects", "subject_references", "subjectReferences", "selectedSubjects", "selected_subjects", "aic_subjects"):
        _aic_collect_subject_payload_refs(data.get(key), subjects, names, ids)
    for key in ("subject_reference_names", "subject_names", "subjectNames", "subjectName", "subject_name", "selected_subject_names", "aicSubjectNames"):
        _aic_collect_subject_payload_refs(data.get(key), [], names, ids)
    for key in ("subject_ids", "subjectIds", "subjectId", "subject_id", "selected_subject_ids", "aicSubjectIds"):
        value = data.get(key)
        if isinstance(value, (list, tuple)):
            ids.extend(str(item or "").strip() for item in value if str(item or "").strip())
        elif value not in (None, ""):
            ids.append(str(value).strip())
    names = list(dict.fromkeys([name for name in names if name]))
    ids = list(dict.fromkeys([sid for sid in ids if sid]))
    return subjects, names, ids


def _aic_subject_reference_urls_for_prompt(prompt):
    wanted = _subject_name_tokens_from_prompt(prompt)
    if not wanted:
        return _aic_empty_subject_ref_bundle()
    return _aic_subject_ref_bundle_from_subjects(_load_aic_subjects_for_prompt(wanted), wanted_tokens=wanted)


def _aic_subject_reference_urls_for_payload(data, prompt):
    result = _aic_subject_reference_urls_for_prompt(prompt)
    inline_subjects, names, ids = _aic_subject_payload_mentions(data)
    if inline_subjects:
        _aic_merge_subject_ref_bundle(result, _aic_subject_ref_bundle_from_subjects(inline_subjects))
    if names or ids:
        subjects = _aic_load_subjects_by_names_or_ids(names, ids)
        _aic_merge_subject_ref_bundle(result, _aic_subject_ref_bundle_from_subjects(subjects, wanted_tokens=names, wanted_ids=ids))
    return result

def _merge_unique_list(existing, additions):
    out = []
    for value in existing or []:
        text = str(value or "").strip()
        if text and text not in out:
            out.append(text)
    for value in additions or []:
        text = str(value or "").strip()
        if text and text not in out:
            out.append(text)
    return out


def _merge_image_role_list(existing, additions):
    out = []
    seen = set()
    def _add(value):
        if isinstance(value, dict):
            url = str(value.get("url") or value.get("image_url") or value.get("imageUrl") or "").strip()
            role = str(value.get("role") or "").strip()
            if not url:
                return
            key = (url, role)
            if key in seen:
                return
            seen.add(key)
            out.append({"url": url, "role": role} if role else {"url": url})
            return
        url = str(value or "").strip()
        if not url:
            return
        key = (url, "")
        if key in seen:
            return
        seen.add(key)
        out.append({"url": url})
    for item in existing or []:
        _add(item)
    for item in additions or []:
        _add(item)
    return out


def _ensure_subject_refs_in_media_payload(data, prompt=None):
    if not isinstance(data, dict):
        return data
    prompt_text = str(prompt if prompt is not None else data.get("prompt") or data.get("text") or "")
    refs = _aic_subject_reference_urls_for_payload(data, prompt_text)
    images = refs.get("images") or []
    audios = refs.get("audios") or []
    voices = refs.get("voices") or []
    tts_voices = refs.get("tts_voices") or []
    notes = refs.get("notes") or []
    missing_voice_audio = refs.get("missing_audio_voices") or []
    if not images and not audios and not voices and not tts_voices and not notes and not missing_voice_audio:
        return data
    for key in ("images", "image_urls", "imageUrls", "reference_image_urls", "inputUrls"):
        data[key] = _merge_unique_list(data.get(key), images)
    if images:
        # Subject references are model references only. Do not synthesize old first/last-frame fields here.
        data.setdefault("image_url", images[0])
        data.setdefault("imageUrl", images[0])
    if audios:
        for key in (
            "audios",
            "audio_urls",
            "audioUrls",
            "reference_audio_urls",
            "voice_audio_urls",
            "voiceAudioUrls",
            "subject_audio_urls",
            "subjectAudioUrls",
        ):
            data[key] = _merge_unique_list(data.get(key), audios)
        data.setdefault("audioUrl", audios[0])
        data.setdefault("audio_url", audios[0])
        data.setdefault("reference_audio", audios[0])
        data.setdefault("referenceAudio", audios[0])
        data.setdefault("reference_audio_url", audios[0])
        data.setdefault("referenceAudioUrl", audios[0])
        data.setdefault("voice_audio", audios[0])
        data.setdefault("voiceAudio", audios[0])
        data.setdefault("voice_audio_url", audios[0])
        data.setdefault("voiceAudioUrl", audios[0])
        data.setdefault("subject_audio", audios[0])
        data.setdefault("subjectAudio", audios[0])
        data.setdefault("subject_audio_url", audios[0])
        data.setdefault("subjectAudioUrl", audios[0])
        data.setdefault("require_subject_voice_audio", True)
        data.setdefault("strictSubjectVoice", True)
        data.setdefault("voiceConsistencyRequired", True)
        data.setdefault("subject_voice_mode", "strict")
    if voices:
        data["subject_voice_names"] = _merge_unique_list(data.get("subject_voice_names"), voices)
        data.setdefault("voice", voices[0])
        data.setdefault("voiceName", voices[0])
        if not tts_voices:
            data.setdefault("ttsVoice", voices[0])
        data.setdefault("generate_audio", True)
        data.setdefault("with_audio", True)
        data.setdefault("sound", "on")
    if tts_voices:
        data["subject_tts_voices"] = _merge_unique_list(data.get("subject_tts_voices"), tts_voices)
        data.setdefault("ttsVoice", tts_voices[0])
        data.setdefault("voiceId", tts_voices[0])
        data.setdefault("generate_audio", True)
        data.setdefault("with_audio", True)
        data.setdefault("sound", "on")
    data["subject_reference_names"] = _merge_unique_list(data.get("subject_reference_names"), refs.get("subjects") or [])
    if missing_voice_audio:
        data["subject_voice_missing_audio"] = _merge_unique_list(data.get("subject_voice_missing_audio"), missing_voice_audio)
        data.setdefault("require_subject_voice_audio", True)
        data.setdefault("strictSubjectVoice", True)
        data.setdefault("voiceConsistencyRequired", True)
        data.setdefault("subject_voice_mode", "strict")
    if notes:
        data["subject_model_notes"] = _merge_unique_list(data.get("subject_model_notes"), notes)
        if audios or voices:
            voice_instruction = "\u82e5\u6709\u4e3b\u4f53\u97f3\u8272\u6216\u53c2\u8003\u97f3\u9891\uff0c\u58f0\u97f3\u5fc5\u987b\u6309\u8be5\u4e3b\u4f53\u4fdd\u6301\u4e00\u81f4\u3002"
        elif missing_voice_audio:
            voice_instruction = "\u82e5\u4e3b\u4f53\u53ea\u6709\u6587\u5b57\u97f3\u8272\u5907\u6ce8\uff0c\u6309\u8be5\u6587\u5b57\u97f3\u8272\u5c3d\u91cf\u5339\u914d\uff0c\u4e0d\u8981\u56e0\u7f3a\u5c11\u97f3\u9891\u800c\u6539\u53d8\u4eba\u7269\u5f62\u8c61\u3002"
        else:
            voice_instruction = ""
        note_text = (
            "\n\n\u3010\u4e3b\u4f53\u53c2\u8003\u4fe1\u606f\uff0c\u5fc5\u987b\u4fdd\u6301\u4e00\u81f4\u3011"
            + "\uff1b".join(notes)
            + "\u3002\u751f\u6210\u89c6\u9891\u65f6\uff1a\u4eba\u7269\u5fc5\u987b\u53c2\u7167\u4e3b\u4f53\u56fe\u50cf\u7684\u8138\u578b\u3001\u53d1\u578b\u3001\u8eab\u5f62\u3001\u670d\u88c5\u548c\u4e3b\u8981\u7279\u5f81\uff1b"
            + voice_instruction
        )
        if note_text not in prompt_text:
            data["prompt"] = prompt_text + note_text
    try:
        _json_log(
            "aic_subject_refs_injected",
            subjects=refs.get("subjects") or [],
            image_count=len(images),
            audio_count=len(audios),
            voice_count=len(voices),
            tts_voice_count=len(tts_voices),
            missing_voice_audio_count=len(missing_voice_audio),
            note_count=len(notes),
        )
    except Exception:
        pass
    return data
