def _aic_subject_check_model_id(model):
    raw = str(model or "").strip()
    if not raw:
        return ""
    try:
        raw = _apply_model_remap(raw)
    except Exception:
        pass
    try:
        raw = _lk888_normalize_video_model(raw)
    except Exception:
        pass
    return str(raw or model or "").strip()


def _aic_collect_image_refs_from_payload(data):
    refs = []
    data = data if isinstance(data, dict) else {}
    for key in (
        "images",
        "image_urls",
        "imageUrls",
        "reference_image_urls",
        "inputUrls",
        "image_url",
        "imageUrl",
        "first",
        "first_frame",
        "firstFrameUrl",
    ):
        _extend_url_list(refs, data.get(key))
    _extend_url_list(refs, data.get("image_with_roles"))
    return _dedupe_urls(refs)


def _aic_payload_subject_context(data):
    data = data if isinstance(data, dict) else {}
    prompt = str(data.get("prompt") or data.get("text") or data.get("input") or data.get("content") or "")
    prompt_names = _subject_name_tokens_from_prompt(prompt)
    inline_subjects, names, ids = _aic_subject_payload_mentions(data)
    subject_names = _merge_unique_list(data.get("subject_reference_names"), [*prompt_names, *names])
    notes = data.get("subject_model_notes") if isinstance(data.get("subject_model_notes"), list) else []
    requested = bool(prompt_names or inline_subjects or names or ids or subject_names or notes or data.get("__aicSubjectInjected"))
    return {
        "requested": requested,
        "prompt_names": prompt_names,
        "subject_names": subject_names,
        "ids": ids,
        "notes": notes,
    }


def _aic_payload_has_subject_voice(data):
    data = data if isinstance(data, dict) else {}
    for key in ("voice", "voiceName", "ttsVoice"):
        if str(data.get(key) or "").strip():
            return True
    voices = data.get("subject_voice_names")
    if isinstance(voices, list):
        return any(str(value or "").strip() for value in voices)
    return bool(str(voices or "").strip())


def _aic_subject_voice_is_required(data):
    data = data if isinstance(data, dict) else {}
    for key in ("require_subject_voice_audio", "subjectVoiceRequired", "strictSubjectVoice", "voiceConsistencyRequired"):
        value = data.get(key)
        if value is True:
            return True
        if str(value or "").strip().lower() in ("1", "true", "yes", "required", "strict"):
            return True
    mode = str(data.get("subject_voice_mode") or data.get("voiceConsistency") or "").strip().lower()
    return mode in ("required", "strict", "clone", "audio", "voice")


def _aic_audio_reference_is_required(data):
    data = data if isinstance(data, dict) else {}
    for key in (
        "require_audio_reference",
        "requireAudioReference",
        "audioReferenceRequired",
        "lipSyncRequired",
        "lip_sync_required",
        "mouthSyncRequired",
    ):
        value = data.get(key)
        if value is True:
            return True
        if str(value or "").strip().lower() in ("1", "true", "yes", "required", "strict"):
            return True
    mode = str(
        data.get("mode")
        or data.get("referenceMode")
        or data.get("videoReferenceMode")
        or data.get("audioReferenceMode")
        or data.get("subject_voice_mode")
        or ""
    ).strip().lower()
    return mode in ("音频参考", "audio", "audio_reference", "reference_audio", "lip_sync", "lipsync")


def _aic_model_supports_subject_images(model):
    mid = _aic_subject_check_model_id(model)
    if not mid:
        return False
    if mid in AIC_SUBJECT_IMAGE_BLOCKED_MODELS:
        return False
    if _ark_should_route(mid) or mid in AIC_SUBJECT_IMAGE_VIDEO_MODELS:
        return True
    low = mid.lower()
    return any(token in low for token in ("cankao", "reference", "-ref", "r2v", "seedance-2-0"))


def _aic_model_supports_subject_voice(model):
    mid = _aic_subject_check_model_id(model)
    if not mid:
        return False
    if _ark_should_route(mid) or mid in AIC_SUBJECT_VOICE_VIDEO_MODELS:
        return True
    return False


def _aic_subject_voice_model_options_text():
    labels = []
    for model_id, label in AIC_SUBJECT_VOICE_MODEL_LABELS:
        if _ark_should_route(model_id) or model_id in AIC_SUBJECT_VOICE_VIDEO_MODELS:
            labels.append(label)
    return "、".join(labels)


def _aic_validate_subject_model_support(data, media_kind=None):
    data = data if isinstance(data, dict) else {}
    if str(media_kind or "").strip().lower() not in ("", "video"):
        return ""
    ctx = _aic_payload_subject_context(data)
    audio_mode_required = _aic_audio_reference_is_required(data)
    if not ctx.get("requested") and not audio_mode_required:
        return ""
    image_refs = _aic_collect_image_refs_from_payload(data)
    audio_refs = _aic_collect_audio_refs(data)
    has_voice = _aic_payload_has_subject_voice(data)
    missing_voice_audio = data.get("subject_voice_missing_audio")
    names = ctx.get("subject_names") or ctx.get("prompt_names") or []
    display_name = "、".join(names[:3]) if names else "当前主体"
    model = data.get("model")
    if audio_mode_required:
        if not audio_refs:
            return "已选择音频参考，但没有找到可用音频。请先上传或连入音频，再生成视频。"
        if not _aic_model_supports_subject_voice(model):
            return "当前模型不支持音频参考/嘴型同步，已停止生成。可用模型：%s。请切换后再生成，避免声音和嘴型不一致。" % _aic_subject_voice_model_options_text()
    if not ctx.get("requested"):
        return ""
    if not image_refs:
        return "找不到@主体「%s」的参考图片，请先从主体库选择主体，或确认当前账号下已经保存这个主体。" % display_name
    if not _aic_model_supports_subject_images(model):
        return "当前模型不支持主体参考，已停止生成。请切换到火山官方 Seedance、可灵-Omni 参考生、Vidu Q3 参考生等支持主体参考的模型。"
    if missing_voice_audio and _aic_subject_voice_is_required(data):
        if isinstance(missing_voice_audio, list):
            missing_text = "、".join(str(v or "").strip() for v in missing_voice_audio if str(v or "").strip())
        else:
            missing_text = str(missing_voice_audio or "").strip()
        return "主体「%s」只有文字音色备注，没有真实音频。请在主体详情里上传音频或AI生成音色后再生成视频，否则声音无法保持一致。" % (missing_text or display_name)
    if (audio_refs or has_voice) and not _aic_model_supports_subject_voice(model):
        return "当前模型不支持主体声音参考，已停止生成。可用模型：%s。请切换后再生成，避免声音不一致。" % _aic_subject_voice_model_options_text()
    return ""


def _load_local_comic_state():
    global LOCAL_COMIC_PROJECT_NEXT_ID, LOCAL_COMIC_ASSET_NEXT_ID
    path = os.path.abspath(str(_current_local_comic_state_path() or ""))
    state = _agent_comic_runtime_state()
    if not path or not os.path.isfile(path):
        if state is not None:
            state["loaded"] = True
        return False
    try:
        with open(path, "r", encoding="utf-8") as file:
            payload = json.load(file)
    except Exception as error:
        _json_log("local_comic_state_load_failed", path=path, error=str(error))
        if state is not None:
            state["loaded"] = True
        return False

    projects = payload.get("projects") if isinstance(payload, dict) else {}
    tasks = payload.get("tasks") if isinstance(payload, dict) else {}
    assets = payload.get("assets") if isinstance(payload, dict) else {}
    asset_usages = payload.get("asset_usages") if isinstance(payload, dict) else []
    LOCAL_COMIC_PROJECTS.clear()
    if isinstance(projects, dict):
        iterable = projects.values()
    elif isinstance(projects, list):
        iterable = projects
    else:
        iterable = []
    max_project_id = 0
    for project in iterable:
        if not isinstance(project, dict):
            continue
        try:
            project_id = int(project.get("id"))
        except Exception:
            continue
        max_project_id = max(max_project_id, project_id)
        LOCAL_COMIC_PROJECTS[project_id] = project

    LOCAL_COMIC_TASKS.clear()
    AI_COMIC_TASKS.clear()
    if isinstance(tasks, dict):
        for task_id, task in tasks.items():
            if not isinstance(task, dict):
                continue
            normalized_id = str(task.get("id") or task_id)
            task["id"] = normalized_id
            LOCAL_COMIC_TASKS[normalized_id] = task
            if str(task.get("provider") or "").lower() == "ai" or normalized_id.startswith("ai-"):
                AI_COMIC_TASKS[normalized_id] = task

    try:
        next_project_id = max(int(payload.get("next_project_id") or 1), max_project_id + 1)
    except Exception:
        next_project_id = max_project_id + 1 if max_project_id else 1
    if not _set_local_comic_counter("next_project_id", next_project_id):
        LOCAL_COMIC_PROJECT_NEXT_ID = next_project_id

    LOCAL_COMIC_ASSETS.clear()
    if isinstance(assets, dict):
        asset_iterable = assets.values()
    elif isinstance(assets, list):
        asset_iterable = assets
    else:
        asset_iterable = []
    max_asset_id = 0
    for asset in asset_iterable:
        if not isinstance(asset, dict):
            continue
        try:
            asset_id = int(asset.get("id"))
        except Exception:
            continue
        max_asset_id = max(max_asset_id, asset_id)
        LOCAL_COMIC_ASSETS[asset_id] = asset
    try:
        next_asset_id = max(int(payload.get("next_asset_id") or 1), max_asset_id + 1)
    except Exception:
        next_asset_id = max_asset_id + 1 if max_asset_id else 1
    if not _set_local_comic_counter("next_asset_id", next_asset_id):
        LOCAL_COMIC_ASSET_NEXT_ID = next_asset_id

    LOCAL_COMIC_ASSET_USAGES.clear()
    if isinstance(asset_usages, list):
        LOCAL_COMIC_ASSET_USAGES.extend(item for item in asset_usages if isinstance(item, dict))
    if state is not None:
        state["loaded"] = True
    return True


def _activate_agent_comic_runtime(scope):
    scope = _sanitize_account_scope(scope)
    if not scope:
        return
    _set_agent_runtime_scope(scope)
    state = _agent_comic_runtime_state(scope)
    with state["load_lock"]:
        if not state["loaded"]:
            _load_local_comic_state()


@contextmanager
def _agent_comic_runtime_context(scope):
    previous_account_scope = _get_request_account_scope()
    previous_runtime_scope = _get_agent_runtime_scope()
    scope = _sanitize_account_scope(scope)
    _set_request_account_scope(scope)
    _activate_agent_comic_runtime(scope)
    try:
        yield
    finally:
        _set_request_account_scope(previous_account_scope)
        _set_agent_runtime_scope(previous_runtime_scope)


def _append_unique_url(values, url):
    url = str(url or "").strip()
    current = values if isinstance(values, list) else []
    result = [str(item).strip() for item in current if str(item or "").strip()]
    if url and url not in result:
        result.append(url)
    return result


def _set_url_at_index(values, url, index):
    url = str(url or "").strip()
    if not url:
        return _append_unique_url(values, url)
    try:
        idx = int(index) - 1
    except Exception:
        idx = -1
    if idx < 0:
        return _append_unique_url(values, url)
    result = [str(item or "").strip() for item in (values if isinstance(values, list) else [])]
    while len(result) <= idx:
        result.append("")
    result = ["" if item == url else item for item in result]
    result[idx] = url
    return result


