def _clip_comic_prompt_text(value, limit=1200):
    text = re.sub(r"\s+", " ", str(value or "")).strip()
    limit = int(limit or 0)
    if limit <= 0 or len(text) <= limit:
        return text
    return text[: limit - 1].rstrip() + "…"


COMIC_VIDEO_SUBMIT_PROMPT_MAX_CHARS = 4096
COMIC_KLING_OMNI_REFERENCE_VIDEO_PROMPT_MAX_CHARS = 2500


def _comic_video_submit_prompt_limit(model):
    model_id = str(model or "").strip()
    try:
        model_id = _lk888_normalize_video_model(_apply_model_remap(model_id))
    except Exception:
        model_id = _lk888_normalize_video_model(model_id)
    if model_id == "kling-v3-omni-cankao":
        return COMIC_KLING_OMNI_REFERENCE_VIDEO_PROMPT_MAX_CHARS
    return COMIC_VIDEO_SUBMIT_PROMPT_MAX_CHARS


def _truncate_comic_video_submit_prompt(prompt, limit=COMIC_VIDEO_SUBMIT_PROMPT_MAX_CHARS):
    text = str(prompt or "").strip()
    limit = int(limit or 0)
    if limit <= 0 or len(text) <= limit:
        return text
    return text[:limit].rstrip()


