def _local_comic_visual_origin_rule(project, target_type=""):
    if not isinstance(project, dict):
        return ""
    config = project.get("config") if isinstance(project.get("config"), dict) else {}
    raw = _first_non_empty(
        config.get("visual_origin"),
        config.get("visualOrigin"),
        project.get("visual_origin"),
        project.get("visualOrigin"),
    )
    origin = str(raw or "").strip().lower()
    if not origin:
        return ""
    target_type = str(target_type or "").strip()
    if origin in {"foreign", "overseas", "global", "international", "abroad", "国外", "海外"}:
        base = (
            "视觉地域偏好：国外/海外；该规则只影响画面中的人物外貌、服装、场景环境和生活细节，"
            "所有脚本、人物描述、分镜描述、image_prompt、video_prompt 仍必须使用中文。"
        )
        if target_type == "character":
            return base + (
                "人物视觉外貌默认必须表现为外国人/海外多元族裔，避免中国本土/东亚默认脸；"
                "中文姓名、中文对白或中文剧本描述不能作为生成中国人外貌的依据。"
                "五官轮廓、发色/发型、肤色多样性、服装和气质要符合海外当地环境；"
                "除非剧本明确写明中国人/华人/东亚人，否则不要生成中国本土人物。"
            )
        if target_type == "scene":
            return base + "场景默认必须表现海外城市、建筑、街区、室内陈设和当地生活环境，不要默认中国本土环境。"
        return base + (
            "角色视觉外貌默认必须是外国人/海外多元族裔，场景和道具也要贴合海外当地环境；"
            "中文姓名、中文对白或中文分镜文字不能把画面拉回中国本土人物/环境。"
        )
    if origin in {"domestic", "china", "chinese", "cn", "国内", "本土", "中国"}:
        return "视觉地域偏好：国内/中国本土。人物形象、场景环境和生活细节优先符合中国语境。"
    return ""


def _local_comic_style_rule(project):
    if not isinstance(project, dict):
        return ""
    config = project.get("config") if isinstance(project.get("config"), dict) else {}
    style = _first_non_empty(config.get("comic_style"), config.get("comicStyle"))
    custom_name = _first_non_empty(config.get("custom_style_name"), config.get("customStyleName"))
    custom_desc = _first_non_empty(config.get("custom_style_description"), config.get("customStyleDescription"))
    custom_prompt = _first_non_empty(config.get("custom_style_prompt"), config.get("customStylePrompt"))
    parts = []
    if custom_name:
        parts.append(f"自定义风格：{_clip_comic_prompt_text(custom_name, 120)}")
    if custom_desc:
        parts.append(f"风格说明：{_clip_comic_prompt_text(custom_desc, 260)}")
    if custom_prompt:
        parts.append(f"画风提示词：{_clip_comic_prompt_text(custom_prompt, 700)}")
    elif style:
        parts.append(f"画风/美术风格：{_clip_comic_prompt_text(style, 240)}")
    if not parts:
        return ""
    return "项目画风约束：必须在角色、场景、道具和分镜画面中保持一致；" + "；".join(parts)


def _split_comic_script_fragments(text):
    source = str(text or "").replace("\r\n", "\n").replace("\r", "\n")
    fragments = []
    for part in re.split(r"(?<=[。！？!?；;])|\n+", source):
        part = part.strip(" \t\r\n，,；;。！？")
        if part:
            fragments.append(part)
    if not fragments and source.strip():
        fragments = [source.strip()]
    return fragments


def _comic_asset_name_candidates(item, collection=""):
    if not isinstance(item, dict):
        return []
    candidates = []

    def add(value):
        if isinstance(value, (list, tuple, set)):
            for child in value:
                add(child)
            return
        text = str(value or "").strip()
        if text and text not in candidates:
            candidates.append(text)

    for key in (
        "name",
        "title",
        "character_name",
        "characterName",
        "scene_name",
        "sceneName",
        "prop_name",
        "propName",
        "location",
        "place",
        "venue",
        "environment",
        "object",
        "item",
        "type_name",
        "typeName",
        "name_en",
        "nameEn",
        "english_name",
        "englishName",
        "alias",
        "aliases",
        "aka",
    ):
        add(item.get(key))

    if str(collection or "") == "scenes":
        for key in ("time_of_day", "atmosphere", "setting"):
            add(item.get(key))
    elif str(collection or "") == "props":
        for key in ("category", "material", "color", "usage", "owner"):
            add(item.get(key))

    for name in candidates:
        if re.search(r"[A-Za-z]", name):
            for token in re.findall(r"[A-Za-z][A-Za-z'-]{2,}", name):
                add(token)
            words = re.findall(r"[A-Za-z][A-Za-z'-]{2,}", name)
            if len(words) >= 2:
                add(" ".join(words[-2:]))
        for part in re.split(r"[/／|、，,（）()\[\]【】\s]+", name):
            part = part.strip()
            if len(part) >= 2:
                add(part)
        if re.search(r"[\u4e00-\u9fff]", name):
            common_terms = []
            if str(collection or "") == "scenes":
                common_terms = [
                    "咖啡店",
                    "酒吧",
                    "餐厅",
                    "学校",
                    "教室",
                    "医院",
                    "病房",
                    "街道",
                    "巷子",
                    "房间",
                    "客厅",
                    "卧室",
                    "办公室",
                    "仓库",
                    "天台",
                    "地铁站",
                    "车站",
                    "吧台",
                    "门口",
                    "走廊",
                    "楼梯",
                    "庭院",
                    "森林",
                    "山洞",
                    "海边",
                ]
            elif str(collection or "") == "props":
                common_terms = [
                    "信封",
                    "信件",
                    "手机",
                    "钥匙",
                    "手表",
                    "戒指",
                    "项链",
                    "照片",
                    "相片",
                    "书",
                    "日记",
                    "笔记本",
                    "箱子",
                    "盒子",
                    "药瓶",
                    "杯子",
                    "咖啡",
                    "刀",
                    "剑",
                    "枪",
                    "伞",
                    "包",
                    "徽章",
                    "硬币",
                    "票据",
                ]
            for term in common_terms:
                if term in name:
                    add(term)
            if len(name) >= 3 and name[0] in "旧老新破黑白红蓝金银湿冷热小大古":
                add(name[1:])
    return candidates


def _comic_text_has_asset_name(text, names):
    text = str(text or "")
    if not text:
        return False
    for name in names or []:
        name = str(name or "").strip()
        if not name:
            continue
        if re.search(r"[A-Za-z]", name):
            if len(re.sub(r"[^A-Za-z0-9]", "", name)) < 3:
                continue
            if re.search(rf"(?<![A-Za-z0-9]){re.escape(name)}(?![A-Za-z0-9])", text, re.IGNORECASE):
                return True
        elif name in text:
            return True
    return False


def _comic_asset_related_script_snippets(project, item, limit=900, collection=""):
    if not isinstance(project, dict) or not isinstance(item, dict):
        return ""
    names = _comic_asset_name_candidates(item, collection)
    if not names:
        return ""
    candidates = []
    source_text = "\n".join(
        str(value or "")
        for value in (project.get("source_text"), project.get("description"), project.get("title"))
        if str(value or "").strip()
    )
    fragments = _split_comic_script_fragments(source_text)
    matched_indexes = set()
    for index, fragment in enumerate(fragments):
        if _comic_text_has_asset_name(fragment, names):
            matched_indexes.update(i for i in (index - 1, index, index + 1) if 0 <= i < len(fragments))
    for index in sorted(matched_indexes):
        candidates.append(fragments[index])
    for storyboard in project.get("storyboards") or []:
        if not isinstance(storyboard, dict):
            continue
        text = " ".join(
            str(storyboard.get(key) or "")
            for key in (
                "description",
                "image_prompt",
                "storyboard_image_prompt",
                "action_grid_prompt",
                "video_prompt",
                "shot_type",
                "camera_angle",
                "camera_movement",
            )
        )
        related = _comic_text_has_asset_name(text, names)
        if not related:
            for collection_key in ("characters", "props"):
                for value in storyboard.get(collection_key) or []:
                    if isinstance(value, dict) and _comic_text_has_asset_name(" ".join(_comic_asset_name_candidates(value, collection_key)), names):
                        related = True
                        break
                if related:
                    break
        scene = storyboard.get("scene")
        if not related and isinstance(scene, dict):
            related = _comic_text_has_asset_name(" ".join(_comic_asset_name_candidates(scene, "scenes")), names)
        if related and text.strip():
            sequence = storyboard.get("sequence") or storyboard.get("id") or ""
            candidates.append(f"分镜{sequence}：{text.strip()}")
    seen = set()
    merged = []
    total = 0
    snippet_limit = max(80, min(360, int(limit or 360)))
    for candidate in candidates:
        text = _clip_comic_prompt_text(candidate, snippet_limit)
        if not text or text in seen:
            continue
        seen.add(text)
        if total + len(text) > int(limit or 0) and merged:
            break
        merged.append(text)
        total += len(text)
    return "\n".join(merged)


def _comic_asset_generation_prompt(collection, item, related):
    name = str((item or {}).get("name") or "").strip()
    if collection == "characters":
        gender = _clip_comic_prompt_text((item or {}).get("gender"), 80)
        age = _clip_comic_prompt_text((item or {}).get("age"), 80)
        personality = _clip_comic_prompt_text((item or {}).get("personality"), 180)
        appearance = (item or {}).get("appearance")
        if isinstance(appearance, dict) and appearance:
            appearance_text = _clip_comic_prompt_text(json.dumps(appearance, ensure_ascii=False), 300)
        else:
            appearance_text = _clip_comic_prompt_text(appearance, 300)
        visual_fragments = []
        action_fragments = []
        relation_fragments = []
        for fragment in _split_comic_script_fragments(related):
            if re.search(r"外貌|脸|眼|发|头发|身材|穿|戴|衣|裙|袍|甲|鞋|帽|风衣|校服|制服|雨水|血|伤|神情|表情|笑|哭|紧张|愤怒|疲惫|冷漠|face|eye|hair|body|wear|wore|dress|coat|trench|uniform|shirt|jacket|hat|shoe|wet|rain|blood|scar|wound|expression|looked|smile|cry|angry|nervous|tense|tired|exhausted|cold", fragment, re.IGNORECASE):
                visual_fragments.append(fragment)
            if re.search(r"推门|走|跑|看|注视|拿|握|抱|坐|站|躲|打|杀|救|递|放|带着|手边|动作|enter|entered|walk|run|look|watch|stare|hold|held|grab|carry|carried|raise|raises|raised|sit|stand|hide|fight|kill|save|hand|give|put|with|beside", fragment, re.IGNORECASE):
                action_fragments.append(fragment)
            if re.search(r"父|母|兄|姐|弟|妹|恋|夫妻|朋友|同事|敌|关系|相识|重逢|背叛|保护|father|mother|brother|sister|lover|couple|wife|husband|friend|colleague|enemy|relationship|reunion|betray|protect", fragment, re.IGNORECASE):
                relation_fragments.append(fragment)
        visual_text = _clip_comic_prompt_text("；".join(dict.fromkeys(visual_fragments)), 420)
        action_text = _clip_comic_prompt_text("；".join(dict.fromkeys(action_fragments)), 360)
        relation_text = _clip_comic_prompt_text("；".join(dict.fromkeys(relation_fragments)), 280)
        lines = [
            f"人物：{name}" if name else "人物参考图",
            "人物描写（必须用于生图）：",
            f"角色定位：{name}" + (f"，{gender}" if gender else "") + (f"，{age}" if age else ""),
            f"外貌服装/状态：{_first_non_empty(appearance_text, visual_text, '剧本未直接说明具体五官时，按剧情语境做保守可视化补足，不能脱离剧本气质。')}",
            f"神态情绪/性格：{_first_non_empty(personality, visual_text, '根据剧本片段提取当前情绪和气质。')}",
            f"关键动作/随身道具：{_first_non_empty(action_text, '根据剧本片段提取动作和手中/身边道具。')}",
        ]
        if relation_text:
            lines.append(f"人物关系/剧情关联：{relation_text}")
        lines.extend(
            [
                f"剧本依据：\n{related}",
                "生成角色参考图时，必须把上面的人物描写转成可见画面；优先表现剧本明示的服装、状态、神态、动作和道具；未明示的外貌只做保守补足。",
            ]
        )
        return _clip_comic_prompt_text("\n".join(line for line in lines if line), 1800)
    intro = f"{name}在剧本中的相关片段" if name else "剧本相关片段"
    type_rules = {
        "characters": "生成角色参考图时，必须从片段中提取身份、年龄感、性别气质、外貌服装、神态情绪、关键动作、随身道具和人物关系；剧本未明确的外观只做保守可视化补足。",
        "scenes": "生成场景参考图时，必须从片段中提取地点、时代/时间、天气光线、空间布局、重要陈设、氛围和叙事功能；剧本未明确的部分只做保守可视化补足。",
        "props": "生成道具参考图时，必须从片段中提取外观形状、材质、颜色/状态、使用方式、所属角色和剧情作用；剧本未明确的部分只做保守可视化补足。",
    }
    rule = type_rules.get(collection, "生成参考图时，必须优先使用剧本片段中的具体视觉信息。")
    return _clip_comic_prompt_text(f"{intro}：\n{related}\n{rule}", 1600)


def _enrich_local_comic_asset_prompts(project, collection):
    if not isinstance(project, dict):
        return 0
    changed = 0
    for item in project.get(collection) or []:
        if not isinstance(item, dict):
            continue
        related = _comic_asset_related_script_snippets(project, item, 900, collection)
        if not related:
            continue
        name = str(item.get("name") or "").strip()
        current_description = str(item.get("description") or "").strip()
        current_base = str(item.get("base_prompt") or "").strip()
        generated = _comic_asset_generation_prompt(collection, item, related)
        if not current_description or current_description == name or len(current_description) < 12:
            item["description"] = generated
            changed += 1
        elif related not in current_description:
            item["description"] = _clip_comic_prompt_text(current_description + "\n剧本相关片段：\n" + related, 1400)
            changed += 1
        if not current_base or current_base == name or len(current_base) < 12 or related not in current_base:
            item["base_prompt"] = generated
            changed += 1
        for prompt_key in ("visual_prompt", "asset_prompt"):
            current_value = str(item.get(prompt_key) or "").strip()
            if not current_value or related not in current_value:
                item[prompt_key] = generated
                changed += 1
    return changed


def _local_comic_asset_context(project, target_type, target_id):
    collection = {"character": "characters", "scene": "scenes", "prop": "props"}.get(str(target_type or ""))
    item = _local_comic_find_by_id(project.get(collection), target_id) if collection and isinstance(project, dict) else None
    if not isinstance(item, dict):
        return ""
    labels = {"character": "人物/角色", "scene": "场景", "prop": "道具"}
    lines = [f"生成对象：{labels.get(target_type, target_type)}"]
    for label, key in (
        ("名称", "name"),
        ("描述", "description"),
        ("基础提示词", "base_prompt"),
        ("时间", "time_of_day"),
        ("氛围", "atmosphere"),
        ("类别", "category"),
        ("性别", "gender"),
        ("年龄", "age"),
    ):
        text = _comic_asset_field_prompt_text(collection, key, item.get(key))
        text = _clip_comic_prompt_text(text, 140 if collection == "characters" else 240)
        if text:
            lines.append(f"{label}：{text}")
    appearance = item.get("appearance")
    if isinstance(appearance, dict) and appearance:
        lines.append(f"外观设定：{_clip_comic_prompt_text(json.dumps(appearance, ensure_ascii=False), 180 if collection == 'characters' else 240)}")
    related_limit = 160 if collection == "characters" else 360
    related = _comic_asset_related_script_snippets(project, item, related_limit, collection)
    if related:
        lines.append(f"短剧本依据（只用于识别资产，不得覆盖上方硬性规格）：\n{related}")
    return "\n".join(lines)


def _comic_asset_field_prompt_text(collection, key, value):
    text = re.sub(r"\s+", " ", str(value or "")).strip()
    if not text:
        return ""
    if collection == "characters":
        for marker in (
            "剧本相关片段：",
            "短剧本依据",
            "剧本依据：",
            "本次生成要求：",
            "分镜1",
            "分镜2",
            "分镜3",
            "photorealistic",
            "cinematic",
        ):
            idx = text.find(marker)
            if idx > 0:
                text = text[:idx].strip(" ；;，,。")
        if key == "base_prompt":
            return ""
    return text


def _comic_scene_allows_crowd(item):
    if not isinstance(item, dict):
        return False
    text = " ".join(
        str(item.get(key) or "")
        for key in (
            "name",
            "title",
            "description",
            "base_prompt",
            "visual_prompt",
            "asset_prompt",
            "prompt",
            "atmosphere",
            "setting",
        )
    )
    return bool(re.search(r"群众|人群|群演|围观人群|路人群|crowd|crowded|extras|background people", text, flags=re.IGNORECASE))


def _comic_asset_prompt_rule(target_type, item=None):
    target_type = str(target_type or "").strip()
    if target_type == "character":
        return (
            "人物参考图硬性规格（最高优先级，违反即判定失败）：必须生成单张白底角色三视图或四视图设定表，"
            "不是剧情插画，也不是两张候选图。最终输出只能是一张完整图片，版式必须是同一个角色的全身转面图，纯白背景；至少包含正视图、侧视图、背视图，"
            "可额外加入 3/4 视图，并必须在同一张设定表里加入一个正脸大头照/头像特写面板，用于锁定五官；"
            "各视图和正脸大头照的服装、发型、脸型、年龄感、身材比例完全一致；"
            "角色保持中性站姿或轻微 A-pose/T-pose，无遮挡，三视图头到脚完整可见，正脸大头照必须面向镜头。"
            "禁止生成场景背景、剧情动作、多人合照、只有半身头像、只有近景肖像、动态打斗、手持剧情道具、复杂道具背景、室内/街景/自然环境、第二张非白底变体。"
            "画面可以有简洁中文小标签（正视/侧视/背视/四分之三），但不要水印、边框、漫画分镜或海报排版。"
        )
    if target_type == "scene":
        if _comic_scene_allows_crowd(item):
            return (
                "场景参考图硬性规格（最高优先级）：主体只能是空间环境、建筑、室内陈设、光线、天气和氛围，不是人物图。"
                "本场景文本明确包含群众/人群语义，因此只允许远处或背景中的群众作为环境尺度；"
                "禁止出现任何命名角色、主角、前景人物、人物特写、单独摆拍人物或可识别人物肖像。"
                "不要白底棚拍；必须生成完整可用的场景/环境参考图。"
            )
        return (
            "场景参考图硬性规格（最高优先级，违反即判定失败）：只生成无人空景/环境参考图，主体是地点、空间结构、"
            "建筑、室内陈设、光线、天气和氛围。画面中不得出现任何人物、人脸、人形剪影、路人、手脚身体局部、"
            "主角、群众或可识别生物；即使剧本文字涉及人物，也不要把人物画进场景参考图。"
            "不要白底棚拍；必须生成完整可用的场景/环境参考图。"
        )
    if target_type == "prop":
        return (
            "道具参考图硬性规格：只生成单独道具产品图，主体是道具本身，纯白或干净中性背景；"
            "不要人物、手持道具、剧情场景、复杂背景、多人或角色摆拍。"
        )
    return ""


def _comic_asset_negative_prompt_rule(target_type, item=None):
    target_type = str(target_type or "").strip()
    if target_type == "character":
        return (
            "scene background, environment, street, room, landscape, action scene, fighting pose, running pose, "
            "multiple characters, group photo, crowd, headshot-only output, bust-only output, cropped body, missing feet, "
            "props covering body, holding object, colored background, poster layout, comic panel, second image, alternate variant"
        )
    if target_type == "scene":
        if _comic_scene_allows_crowd(item):
            return "foreground person, main character, named character, portrait, close-up face, posing person, single person focus"
        return (
            "people, person, human, man, woman, child, face, body, hands, legs, silhouette, crowd, pedestrian, "
            "foreground character, main character, portrait, animal, white studio background"
        )
    if target_type == "prop":
        return "people, person, human hand, holding object, character, model, scene background, room, street, crowd, portrait"
    return ""


def _merge_comic_negative_prompt(params, target_type, item=None):
    params = dict(params if isinstance(params, dict) else {})
    rule = _comic_asset_negative_prompt_rule(target_type, item)
    if not rule:
        return params
    current = str(params.get("negative_prompt") or params.get("negativePrompt") or "").strip()
    merged = ", ".join(part for part in (current, rule) if part)
    params["negative_prompt"] = merged
    params["negativePrompt"] = merged
    return params


def _compose_local_comic_asset_prompt(project, target_type, target_id, prompt):
    base = _clip_comic_prompt_text(prompt, 600)
    collection = {"character": "characters", "scene": "scenes", "prop": "props"}.get(str(target_type or ""))
    item = _local_comic_find_by_id(project.get(collection), target_id) if collection and isinstance(project, dict) else None
    hard_rule = _comic_asset_prompt_rule(target_type, item)
    parts = [
        "请根据以下漫剧项目上下文生成参考图，必须服务于剧本设定，不要只按名称自由发挥。",
        _local_comic_visual_origin_rule(project, target_type),
        _local_comic_style_rule(project),
        hard_rule,
        _local_comic_asset_project_context(project),
        _local_comic_asset_context(project, target_type, target_id),
        f"本次生成要求：{base}" if base else "",
        f"最终锁定：{hard_rule}" if hard_rule else "",
        "保持角色、场景、道具与剧本描述一致；不要生成字幕、水印、边框、拼图或无关元素。",
    ]
    return "\n".join(part for part in parts if part)


def _local_comic_storyboard_context(project, storyboard):
    if not isinstance(storyboard, dict):
        return ""
    project = _local_comic_project_with_valid_character_refs(project)
    storyboard = _local_comic_storyboard_normalize_refs(project, _local_comic_storyboard_with_asset_refs(project, storyboard))
    lines = []
    for label, key in (
        ("分镜序号", "sequence"),
        ("分镜描述", "description"),
        ("景别", "shot_type"),
        ("机位角度", "camera_angle"),
        ("镜头运动", "camera_movement"),
        ("图片提示词", "image_prompt"),
        ("分镜图提示词", "storyboard_image_prompt"),
        ("动作流程提示词", "action_grid_prompt"),
        ("视频提示词", "video_prompt"),
    ):
        text = _clip_comic_prompt_text(storyboard.get(key), 700)
        if text:
            lines.append(f"{label}：{text}")
    names = []
    for value in storyboard.get("characters") or []:
        if isinstance(value, dict):
            name = str(value.get("name") or "").strip()
            desc = _clip_comic_prompt_text(value.get("description") or value.get("base_prompt"), 220)
            if name:
                names.append(f"{name}（{desc}）" if desc else name)
    scene = storyboard.get("scene")
    if isinstance(scene, dict) and scene.get("name"):
        lines.append(f"场景：{scene.get('name')} {_clip_comic_prompt_text(scene.get('description') or scene.get('base_prompt'), 260)}".strip())
    props = [str(value.get("name")) for value in (storyboard.get("props") or []) if isinstance(value, dict) and value.get("name")]
    if names:
        lines.append("涉及人物：" + "、".join(names))
    if props:
        lines.append("涉及道具：" + "、".join(props))
    return "\n".join(lines)


def _compose_local_comic_storyboard_prompt(project, storyboard, prompt, media_kind="image"):
    if media_kind == "video":
        return _compose_local_comic_storyboard_video_prompt(project, storyboard, prompt)
    base = _clip_comic_prompt_text(prompt, 1800)
    media_label = "分镜视频" if media_kind == "video" else "分镜图"
    parts = [
        f"请根据以下漫剧剧本和当前分镜生成{media_label}，必须保留剧本语义、人物关系、场景和道具。",
        _local_comic_visual_origin_rule(project, "storyboard"),
        _local_comic_style_rule(project),
        _local_comic_project_script_context(project, 1400),
        _local_comic_storyboard_context(project, storyboard),
        f"本次生成要求：{base}" if base else "",
        "画面只表现当前分镜，不要生成字幕、水印、边框、拼图或无关人物。",
    ]
    return "\n".join(part for part in parts if part)


def _compose_local_comic_storyboard_flowchart_prompt(project, storyboard, prompt):
    base = _clip_comic_prompt_text(prompt, 1800)
    duration = _first_non_empty(storyboard.get("video_duration"), storyboard.get("videoDuration"), storyboard.get("duration")) if isinstance(storyboard, dict) else ""
    duration_text = str(duration or "").strip()
    if duration_text and not duration_text.endswith("秒"):
        duration_text = f"{duration_text}秒"
    duration_rule = (
        f"流程图总时长必须严格按当前页面设置：{duration_text}；时间轴从0秒开始，到{duration_text}结束，首帧、关键帧、尾帧节点的时间标注必须落在这个总时长内；如分镜描述、图片提示词或动作流程提示词中存在其它秒数，以当前页面设置为准。"
        if duration_text
        else ""
    )
    parts = [
        "请根据以下漫剧剧本和当前分镜生成单张镜头流程图，必须保留剧本语义、人物关系、场景和道具。",
        _local_comic_visual_origin_rule(project, "storyboard"),
        _local_comic_style_rule(project),
        _local_comic_project_script_context(project, 1400),
        _local_comic_storyboard_context(project, storyboard),
        f"本次生成要求：{base}" if base else "",
        duration_rule,
        "根据这个剧本生成一张单图流程图，不要输出九宫格、分屏、漫画页或多张独立关键帧拼贴。",
        "流程图必须包含首帧、尾帧和关键帧节点，并通过箭头、时间线或流程关系展示镜头推进。",
        "每个节点都要标注标题、镜头时间设计、出场人物、关键动作和必要的场景/道具变化。",
        "允许使用中文标题、注释框、箭头、时间轴和人物标签，方便图片模型自行设计清晰版式。",
        "整张图必须是完整、清晰、可读的流程图海报式单画面，信息集中在同一张图中。",
        "画面只表现当前分镜，不要生成无关字幕、水印或无关人物。",
    ]
    return "\n".join(part for part in parts if part)


def _local_comic_video_storyboard_context(storyboard):
    if not isinstance(storyboard, dict):
        return ""
    lines = []
    sequence = _clip_comic_prompt_text(storyboard.get("sequence"), 80)
    if sequence:
        lines.append(f"分镜序号：{sequence}")
    scene = storyboard.get("scene")
    if isinstance(scene, dict):
        scene_text = scene.get("name") or scene.get("description") or scene.get("base_prompt")
    else:
        scene_text = scene
    if scene_text:
        lines.append(f"场景：{_clip_comic_prompt_text(scene_text, 220)}")
    names = []
    for value in storyboard.get("characters") or []:
        if isinstance(value, dict):
            name = str(value.get("name") or "").strip()
            if name:
                names.append(name)
        else:
            name = str(value or "").strip()
            if name:
                names.append(name)
    props = []
    for value in storyboard.get("props") or []:
        name = str(value.get("name") or "").strip() if isinstance(value, dict) else str(value or "").strip()
        if name:
            props.append(name)
    if names:
        lines.append("人物：" + "、".join(names[:6]))
    if props:
        lines.append("道具：" + "、".join(props[:6]))
    return "\n".join(lines)


def _local_comic_storyboard_audio_values(storyboard):
    if not isinstance(storyboard, dict):
        return "", ""
    audio_prompt = storyboard.get("audio_prompt") or storyboard.get("audioPrompt") or {}
    dialogue = audio_prompt.get("dialogue") if isinstance(audio_prompt, dict) else None
    dialogue_text = ""
    if isinstance(dialogue, dict):
        dialogue_text = _first_non_empty(dialogue.get("text"), dialogue.get("content"), dialogue.get("dialogue"))
    else:
        dialogue_text = dialogue
    dialogue_text = _first_non_empty(
        storyboard.get("dialogue_text"),
        storyboard.get("dialogueText"),
        storyboard.get("dialogue"),
        dialogue_text,
    )
    sound_text = _first_non_empty(
        storyboard.get("sound_effect"),
        storyboard.get("soundEffect"),
        storyboard.get("action_sound"),
        audio_prompt.get("action_sound") if isinstance(audio_prompt, dict) else "",
        audio_prompt.get("actionSound") if isinstance(audio_prompt, dict) else "",
    )
    return str(dialogue_text or "").strip(), str(sound_text or "").strip()


def _local_comic_storyboard_audio_context_lines(storyboard):
    dialogue_text, sound_text = _local_comic_storyboard_audio_values(storyboard)
    lines = []
    dialogue_text = _clip_comic_prompt_text(dialogue_text, 360)
    sound_text = _clip_comic_prompt_text(sound_text, 260)
    if dialogue_text and dialogue_text not in {"无", "无台词", "无对白", "无旁白", "none", "null"}:
        lines.append(f"对白/旁白：{dialogue_text}")
    if sound_text and sound_text not in {"无", "无音效", "none", "null"}:
        lines.append(f"音效：{sound_text}")
    return lines


def _local_comic_storyboard_field_lines(storyboard, final_prompt=None):
    if not isinstance(storyboard, dict):
        return []
    duration = _first_non_empty(storyboard.get("video_duration"), storyboard.get("videoDuration"), storyboard.get("duration"))
    duration_text = str(duration or "").strip()
    if duration_text and not duration_text.endswith("秒"):
        duration_text = f"{duration_text}秒"
    dialogue_text, sound_text = _local_comic_storyboard_audio_values(storyboard)
    final_prompt_text = _first_non_empty(
        final_prompt,
        storyboard.get("final_prompt"),
        storyboard.get("finalPrompt"),
        storyboard.get("action_video_prompt"),
        storyboard.get("actionVideoPrompt"),
        storyboard.get("keyframes_video_prompt"),
        storyboard.get("keyframesVideoPrompt"),
        storyboard.get("video_prompt"),
        storyboard.get("videoPrompt"),
        storyboard.get("image_prompt"),
        storyboard.get("imagePrompt"),
    )
    fields = (
        ("画面描述", storyboard.get("description"), 700),
        ("景别", storyboard.get("shot_type") or storyboard.get("shotType"), 120),
        ("角度", storyboard.get("camera_angle") or storyboard.get("cameraAngle"), 120),
        ("运镜", storyboard.get("camera_movement") or storyboard.get("cameraMovement") or storyboard.get("parsedCameraMovement"), 180),
        ("时长", duration_text, 80),
        ("对白/旁白", dialogue_text or "无", 360),
        ("音效", sound_text or "无", 260),
        ("最终提示词", final_prompt_text, 1400),
    )
    lines = []
    for label, value, limit in fields:
        text = _clip_comic_prompt_text(value, limit)
        if text:
            lines.append(f"{label}：{text}")
    return lines


def _compose_local_comic_storyboard_video_prompt(project, storyboard, prompt):
    base = _clip_comic_prompt_text(prompt, 1800)
    safe_storyboard = _local_comic_storyboard_normalize_refs(
        _local_comic_project_with_valid_character_refs(project),
        _local_comic_storyboard_with_asset_refs(project, storyboard),
    )
    parts = [
        "请根据以下漫剧剧本和当前分镜生成分镜视频，必须保留剧本语义、人物关系、场景和道具。",
        _local_comic_visual_origin_rule(project, "storyboard"),
        _local_comic_style_rule(project),
        _local_comic_video_storyboard_context(safe_storyboard),
        f"本次生成要求：{base}" if base else "",
        "画面只表现当前分镜，不要生成字幕、水印、边框、拼图或无关人物。",
    ]
    return "\n".join(part for part in parts if part)


def _local_comic_extract_generation_requirement(prompt):
    match = re.search(r"(?:^|\n)本次生成要求：([^\n]+)", str(prompt or ""))
    return str(match.group(1) or "").strip() if match else ""


def _storyboard_video_unique_instruction(project, storyboard, prompt="", include_current_context=True):
    if not isinstance(storyboard, dict):
        return ""
    safe_project = _local_comic_project_with_valid_character_refs(project)
    storyboard = _local_comic_storyboard_normalize_refs(
        safe_project,
        _local_comic_storyboard_with_asset_refs(safe_project, storyboard),
    )
    sequence = _first_non_empty(storyboard.get("sequence"), storyboard.get("index"), storyboard.get("id"))
    description = _first_non_empty(
        storyboard.get("action_video_prompt"),
        storyboard.get("actionVideoPrompt"),
        storyboard.get("keyframes_video_prompt"),
        storyboard.get("keyframesVideoPrompt"),
        storyboard.get("video_prompt"),
        storyboard.get("videoPrompt"),
        storyboard.get("description"),
        storyboard.get("storyboard_image_prompt"),
        storyboard.get("storyboardImagePrompt"),
        storyboard.get("image_prompt"),
        storyboard.get("imagePrompt"),
        storyboard.get("prompt"),
    )
    shot_parts = []
    for label, key in (
        ("景别", "shot_type"),
        ("机位角度", "camera_angle"),
        ("镜头运动", "camera_movement"),
    ):
        value = _clip_comic_prompt_text(storyboard.get(key), 180)
        if value:
            shot_parts.append(f"{label}：{value}")
    scene = storyboard.get("scene")
    if isinstance(scene, dict):
        scene_text = _first_non_empty(scene.get("name"), scene.get("description"), scene.get("base_prompt"))
    else:
        scene_text = scene
    if scene_text:
        shot_parts.append(f"场景：{_clip_comic_prompt_text(scene_text, 220)}")
    character_names = []
    for value in storyboard.get("characters") or []:
        if isinstance(value, dict):
            name = str(value.get("name") or "").strip()
        else:
            name = str(value or "").strip()
        if name and name not in character_names:
            character_names.append(name)
    if character_names:
        shot_parts.append("人物：" + "、".join(character_names[:6]))
    prop_names = []
    for value in storyboard.get("props") or []:
        if isinstance(value, dict):
            name = str(value.get("name") or "").strip()
        else:
            name = str(value or "").strip()
        if name and name not in prop_names:
            prop_names.append(name)
    if prop_names:
        shot_parts.append("道具：" + "、".join(prop_names[:6]))
    field_lines = _local_comic_storyboard_field_lines(storyboard, _local_comic_extract_generation_requirement(prompt) or description)
    total_storyboards = len(project.get("storyboards") or []) if isinstance(project, dict) else 0
    title = f"第 {sequence} 个分镜" if sequence else "当前分镜"
    if total_storyboards:
        title = f"{title} / 共 {total_storyboards} 个分镜"
    lines = [
        "视频生成硬性要求：本次只生成下面这个分镜对应的视频，不能复用、概括或重复其他分镜的视频内容。",
        f"当前目标：{title}",
        "确认镜头页8字段：\n" + "\n".join(field_lines) if field_lines else "",
        f"当前分镜描述：{_clip_comic_prompt_text(description, 900)}" if include_current_context and description else "",
        "；".join(shot_parts) if include_current_context else "",
        "如果同一项目需要生成多个视频，每个视频必须分别按照自己的分镜描述、动作、场景和镜头运动生成，禁止把第一个分镜或任意一个分镜的内容套用到其他分镜。",
    ]
    return "\n".join(line for line in lines if line)


def _lock_storyboard_video_prompt_to_current_shot(project, storyboard, prompt, compact=False):
    prompt = str(prompt or "").strip()
    instruction = _storyboard_video_unique_instruction(
        project,
        storyboard,
        prompt,
        include_current_context=not compact,
    )
    if not instruction:
        return prompt
    if compact:
        return "\n".join(
            part
            for part in (
                instruction,
                _local_comic_visual_origin_rule(project, "storyboard"),
                _local_comic_style_rule(project),
                "画面只表现当前分镜，不要生成字幕、水印、边框、拼图或无关人物。",
            )
            if part
        )
    return f"{instruction}\n\n{prompt}" if prompt else instruction


def _merge_reference_urls_into_params(params, refs):
    params = dict(params if isinstance(params, dict) else {})
    refs = _dedupe_urls(_apimart_publicize_ref(ref) for ref in refs)
    refs = [ref for ref in refs if re.match(r"^https?://", str(ref or ""), flags=re.IGNORECASE)]
    if not refs:
        return params
    existing = []
    for key in ("reference_image_urls", "image_urls", "images", "urls", "inputUrls"):
        _extend_url_list(existing, params.get(key))
    refs = _dedupe_urls(_apimart_publicize_ref(ref) for ref in [*existing, *refs])
    refs = [ref for ref in refs if re.match(r"^https?://", str(ref or ""), flags=re.IGNORECASE)]
    params["reference_image_urls"] = refs
    params["image_urls"] = refs
    params["images"] = refs
    return params


def _merge_reference_video_urls_into_params(params, refs):
    params = dict(params if isinstance(params, dict) else {})
    refs = _dedupe_urls(_apimart_publicize_ref(ref) for ref in refs)
    refs = [ref for ref in refs if re.match(r"^https?://", str(ref or ""), flags=re.IGNORECASE)]
    if not refs:
        return params
    existing = []
    for key in ("reference_video_urls", "referenceVideos", "video_urls", "videos"):
        _extend_url_list(existing, params.get(key))
    for key in ("reference_video", "referenceVideo", "video_url", "videoUrl"):
        _extend_url_list(existing, params.get(key))
    refs = _dedupe_urls([*existing, *refs])
    params["reference_video"] = refs[0]
    params["referenceVideo"] = refs[0]
    params["video_url"] = refs[0]
    params["videoUrl"] = refs[0]
    params["reference_video_urls"] = refs
    params["referenceVideos"] = refs
    params["video_urls"] = refs
    params["videos"] = refs
    return params


def _ai_comic_max_reference_images(model):
    model = str(model or "").strip()
    if model == "gpt-image-2":
        return 1
    return 0


def _ai_comic_strengthen_reference_request(model, prompt, params):
    params = dict(params if isinstance(params, dict) else {})
    frame_style_mode = str(
        params.get("frame_style_mode")
        or params.get("frameStyleMode")
        or params.get("style_mode")
        or params.get("styleMode")
        or ""
    ).strip().lower()
    colored_pencil_mode = frame_style_mode in {
        "colored_pencil", "colored-pencil", "coloredpencil", "彩铅", "彩铅手绘"
    }
    refs = _dedupe_urls(params.get("reference_image_urls") or params.get("image_urls") or params.get("images") or [])
    limit = _ai_comic_max_reference_images(model)
    preserve_refs = bool(params.get("_preserve_reference_images") or params.get("_strict_storyboard_references"))
    if limit > 0 and len(refs) > limit and not preserve_refs:
        refs = refs[:limit]
        params["reference_image_urls"] = refs
        params["image_urls"] = refs
        params["images"] = refs
    prompt = str(prompt or "").strip()
    if refs and colored_pencil_mode:
        if "彩铅" not in prompt:
            prompt = (
                "首尾帧图片风格要求：将参考图和当前画面统一处理为彩铅手绘风格；"
                "保留人物身份、五官、发型、服装、体型、产品外形、颜色、包装文字和 Logo，画面只改变绘制质感；"
                + prompt
            )
        return prompt, params
    reference_usage = str(params.get("_reference_usage") or params.get("reference_usage") or params.get("usage") or "").lower()
    has_scene_refs = bool(_dedupe_urls(params.get("scene_reference_images") or params.get("scene_reference_image_urls") or []))
    has_background_intent = (
        reference_usage in {"background", "scene", "environment"}
        or has_scene_refs
        or bool(re.search(r"背景参考|场景参考|环境参考|作为背景|当作背景|作为场景|当作场景|scene reference|background reference", prompt, flags=re.IGNORECASE))
    )
    if refs and has_background_intent:
        if "严格保持参考图背景一致" not in prompt:
            prompt = "严格保持参考图背景一致，保留参考图中的空间结构、环境氛围、色彩光线、透视关系和主要场景元素；" + prompt
    elif refs and "严格保持参考图主体一致" not in prompt:
        prompt = "严格保持参考图主体一致，保留参考图中的脸型、发型、服装、颜色、道具形状和主要视觉特征；" + prompt
    if refs and "禁止动漫" not in prompt:
        prompt = (
            "画面风格必须严格跟随参考图的真实质感、摄影/影视质感、材质和光影；"
            "如果参考图是真人或写实风格，禁止动漫、二次元、漫画、插画、赛璐璐、Q版、卡通、手绘风格；"
            + prompt
        )
    return prompt, params


def _reference_urls_from_payload(payload):
    refs = []
    payload = payload if isinstance(payload, dict) else {}
    storyboard_refs = payload.get("storyboard_reference_images")
    if isinstance(storyboard_refs, dict):
        for value in storyboard_refs.values():
            _extend_url_list(refs, value)
    reference_assets = payload.get("reference_assets")
    if not isinstance(reference_assets, list):
        reference_assets = payload.get("referenceAssets")
    if isinstance(reference_assets, list):
        for asset in reference_assets:
            if not isinstance(asset, dict):
                _extend_url_list(refs, asset)
                continue
            _extend_url_list(refs, asset)
            _extend_url_list(refs, asset.get("reference_urls"))
            _extend_url_list(refs, asset.get("reference_images"))
            _extend_url_list(refs, asset.get("referenceImages"))
    for key in (
        "storyboard_image",
        "storyboardImage",
        "end_frame_image",
        "endFrameImage",
        "first_frame",
        "firstFrameUrl",
        "last_frame",
        "lastFrameUrl",
        "reference_image_urls",
        "image_urls",
        "images",
        "urls",
        "inputUrls",
        "reference_images",
        "referenceImages",
        "character_reference_images",
        "scene_reference_images",
        "prop_reference_images",
        "action_flow_images",
    ):
        _extend_url_list(refs, payload.get(key))
    for key in ("image_url", "reference_image", "storyboard_image", "end_frame_image"):
        _extend_url_list(refs, payload.get(key))
    return _dedupe_urls(refs)


def _local_comic_project_global_reference_images(project, config=None):
    refs = []
    config = config if isinstance(config, dict) else {}
    project = project if isinstance(project, dict) else {}
    project_config = project.get("config") if isinstance(project.get("config"), dict) else {}
    session = project.get("agent_session") if isinstance(project.get("agent_session"), dict) else {}
    for source in (config, project_config, session):
        for key in ("reference_images", "referenceImages", "reference_image_urls", "image_urls"):
            _extend_url_list(refs, source.get(key))
        reference_assets = source.get("reference_assets")
        if not isinstance(reference_assets, list):
            reference_assets = source.get("referenceAssets")
        if isinstance(reference_assets, list):
            for asset in reference_assets:
                _extend_url_list(refs, asset)
                if isinstance(asset, dict):
                    _extend_url_list(refs, asset.get("reference_urls"))
                    _extend_url_list(refs, asset.get("reference_images"))
    return _dedupe_urls(refs)


def _local_comic_asset_request_context(project, target_type, target_id):
    collection = {"character": "characters", "scene": "scenes", "prop": "props"}.get(str(target_type or ""))
    item = _local_comic_find_by_id(project.get(collection), target_id) if collection and isinstance(project, dict) else None
    return _local_comic_item_prompt(item), _local_comic_item_reference_urls(item)


def _save_local_comic_asset_prompt(project, target_type, target_id, prompt):
    prompt = str(prompt or "").strip()
    collection = {"character": "characters", "scene": "scenes", "prop": "props"}.get(str(target_type or ""))
    if not prompt or not collection or not isinstance(project, dict):
        return False
    item = _local_comic_find_by_id(project.get(collection), target_id)
    if not isinstance(item, dict):
        return False
    item["description"] = prompt
    item["base_prompt"] = prompt
    project["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    _save_local_comic_state()
    return True


def _local_comic_storyboard_reference_context(project, storyboard):
    if not isinstance(project, dict) or not isinstance(storyboard, dict):
        return []
    project = _local_comic_project_with_valid_character_refs(project)
    storyboard = _local_comic_storyboard_normalize_refs(project, _local_comic_storyboard_with_asset_refs(project, storyboard))
    refs = []
    lookups = {
        "characters": _local_comic_asset_lookup(project, "characters"),
        "props": _local_comic_asset_lookup(project, "props"),
    }

    def add_item(value, collection):
        item = value if isinstance(value, dict) else None
        if item is None:
            name = str(value or "").strip()
            item = lookups.get(collection, {}).get(name) if name else None
            item = _local_comic_find_by_id(project.get(collection), value) or item
        if isinstance(value, dict) and (item is None or not _local_comic_item_reference_urls(item)):
            item = _local_comic_find_by_id(project.get(collection), value.get("id")) or item
        refs.extend(_local_comic_item_reference_urls(item))

    for value in storyboard.get("characters") or []:
        add_item(value, "characters")
    for value in (storyboard.get("characterIds") or storyboard.get("character_ids") or []):
        add_item(value, "characters")
    scene = storyboard.get("scene")
    scene_id = _first_non_empty(storyboard.get("sceneId"), storyboard.get("scene_id"))
    scene_item = scene if isinstance(scene, dict) else _local_comic_asset_lookup(project, "scenes").get(str(scene or "").strip())
    if scene_item is None and scene_id is not None:
        scene_item = _local_comic_find_by_id(project.get("scenes"), scene_id)
    if scene_item is not None and isinstance(scene_item, dict) and not _local_comic_item_reference_urls(scene_item):
        scene_item = _local_comic_find_by_id(project.get("scenes"), scene_item.get("id")) or scene_item
    refs.extend(_local_comic_item_reference_urls(scene_item))
    for value in storyboard.get("props") or []:
        add_item(value, "props")
    for value in (storyboard.get("propIds") or storyboard.get("prop_ids") or []):
        add_item(value, "props")
    return _dedupe_urls(refs)


def _local_comic_storyboard_character_audio_reference_context(project, storyboard):
    if not isinstance(project, dict) or not isinstance(storyboard, dict):
        return []
    project = _local_comic_project_with_valid_character_refs(project)
    storyboard = _local_comic_storyboard_normalize_refs(project, _local_comic_storyboard_with_asset_refs(project, storyboard))
    refs = []
    lookup = _local_comic_asset_lookup(project, "characters")

    def add_item(value):
        item = value if isinstance(value, dict) else None
        if item is None:
            name = str(value or "").strip()
            item = lookup.get(name) if name else None
            item = _local_comic_find_by_id(project.get("characters"), value) or item
        if isinstance(value, dict) and (item is None or not _local_comic_item_audio_reference_urls(item)):
            item = _local_comic_find_by_id(project.get("characters"), value.get("id")) or item
        refs.extend(_local_comic_item_audio_reference_urls(item))

    for value in storyboard.get("characters") or []:
        add_item(value)
    for value in (storyboard.get("characterIds") or storyboard.get("character_ids") or []):
        add_item(value)
    return _dedupe_urls(refs)


def _local_comic_storyboard_character_voice_hint(project, storyboard):
    if not isinstance(project, dict) or not isinstance(storyboard, dict):
        return ""
    project = _local_comic_project_with_valid_character_refs(project)
    storyboard = _local_comic_storyboard_normalize_refs(project, _local_comic_storyboard_with_asset_refs(project, storyboard))
    lookup = _local_comic_asset_lookup(project, "characters")

    def voice_hint(item):
        if not isinstance(item, dict):
            return ""
        return str(_first_non_empty(
            item.get("voice_name"),
            item.get("voiceName"),
            item.get("ttsVoice"),
            item.get("tts_voice"),
            item.get("voice"),
            item.get("voice_model") if str(item.get("voice_model") or "").strip().lower() in _AIC_GEMINI_TTS_VOICES else "",
            item.get("voiceDescription"),
            item.get("voice_description"),
            item.get("description"),
            item.get("name"),
        ) or "").strip()

    def find_item(value):
        item = value if isinstance(value, dict) else None
        if item is None:
            name = str(value or "").strip()
            item = lookup.get(name) if name else None
            item = _local_comic_find_by_id(project.get("characters"), value) or item
        if isinstance(value, dict) and item is None:
            item = _local_comic_find_by_id(project.get("characters"), value.get("id"))
        return item

    for value in [*(storyboard.get("characters") or []), *(storyboard.get("characterIds") or storyboard.get("character_ids") or [])]:
        hint = voice_hint(find_item(value))
        if hint:
            return hint
    return ""


COMIC_STORYBOARD_DIALOGUE_AUDIO_VIDEO_MODELS = {
    "doubao-seedance-2-0-260128",
    "doubao-seedance-2-0-fast-260128",
    "doubao-seedance-2-0-mini-260615",
    "kling-avatar-image2video",
}


def _comic_video_model_needs_storyboard_dialogue_audio(model):
    model_id = str(model or "").strip()
    if not model_id:
        return False
    try:
        model_id = _lk888_normalize_video_model(_apply_model_remap(model_id))
    except Exception:
        model_id = _lk888_normalize_video_model(model_id)
    return model_id in COMIC_STORYBOARD_DIALOGUE_AUDIO_VIDEO_MODELS


def _comic_truthy(value):
    if isinstance(value, bool):
        return value
    return str(value or "").strip().lower() in {"1", "true", "yes", "y", "on"}


def _comic_storyboard_dialogue_text_for_tts(storyboard):
    dialogue_text, _sound_text = _local_comic_storyboard_audio_values(storyboard)
    dialogue_text = str(dialogue_text or "").strip()
    if not dialogue_text or dialogue_text.lower() in {"无", "无台词", "无对白", "无旁白", "none", "null"}:
        return ""
    return _clip_comic_prompt_text(dialogue_text, 1200)


def _comic_storyboard_dialogue_audio_result(audio_url):
    audio_url = str(audio_url or "").strip()
    result = {"audio_url": audio_url}
    if not audio_url:
        return result
    try:
        media = _local_comic_auto_edit_probe(audio_url)
        duration = float((media or {}).get("duration") or 0.0)
    except Exception:
        duration = 0.0
    if duration > 0:
        result["audio_duration_seconds"] = round(duration, 3)
        result["duration_source"] = "measured"
    else:
        result["duration_source"] = "unmeasured"
    return result


def _submit_comic_storyboard_dialogue_audio(project_id, storyboard_id, dialogue_text, voice_sample_url, voice_hint="", include_metadata=False):
    dialogue_text = str(dialogue_text or "").strip()
    voice_sample_url = str(voice_sample_url or "").strip()
    if not dialogue_text:
        return ""
    audio_model = COMIC_STORYBOARD_DIALOGUE_AUDIO_MODEL
    voice_hint = str(voice_hint or "").strip()
    tts_voice = voice_hint.lower() if voice_hint.lower() in _AIC_GEMINI_TTS_VOICES else _aic_pick_text_voice(voice_hint)
    params = {
        "text": dialogue_text,
        "input_text": dialogue_text,
        "prompt": dialogue_text,
        "target_text": dialogue_text,
        "clone_text": dialogue_text,
        "voice_text": dialogue_text,
        "format": "mp3",
        "source": "comic-storyboard-dialogue-preset-voice",
        "project_id": int(project_id or 0),
        "storyboard_id": str(storyboard_id or ""),
        "audioRefCount": 1 if voice_sample_url else 0,
        "voice": tts_voice,
        "voice_name": tts_voice,
        "voiceName": tts_voice,
        "speaker": tts_voice,
        "voice_description": voice_hint,
        "style_prompt": voice_hint,
    }
    if voice_sample_url:
        params.update({
            "reference_audio": voice_sample_url,
            "reference_audio_url": voice_sample_url,
            "referenceAudioUrl": voice_sample_url,
            "reference_audio_urls": [voice_sample_url],
            "audio_url": voice_sample_url,
            "audioUrl": voice_sample_url,
            "voiceAudioUrl": voice_sample_url,
        })
    billing_ctx = None
    try:
        billing_ctx = _charge_local_ai_model_call(
            "tts",
            audio_model,
            {**params, "prompt": dialogue_text},
            project_id=project_id,
            description=f"云灵AI漫剧分镜台词配音 #{storyboard_id}：{audio_model}",
        )
        result = AI_API_SERVICE.submit_media_task(audio_model, dialogue_text, params=params, count=1)
        task_id = str(result.get("task_id") or result.get("id") or "").strip() if isinstance(result, dict) else ""
        if not task_id:
            raise RuntimeError("台词音频任务没有返回 task_id")
        task = _register_ai_comic_task(
            remote_task_id=task_id,
            project_id=project_id,
            task_type="generate_audio",
            task_name=f"生成分镜台词音频 #{storyboard_id}",
            target_id=storyboard_id,
            target_type="storyboard_audio",
            model=audio_model,
            prompt=dialogue_text,
            params=params,
            count=1,
            billing_ctx=billing_ctx,
        )
        billing_ctx = None
        audio_url = str(_extract_ai_result_url(result) or "").strip()
        if audio_url:
            task["status"] = "completed"
            task["state"] = "completed"
            task["progress_percent"] = 100
            task["current_step"] = "已完成"
            task["result_url"] = audio_url
            task["completed_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
            _sync_ai_comic_task_actual_billing_cost(task, result)
            _save_local_comic_state()
            return _comic_storyboard_dialogue_audio_result(audio_url) if include_metadata else audio_url
        for attempt in range(30):
            if attempt:
                time.sleep(2)
            task = _refresh_ai_comic_task(task)
            audio_url = str(_extract_ai_result_url(task) or "").strip()
            if audio_url:
                return _comic_storyboard_dialogue_audio_result(audio_url) if include_metadata else audio_url
            state = str(task.get("state") or task.get("status") or "").strip().lower() if isinstance(task, dict) else ""
            if state in {"failed", "failure", "error", "cancelled", "canceled"}:
                raise RuntimeError(task.get("error_message") or task.get("current_step") or "台词音频生成失败")
        raise RuntimeError("台词音频仍在生成，暂时无法提交数字人视频")
    except Exception:
        _refund_canvas_model_call(billing_ctx, f"云灵AI漫剧分镜台词配音失败退款：#{storyboard_id}")
        raise


def _normalize_comic_storyboard_audio_mode(value):
    normalized = str(value or "").strip().lower()
    return normalized if normalized in {"auto", "tts"} else "legacy"


def _is_matrix_video_replacement_project(project):
    project = project if isinstance(project, dict) else {}
    config = project.get("config") if isinstance(project.get("config"), dict) else {}
    source_mode = str(
        project.get("source_mode")
        or project.get("sourceMode")
        or project.get("project_source_mode")
        or project.get("projectSourceMode")
        or config.get("source_mode")
        or config.get("sourceMode")
        or ""
    ).strip()
    return source_mode == "matrix_video_replacement"


def _comic_storyboard_video_params_with_dialogue_audio(params, project, storyboard, model, project_id, storyboard_id):
    params = dict(params if isinstance(params, dict) else {})
    audio_mode = _normalize_comic_storyboard_audio_mode(params.pop("audio_mode", None))
    auto_match_audio_duration = _comic_truthy(
        params.pop("auto_match_audio_duration", params.pop("autoMatchAudioDuration", False))
    )
    if audio_mode == "auto" and _is_matrix_video_replacement_project(project):
        audio_mode = "tts"
    if audio_mode == "auto":
        _json_log(
            "comic_storyboard_dialogue_audio_skipped",
            project_id=project_id,
            storyboard_id=storyboard_id,
            model=str(model or "").strip(),
            audio_mode="auto",
        )
        return params
    if not _comic_video_model_needs_storyboard_dialogue_audio(model):
        return params
    if _find_recent_duplicate_storyboard_video_task(
        project_id, storyboard_id, model, audio_mode=audio_mode,
    ):
        return params
    dialogue_text = _comic_storyboard_dialogue_text_for_tts(storyboard)
    voice_sample_refs = _local_comic_storyboard_character_audio_reference_context(project, storyboard)
    voice_hint = _local_comic_storyboard_character_voice_hint(project, storyboard)
    if not dialogue_text or (not voice_sample_refs and not voice_hint):
        return params
    preset_voice_hint = str(voice_hint or "").strip().lower()
    dialogue_audio_result = _submit_comic_storyboard_dialogue_audio(
        project_id,
        storyboard_id,
        dialogue_text,
        "" if preset_voice_hint in _AIC_GEMINI_TTS_VOICES else (voice_sample_refs[0] if voice_sample_refs else ""),
        voice_hint,
        include_metadata=auto_match_audio_duration,
    )
    if isinstance(dialogue_audio_result, dict):
        dialogue_audio_url = str(dialogue_audio_result.get("audio_url") or dialogue_audio_result.get("url") or "").strip()
        audio_duration_seconds = dialogue_audio_result.get("audio_duration_seconds")
        duration_source = str(dialogue_audio_result.get("duration_source") or "").strip()
    else:
        dialogue_audio_url = str(dialogue_audio_result or "").strip()
        audio_duration_seconds = None
        duration_source = ""
    if not dialogue_audio_url:
        return params
    params = _merge_audio_refs_into_params(params, [dialogue_audio_url])
    params["sound_file"] = dialogue_audio_url
    params["soundFile"] = dialogue_audio_url
    params["audio"] = dialogue_audio_url
    params["audio_file"] = dialogue_audio_url
    params["audioFile"] = dialogue_audio_url
    params["reference_audio_file"] = dialogue_audio_url
    if auto_match_audio_duration:
        matched_duration = _comic_nearest_video_duration_for_model(model, audio_duration_seconds)
        if matched_duration is not None:
            params["duration"] = matched_duration
            params["video_duration"] = matched_duration
            params["audio_duration_seconds"] = float(audio_duration_seconds)
            params["duration_source"] = duration_source or "measured"
    return params


def _local_comic_storyboard_typed_reference_context(project, storyboard):
    if not isinstance(project, dict) or not isinstance(storyboard, dict):
        return {"characters": [], "scenes": [], "props": [], "all": []}
    project = _local_comic_project_with_valid_character_refs(project)
    storyboard = _local_comic_storyboard_normalize_refs(project, _local_comic_storyboard_with_asset_refs(project, storyboard))
    typed = {"characters": [], "scenes": [], "props": []}
    lookups = {
        "characters": _local_comic_asset_lookup(project, "characters"),
        "scenes": _local_comic_asset_lookup(project, "scenes"),
        "props": _local_comic_asset_lookup(project, "props"),
    }

    def resolve(collection, value):
        item = value if isinstance(value, dict) else None
        if item is None:
            name = str(value or "").strip()
            item = lookups.get(collection, {}).get(name) if name else None
            item = _local_comic_find_by_id(project.get(collection), value) or item
        if isinstance(value, dict):
            item = _local_comic_find_by_id(project.get(collection), value.get("id")) or item
        return item if isinstance(item, dict) else None

    for value in storyboard.get("characters") or []:
        typed["characters"].extend(_local_comic_item_reference_urls(resolve("characters", value))[:1])
    for value in storyboard.get("characterIds") or storyboard.get("character_ids") or []:
        typed["characters"].extend(_local_comic_item_reference_urls(resolve("characters", value))[:1])
    scene = storyboard.get("scene")
    scene_id = _first_non_empty(storyboard.get("sceneId"), storyboard.get("scene_id"))
    scene_item = resolve("scenes", scene) if scene else None
    if scene_item is None and scene_id is not None:
        scene_item = resolve("scenes", scene_id)
    typed["scenes"].extend(_local_comic_item_reference_urls(scene_item)[:1])
    for value in storyboard.get("props") or []:
        typed["props"].extend(_local_comic_item_reference_urls(resolve("props", value))[:1])
    for value in storyboard.get("propIds") or storyboard.get("prop_ids") or []:
        typed["props"].extend(_local_comic_item_reference_urls(resolve("props", value))[:1])
    for key in list(typed):
        typed[key] = _dedupe_urls(_apimart_publicize_ref(ref) for ref in typed[key])
        typed[key] = [ref for ref in typed[key] if re.match(r"^https?://", str(ref or ""), flags=re.IGNORECASE)]
    typed["all"] = _dedupe_urls([*typed["characters"], *typed["scenes"], *typed["props"]])
    return typed


def _apply_strict_storyboard_references_to_params(params, typed_refs):
    params = dict(params if isinstance(params, dict) else {})
    typed_refs = typed_refs if isinstance(typed_refs, dict) else {}
    character_refs = _dedupe_urls(typed_refs.get("characters") or [])
    scene_refs = _dedupe_urls(typed_refs.get("scenes") or [])
    prop_refs = _dedupe_urls(typed_refs.get("props") or [])
    all_refs = _dedupe_urls([*(typed_refs.get("all") or []), *character_refs, *scene_refs, *prop_refs])
    if not all_refs:
        return params
    params = _merge_reference_urls_into_params(params, all_refs)
    params["character_reference_images"] = character_refs
    params["scene_reference_images"] = scene_refs
    params["prop_reference_images"] = prop_refs
    params["strict_reference_image_urls"] = all_refs
    params["_strict_storyboard_references"] = True
    params["_preserve_reference_images"] = True
    return params


def _local_comic_storyboard_character_refs_for_prompt(project, storyboard, prompt):
    if not isinstance(project, dict) or not isinstance(storyboard, dict):
        return [], []
    project = _local_comic_project_with_valid_character_refs(project)
    storyboard = _local_comic_storyboard_normalize_refs(project, _local_comic_storyboard_with_asset_refs(project, storyboard))
    prompt = str(prompt or "")
    refs = []
    names = []
    lookup = _local_comic_asset_lookup(project, "characters")

    def resolve(value):
        item = value if isinstance(value, dict) else None
        if item is None:
            name = str(value or "").strip()
            item = lookup.get(name) if name else None
            item = _local_comic_find_by_id(project.get("characters"), value) or item
        if isinstance(value, dict):
            item = _local_comic_find_by_id(project.get("characters"), value.get("id")) or item
        return item if isinstance(item, dict) else None

    for value in [*(storyboard.get("characters") or []), *(storyboard.get("characterIds") or storyboard.get("character_ids") or [])]:
        item = resolve(value)
        name = str((item or {}).get("name") or "").strip()
        if not name or name not in prompt:
            continue
        item_refs = _local_comic_item_reference_urls(item)
        if item_refs:
            refs.extend(item_refs[:1])
            names.append(name)
    return _dedupe_urls(refs), list(dict.fromkeys(names))


def _with_character_binding_prompt(prompt, names):
    names = [str(name or "").strip() for name in (names or []) if str(name or "").strip()]
    if not names:
        return prompt
    return f"本次画面只允许出现这些被文字点名的人物：{'、'.join(names)}；人物参考图只对应这些同名人物，未点名人物不要出现。" + str(prompt or "")


def _local_comic_storyboard_prompt(storyboard, media_kind="image", workflow_mode=""):
    if not isinstance(storyboard, dict):
        return ""
    workflow_mode = str(workflow_mode or "").strip()
    if media_kind == "video":
        return _first_non_empty(
            storyboard.get("action_video_prompt"),
            storyboard.get("actionVideoPrompt"),
            storyboard.get("keyframes_video_prompt"),
            storyboard.get("keyframesVideoPrompt"),
            storyboard.get("video_prompt"),
            storyboard.get("videoPrompt"),
            storyboard.get("prompt"),
            storyboard.get("description"),
        )
    return _first_non_empty(
        storyboard.get("prompt"),
        storyboard.get("action_grid_prompt"),
        storyboard.get("actionGridPrompt"),
        storyboard.get("storyboard_image_prompt"),
        storyboard.get("storyboardImagePrompt"),
        storyboard.get("image_prompt"),
        storyboard.get("imagePrompt"),
        storyboard.get("description"),
    )


def _local_comic_storyboard_reference_binding_prompt(project, storyboard):
    safe_project = _local_comic_project_with_valid_character_refs(project)
    safe_storyboard = _local_comic_storyboard_normalize_refs(
        safe_project,
        _local_comic_storyboard_with_asset_refs(safe_project, storyboard),
    )
    return _local_comic_storyboard_reference_binding_prompt_impl(
        safe_project,
        safe_storyboard,
        asset_lookup=_local_comic_asset_lookup,
        find_by_id=_local_comic_find_by_id,
        item_reference_urls=_local_comic_item_reference_urls,
        first_non_empty=_first_non_empty,
    )


def _apply_ai_comic_task_result_to_project(task):
    if isinstance(task, dict) and task.get("status") == "completed":
        try:
            project_id = int(task.get("project_id") or 0)
        except Exception:
            project_id = 0
        if project_id and project_id not in LOCAL_COMIC_PROJECTS:
            _restore_local_comic_project_from_history(project_id)
    return _apply_ai_comic_task_result_to_project_impl(
        task,
        local_projects=LOCAL_COMIC_PROJECTS,
        find_by_id=_local_comic_find_by_id,
        append_unique_url=_append_unique_url,
        set_url_at_index=_set_url_at_index,
        save_state=_save_local_comic_state,
        json_log=_json_log,
    )


def _ai_comic_task_has_applyable_result(task):
    if not isinstance(task, dict):
        return False
    if not str(task.get("result_url") or "").strip():
        return False
    status = str(task.get("status") or "").strip().lower()
    return status not in {"failed", "cancelled", "canceled"}


def _mark_ai_comic_task_completed_from_result(task):
    if not _ai_comic_task_has_applyable_result(task):
        return task
    if str(task.get("status") or "").strip().lower() != "completed":
        task["status"] = "completed"
        task["state"] = "completed"
        task["progress_percent"] = 100
        task["current_step"] = "已完成"
        task["completed_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    return task


def _ai_comic_task_project_result_needs_sync(task):
    if not _ai_comic_task_has_applyable_result(task):
        return False
    if not task.get("project_result_applied"):
        return True
    target_type = str(task.get("target_type") or "").strip().lower()
    task_type = str(task.get("task_type") or "").strip().lower()
    if target_type in {"character", "scene", "prop"}:
        try:
            project_id = int(task.get("project_id") or 0)
        except Exception:
            project_id = 0
        project = LOCAL_COMIC_PROJECTS.get(project_id) if project_id else None
        if not isinstance(project, dict):
            return False
        collection = {"character": "characters", "scene": "scenes", "prop": "props"}.get(target_type)
        item = _local_comic_find_by_id(project.get(collection), task.get("target_id")) if collection else None
        if not isinstance(item, dict):
            return False
        result_url = str(task.get("result_url") or "").strip()
        return result_url not in _local_comic_item_reference_urls(item)
    if target_type != "storyboard" or ("video" not in task_type and "image" not in task_type):
        return False
    try:
        project_id = int(task.get("project_id") or 0)
    except Exception:
        project_id = 0
    project = LOCAL_COMIC_PROJECTS.get(project_id) if project_id else None
    if not isinstance(project, dict):
        return False
    storyboard = _local_comic_find_by_id(project.get("storyboards"), task.get("target_id"))
    if not isinstance(storyboard, dict):
        return False
    result_url = str(task.get("result_url") or "").strip()
    if "image" in task_type:
        return storyboard.get("image_url") != result_url or storyboard.get("imageUrl") != result_url
    return storyboard.get("video_url") != result_url or storyboard.get("videoUrl") != result_url


def _parse_ai_comic_platform_sync_time(value):
    value = str(value or "").strip()
    if not value:
        return None
    try:
        parsed = datetime.datetime.fromisoformat(value.replace("Z", "+00:00"))
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=datetime.timezone.utc)
        return parsed
    except Exception:
        return None


def _ai_comic_platform_sync_backoff_seconds(attempts):
    try:
        attempts = int(attempts or 0)
    except Exception:
        attempts = 0
    if attempts <= 1:
        return 60
    if attempts == 2:
        return 300
    if attempts == 3:
        return 900
    return 3600


def _sync_ai_comic_task_result_to_platform(handler, task):
    if not _has_platform_proxy_authorization(handler):
        return False
    if not _ai_comic_task_has_applyable_result(task):
        return False
    if task.get("platform_result_synced"):
        return True
    if task.get("platform_result_sync_skipped"):
        return False
    now = datetime.datetime.now(datetime.timezone.utc)
    next_at = _parse_ai_comic_platform_sync_time(task.get("platform_result_sync_next_at"))
    if next_at and next_at > now:
        return False
    target_type = str(task.get("target_type") or "").strip().lower()
    task_type = str(task.get("task_type") or "").strip().lower()
    if target_type not in {"character", "scene", "prop", "storyboard"}:
        return False
    target_id = str(task.get("target_id") or "").strip()
    result_url = str(task.get("result_url") or "").strip()
    if not target_id or not result_url:
        return False
    payload = {
        "result_url": result_url,
        "task_type": task_type,
        "workflow_mode": task.get("workflow_mode"),
        "frame_index": task.get("frame_index"),
    }
    try:
        project_id = int(task.get("project_id") or 0)
    except Exception:
        project_id = 0
    if not project_id:
        return False
    quoted_type = urllib.parse.quote(target_type)
    quoted_id = urllib.parse.quote(target_id)
    targets = [
        f"/comic-drama/projects/{project_id}/generation-results/{quoted_type}/{quoted_id}",
        f"/api/v1/comic-drama/projects/{project_id}/generation-results/{quoted_type}/{quoted_id}",
    ]
    last_status = 0
    last_payload = {}
    try:
        attempts = int(task.get("platform_result_sync_attempts") or 0) + 1
    except Exception:
        attempts = 1
    task["platform_result_sync_attempts"] = attempts
    task["platform_result_sync_last_at"] = now.isoformat()
    for target_path in targets:
        status, response_payload = _send_platform_json_for_current_request(handler, target_path, payload, "PUT")
        last_status, last_payload = status, response_payload
        if int(status or 0) in range(200, 300):
            task["platform_result_synced"] = True
            task["platform_result_synced_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
            task["platform_result_sync_path"] = target_path
            task["platform_result_sync_method"] = "PUT"
            task.pop("platform_result_sync_error", None)
            task.pop("platform_result_sync_next_at", None)
            _save_local_comic_state()
            _json_log(
                "ai_comic_task_result_synced_to_platform",
                task_id=task.get("id"),
                project_id=task.get("project_id"),
                target_type=target_type,
                target_id=target_id,
                path=target_path,
                method="PUT",
            )
            return True
        if int(status or 0) not in {404, 405}:
            break
    task["platform_result_sync_error"] = _platform_error_message(last_payload, f"平台回传失败：HTTP {last_status or 0}")
    task["platform_result_sync_status"] = last_status
    if int(last_status or 0) in {404, 405}:
        task["platform_result_sync_skipped"] = True
        task["platform_result_sync_skip_reason"] = "platform_endpoint_not_found"
        task["platform_result_sync_skipped_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        task.pop("platform_result_sync_next_at", None)
        _save_local_comic_state()
        _json_log(
            "ai_comic_task_result_platform_sync_skipped",
            task_id=task.get("id"),
            project_id=task.get("project_id"),
            target_type=target_type,
            target_id=target_id,
            status=last_status,
            error=task.get("platform_result_sync_error"),
        )
        return False
    task["platform_result_sync_next_at"] = (
        now + datetime.timedelta(seconds=_ai_comic_platform_sync_backoff_seconds(attempts))
    ).isoformat()
    _save_local_comic_state()
    _json_log(
        "ai_comic_task_result_platform_sync_failed",
        task_id=task.get("id"),
        project_id=task.get("project_id"),
        target_type=target_type,
        target_id=target_id,
        status=last_status,
        error=task.get("platform_result_sync_error"),
    )
    return False


def _sync_ai_comic_project_results_to_platform(handler, project_id):
    if not _has_platform_proxy_authorization(handler):
        return 0
    try:
        wanted_project_id = int(project_id or 0)
    except Exception:
        wanted_project_id = 0
    if not wanted_project_id:
        return 0
    synced = 0
    for task in list(AI_COMIC_TASKS.values()):
        if not isinstance(task, dict):
            continue
        try:
            task_project_id = int(task.get("project_id") or 0)
        except Exception:
            task_project_id = 0
        if task_project_id != wanted_project_id:
            continue
        if not _local_comic_task_belongs_to_project_scope(task, wanted_project_id):
            continue
        if _sync_ai_comic_task_result_to_platform(handler, task):
            synced += 1
    return synced


def _apply_completed_ai_comic_results_for_project(project_id, *, task_types=None):
    try:
        wanted_project_id = int(project_id or 0)
    except Exception:
        wanted_project_id = 0
    if not wanted_project_id or wanted_project_id not in LOCAL_COMIC_PROJECTS:
        return 0
    project = LOCAL_COMIC_PROJECTS.get(wanted_project_id) or {}
    storyboard_ids = {
        str(item.get("id") or item.get("storyboard_id") or "").strip()
        for item in (project.get("storyboards") or [])
        if isinstance(item, dict)
    }
    storyboard_ids.discard("")
    allowed_task_types = {str(item).strip() for item in (task_types or []) if str(item).strip()}
    applied = 0
    for task in list(AI_COMIC_TASKS.values()):
        if not isinstance(task, dict):
            continue
        task_type = str(task.get("task_type") or "").strip()
        if allowed_task_types and task_type not in allowed_task_types:
            continue
        try:
            task_project_id = int(task.get("project_id") or 0)
        except Exception:
            task_project_id = 0
        target_id = str(task.get("target_id") or "").strip()
        target_type = str(task.get("target_type") or "").strip().lower()
        if task_project_id == wanted_project_id and not _local_comic_task_belongs_to_project_scope(task, wanted_project_id):
            continue
        belongs_to_project = task_project_id == wanted_project_id or (target_type == "storyboard" and target_id in storyboard_ids)
        if not belongs_to_project:
            continue
        if _ai_comic_task_project_result_needs_sync(task):
            _mark_ai_comic_task_completed_from_result(task)
            apply_task = task
            if task_project_id != wanted_project_id:
                if target_type == "storyboard" and "video" in str(task.get("task_type") or "").lower():
                    storyboard = _local_comic_find_by_id(project.get("storyboards"), target_id)
                    current_video = str((storyboard or {}).get("video_url") or (storyboard or {}).get("videoUrl") or "").strip()
                    if current_video:
                        task["project_result_applied"] = True
                        task["project_result_applied_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
                        continue
                apply_task = dict(task)
                apply_task["project_id"] = wanted_project_id
            if _apply_ai_comic_task_result_to_project(apply_task):
                if apply_task is not task:
                    task["project_result_applied"] = True
                    task["project_result_applied_at"] = apply_task.get("project_result_applied_at") or datetime.datetime.now(datetime.timezone.utc).isoformat()
                applied += 1
    return applied


def _refresh_ai_comic_tasks_for_project(project_id, *, only_frame_tasks=False, limit=24, task_types=None):
    try:
        wanted_project_id = int(project_id or 0)
    except Exception:
        wanted_project_id = 0
    if not wanted_project_id:
        return 0
    allowed_task_types = {str(item).strip() for item in (task_types or []) if str(item).strip()}
    refreshed = 0
    candidates = []
    for task in list(AI_COMIC_TASKS.values()):
        if not isinstance(task, dict):
            continue
        try:
            task_project_id = int(task.get("project_id") or 0)
        except Exception:
            task_project_id = 0
        if task_project_id != wanted_project_id:
            continue
        if not _local_comic_task_belongs_to_project_scope(task, wanted_project_id):
            continue
        task_type = str(task.get("task_type") or "").strip()
        if allowed_task_types and task_type not in allowed_task_types:
            continue
        if only_frame_tasks:
            is_frame_task = bool(task.get("frame_index")) or str(task.get("workflow_mode") or "") in {"keyframes", "multiframe"}
            if not is_frame_task:
                continue
        candidates.append(task)
    candidates.sort(key=lambda item: str(item.get("created_at") or item.get("updated_at") or item.get("submitted_at") or ""), reverse=True)
    for task in candidates:
        if refreshed >= int(limit or 0):
            break
        if str(task.get("status") or "") in {"completed", "failed"}:
            if _ai_comic_task_has_applyable_result(task) and not task.get("project_result_applied"):
                _mark_ai_comic_task_completed_from_result(task)
                _apply_ai_comic_task_result_to_project(task)
            continue
        _refresh_ai_comic_task(task)
        refreshed += 1
    return refreshed


def _local_comic_target_exists(project, target_type, target_id):
    if not isinstance(project, dict):
        return False
    collection = {
        "character": "characters",
        "scene": "scenes",
        "prop": "props",
        "storyboard": "storyboards",
    }.get(str(target_type or "").strip())
    if not collection:
        return True
    if _local_comic_find_by_id(project.get(collection), target_id) is not None:
        return True
    if str(target_type or "").strip() == "storyboard":
        project_id = int(project.get("id") or 0)
        if project_id and _comic_storyboard_has_task_history(project_id, target_id):
            return True
    return False


def _comic_completed_action_frame_urls_from_tasks(project_id, storyboard_id):
    try:
        wanted_project_id = int(project_id or 0)
    except Exception:
        wanted_project_id = 0
    wanted_storyboard_id = str(storyboard_id or "").strip()
    frames = {}
    if not wanted_project_id or not wanted_storyboard_id:
        return []
    for task in list(AI_COMIC_TASKS.values()):
        if not isinstance(task, dict):
            continue
        try:
            task_project_id = int(task.get("project_id") or 0)
        except Exception:
            task_project_id = 0
        if task_project_id != wanted_project_id:
            continue
        if str(task.get("target_id") or "").strip() != wanted_storyboard_id:
            continue
        if str(task.get("workflow_mode") or "").strip() != "multiframe":
            continue
        if str(task.get("status") or "").strip() != "completed":
            continue
        result_url = str(task.get("result_url") or "").strip()
        if not result_url:
            continue
        try:
            frame_index = int(task.get("frame_index") or 0)
        except Exception:
            frame_index = 0
        if 1 <= frame_index <= 7:
            frames[frame_index] = result_url
    return [frames[index] for index in range(1, 8) if frames.get(index)]


def _comic_project_id_from_storyboard_tasks(storyboard_id):
    wanted_storyboard_id = str(storyboard_id or "").strip()
    if not wanted_storyboard_id:
        return 0
    candidates = {}
    for task in list(AI_COMIC_TASKS.values()):
        if not isinstance(task, dict):
            continue
        if not _local_comic_scope_allows_task(task):
            continue
        if str(task.get("target_id") or "").strip() != wanted_storyboard_id:
            continue
        try:
            project_id = int(task.get("project_id") or 0)
        except Exception:
            project_id = 0
        if not project_id:
            continue
        workflow_mode = str(task.get("workflow_mode") or "").strip()
        status = str(task.get("status") or "").strip()
        score = 0
        if status == "completed":
            score += 1
        if str(task.get("result_url") or "").strip():
            score += 2
        if str(task.get("task_type") or "").strip() == "generate_video":
            score += 1
        if workflow_mode == "multiframe":
            score += 3
        elif workflow_mode == "keyframes":
            score += 2
        elif workflow_mode:
            score += 1
        if score:
            candidates[project_id] = candidates.get(project_id, 0) + score
    if not candidates:
        return 0
    return max(candidates.items(), key=lambda item: (item[1], item[0]))[0]


def _comic_storyboard_has_task_history(project_id, storyboard_id):
    try:
        wanted_project_id = int(project_id or 0)
    except Exception:
        wanted_project_id = 0
    wanted_storyboard_id = str(storyboard_id or "").strip()
    if not wanted_project_id or not wanted_storyboard_id:
        return False
    for task in list(AI_COMIC_TASKS.values()):
        if not isinstance(task, dict):
            continue
        if not _local_comic_scope_allows_task(task):
            continue
        if str(task.get("target_id") or "").strip() != wanted_storyboard_id:
            continue
        try:
            task_project_id = int(task.get("project_id") or 0)
        except Exception:
            task_project_id = 0
        if task_project_id != wanted_project_id:
            continue
        if str(task.get("status") or "").strip() not in {"completed", "failed"}:
            continue
        if str(task.get("result_url") or "").strip() or str(task.get("workflow_mode") or "").strip():
            return True
    return False


def _comic_storyboard_has_completed_action_frames(project_id, storyboard_id):
    return len(_comic_completed_action_frame_urls_from_tasks(project_id, storyboard_id)) >= 7


def _reject_missing_local_comic_target(handler, project_id, target_type="", target_id=None):
    try:
        project_id = int(project_id or 0)
    except Exception:
        project_id = 0
    project = LOCAL_COMIC_PROJECTS.get(project_id)
    if not isinstance(project, dict) and project_id:
        project = _sync_local_comic_project_from_platform(handler, project_id)
    if not isinstance(project, dict):
        if str(target_type or "").strip() == "storyboard":
            fallback_project_id = _comic_project_id_from_storyboard_tasks(target_id)
            if fallback_project_id and _comic_storyboard_has_task_history(fallback_project_id, target_id):
                return False
        if _has_platform_proxy_authorization(handler):
            return False
        _send_json_with_headers(
            handler,
            404,
            {
                "detail": f"本地漫剧项目 {project_id} 不存在，不能提交生成任务。请先重新进入/同步项目后再生成。",
                "localDev": True,
            },
        )
        return True
    if target_type and not _local_comic_target_exists(project, target_type, target_id):
        synced_project = _sync_local_comic_project_from_platform(handler, project_id)
        if isinstance(synced_project, dict) and _local_comic_target_exists(synced_project, target_type, target_id):
            return False
        if str(target_type or "").strip() == "storyboard":
            fallback_project_id = _comic_project_id_from_storyboard_tasks(target_id)
            if fallback_project_id and _comic_storyboard_has_task_history(fallback_project_id, target_id):
                return False
        _send_json_with_headers(
            handler,
            404,
            {
                "detail": f"本地{target_type}目标 {target_id} 不存在，不能提交生成任务。请刷新项目后重试。",
                "localDev": True,
            },
        )
        return True
    return False


def _platform_comic_project_for_request(handler, project_id):
    try:
        project_id = int(project_id or 0)
    except Exception:
        project_id = 0
    if not project_id or not _has_platform_proxy_authorization(handler):
        return {}
    status, payload = _fetch_platform_json_for_current_request(
        handler,
        f"/comic-drama/projects/{project_id}?include_details=true",
    )
    if int(status or 0) not in range(200, 300) or not isinstance(payload, dict):
        return {}
    data = payload.get("data") if isinstance(payload.get("data"), dict) else payload
    return data if isinstance(data, dict) else {}


def _sync_local_comic_project_from_platform(handler, project_id):
    try:
        project_id = int(project_id or 0)
    except Exception:
        project_id = 0
    if not project_id:
        return None
    platform_project = _platform_comic_project_for_request(handler, project_id)
    if not isinstance(platform_project, dict) or not platform_project:
        return None
    existing = LOCAL_COMIC_PROJECTS.get(project_id) if isinstance(LOCAL_COMIC_PROJECTS.get(project_id), dict) else {}
    request_scope = _sanitize_account_scope(_get_request_account_scope())
    existing_scope = _local_comic_project_owner_scope(existing)
    if request_scope and existing_scope and existing_scope != request_scope:
        existing = {}
    source_text = _first_non_empty(platform_project.get("source_text"), platform_project.get("description"), platform_project.get("title"))
    preserve_existing_details = bool(existing) and _local_comic_storyboards_match_source(source_text, existing.get("storyboards") or [])
    if existing and not preserve_existing_details:
        _json_log("local_comic_platform_sync_existing_details_rejected", project_id=project_id, request_scope=request_scope)
    merged = {**existing, **platform_project}
    merged["id"] = int(platform_project.get("id") or project_id)
    merged["storyboards"] = platform_project.get("storyboards") or (existing.get("storyboards") if preserve_existing_details else []) or []
    merged["characters"] = platform_project.get("characters") or (existing.get("characters") if preserve_existing_details else []) or []
    merged["scenes"] = platform_project.get("scenes") or (existing.get("scenes") if preserve_existing_details else []) or []
    merged["props"] = platform_project.get("props") or (existing.get("props") if preserve_existing_details else []) or []
    if request_scope:
        merged["account_scope"] = request_scope
    if preserve_existing_details and existing.get("agent_session") and not merged.get("agent_session"):
        merged["agent_session"] = existing.get("agent_session")
    if preserve_existing_details and existing.get("agent_task_group_id") and not merged.get("agent_task_group_id"):
        merged["agent_task_group_id"] = existing.get("agent_task_group_id")
    LOCAL_COMIC_PROJECTS[project_id] = merged
    _save_local_comic_state()
    return merged


def _comic_project_for_generation(handler, project_id):
    try:
        project_id = int(project_id or 0)
    except Exception:
        project_id = 0
    local_project = LOCAL_COMIC_PROJECTS.get(project_id)
    if isinstance(local_project, dict):
        return local_project
    synced = _sync_local_comic_project_from_platform(handler, project_id)
    if isinstance(synced, dict):
        return synced
    return _platform_comic_project_for_request(handler, project_id)


