def _normalize_ai_task_status(status_payload):
    status_payload = status_payload if isinstance(status_payload, dict) else {}
    state = str(status_payload.get("state") or "").strip().lower()
    status_text = str(status_payload.get("status") or status_payload.get("task_status") or "").strip().lower()
    group = str(status_payload.get("status_group") or "").strip()
    is_final = bool(status_payload.get("is_final"))
    if state == "success" or group == "已完成":
        status = "completed"
        progress = 100
    elif state in {"failed", "failure", "error", "expired", "cancelled", "canceled"} or status_text in {"failed", "failure", "error"} or group == "失败":
        status = "failed"
        progress = 100
    elif is_final:
        status = "failed"
        progress = 100
    else:
        status = "running" if state in {"running", "processing"} or group == "处理中" else "pending"
        raw_progress = str(status_payload.get("progress") or "0").strip().rstrip("%")
        try:
            progress = max(0, min(99, int(float(raw_progress))))
        except Exception:
            progress = 0
    return status, progress


def _extract_ai_result_url(payload):
    if not isinstance(payload, dict):
        return ""
    keys = (
        "result_url",
        "url",
        "image_url",
        "video_url",
        "videoUrls",
        "imageUrls",
        "fileUrls",
        "downloadUrls",
        "audio_url",
        "output",
        "fileUrl",
        "file_url",
        "videoUrl",
        "audioUrl",
        "imageUrl",
        "media_url",
        "download_url",
    )
    for key in keys:
        value = payload.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
    for key in ("data", "result", "response", "payload"):
        value = payload.get(key)
        if isinstance(value, dict):
            found = _extract_ai_result_url(value)
            if found:
                return found
        elif isinstance(value, list):
            for item in value:
                found = _extract_ai_result_url(item)
                if found:
                    return found
    for key in ("results", "images", "files", "outputs", "videoUrls", "imageUrls", "fileUrls", "downloadUrls", "urls"):
        value = payload.get(key)
        if isinstance(value, list):
            for item in value:
                found = _extract_ai_result_url(item)
                if found:
                    return found
                if isinstance(item, str) and item.strip():
                    return item.strip()
    return ""


def _fallback_ai_comic_task_result_url(task):
    if not isinstance(task, dict):
        return ""
    target_type = str(task.get("target_type") or "").strip().lower()
    if target_type != "storyboard":
        return ""
    try:
        project_id = int(task.get("project_id") or 0)
    except Exception:
        project_id = 0
    if not project_id:
        return ""
    storyboard_id = str(task.get("target_id") or "").strip()
    if not storyboard_id:
        return ""
    project = LOCAL_COMIC_PROJECTS.get(project_id)
    if not isinstance(project, dict):
        return ""
    storyboard = _local_comic_find_by_id(project.get("storyboards"), storyboard_id)
    if not isinstance(storyboard, dict):
        return ""
    task_type = str(task.get("task_type") or "").lower()
    if "video" in task_type:
        return str(storyboard.get("video_url") or storyboard.get("videoUrl") or "").strip()
    return str(
        storyboard.get("image_url")
        or storyboard.get("imageUrl")
        or storyboard.get("start_frame_url")
        or storyboard.get("startFrameUrl")
        or storyboard.get("end_frame_url")
        or storyboard.get("endFrameUrl")
        or ""
    ).strip()


