def _local_comic_auto_edit_now():
    return datetime.datetime.now(datetime.timezone.utc).isoformat()


def _local_comic_auto_edit_source(storyboard):
    if not isinstance(storyboard, dict):
        return ""
    return _clean_media_url(
        _first_non_empty(
            storyboard.get("video_url"),
            storyboard.get("videoUrl"),
            storyboard.get("result_video_url"),
            storyboard.get("resultVideoUrl"),
            storyboard.get("media_url"),
            storyboard.get("mediaUrl"),
        )
    )


def _comic_task_sort_time(task):
    if not isinstance(task, dict):
        return 0.0
    for key in ("completed_at", "completedAt", "updated_at", "updatedAt", "created_at", "createdAt"):
        value = str(task.get(key) or "").strip()
        if not value:
            continue
        try:
            return datetime.datetime.fromisoformat(value.replace("Z", "+00:00")).timestamp()
        except Exception:
            continue
    return 0.0


def _local_comic_auto_edit_task_videos(project):
    try:
        wanted_project_id = int((project or {}).get("id") or 0)
    except Exception:
        wanted_project_id = 0
    if not wanted_project_id:
        return {}
    storyboard_ids = {
        str(item.get("id") or item.get("storyboard_id") or "").strip()
        for item in ((project or {}).get("storyboards") or [])
        if isinstance(item, dict)
    }
    storyboard_ids.discard("")
    by_storyboard = {}
    by_storyboard_time = {}
    seen_task_ids = set()
    tasks = [*LOCAL_COMIC_TASKS.values(), *AI_COMIC_TASKS.values()]
    for task in tasks:
        if not isinstance(task, dict):
            continue
        task_id = str(task.get("id") or task.get("task_id") or "")
        if task_id and task_id in seen_task_ids:
            continue
        if task_id:
            seen_task_ids.add(task_id)
        try:
            task_project_id = int(task.get("project_id") or 0)
        except Exception:
            task_project_id = 0
        storyboard_id = str(task.get("target_id") or "").strip()
        target_type = str(task.get("target_type") or "").lower()
        if task_project_id == wanted_project_id and not _local_comic_task_belongs_to_project_scope(task, wanted_project_id):
            continue
        belongs_to_project = task_project_id == wanted_project_id or (target_type == "storyboard" and storyboard_id in storyboard_ids)
        if not belongs_to_project:
            continue
        if str(task.get("status") or "").lower() != "completed":
            continue
        if target_type != "storyboard":
            continue
        if "video" not in str(task.get("task_type") or "").lower():
            continue
        result_url = _clean_media_url(_first_non_empty(task.get("result_url"), task.get("video_url"), task.get("url")))
        if not storyboard_id or not result_url:
            continue
        task_time = _comic_task_sort_time(task)
        if storyboard_id not in by_storyboard or task_time >= by_storyboard_time.get(storyboard_id, 0.0):
            by_storyboard[storyboard_id] = result_url
            by_storyboard_time[storyboard_id] = task_time
    return by_storyboard


def _local_comic_billing_amount(value):
    if not isinstance(value, dict):
        return 0.0
    candidates = [
        value.get("billing_amount"),
        value.get("billingAmount"),
        value.get("charged_amount"),
        value.get("chargedAmount"),
        value.get("cost_amount"),
        value.get("costAmount"),
    ]
    for key in ("billing_usage_log", "billingUsageLog", "usage_log", "usageLog"):
        nested = value.get(key)
        if isinstance(nested, dict):
            candidates.extend([nested.get("amount"), nested.get("billing_amount"), nested.get("billingAmount")])
    usage = value.get("usage")
    if isinstance(usage, dict):
        usage_log = usage.get("usage_log") or usage.get("usageLog")
        if isinstance(usage_log, dict):
            candidates.append(usage_log.get("amount"))
    for candidate in candidates:
        if candidate in (None, ""):
            continue
        try:
            amount = float(candidate)
        except (TypeError, ValueError):
            continue
        if amount > 0:
            return round(amount, 6)
    return 0.0


def _extract_ai_actual_cost(payload):
    if not isinstance(payload, dict):
        return 0.0
    for key in ("cost", "actual_cost", "actualCost", "charged_amount", "chargedAmount"):
        value = payload.get(key)
        if value in (None, ""):
            continue
        try:
            amount = float(value)
        except (TypeError, ValueError):
            continue
        if amount > 0:
            return round(amount, 6)
    for key in ("data", "result", "response", "payload"):
        amount = _extract_ai_actual_cost(payload.get(key))
        if amount > 0:
            return amount
    return 0.0


def _local_comic_auto_edit_billing_summary(project, plan):
    source_urls = {
        _clean_media_url(clip.get("source"))
        for clip in (plan.get("clips") if isinstance(plan, dict) else []) or []
        if isinstance(clip, dict)
    }
    source_urls.discard("")
    if not source_urls:
        return {}
    try:
        wanted_project_id = int((project or {}).get("id") or 0)
    except Exception:
        wanted_project_id = 0
    if not wanted_project_id:
        return {}
    seen_task_ids = set()
    seen_urls = set()
    items = []
    total = 0.0
    for task in [*LOCAL_COMIC_TASKS.values(), *AI_COMIC_TASKS.values()]:
        if not isinstance(task, dict):
            continue
        task_id = str(task.get("id") or task.get("task_id") or "").strip()
        if task_id and task_id in seen_task_ids:
            continue
        if task_id:
            seen_task_ids.add(task_id)
        try:
            task_project_id = int(task.get("project_id") or 0)
        except Exception:
            task_project_id = 0
        if task_project_id != wanted_project_id or not _local_comic_task_belongs_to_project_scope(task, wanted_project_id):
            continue
        if str(task.get("status") or "").lower() != "completed":
            continue
        if str(task.get("target_type") or "").lower() != "storyboard":
            continue
        if "video" not in str(task.get("task_type") or "").lower():
            continue
        result_url = _clean_media_url(_first_non_empty(task.get("result_url"), task.get("video_url"), task.get("url")))
        if not result_url or result_url not in source_urls or result_url in seen_urls:
            continue
        amount = _local_comic_billing_amount(task)
        if amount <= 0:
            continue
        seen_urls.add(result_url)
        total += amount
        items.append({
            "task_id": task_id,
            "taskId": task_id,
            "url": result_url,
            "amount": amount,
            "billing_amount": amount,
            "billingAmount": amount,
        })
    if total <= 0:
        return {}
    total = round(total, 6)
    return {
        "amount": total,
        "billing_amount": total,
        "billingAmount": total,
        "items": items,
        "billing_items": items,
        "billingItems": items,
    }


def _local_comic_auto_edit_storyboards(project):
    items = [item for item in (project.get("storyboards") or []) if isinstance(item, dict)]

    def _sort_key(item):
        for key in ("sequence", "order", "index", "id"):
            try:
                return int(item.get(key) or 0)
            except Exception:
                pass
        return 0

    return sorted(items, key=_sort_key)


def _local_comic_auto_edit_resolve_source(source):
    text = str(source or "").strip()
    if not text:
        return ""
    if re.match(r"^https?://", text, flags=re.IGNORECASE):
        return text
    resolved = _resolve_local_virtual_path(text)
    if resolved and os.path.isfile(resolved):
        return os.path.abspath(resolved)
    decoded = urllib.parse.unquote(urllib.parse.urlsplit(text).path or text).replace("\\", "/")
    roots = (
        ("/uploads/", _current_uploads_dir()),
        ("/data/uploads/", _current_uploads_dir()),
        ("/output/", _current_output_dir()),
        ("uploads/", _current_uploads_dir()),
        ("data/uploads/", _current_uploads_dir()),
        ("output/", _current_output_dir()),
    )
    for prefix, root in roots:
        if decoded.startswith(prefix):
            rel = decoded[len(prefix):].lstrip("/")
            candidate = os.path.abspath(os.path.join(root, rel))
            if _is_path_inside(candidate, root) and os.path.isfile(candidate):
                return candidate
    return text


def _local_comic_auto_edit_probe(source):
    meta = {"duration": 0.0, "has_audio": False}
    probe = shutil.which(FFPROBE_EXE) or shutil.which("ffprobe") or FFPROBE_EXE
    try:
        result = subprocess.run(
            [
                probe,
                "-v",
                "error",
                "-show_entries",
                "format=duration:stream=codec_type",
                "-of",
                "json",
                str(source),
            ],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            timeout=20,
        )
        if result.returncode != 0:
            return meta
        payload = json.loads(result.stdout or "{}")
        try:
            meta["duration"] = max(0.0, float((payload.get("format") or {}).get("duration") or 0.0))
        except Exception:
            meta["duration"] = 0.0
        for stream in payload.get("streams") or []:
            if isinstance(stream, dict) and str(stream.get("codec_type") or "").lower() == "audio":
                meta["has_audio"] = True
                break
    except Exception:
        pass
    return meta


def _local_comic_auto_edit_silence_trims(source, duration):
    if not source or not duration or duration <= 0:
        return 0.0, 0.0
    ffmpeg = shutil.which(FFMPEG_EXE) or shutil.which("ffmpeg") or FFMPEG_EXE
    try:
        result = subprocess.run(
            [
                ffmpeg,
                "-hide_banner",
                "-nostdin",
                "-i",
                str(source),
                "-af",
                f"silencedetect=n={COMIC_AUTO_EDIT_SILENCE_DB}dB:d={COMIC_AUTO_EDIT_SILENCE_MIN_DURATION}",
                "-f",
                "null",
                "-",
            ],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            timeout=45,
        )
    except Exception:
        return 0.0, 0.0
    if result.returncode not in (0, 1):
        return 0.0, 0.0
    text = f"{result.stderr or ''}\n{result.stdout or ''}"
    try:
        starts = [float(value) for value in re.findall(r"silence_start:\s*([0-9.]+)", text)]
        ends = [float(value) for value in re.findall(r"silence_end:\s*([0-9.]+)", text)]
    except Exception:
        return 0.0, 0.0
    leading = 0.0
    trailing = 0.0
    if starts and starts[0] <= 0.08 and ends:
        leading = max(0.0, min(ends[0], duration) - COMIC_AUTO_EDIT_SILENCE_MARGIN)
    if starts:
        last_start = starts[-1]
        has_open_tail = not ends or len(ends) < len(starts)
        ends_at_tail = bool(ends and len(ends) >= len(starts) and ends[-1] >= duration - 0.08)
        if last_start < duration and (has_open_tail or ends_at_tail):
            trailing = max(0.0, duration - last_start - COMIC_AUTO_EDIT_SILENCE_MARGIN)
    max_trim = max(0.0, duration - 0.8)
    leading = min(leading, max_trim)
    trailing = min(trailing, max(0.0, duration - leading - 0.8))
    return round(leading, 3), round(trailing, 3)


def _local_comic_auto_edit_black_trims(source, duration):
    if not source or not duration or duration <= 0:
        return 0.0, 0.0
    ffmpeg = shutil.which(FFMPEG_EXE) or shutil.which("ffmpeg") or FFMPEG_EXE
    try:
        result = subprocess.run(
            [
                ffmpeg,
                "-hide_banner",
                "-nostdin",
                "-i",
                str(source),
                "-vf",
                f"blackdetect=d={COMIC_AUTO_EDIT_BLACK_MIN_DURATION}:pix_th=0.10",
                "-an",
                "-f",
                "null",
                "-",
            ],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            timeout=45,
        )
    except Exception:
        return 0.0, 0.0
    if result.returncode not in (0, 1):
        return 0.0, 0.0
    text = f"{result.stderr or ''}\n{result.stdout or ''}"
    blocks = []
    for match in re.finditer(r"black_start:\s*([0-9.]+)\s+black_end:\s*([0-9.]+)", text):
        try:
            blocks.append((float(match.group(1)), float(match.group(2))))
        except Exception:
            continue
    leading = 0.0
    trailing = 0.0
    for start, end in blocks:
        if start <= 0.08:
            leading = max(leading, max(0.0, min(end, duration) - COMIC_AUTO_EDIT_BLACK_MARGIN))
        if end >= duration - 0.08:
            trailing = max(trailing, max(0.0, duration - start - COMIC_AUTO_EDIT_BLACK_MARGIN))
    max_trim = max(0.0, duration - COMIC_AUTO_EDIT_MIN_CLIP_SECONDS)
    leading = min(leading, max_trim)
    trailing = min(trailing, max(0.0, duration - leading - COMIC_AUTO_EDIT_MIN_CLIP_SECONDS))
    return round(leading, 3), round(trailing, 3)


def _local_comic_auto_edit_storyboard_text(storyboard):
    if not isinstance(storyboard, dict):
        return ""
    parts = []
    for key in (
        "title",
        "scene",
        "script",
        "dialogue",
        "description",
        "camera",
        "camera_movement",
        "visual_prompt",
        "video_prompt",
        "prompt",
    ):
        value = storyboard.get(key)
        if value not in (None, "", [], {}):
            parts.append(str(value))
    return " ".join(parts)


def _local_comic_auto_edit_has_dialogue(storyboard):
    if not isinstance(storyboard, dict):
        return False

    no_dialogue_values = {
        "",
        "无",
        "没有",
        "无需",
        "无台词",
        "无对白",
        "无旁白",
        "无配音或对白",
        "none",
        "null",
    }

    def _is_dialogue(value):
        if isinstance(value, dict):
            value = _first_non_empty(value.get("text"), value.get("content"), value.get("dialogue"))
        text = str(value or "").strip().strip("；;，,。.!！")
        compact = re.sub(r"\s+", "", text).lower()
        return bool(compact and compact not in no_dialogue_values)

    audio_prompt = storyboard.get("audio_prompt") or storyboard.get("audioPrompt") or {}
    audio_dialogue = audio_prompt.get("dialogue") if isinstance(audio_prompt, dict) else None
    for value in (
        storyboard.get("dialogue"),
        storyboard.get("dialogue_text"),
        storyboard.get("dialogueText"),
        storyboard.get("audio_text"),
        storyboard.get("audioText"),
        audio_dialogue,
    ):
        if _is_dialogue(value):
            return True

    text = _local_comic_auto_edit_storyboard_text(storyboard)
    for match in re.finditer(r"(?:台词|对白|旁白)\s*[:：]\s*([^；;\n。]*)", text, flags=re.IGNORECASE):
        if _is_dialogue(match.group(1)):
            return True
    return bool(re.search(r"[A-Za-z0-9_\u4e00-\u9fff]{1,30}\s*[:：]\s*[‘'“\"]\s*[^’'”\"]+", text))


def _local_comic_auto_edit_pacing(storyboard, index, total, duration):
    text = _local_comic_auto_edit_storyboard_text(storyboard).lower()
    fast_words = ("追", "跑", "打", "爆", "冲", "撞", "逃", "闪", "战斗", "动作", "紧张", "急促", "chase", "fight", "run", "action")
    slow_words = ("凝视", "沉默", "回忆", "独白", "对话", "特写", "慢慢", "停顿", "悲伤", "温柔", "close", "slow", "dialogue")
    if any(word in text for word in fast_words):
        return {
            "pace": "fast",
            "max_duration": COMIC_AUTO_EDIT_FAST_MAX_CLIP_SECONDS,
            "transition": "cut",
            "transition_duration": COMIC_AUTO_EDIT_MICRO_TRANSITION_SECONDS,
            "reason": "动作/紧张镜头，缩短停留并使用几乎不可见的微切",
        }
    if any(word in text for word in slow_words):
        return {
            "pace": "slow",
            "max_duration": COMIC_AUTO_EDIT_SLOW_MAX_CLIP_SECONDS,
            "transition": "fade" if index > 1 else "cut",
            "transition_duration": 0.26,
            "reason": "对白/情绪镜头，保留表演并使用柔和过渡",
        }
    return {
        "pace": "normal",
        "max_duration": COMIC_AUTO_EDIT_DEFAULT_MAX_CLIP_SECONDS,
        "transition": "cut" if index <= 1 or index % 3 else "fade",
        "transition_duration": COMIC_AUTO_EDIT_MICRO_TRANSITION_SECONDS if index <= 1 or index % 3 else 0.22,
        "reason": "常规叙事镜头，以自然切换为主，少量柔和过渡",
    }


def _local_comic_auto_edit_build_plan(project):
    clips = []
    project_id = int(project.get("id") or 0) if isinstance(project, dict) else 0
    task_videos = _local_comic_auto_edit_task_videos(project)
    for storyboard in _local_comic_auto_edit_storyboards(project):
        source_url = _local_comic_auto_edit_source(storyboard)
        storyboard_id = str(storyboard.get("id") or storyboard.get("storyboard_id") or "").strip()
        task_source_url = task_videos.get(storyboard_id, "") if storyboard_id else ""
        if task_source_url and task_source_url != source_url:
            history_values = storyboard.get("video_history") or storyboard.get("videoHistory") or []
            if isinstance(history_values, str):
                history_values = [history_values]
            history = _dedupe_urls(history_values if isinstance(history_values, list) else [])
            if source_url:
                history = _append_unique_url(history, source_url)
            source_url = task_source_url
            storyboard["video_history"] = [url for url in history if url != source_url][:12]
            storyboard["videoHistory"] = list(storyboard["video_history"])
            storyboard["video_url"] = source_url
            storyboard["videoUrl"] = source_url
            storyboard["videoStatus"] = "completed"
        elif not source_url and task_source_url:
            source_url = task_source_url
            storyboard["video_url"] = source_url
            storyboard["videoUrl"] = source_url
            storyboard["videoStatus"] = "completed"
        if not source_url:
            continue
        source = _local_comic_auto_edit_resolve_source(source_url)
        media = _local_comic_auto_edit_probe(source)
        duration = float(media.get("duration") or 0.0)
        if duration <= 0:
            try:
                duration = float(_first_non_empty(storyboard.get("video_duration"), storyboard.get("videoDuration"), 5))
            except Exception:
                duration = 5.0
        clip_index = len(clips) + 1
        total_count = len(project.get("storyboards") or []) if isinstance(project, dict) else 0
        pacing = _local_comic_auto_edit_pacing(storyboard, clip_index, total_count, duration)
        dialogue_protected = _local_comic_auto_edit_has_dialogue(storyboard)
        silence_head_trim, silence_tail_trim = 0.0, 0.0
        if media.get("has_audio"):
            silence_head_trim, silence_tail_trim = _local_comic_auto_edit_silence_trims(source, duration)
        black_head_trim, black_tail_trim = (0.0, 0.0)
        if not dialogue_protected:
            black_head_trim, black_tail_trim = _local_comic_auto_edit_black_trims(source, duration)
        head_trim = max(silence_head_trim, black_head_trim)
        tail_trim = max(silence_tail_trim, black_tail_trim)
        start = min(head_trim, max(0.0, duration - 0.8))
        clip_duration = max(0.5, duration - start - tail_trim)
        clip_duration = min(clip_duration, max(0.5, duration - start))
        transition_duration = min(
            float(pacing.get("transition_duration") or COMIC_AUTO_EDIT_TRANSITION_SECONDS),
            max(0.0, (clip_duration - COMIC_AUTO_EDIT_MIN_CLIP_SECONDS) / 2.0),
        )
        clips.append(
            {
                "index": clip_index,
                "storyboard_id": storyboard.get("id"),
                "storyboardId": storyboard.get("id"),
                "title": _first_non_empty(storyboard.get("title"), storyboard.get("scene"), f"分镜 {clip_index}"),
                "source": source_url,
                "start": round(start, 3),
                "duration": round(clip_duration, 3),
                "transition": pacing.get("transition") or ("fade" if clips else "cut"),
                "transition_duration": round(transition_duration, 3),
                "pace": pacing.get("pace") or "normal",
                "edit_reason": pacing.get("reason") or "",
                "has_audio": bool(media.get("has_audio")),
                "dialogue_protected": dialogue_protected,
                "silence_head_trim": silence_head_trim,
                "silence_tail_trim": silence_tail_trim,
                "black_head_trim": black_head_trim,
                "black_tail_trim": black_tail_trim,
            }
        )
    if not clips:
        raise ValueError("没有可用于自动剪辑的分镜视频，请先生成至少一个分镜视频。")
    return {
        "version": 1,
        "strategy": "professional-auto-edit-v1",
        "edit_features": [
            "latest-storyboard-video",
            "silence-trim",
            "black-trim",
            "pacing-aware-duration",
            "selective-transition",
            "audio-crossfade",
            "audio-normalize",
            "visual-polish",
        ],
        "width": COMIC_AUTO_EDIT_WIDTH,
        "height": COMIC_AUTO_EDIT_HEIGHT,
        "fps": COMIC_AUTO_EDIT_FPS,
        "clip_count": len(clips),
        "clipCount": len(clips),
        "clips": clips,
    }


def _local_comic_auto_edit_set_task(task, **updates):
    if not isinstance(task, dict):
        return
    task.update(updates)
    task["updated_at"] = _local_comic_auto_edit_now()


def _local_comic_auto_edit_reconcile_project_from_task(project, task=None):
    if not isinstance(project, dict):
        return False
    task_id = str(project.get("auto_edit_task_id") or "")
    if task is None and task_id:
        task = LOCAL_COMIC_TASKS.get(task_id)
    if not isinstance(task, dict):
        return False
    task_status = str(task.get("status") or task.get("state") or "").strip().lower()
    final_url = _first_non_empty(task.get("result_url"), task.get("video_url"), task.get("url"))
    changed = False
    if task_status == "completed" and final_url:
        completed_at = _first_non_empty(task.get("completed_at"), task.get("completedAt"), _local_comic_auto_edit_now())
        updates = {
            "auto_edit_status": "completed",
            "autoEditStatus": "completed",
            "auto_edit_error": "",
            "final_video_url": final_url,
            "finalVideoUrl": final_url,
            "auto_edit_completed_at": completed_at,
            "autoEditCompletedAt": completed_at,
        }
        for key, value in updates.items():
            if project.get(key) != value:
                project[key] = value
                changed = True
        history_item = {
            "url": final_url,
            "final_video_url": final_url,
            "finalVideoUrl": final_url,
            "title": "完整视频",
            "status": "completed",
            "completed_at": completed_at,
            "completedAt": completed_at,
        }
        billing_amount = _local_comic_billing_amount(task) or _local_comic_billing_amount(project.get("auto_edit_plan"))
        if billing_amount > 0:
            history_item["billing_amount"] = billing_amount
            history_item["billingAmount"] = billing_amount
        history = [
            item
            for item in (project.get("auto_edit_history") or project.get("autoEditHistory") or [])
            if isinstance(item, dict)
        ]
        if not any(_first_non_empty(item.get("url"), item.get("final_video_url"), item.get("finalVideoUrl")) == final_url for item in history):
            history.insert(0, history_item)
            project["auto_edit_history"] = history[:20]
            project["autoEditHistory"] = list(project["auto_edit_history"])
            changed = True
        if not task.get("project_result_applied"):
            task["project_result_applied"] = True
            task["project_result_applied_at"] = completed_at
            changed = True
    elif task_status == "failed" and str(project.get("auto_edit_status") or "").lower() in {"", "idle", "pending", "planning", "rendering", "running"}:
        project["auto_edit_status"] = "failed"
        project["autoEditStatus"] = "failed"
        project["auto_edit_error"] = _first_non_empty(task.get("error_message"), task.get("current_step"), "自动剪辑失败")
        changed = True
    if changed:
        project["updated_at"] = _local_comic_auto_edit_now()
    return changed


def _local_comic_auto_edit_concat_line(path_value):
    normalized = os.path.abspath(str(path_value or "")).replace("\\", "/")
    return "file '" + normalized.replace("'", "'\\''") + "'\n"


def _local_comic_auto_edit_render(project, plan, task):
    ffmpeg = shutil.which(FFMPEG_EXE) or shutil.which("ffmpeg") or FFMPEG_EXE
    output_root = os.path.join(_current_uploads_dir(), "comic-drama")
    os.makedirs(output_root, exist_ok=True)
    work_dir = tempfile.mkdtemp(prefix="auto_edit_", dir=output_root)
    segment_paths = []
    segment_durations = []
    clips = list(plan.get("clips") or [])
    try:
        for index, clip in enumerate(clips, start=1):
            progress = 10 + int((index - 1) * 75 / max(1, len(clips)))
            _local_comic_auto_edit_set_task(
                task,
                status="running",
                state="rendering",
                progress_percent=progress,
                current_step=f"正在剪辑第 {index}/{len(clips)} 个分镜",
            )
            _save_local_comic_state()
            source = _local_comic_auto_edit_resolve_source(clip.get("source"))
            if not source:
                raise RuntimeError(f"第 {index} 个分镜缺少视频源")
            media = _local_comic_auto_edit_probe(source)
            duration = float(clip.get("duration") or media.get("duration") or 0.0)
            if duration <= 0:
                raise RuntimeError(f"第 {index} 个分镜视频时长不可用")
            start = max(0.0, float(clip.get("start") or 0.0))
            duration = max(0.5, duration)
            fade_in = min(0.10, duration / 3.0) if index == 1 else 0.0
            fade_out = min(0.14, duration / 3.0) if index == len(clips) else 0.0
            fade_out_start = max(0.0, duration - fade_out)
            out_path = os.path.join(work_dir, f"segment_{index:03d}.mp4")
            pace = str(clip.get("pace") or "normal").lower()
            polish = "eq=contrast=1.025:saturation=1.035:brightness=0.002,unsharp=3:3:0.35:3:3:0.0"
            if pace == "fast":
                polish = "eq=contrast=1.04:saturation=1.04:brightness=0.002,unsharp=3:3:0.45:3:3:0.0"
            elif pace == "slow":
                polish = "eq=contrast=1.015:saturation=1.02:brightness=0.001,unsharp=3:3:0.25:3:3:0.0"
            vf = (
                f"scale={COMIC_AUTO_EDIT_WIDTH}:{COMIC_AUTO_EDIT_HEIGHT}:force_original_aspect_ratio=decrease,"
                f"pad={COMIC_AUTO_EDIT_WIDTH}:{COMIC_AUTO_EDIT_HEIGHT}:(ow-iw)/2:(oh-ih)/2,"
                f"setsar=1,fps={COMIC_AUTO_EDIT_FPS},format=yuv420p,"
                f"{polish}"
            )
            if fade_in > 0:
                vf += f",fade=t=in:st=0:d={fade_in:.3f}"
            if fade_out > 0:
                vf += f",fade=t=out:st={fade_out_start:.3f}:d={fade_out:.3f}"
            af = (
                "aresample=48000,"
                "dynaudnorm=f=150:g=9:p=0.9,"
                "alimiter=limit=0.95"
            )
            if index == 1:
                af += f",afade=t=in:st=0:d={min(0.06, duration / 4.0):.3f}"
            if index == len(clips):
                af += f",afade=t=out:st={max(0.0, duration - min(0.10, duration / 4.0)):.3f}:d={min(0.10, duration / 4.0):.3f}"
            base = [
                ffmpeg,
                "-y",
                "-hide_banner",
                "-loglevel",
                "error",
                "-ss",
                f"{start:.3f}",
                "-i",
                str(source),
            ]
            if media.get("has_audio"):
                cmd = base + [
                    "-t",
                    f"{duration:.3f}",
                    "-map",
                    "0:v:0",
                    "-map",
                    "0:a:0",
                    "-vf",
                    vf,
                    "-af",
                    af,
                    "-c:v",
                    "libx264",
                    "-preset",
                    "veryfast",
                    "-crf",
                    "21",
                    "-c:a",
                    "aac",
                    "-ar",
                    "48000",
                    "-ac",
                    "2",
                    "-movflags",
                    "+faststart",
                    out_path,
                ]
            else:
                cmd = base + [
                    "-f",
                    "lavfi",
                    "-t",
                    f"{duration:.3f}",
                    "-i",
                    "anullsrc=channel_layout=stereo:sample_rate=48000",
                    "-t",
                    f"{duration:.3f}",
                    "-map",
                    "0:v:0",
                    "-map",
                    "1:a:0",
                    "-vf",
                    vf,
                    "-c:v",
                    "libx264",
                    "-preset",
                    "veryfast",
                    "-crf",
                    "21",
                    "-c:a",
                    "aac",
                    "-ar",
                    "48000",
                    "-ac",
                    "2",
                    "-shortest",
                    "-movflags",
                    "+faststart",
                    out_path,
                ]
            result = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, timeout=300)
            if result.returncode != 0 or not os.path.isfile(out_path):
                err = (result.stderr or "").strip()[-800:] or "FFmpeg 剪辑失败"
                raise RuntimeError(f"第 {index} 个分镜剪辑失败：{err}")
            segment_paths.append(out_path)
            segment_durations.append(duration)

        _local_comic_auto_edit_set_task(
            task,
            status="running",
            state="rendering",
            progress_percent=90,
            current_step="正在合成完整视频",
        )
        _save_local_comic_state()
        final_name = f"final_video_{int(project.get('id') or 0)}_{int(time.time() * 1000)}.mp4"
        final_path = os.path.join(output_root, final_name)
        if len(segment_paths) == 1:
            shutil.copyfile(segment_paths[0], final_path)
            return f"/uploads/comic-drama/{final_name}"

        xfade_cmd = [
            ffmpeg,
            "-y",
            "-hide_banner",
            "-loglevel",
            "error",
        ]
        for segment_path in segment_paths:
            xfade_cmd.extend(["-i", segment_path])
        filter_parts = []
        current_v = "[0:v]"
        current_a = "[0:a]"
        current_duration = float(segment_durations[0] or COMIC_AUTO_EDIT_MIN_CLIP_SECONDS)
        for idx in range(1, len(segment_paths)):
            next_duration = float(segment_durations[idx] or COMIC_AUTO_EDIT_MIN_CLIP_SECONDS)
            clip = clips[idx] if idx < len(clips) and isinstance(clips[idx], dict) else {}
            previous_clip = clips[idx - 1] if idx - 1 < len(clips) and isinstance(clips[idx - 1], dict) else {}
            next_v = f"[{idx}:v]"
            next_a = f"[{idx}:a]"
            out_v = f"[vxf{idx}]"
            out_a = f"[axf{idx}]"
            if previous_clip.get("dialogue_protected") or clip.get("dialogue_protected"):
                filter_parts.append(
                    f"{current_v}{current_a}{next_v}{next_a}concat=n=2:v=1:a=1{out_v}{out_a}"
                )
                current_v = out_v
                current_a = out_a
                current_duration += next_duration
                continue
            transition_kind = str(clip.get("transition") or "fade")
            requested_transition = float(clip.get("transition_duration") or COMIC_AUTO_EDIT_TRANSITION_SECONDS)
            if transition_kind == "cut":
                requested_transition = 0.08
            transition_duration = min(
                max(0.06, requested_transition),
                max(0.06, current_duration / 3.0),
                max(0.06, next_duration / 3.0),
            )
            offset = max(0.0, current_duration - transition_duration)
            filter_parts.append(
                f"{current_v}{next_v}xfade=transition=fade:duration={transition_duration:.3f}:offset={offset:.3f}{out_v}"
            )
            filter_parts.append(
                f"{current_a}{next_a}acrossfade=d={transition_duration:.3f}:c1=tri:c2=tri{out_a}"
            )
            current_v = out_v
            current_a = out_a
            current_duration = current_duration + next_duration - transition_duration
        xfade_cmd.extend(
            [
                "-filter_complex",
                ";".join(filter_parts),
                "-map",
                current_v,
                "-map",
                current_a,
                "-c:v",
                "libx264",
                "-preset",
                "veryfast",
                "-crf",
                "21",
                "-c:a",
                "aac",
                "-ar",
                "48000",
                "-ac",
                "2",
                "-movflags",
                "+faststart",
                final_path,
            ]
        )
        result = subprocess.run(xfade_cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, timeout=300)
        if result.returncode != 0 or not os.path.isfile(final_path):
            concat_file = os.path.join(work_dir, "concat.txt")
            with open(concat_file, "w", encoding="utf-8") as f:
                for segment_path in segment_paths:
                    f.write(_local_comic_auto_edit_concat_line(segment_path))
            result = subprocess.run(
                [
                    ffmpeg,
                    "-y",
                    "-hide_banner",
                    "-loglevel",
                    "error",
                    "-f",
                    "concat",
                    "-safe",
                    "0",
                    "-i",
                    concat_file,
                    "-c",
                    "copy",
                    "-movflags",
                    "+faststart",
                    final_path,
                ],
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                timeout=300,
            )
        if result.returncode != 0 or not os.path.isfile(final_path):
            err = (result.stderr or "").strip()[-800:] or "FFmpeg 合成失败"
            raise RuntimeError(err)
        return f"/uploads/comic-drama/{final_name}"
    finally:
        try:
            shutil.rmtree(work_dir, ignore_errors=True)
        except Exception:
            pass


def _local_comic_auto_edit_response(project, task=None):
    task_id = str((project or {}).get("auto_edit_task_id") or "")
    if task is None and task_id:
        task = LOCAL_COMIC_TASKS.get(task_id)
    if _local_comic_auto_edit_reconcile_project_from_task(project, task):
        _save_local_comic_state()
    project_status = str((project or {}).get("auto_edit_status") or "").strip()
    task_status = str(((task or {}).get("status") or (task or {}).get("state") or "") if task else "").strip()
    final_url = _first_non_empty((project or {}).get("final_video_url"), (task or {}).get("result_url") if task else "")
    if task_status == "completed" and final_url:
        status = "completed"
    elif task_status == "failed" and project_status.lower() in {"", "idle", "pending", "planning", "rendering", "running"}:
        status = "failed"
    else:
        status = project_status or task_status or "idle"
    error_message = "" if status == "completed" else _first_non_empty((project or {}).get("auto_edit_error"), (task or {}).get("error_message") if task else "")
    billing_amount = _local_comic_billing_amount(task) or _local_comic_billing_amount((project or {}).get("auto_edit_plan"))
    return {
        "project_id": (project or {}).get("id"),
        "projectId": (project or {}).get("id"),
        "task_id": task_id,
        "taskId": task_id,
        "status": status,
        "state": status,
        "progress_percent": (task or {}).get("progress_percent", 100 if status == "completed" else 0),
        "progressPercent": (task or {}).get("progress_percent", 100 if status == "completed" else 0),
        "current_step": (task or {}).get("current_step") or "",
        "currentStep": (task or {}).get("current_step") or "",
        "final_video_url": final_url,
        "finalVideoUrl": final_url,
        "url": final_url,
        "plan": (project or {}).get("auto_edit_plan") or {},
        "billing_amount": billing_amount,
        "billingAmount": billing_amount,
        "error": error_message,
    }


def _run_local_comic_auto_edit_task(project_id, task_id):
    project = LOCAL_COMIC_PROJECTS.get(int(project_id or 0))
    task = LOCAL_COMIC_TASKS.get(str(task_id or ""))
    if not project or not task:
        return
    try:
        now = _local_comic_auto_edit_now()
        project["auto_edit_status"] = "planning"
        project["auto_edit_error"] = ""
        project["updated_at"] = now
        _local_comic_auto_edit_set_task(task, status="running", state="planning", progress_percent=5, current_step="正在生成剪辑方案")
        _save_local_comic_state()
        _apply_completed_ai_comic_results_for_project(project_id)
        plan = _local_comic_auto_edit_build_plan(project)
        project["auto_edit_plan"] = plan
        project["auto_edit_status"] = "rendering"
        project["updated_at"] = _local_comic_auto_edit_now()
        _local_comic_auto_edit_set_task(task, status="running", state="rendering", progress_percent=10, current_step="剪辑方案已生成")
        _save_local_comic_state()
        final_url = _local_comic_auto_edit_render(project, plan, task)
        project["auto_edit_status"] = "completed"
        project["auto_edit_error"] = ""
        project["final_video_url"] = final_url
        project["finalVideoUrl"] = final_url
        completed_at = _local_comic_auto_edit_now()
        billing_summary = _local_comic_auto_edit_billing_summary(project, plan)
        billing_amount = float(billing_summary.get("amount") or 0) if isinstance(billing_summary, dict) else 0.0
        if billing_amount > 0:
            plan["billing_amount"] = billing_amount
            plan["billingAmount"] = billing_amount
            plan["billing_items"] = billing_summary.get("items") or []
            plan["billingItems"] = list(plan["billing_items"])
        project["auto_edit_completed_at"] = completed_at
        project["autoEditCompletedAt"] = completed_at
        project["updated_at"] = completed_at
        history_item = {
            "url": final_url,
            "final_video_url": final_url,
            "finalVideoUrl": final_url,
            "title": "完整视频",
            "status": "completed",
            "completed_at": completed_at,
            "completedAt": completed_at,
            "clip_count": len(plan.get("clips") or []),
            "clipCount": len(plan.get("clips") or []),
            "strategy": plan.get("strategy") or "professional-auto-edit-v1",
        }
        if billing_amount > 0:
            history_item["billing_amount"] = billing_amount
            history_item["billingAmount"] = billing_amount
            history_item["billing_items"] = plan.get("billing_items") or []
            history_item["billingItems"] = list(history_item["billing_items"])
        history = list(project.get("auto_edit_history") or project.get("autoEditHistory") or [])
        history = [item for item in history if isinstance(item, dict) and _first_non_empty(item.get("url"), item.get("final_video_url"), item.get("finalVideoUrl")) != final_url]
        history.insert(0, history_item)
        project["auto_edit_history"] = history[:20]
        project["autoEditHistory"] = list(project["auto_edit_history"])
        _local_comic_auto_edit_set_task(
            task,
            status="completed",
            state="completed",
            progress_percent=100,
            current_step="完整视频已剪辑完成",
            result_url=final_url,
            video_url=final_url,
            completed_at=completed_at,
            billing_amount=billing_amount,
            billingAmount=billing_amount,
        )
    except Exception as error:
        message = AiApiService.sanitize_error(str(error) or repr(error))
        project["auto_edit_status"] = "failed"
        project["auto_edit_error"] = message
        project["updated_at"] = _local_comic_auto_edit_now()
        _local_comic_auto_edit_set_task(
            task,
            status="failed",
            state="failed",
            progress_percent=100,
            current_step=message,
            error_message=message,
            completed_at=_local_comic_auto_edit_now(),
        )
        _json_log("local_comic_auto_edit_failed", project_id=project_id, task_id=task_id, error=message)
    _save_local_comic_state()


def _start_local_comic_auto_edit(project_id):
    project = LOCAL_COMIC_PROJECTS.get(int(project_id or 0))
    if not project:
        return None
    current_task_id = str(project.get("auto_edit_task_id") or "")
    current_task = LOCAL_COMIC_TASKS.get(current_task_id) if current_task_id else None
    if isinstance(current_task, dict) and current_task.get("status") in {"pending", "running"}:
        return _local_comic_auto_edit_response(project, current_task)
    now = _local_comic_auto_edit_now()
    task_id = f"local-auto-edit-{int(project_id)}-{int(time.time() * 1000)}"
    task = {
        "id": task_id,
        "task_id": task_id,
        "task_type": "auto_edit_video",
        "task_name": "自动剪辑完整视频",
        "status": "pending",
        "state": "pending",
        "progress_percent": 0,
        "current_step": "等待开始自动剪辑",
        "project_id": int(project_id),
        "target_type": "project",
        "target_id": int(project_id),
        "created_at": now,
        "updated_at": now,
        "provider": "local",
    }
    _local_comic_apply_scope_to_task(task, project_id)
    LOCAL_COMIC_TASKS[task_id] = task
    project["auto_edit_task_id"] = task_id
    project["auto_edit_status"] = "pending"
    project["auto_edit_error"] = ""
    project["updated_at"] = now
    _save_local_comic_state()
    thread = threading.Thread(target=_run_local_comic_auto_edit_task, args=(int(project_id), task_id), daemon=True)
    thread.start()
    return _local_comic_auto_edit_response(project, task)


def _ai_comic_fail_task(task, message):
    if not isinstance(task, dict):
        return task
    billing_request_id = str(task.get("billing_request_id") or "").strip()
    if billing_request_id and not task.get("billing_refunded"):
        _refund_canvas_model_call({"request_id": billing_request_id}, str(message or "任务失败"))
        task["billing_refunded"] = True
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()
    task["status"] = "failed"
    task["state"] = "failed"
    task["progress_percent"] = 100
    task["current_step"] = str(message or "任务失败")
    task["error_message"] = AiApiService.sanitize_error(str(message or "任务失败"))
    task["completed_at"] = now
    _save_local_comic_state()
    return task


def _ai_comic_remote_id(task):
    remote_task_id = str((task or {}).get("remote_task_id") or "").strip()
    if not remote_task_id or remote_task_id.lower() in {"none", "null", "undefined"}:
        return ""
    return remote_task_id


def _sync_ai_comic_task_actual_billing_cost(task, status_payload=None):
    if not isinstance(task, dict):
        return False
    payload = status_payload if isinstance(status_payload, dict) else task
    actual_cost = _extract_ai_actual_cost(payload) or _extract_ai_actual_cost(task)
    if actual_cost <= 0:
        return False
    request_id = str(task.get("billing_request_id") or task.get("billingRequestId") or "").strip()
    if not request_id:
        return False
    synced_cost = _local_comic_billing_amount({"billing_amount": task.get("billing_actual_cost_synced_amount")})
    if task.get("billing_actual_cost_synced") and synced_cost == actual_cost:
        return False
    channel_group = ""
    if isinstance(payload, dict):
        channel_group = str(payload.get("channel_group") or payload.get("channelGroup") or "").strip()
    reason = f"漫剧生成器中转站真实消耗同步：{task.get('task_type') or task.get('task_name') or ''}".strip("：")
    if channel_group:
        reason = f"{reason}（{channel_group}）"
    try:
        usage_log = _settle_canvas_model_actual_cost(request_id, actual_cost, reason)
    except Exception as error:
        task["billing_actual_cost"] = actual_cost
        if channel_group:
            task["billing_channel_group"] = channel_group
        task["billing_actual_cost_sync_error"] = AiApiService.sanitize_error(str(error))
        return False
    task["billing_actual_cost"] = actual_cost
    task["billing_actual_cost_synced"] = True
    task["billing_actual_cost_synced_amount"] = actual_cost
    task["billing_actual_cost_synced_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    task.pop("billing_actual_cost_sync_error", None)
    if channel_group:
        task["billing_channel_group"] = channel_group
    if isinstance(usage_log, dict):
        task["billing_usage_log"] = copy.deepcopy(usage_log)
        task["billingUsageLog"] = copy.deepcopy(usage_log)
    task["billing_amount"] = actual_cost
    task["billingAmount"] = actual_cost
    return True


def _sync_completed_ai_comic_task_actual_billing_cost(task):
    if not isinstance(task, dict) or str(task.get("status") or "").lower() != "completed":
        return False
    if task.get("billing_actual_cost_synced"):
        return False
    if not str(task.get("billing_request_id") or task.get("billingRequestId") or "").strip():
        return False
    if _extract_ai_actual_cost(task) > 0:
        return _sync_ai_comic_task_actual_billing_cost(task)
    remote_task_id = _ai_comic_remote_id(task)
    if not remote_task_id or str(remote_task_id).startswith(ARK_TASK_ID_PREFIX):
        return False
    try:
        status_payload = AI_API_SERVICE.get_task_status(remote_task_id)
    except Exception as error:
        task["billing_actual_cost_sync_error"] = AiApiService.sanitize_error(str(error))
        return False
    return _sync_ai_comic_task_actual_billing_cost(task, status_payload)


def _ai_comic_task_age_seconds(task):
    created_at = str((task or {}).get("created_at") or "").strip()
    if not created_at:
        return 0
    try:
        created = datetime.datetime.fromisoformat(created_at.replace("Z", "+00:00"))
        if created.tzinfo is None:
            created = created.replace(tzinfo=datetime.timezone.utc)
        return max(0, int((datetime.datetime.now(datetime.timezone.utc) - created).total_seconds()))
    except Exception:
        return 0


def _ai_comic_task_stale_seconds(task):
    task_type = str((task or {}).get("task_type") or "").lower()
    if "video" in task_type:
        return 2 * 60 * 60
    if task_type == "agent_task_group":
        return 2 * 60 * 60
    return 45 * 60


def _ai_comic_task_is_stale(task):
    age_seconds = _ai_comic_task_age_seconds(task)
    return bool(age_seconds and age_seconds >= _ai_comic_task_stale_seconds(task))


def _is_local_comic_analysis_task(task):
    if not isinstance(task, dict):
        return False
    task_id = str(task.get("id") or task.get("task_id") or "")
    task_type = str(task.get("task_type") or "").strip().lower()
    return task_id.startswith("local-analyze-") and task_type == "analyze_script"


def _is_local_comic_auto_edit_task(task):
    if not isinstance(task, dict):
        return False
    task_id = str(task.get("id") or task.get("task_id") or "")
    task_type = str(task.get("task_type") or "").strip().lower()
    return task_id.startswith("local-auto-edit-") or task_type == "auto_edit_video"


def _ai_comic_task_refresh_ttl_seconds(task):
    task_type = str((task or {}).get("task_type") or "").lower()
    default_ttl = 12 if "video" in task_type else 8
    try:
        return max(3, int(os.environ.get("COMIC_TASK_STATUS_REFRESH_TTL_SECONDS", str(default_ttl)) or default_ttl))
    except Exception:
        return default_ttl


def _ai_comic_task_recently_refreshed(task, now_ts=None):
    now_ts = float(now_ts or time.time())
    try:
        last_ts = float((task or {}).get("status_last_checked_ts") or 0)
    except Exception:
        last_ts = 0
    return bool(last_ts and now_ts - last_ts < _ai_comic_task_refresh_ttl_seconds(task))


def _refresh_ai_comic_task(task):
    if not isinstance(task, dict):
        return task
    if _is_local_comic_analysis_task(task):
        task["provider"] = "local"
        task["local_analysis"] = True
        try:
            project_id = int(task.get("project_id") or 0)
        except Exception:
            project_id = 0
        project = LOCAL_COMIC_PROJECTS.get(project_id)
        project_status = str((project or {}).get("status") or "").strip().lower()
        if project_status and project_status not in {"pending", "analyzing"}:
            now = datetime.datetime.now(datetime.timezone.utc).isoformat()
            if project_status in {"failed", "error"}:
                task["status"] = "failed"
                task["state"] = "failed"
                task["error_message"] = task.get("error_message") or (project or {}).get("analysis_error") or "剧本分析失败"
            else:
                task["status"] = "completed"
                task["state"] = "completed"
            task["progress_percent"] = 100
            task["completed_at"] = task.get("completed_at") or now
            _save_local_comic_state()
        return task
    if _is_local_comic_auto_edit_task(task):
        task["provider"] = "local"
        if str(task.get("status") or "").lower() == "completed" and task.get("result_url"):
            task.pop("error_message", None)
        return task
    if (
        str(task.get("status") or "").strip().lower() == "completed"
        and str(task.get("result_url") or "").strip()
    ):
        try:
            _finalize_ai_comic_fallback_video_audio(task)
        except Exception as error:
            sanitized = AiApiService.sanitize_error(str(error or "fallback video TTS mix failed"))
            return _ai_comic_fail_task(task, f"comic_fallback_tts_mix_failed:{sanitized}")
    if _ai_comic_task_project_result_needs_sync(task):
        _mark_ai_comic_task_completed_from_result(task)
        _apply_ai_comic_task_result_to_project(task)
        if _sync_completed_ai_comic_task_actual_billing_cost(task):
            _save_local_comic_state()
        return task
    if task.get("status") in {"completed", "failed"}:
        if task.get("status") == "completed" and not task.get("project_result_applied"):
            if not task.get("result_url"):
                task["result_url"] = _fallback_ai_comic_task_result_url(task)
            _apply_ai_comic_task_result_to_project(task)
        if task.get("status") == "completed" and _sync_completed_ai_comic_task_actual_billing_cost(task):
            _save_local_comic_state()
        return task
    remote_task_id = _ai_comic_remote_id(task)
    if not remote_task_id:
        return _ai_comic_fail_task(task, "远端任务 ID 缺失，无法查询生成状态")
    refresh_key = str(task.get("id") or task.get("task_id") or remote_task_id)
    now_ts = time.time()
    if _ai_comic_task_recently_refreshed(task, now_ts):
        return task
    with AI_COMIC_TASK_REFRESH_LOCK:
        if refresh_key in AI_COMIC_TASK_REFRESH_IN_FLIGHT:
            return task
        AI_COMIC_TASK_REFRESH_IN_FLIGHT.add(refresh_key)
    try:
        try:
            if str(task.get("provider") or "").strip().lower() == "minimax-direct":
                status_payload = _minimax_h3_task_status_envelope(remote_task_id)
            elif str(remote_task_id).startswith(ARK_TASK_ID_PREFIX):
                status_payload = _ark_task_envelope_for_proxy(remote_task_id)
            else:
                status_payload = AI_API_SERVICE.get_task_status(remote_task_id)
        finally:
            task["status_last_checked_ts"] = time.time()
            task["status_refreshed_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
            with AI_COMIC_TASK_REFRESH_LOCK:
                AI_COMIC_TASK_REFRESH_IN_FLIGHT.discard(refresh_key)
    except Exception as error:
        sanitized = AiApiService.sanitize_error(str(error))
        if re.search(r"(not\s*found|404|不存在|未找到|invalid\s*task|任务不存在)", sanitized, re.IGNORECASE):
            return _ai_comic_fail_task(task, f"远端任务查询失败：{sanitized}")
        task["poll_error_count"] = int(task.get("poll_error_count") or 0) + 1
        if _ai_comic_task_is_stale(task):
            _json_log(
                "ai_api_comic_task_marked_stale",
                task_id=task.get("id"),
                remote_task_id=remote_task_id,
                task_type=task.get("task_type"),
                target_id=task.get("target_id"),
                poll_error_count=task.get("poll_error_count"),
                age_seconds=_ai_comic_task_age_seconds(task),
                error=sanitized,
            )
            return _ai_comic_fail_task(task, f"远端任务状态查询超时，已停止等待：{sanitized}")
        task["current_step"] = f"任务状态查询暂时失败，稍后自动重试：{sanitized}"
        _save_local_comic_state()
        return task
    status, progress = _normalize_ai_task_status(status_payload)
    task["status"] = status
    task["state"] = status_payload.get("state") or status
    task["progress_percent"] = progress
    task["current_step"] = status_payload.get("status") or status_payload.get("status_group") or task.get("current_step", "")
    result_url = _extract_ai_result_url(status_payload)
    if not result_url and status == "completed":
        result_url = _fallback_ai_comic_task_result_url(task)
    if result_url:
        task["result_url"] = result_url
    if status_payload.get("result_type"):
        task["result_type"] = status_payload.get("result_type")
    if status_payload.get("error"):
        task["error_message"] = AiApiService.sanitize_error(status_payload.get("error"))
    if status == "failed":
        failure = task.get("error_message") or task.get("current_step") or "远端任务失败"
        advanced = _advance_ai_comic_video_fallback(task, failure)
        if advanced is not None:
            return advanced
        return _ai_comic_fail_task(task, failure)
    if _ai_comic_task_has_applyable_result(task):
        try:
            _finalize_ai_comic_fallback_video_audio(task)
        except Exception as error:
            sanitized = AiApiService.sanitize_error(str(error or "fallback video TTS mix failed"))
            return _ai_comic_fail_task(task, f"comic_fallback_tts_mix_failed:{sanitized}")
        status = "completed"
        task["status"] = "completed"
        task["state"] = "completed"
        task["progress_percent"] = 100
        task["current_step"] = "已完成"
    if status in {"completed", "failed"}:
        task["completed_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    if status == "completed":
        _sync_ai_comic_task_actual_billing_cost(task, status_payload)
        _apply_ai_comic_task_result_to_project(task)
    elif _ai_comic_task_is_stale(task):
        _json_log(
            "ai_api_comic_task_marked_stale",
            task_id=task.get("id"),
            remote_task_id=remote_task_id,
            task_type=task.get("task_type"),
            target_id=task.get("target_id"),
            age_seconds=_ai_comic_task_age_seconds(task),
            remote_state=task.get("state"),
            remote_step=task.get("current_step"),
        )
        return _ai_comic_fail_task(task, "远端任务长时间未完成，已停止等待。请重新生成当前帧。")
    else:
        _save_local_comic_state()
    return task


def _register_ai_comic_task(*, remote_task_id, project_id=0, task_type, task_name, target_id=None, target_type=None, model="", prompt="", params=None, count=1, billing_ctx=None):
    remote_task_id = str(remote_task_id or "").strip()
    if not remote_task_id or remote_task_id.lower() in {"none", "null", "undefined"}:
        raise RuntimeError("ai 平台未返回有效 task_id")
    task_id = f"ai-{remote_task_id}"
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()
    task = {
        "id": task_id,
        "remote_task_id": str(remote_task_id),
        "task_type": task_type,
        "task_name": task_name,
        "status": "pending",
        "state": "pending",
        "progress_percent": 0,
        "current_step": "生成中",
        "project_id": int(project_id or 0),
        "target_id": target_id,
        "target_type": target_type,
        "created_at": now,
        "provider": "ai",
        "model": str(model or ""),
        "prompt": str(prompt or ""),
        "prompt_hash": _ai_comic_submit_prompt_hash(model, prompt),
        "params": copy.deepcopy(params) if isinstance(params, dict) else {},
        "count": int(count or 1),
    }
    if isinstance(params, dict) and params.get("workflow_mode"):
        task["workflow_mode"] = str(params.get("workflow_mode") or "").strip()
    if isinstance(billing_ctx, dict) and billing_ctx.get("request_id"):
        task["billing_request_id"] = str(billing_ctx.get("request_id") or "")
        task["billing_user_id"] = billing_ctx.get("user_id")
        usage_log = billing_ctx.get("usage_log")
        if isinstance(usage_log, dict):
            task["billing_usage_log"] = copy.deepcopy(usage_log)
            task["billingUsageLog"] = copy.deepcopy(usage_log)
        billing_amount = _local_comic_billing_amount(task)
        if billing_amount > 0:
            task["billing_amount"] = billing_amount
            task["billingAmount"] = billing_amount
    _local_comic_apply_scope_to_task(task, project_id)
    AI_COMIC_TASKS[task_id] = task
    LOCAL_COMIC_TASKS[task_id] = task
    _save_local_comic_state()
    return task


def _ai_comic_submit_prompt_hash(model, prompt):
    seed = json.dumps(
        {
            "model": str(model or "").strip(),
            "prompt": str(prompt or "").strip(),
        },
        ensure_ascii=False,
        sort_keys=True,
    )
    return hashlib.sha256(seed.encode("utf-8")).hexdigest()[:16]


def _find_recent_duplicate_character_task(project_id, target_id, model, prompt, seconds=180):
    prompt_hash = _ai_comic_submit_prompt_hash(model, prompt)
    now = datetime.datetime.now(datetime.timezone.utc)
    active_statuses = {"pending", "running", "processing", "submitted", "queued"}
    for task in list(LOCAL_COMIC_TASKS.values()):
        if not isinstance(task, dict):
            continue
        if str(task.get("task_type") or "") != "generate_character_views":
            continue
        if str(task.get("target_type") or "") != "character":
            continue
        if int(task.get("project_id") or 0) != int(project_id or 0):
            continue
        if str(task.get("target_id")) != str(target_id):
            continue
        if str(task.get("model") or "").strip() != str(model or "").strip():
            continue
        if str(task.get("status") or task.get("state") or "").strip().lower() not in active_statuses:
            continue
        if str(task.get("prompt_hash") or "") not in {"", prompt_hash}:
            continue
        if str(task.get("prompt") or "").strip() != str(prompt or "").strip():
            continue
        try:
            created = datetime.datetime.fromisoformat(str(task.get("created_at") or "").replace("Z", "+00:00"))
        except Exception:
            created = now
        if (now - created).total_seconds() <= int(seconds or 0):
            return task
    return None


def _find_recent_duplicate_storyboard_video_task(project_id, target_id, model, seconds=900, *, audio_mode=None):
    now = datetime.datetime.now(datetime.timezone.utc)
    active_statuses = {"pending", "running", "processing", "submitted", "queued"}
    requested_audio_mode = str(audio_mode or "").strip().lower()
    if requested_audio_mode not in {"auto", "tts"}:
        requested_audio_mode = "legacy"
    for task in list(LOCAL_COMIC_TASKS.values()):
        if not isinstance(task, dict):
            continue
        if str(task.get("task_type") or "").strip() not in {"generate_video", "batch_storyboard_videos"}:
            continue
        if str(task.get("target_type") or "") != "storyboard":
            continue
        if int(task.get("project_id") or 0) != int(project_id or 0):
            continue
        if str(task.get("target_id")) != str(target_id):
            continue
        if str(task.get("model") or "").strip() != str(model or "").strip():
            continue
        task_audio_mode = str(
            task.get("audio_mode") if "audio_mode" in task else task.get("audioMode") or ""
        ).strip().lower()
        if task_audio_mode not in {"auto", "tts"}:
            task_audio_mode = "legacy"
        if task_audio_mode != requested_audio_mode:
            continue
        if str(task.get("status") or task.get("state") or "").strip().lower() not in active_statuses:
            continue
        try:
            created = datetime.datetime.fromisoformat(str(task.get("created_at") or "").replace("Z", "+00:00"))
        except Exception:
            created = now
        if (now - created).total_seconds() <= int(seconds or 0):
            return task
    return None


def _register_ai_comic_failed_task(*, project_id=0, task_type, task_name, target_id=None, target_type=None, message="任务失败", model="", prompt="", params=None, count=1):
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()
    base = f"failed-{int(time.time() * 1000)}-{len(LOCAL_COMIC_TASKS) + 1}"
    task_id = f"ai-{base}"
    task = {
        "id": task_id,
        "remote_task_id": "",
        "task_type": task_type,
        "task_name": task_name,
        "status": "failed",
        "state": "failed",
        "progress_percent": 100,
        "current_step": AiApiService.sanitize_error(str(message or "任务失败")),
        "error_message": AiApiService.sanitize_error(str(message or "任务失败")),
        "project_id": int(project_id or 0),
        "target_id": target_id,
        "target_type": target_type,
        "created_at": now,
        "completed_at": now,
        "provider": "ai",
        "model": str(model or ""),
        "prompt": str(prompt or ""),
        "params": copy.deepcopy(params) if isinstance(params, dict) else {},
        "count": int(count or 1),
    }
    _local_comic_apply_scope_to_task(task, project_id)
    AI_COMIC_TASKS[task_id] = task
    LOCAL_COMIC_TASKS[task_id] = task
    _save_local_comic_state()
    return task


def _is_ark_real_person_privacy_error(error):
    code = "InputImageSensitiveContentDetected.PrivacyInformation"
    text = str(error or "")
    return bool(re.search(r"(?<![A-Za-z0-9_.])%s(?![A-Za-z0-9_.])" % re.escape(code), text))


def _ark_storyboard_video_fallback_reason(error):
    if _is_ark_real_person_privacy_error(error):
        return "InputImageSensitiveContentDetected.PrivacyInformation"
    text = str(error or "")
    lowered = text.lower()
    if (
        "inputimagesensitivecontentdetected.policyviolation" in lowered
        or (
            "inputimagesensitivecontentdetected" in lowered
            and any(token in lowered for token in ("copyright restriction", "policyviolation", "policy violation"))
        )
    ):
        return "InputImageSensitiveContentDetected.PolicyViolation"
    if (
        "invalidparameter" in lowered
        and "audio duration" in lowered
        and "less than or equal to" in lowered
        and "doubao-seedance-2-0" in lowered
        and "r2v" in lowered
    ):
        return "InvalidParameter.AudioDurationExceeded"
    return ""


COMIC_REAL_PERSON_VIDEO_FALLBACK_MODELS = (
    "vidu/viduq3-mix_reference2video",
    "wan2.7-shouweizhen",
    "kling-v3-omni-shouweizhen",
    "pixverse-v6-shouweizhen",
)


def _comic_real_person_video_fallback_models():
    plural_key = "COMIC_REAL_PERSON_VIDEO_FALLBACK_MODELS"
    if plural_key in os.environ:
        return tuple(
            item.strip()
            for item in str(os.environ.get(plural_key) or "").split(",")
            if item.strip()
        )
    legacy_key = "COMIC_REAL_PERSON_VIDEO_FALLBACK_MODEL"
    if legacy_key in os.environ:
        legacy_model = str(os.environ.get(legacy_key) or "").strip()
        return (legacy_model,) if legacy_model else ()
    return COMIC_REAL_PERSON_VIDEO_FALLBACK_MODELS


def _comic_real_person_video_fallback_model():
    models = _comic_real_person_video_fallback_models()
    return models[0] if models else ""


def _comic_storyboard_tts_url_from_task(task):
    if not isinstance(task, dict):
        return ""
    sources = (
        task.get("fallback_source_params"),
        task.get("params"),
        task,
    )
    scalar_keys = (
        "storyboard_tts_url", "storyboardTtsUrl", "sound_file", "soundFile",
        "audio_file", "audioFile", "reference_audio_file", "referenceAudioFile",
        "audio_url", "audioUrl", "audio",
    )
    list_keys = ("audio_urls", "audioUrls")
    for source in sources:
        if not isinstance(source, dict):
            continue
        for key in scalar_keys:
            value = source.get(key)
            if isinstance(value, str) and value.strip():
                return value.strip()
        for key in list_keys:
            values = source.get(key)
            if not isinstance(values, list):
                continue
            for value in values:
                if isinstance(value, str) and value.strip():
                    return value.strip()
    return ""


def _comic_remux_video_with_storyboard_tts(video_url, audio_url, project_id, storyboard_id):
    video_url = str(video_url or "").strip()
    audio_url = str(audio_url or "").strip()
    if not video_url:
        raise RuntimeError("comic_fallback_video_url_missing")
    if not audio_url:
        raise RuntimeError("comic_storyboard_tts_missing")
    video_source = _local_comic_auto_edit_resolve_source(video_url)
    audio_source = _local_comic_auto_edit_resolve_source(audio_url)
    video_meta = _local_comic_auto_edit_probe(video_source)
    audio_meta = _local_comic_auto_edit_probe(audio_source)
    video_duration = float((video_meta or {}).get("duration") or 0.0)
    audio_duration = float((audio_meta or {}).get("duration") or 0.0)
    if video_duration <= 0:
        raise RuntimeError("comic_fallback_video_duration_unavailable")
    if audio_duration <= 0 or not bool((audio_meta or {}).get("has_audio")):
        raise RuntimeError("comic_storyboard_tts_invalid")

    final_duration = max(video_duration, audio_duration)
    video_pad = max(0.0, final_duration - video_duration)
    audio_pad = max(0.0, final_duration - audio_duration)
    output_root = os.path.join(_current_uploads_dir(), "comic-drama")
    os.makedirs(output_root, exist_ok=True)
    output_name = (
        f"storyboard_{int(project_id or 0)}_{str(storyboard_id or 'unknown')}_"
        f"tts_{int(time.time() * 1000)}_{secrets.token_hex(3)}.mp4"
    )
    output_path = os.path.join(output_root, output_name)
    temp_path = output_path + ".part.mp4"
    ffmpeg = shutil.which(FFMPEG_EXE) or shutil.which("ffmpeg") or FFMPEG_EXE
    filter_graph = (
        f"[0:v:0]tpad=stop_mode=clone:stop_duration={video_pad:.3f},"
        f"trim=duration={final_duration:.3f},setpts=PTS-STARTPTS[v];"
        f"[1:a:0]aresample=48000,apad=pad_dur={audio_pad:.3f},"
        f"atrim=duration={final_duration:.3f},asetpts=PTS-STARTPTS[a]"
    )
    command = [
        ffmpeg, "-y", "-hide_banner", "-loglevel", "error", "-nostdin",
        "-i", str(video_source), "-i", str(audio_source),
        "-filter_complex", filter_graph,
        "-map", "[v]", "-map", "[a]",
        "-c:v", "libx264", "-preset", "veryfast", "-crf", "20",
        "-c:a", "aac", "-ar", "48000", "-ac", "2",
        "-movflags", "+faststart", "-t", f"{final_duration:.3f}", temp_path,
    ]
    try:
        result = subprocess.run(
            command,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            timeout=max(300, int(final_duration * 20) + 60),
        )
        if result.returncode != 0 or not os.path.isfile(temp_path):
            error_text = AiApiService.sanitize_error((result.stderr or "").strip()[-1200:])
            raise RuntimeError(f"comic_fallback_tts_ffmpeg_failed:{error_text or result.returncode}")
        os.replace(temp_path, output_path)
        output_meta = _local_comic_auto_edit_probe(output_path)
        output_duration = float((output_meta or {}).get("duration") or 0.0)
        if not bool((output_meta or {}).get("has_audio")):
            raise RuntimeError("comic_fallback_tts_output_audio_missing")
        if output_duration + 0.25 < final_duration:
            raise RuntimeError(
                f"comic_fallback_tts_output_truncated:{output_duration:.3f}<{final_duration:.3f}"
            )
    except Exception:
        for candidate in (temp_path, output_path):
            try:
                if os.path.isfile(candidate):
                    os.remove(candidate)
            except Exception:
                pass
        raise
    return {
        "url": f"/data/uploads/comic-drama/{output_name}",
        "video_duration_seconds": round(video_duration, 3),
        "audio_duration_seconds": round(audio_duration, 3),
        "final_duration_seconds": round(final_duration, 3),
    }


def _finalize_ai_comic_fallback_video_audio(task):
    if not isinstance(task, dict):
        return task
    if str(task.get("task_type") or "").strip() not in {"generate_video", "batch_storyboard_videos"}:
        return task
    if str(task.get("target_type") or "").strip() != "storyboard":
        return task
    try:
        project_id = int(task.get("project_id") or 0)
    except Exception:
        project_id = 0
    project = LOCAL_COMIC_PROJECTS.get(project_id) if project_id else None
    matrix_replacement = (
        _is_matrix_video_replacement_project(project)
        or _is_matrix_video_replacement_project(task)
    )
    if not task.get("fallback_applied") and not matrix_replacement:
        return task
    if str(task.get("audio_mix_status") or "").strip().lower() == "completed":
        return task
    provider_result_url = str(
        task.get("provider_result_url") or task.get("result_url") or ""
    ).strip()
    if not provider_result_url:
        raise RuntimeError("comic_fallback_video_url_missing")
    audio_mode = ""
    for source in (task, task.get("fallback_source_params"), task.get("params")):
        if isinstance(source, dict) and "audio_mode" in source:
            audio_mode = str(source.get("audio_mode") or "").strip().lower()
            break
    if audio_mode == "auto" and matrix_replacement and _comic_storyboard_tts_url_from_task(task):
        audio_mode = "tts"
    if audio_mode == "auto":
        task["provider_result_url"] = provider_result_url
        task["providerResultUrl"] = provider_result_url
        task["result_url"] = provider_result_url
        task["audio_source"] = "provider_generated"
        task["audioSource"] = "provider_generated"
        task["audio_mix_status"] = "not_requested"
        task["audioMixStatus"] = "not_requested"
        task.pop("audio_mix_error", None)
        task.pop("audioMixError", None)
        _json_log(
            "comic_storyboard_fallback_audio_mix_skipped",
            project_id=task.get("project_id"),
            storyboard_id=task.get("target_id"),
            task_id=task.get("id"),
            actual_model=task.get("actual_model") or task.get("model"),
            audio_mode="auto",
            audio_source="provider_generated",
            audio_mix_status="not_requested",
        )
        _save_local_comic_state()
        return task
    tts_url = _comic_storyboard_tts_url_from_task(task)
    if not tts_url:
        raise RuntimeError("comic_storyboard_tts_missing")
    task["provider_result_url"] = provider_result_url
    task["providerResultUrl"] = provider_result_url
    task["audio_mix_status"] = "processing"
    task["audioMixStatus"] = "processing"
    task["current_step"] = "Replacing fallback model audio with storyboard TTS"
    _save_local_comic_state()
    try:
        result = _comic_remux_video_with_storyboard_tts(
            provider_result_url,
            tts_url,
            task.get("project_id") or 0,
            task.get("target_id"),
        )
    except Exception as error:
        sanitized = AiApiService.sanitize_error(str(error or "fallback video TTS mix failed"))
        task["audio_mix_status"] = "failed"
        task["audioMixStatus"] = "failed"
        task["audio_mix_error"] = sanitized
        task["audioMixError"] = sanitized
        _json_log(
            "comic_storyboard_fallback_tts_mix_failed",
            project_id=task.get("project_id"),
            storyboard_id=task.get("target_id"),
            task_id=task.get("id"),
            actual_model=task.get("actual_model") or task.get("model"),
            error=sanitized,
        )
        _save_local_comic_state()
        raise
    task["result_url"] = str(result.get("url") or "").strip()
    task["audio_source"] = "storyboard_tts"
    task["audioSource"] = "storyboard_tts"
    task["audio_mix_status"] = "completed"
    task["audioMixStatus"] = "completed"
    task["video_duration_seconds"] = result.get("video_duration_seconds")
    task["audio_duration_seconds"] = result.get("audio_duration_seconds")
    task["final_duration_seconds"] = result.get("final_duration_seconds")
    task.pop("audio_mix_error", None)
    task.pop("audioMixError", None)
    _json_log(
        "comic_storyboard_fallback_tts_mix_completed",
        project_id=task.get("project_id"),
        storyboard_id=task.get("target_id"),
        task_id=task.get("id"),
        actual_model=task.get("actual_model") or task.get("model"),
        video_duration_seconds=result.get("video_duration_seconds"),
        audio_duration_seconds=result.get("audio_duration_seconds"),
        final_duration_seconds=result.get("final_duration_seconds"),
    )
    _save_local_comic_state()
    return task


def _comic_video_fallback_params(model, original):
    params = copy.deepcopy(original if isinstance(original, dict) else {})
    for key in (
        "sound_file", "soundFile", "audio", "audio_file", "audioFile",
        "reference_audio_file", "referenceAudioFile", "audio_url", "audioUrl",
        "audio_urls", "audioUrls", "lip_sync_required", "lipSyncRequired",
    ):
        params.pop(key, None)
    images = []
    for key in (
        "images", "image_urls", "imageUrls", "reference_image_urls",
        "referenceImageUrls", "additional_reference_images",
    ):
        values = params.get(key)
        if isinstance(values, list):
            images.extend(str(value).strip() for value in values if str(value).strip())
    first_frame = str(
        params.get("first_frame_image")
        or params.get("firstFrameImage")
        or (images[0] if images else "")
    ).strip()
    end_frame = str(
        params.get("last_frame_image")
        or params.get("lastFrameImage")
        or params.get("end_frame_image")
        or params.get("endFrameImage")
        or (images[1] if len(images) > 1 else "")
    ).strip()
    images = _dedupe_urls([first_frame, end_frame, *images])
    if str(model or "").strip() == "vidu/viduq3-mix_reference2video":
        params["images"] = images[:7]
    else:
        frame_images = _dedupe_urls([first_frame, end_frame])
        params["images"] = frame_images[:2]
        for key in (
            "image_urls", "imageUrls", "reference_image_urls", "referenceImageUrls",
            "additional_reference_images", "action_flow_images", "actionFlowImages",
            "character_reference_images", "scene_reference_images", "prop_reference_images",
        ):
            params.pop(key, None)
    if first_frame:
        params["first_frame_image"] = first_frame
    if end_frame:
        params["last_frame_image"] = end_frame
    return params


def _advance_ai_comic_video_fallback(task, failure):
    return None
    if not isinstance(task, dict):
        return None
    candidates = list(task.get("fallback_candidates") or [])
    try:
        current_index = int(task.get("fallback_index"))
    except Exception:
        current_index = -1
    if not candidates or current_index + 1 >= len(candidates):
        return None
    original_id = str(task.get("id") or "")
    requested_model = str(task.get("requested_model") or task.get("model") or "").strip()
    fallback_reason = str(task.get("fallback_reason") or failure or "").strip()
    source_params = copy.deepcopy(task.get("fallback_source_params") or task.get("params") or {})
    history = copy.deepcopy(task.get("fallback_history") or [])
    current_model = str(task.get("actual_model") or task.get("model") or "").strip()
    failure_text = AiApiService.sanitize_error(str(failure or "video task failed"))[:500]
    if history and str(history[-1].get("model") or "") == current_model:
        history[-1].update({"status": "failed", "error": failure_text})
    else:
        history.append({"model": current_model, "status": "failed", "error": failure_text})
    _ai_comic_fail_task(task, failure_text)
    for fallback_index in range(current_index + 1, len(candidates)):
        fallback_model = str(candidates[fallback_index] or "").strip()
        fallback_params = _comic_video_fallback_params(fallback_model, source_params)
        fallback_params["_video_fallback_chain_active"] = True
        fallback_params["force_regenerate"] = True
        fallback_task = _submit_ai_comic_media_task(
            model=fallback_model,
            prompt=task.get("prompt") or "",
            params=fallback_params,
            count=task.get("count") or 1,
            project_id=task.get("project_id") or 0,
            task_type=task.get("task_type") or "generate_video",
            task_name=task.get("task_name") or "storyboard video",
            target_id=task.get("target_id"),
            target_type=task.get("target_type") or "storyboard",
            audio_mode=task.get("audio_mode") if "audio_mode" in task else task.get("audioMode"),
        )
        fallback_status = str(fallback_task.get("status") or fallback_task.get("state") or "").lower()
        history_entry = {
            "model": fallback_model,
            "status": "failed" if fallback_status in {"failed", "failure", "error", "cancelled", "canceled"} else "submitted",
            "task_id": fallback_task.get("remote_task_id") or fallback_task.get("id") or "",
        }
        if history_entry["status"] == "failed":
            history_entry["error"] = AiApiService.sanitize_error(str(
                fallback_task.get("error_message") or fallback_task.get("current_step") or "provider failed"
            ))[:500]
        history.append(history_entry)
        temporary_id = str(fallback_task.get("id") or "")
        if temporary_id and temporary_id != original_id:
            AI_COMIC_TASKS.pop(temporary_id, None)
            LOCAL_COMIC_TASKS.pop(temporary_id, None)
        if history_entry["status"] == "failed":
            continue
        replacement = copy.deepcopy(fallback_task)
        task.clear()
        task.update(replacement)
        task["id"] = original_id
        task["requested_model"] = requested_model
        task["actual_model"] = fallback_model
        task["fallback_model"] = fallback_model
        task["fallback_reason"] = fallback_reason
        task["fallback_applied"] = True
        task["fallback_candidates"] = candidates
        task["fallback_index"] = fallback_index
        task["fallback_history"] = history
        task["fallback_source_params"] = source_params
        AI_COMIC_TASKS[original_id] = task
        LOCAL_COMIC_TASKS[original_id] = task
        _json_log(
            "comic_storyboard_video_fallback_advanced",
            project_id=task.get("project_id"),
            target_id=task.get("target_id"),
            task_id=original_id,
            remote_task_id=task.get("remote_task_id"),
            requested_model=requested_model,
            actual_model=fallback_model,
            fallback_index=fallback_index,
            error_code=failure_text[:120],
        )
        _save_local_comic_state()
        return task
    task["requested_model"] = requested_model
    task["actual_model"] = str(candidates[-1] or current_model).strip()
    task["fallback_model"] = task["actual_model"]
    task["fallback_reason"] = fallback_reason
    task["fallback_applied"] = bool(candidates)
    task["fallback_candidates"] = candidates
    task["fallback_index"] = len(candidates) - 1
    task["fallback_history"] = history
    task["fallback_source_params"] = source_params
    AI_COMIC_TASKS[original_id] = task
    LOCAL_COMIC_TASKS[original_id] = task
    _save_local_comic_state()
    return task


def _submit_ai_comic_media_task(*, model, prompt, params=None, count=1, project_id=0, task_type, task_name, target_id=None, target_type=None, audio_mode=None):
    prompt = str(prompt or "").strip()
    params = dict(params if isinstance(params, dict) else {})
    fallback_chain_active = _comic_truthy(params.pop("_video_fallback_chain_active", False))
    params.pop("_real_person_privacy_fallback_attempted", None)
    force_regenerate = _comic_truthy(
        params.pop("force_regenerate", params.pop("forceRegenerate", False))
    )
    task_type_text = str(task_type or "").lower()
    is_video_task = "video" in task_type_text
    is_image_task = "image" in task_type_text or "views" in task_type_text
    storyboard_audio_mode = ""
    storyboard_project_source_mode = ""
    if is_video_task and str(target_type or "").strip() == "storyboard":
        storyboard_audio_mode = str(audio_mode or "").strip().lower()
        if storyboard_audio_mode not in {"auto", "tts"}:
            storyboard_audio_mode = "legacy"
        try:
            source_project_id = int(project_id or 0)
        except Exception:
            source_project_id = 0
        source_project = LOCAL_COMIC_PROJECTS.get(source_project_id) if source_project_id else None
        if not isinstance(source_project, dict) and source_project_id:
            source_project = _local_comic_project_for_current_scope(source_project_id)
        if isinstance(source_project, dict):
            source_config = source_project.get("config") if isinstance(source_project.get("config"), dict) else {}
            storyboard_project_source_mode = str(
                source_project.get("source_mode")
                or source_project.get("sourceMode")
                or source_config.get("source_mode")
                or source_config.get("sourceMode")
                or ""
            ).strip()

    def apply_storyboard_audio_mode(task):
        if not storyboard_audio_mode or not isinstance(task, dict):
            return task
        existing_modes = set()
        for key in ("audio_mode", "audioMode"):
            if key not in task or not str(task.get(key) or "").strip():
                continue
            existing = str(task.get(key) or "").strip().lower()
            existing_modes.add(existing if existing in {"auto", "tts"} else "legacy")
        if existing_modes and existing_modes != {storyboard_audio_mode}:
            return task
        if task.get("audio_mode") == storyboard_audio_mode and task.get("audioMode") == storyboard_audio_mode:
            return task
        task["audio_mode"] = storyboard_audio_mode
        task["audioMode"] = storyboard_audio_mode
        if storyboard_project_source_mode:
            task["project_source_mode"] = storyboard_project_source_mode
            task["projectSourceMode"] = storyboard_project_source_mode
        _save_local_comic_state()
        return task
    if is_video_task:
        params = _normalize_video_size_keys(params)
        prompt = _truncate_comic_video_submit_prompt(prompt, _comic_video_submit_prompt_limit(model))
    if is_image_task and "gemini" in str(model or "").lower():
        params["imageSize"] = "2K"
    if prompt:
        if is_video_task:
            params["prompt"] = prompt
            params["submitted_prompt"] = prompt
            params["submittedPrompt"] = prompt
        else:
            params.setdefault("prompt", prompt)
            params.setdefault("submitted_prompt", prompt)
            params.setdefault("submittedPrompt", prompt)
    if (
        is_video_task
        and str(task_type or "") == "generate_video"
        and str(target_type or "") == "storyboard"
        and not str(params.get("workflow_mode") or "").strip()
    ):
        try:
            inferred_project_id = int(project_id or 0)
        except Exception:
            inferred_project_id = 0
        project = LOCAL_COMIC_PROJECTS.get(inferred_project_id) if inferred_project_id else None
        if not isinstance(project, dict) and inferred_project_id:
            project = _local_comic_project_for_current_scope(inferred_project_id)
        workflow_mode = _comic_storyboard_workflow_mode(project, params)
        if workflow_mode:
            params["workflow_mode"] = workflow_mode
    if (
        not force_regenerate
        and str(task_type or "") == "generate_character_views"
        and str(target_type or "") == "character"
    ):
        duplicate_task = _find_recent_duplicate_character_task(project_id, target_id, model, prompt)
        if duplicate_task:
            _json_log(
                "ai_comic_character_generation_duplicate_reused",
                provider="ai",
                project_id=project_id,
                target_id=target_id,
                task_id=duplicate_task.get("id"),
            )
            return duplicate_task
    if (
        not force_regenerate
        and is_video_task
        and str(task_type or "").strip() in {"generate_video", "batch_storyboard_videos"}
        and str(target_type or "") == "storyboard"
    ):
        duplicate_task = _find_recent_duplicate_storyboard_video_task(
            project_id, target_id, model, audio_mode=storyboard_audio_mode,
        )
        if duplicate_task:
            _json_log(
                "ai_comic_storyboard_video_duplicate_reused",
                provider="ai",
                project_id=project_id,
                target_id=target_id,
                task_id=duplicate_task.get("id"),
                audio_mode=storyboard_audio_mode,
            )
            return duplicate_task
    model_type = "video" if is_video_task else "image"
    billing_payload = dict(params or {})
    billing_payload["prompt"] = prompt
    billing_payload["count"] = count
    minimax_h3_direct = bool(is_video_task and _is_minimax_h3_comic_model(model))
    billing_ctx = None if minimax_h3_direct else _charge_local_ai_model_call(
        model_type,
        model,
        billing_payload,
        project_id=project_id,
        description=f"云灵AI漫剧{task_name}：{model}",
    )
    try:
        if minimax_h3_direct:
            result = _submit_minimax_h3_comic_video_task(prompt, params=params)
        elif is_video_task and _ark_should_route(model):
            data = dict(params or {})
            action_refs, extra_refs, refs = _comic_collect_video_reference_urls(data)
            if len(refs) > 9:
                for field in (
                    "action_flow_images",
                    "actionFlowImages",
                    "reference_image_urls",
                    "referenceImageUrls",
                    "image_urls",
                    "imageUrls",
                    "inputUrls",
                    "images",
                    "image_with_roles",
                    "character_reference_images",
                    "scene_reference_images",
                    "prop_reference_images",
                    "subject_reference_images",
                    "additional_reference_images",
                    "strict_reference_image_urls",
                ):
                    data.pop(field, None)
                data["images"] = _dedupe_urls([*action_refs[:7], *extra_refs])[:9]
                if action_refs:
                    data["action_flow_images"] = action_refs[:7]
            else:
                if refs:
                    data["images"] = refs[:9]
                    data["reference_image_urls"] = refs[:9]
                    data["referenceImageUrls"] = refs[:9]
                    data["image_urls"] = refs[:9]
                    data["imageUrls"] = refs[:9]
                    data["inputUrls"] = refs[:9]
                if action_refs:
                    data["action_flow_images"] = action_refs[:7]
            data["model"] = str(model or "").strip()
            data["prompt"] = prompt
            result = {"task_id": _ark_create_video(data)}
        elif is_video_task:
            result = _submit_comic_gateway_video_task(model, prompt, params=params, count=count)
        else:
            result = AI_API_SERVICE.submit_media_task(model, prompt, params=params, count=count)
    except Exception as exc:
        sanitized_error = AiApiService.sanitize_error(str(exc or "视频任务提交失败"))
        _refund_canvas_model_call(billing_ctx, f"云灵AI漫剧{task_name}提交失败退款")
        fallback_reason = _ark_storyboard_video_fallback_reason(exc)
        fallback_candidates = []
        should_fallback = False
        if should_fallback:
            _json_log(
                "comic_storyboard_video_fallback_started",
                project_id=project_id,
                target_id=target_id,
                requested_model=str(model or ""),
                fallback_model=fallback_candidates[0],
                fallback_candidates=fallback_candidates,
                fallback_reason=fallback_reason,
            )
            seedance_task = _register_ai_comic_failed_task(
                project_id=project_id,
                task_type=task_type,
                task_name=task_name,
                target_id=target_id,
                target_type=target_type,
                message=sanitized_error,
                model=model,
                prompt=prompt,
                params=params,
                count=count,
            )
            seedance_task.update({
                "requested_model": str(model or "").strip(),
                "actual_model": str(model or "").strip(),
                "fallback_reason": fallback_reason,
                "fallback_candidates": fallback_candidates,
                "fallback_index": -1,
                "fallback_source_params": copy.deepcopy(params),
                "fallback_history": [{
                    "model": str(model or "").strip(),
                    "status": "failed",
                    "error": sanitized_error[:500],
                }],
            })
            apply_storyboard_audio_mode(seedance_task)
            advanced = _advance_ai_comic_video_fallback(seedance_task, sanitized_error)
            return advanced if advanced is not None else seedance_task
        if is_video_task:
            failed_task = _register_ai_comic_failed_task(
                project_id=project_id,
                task_type=task_type,
                task_name=task_name,
                target_id=target_id,
                target_type=target_type,
                message=sanitized_error,
                model=model,
                prompt=prompt,
                params=params,
                count=count,
            )
            if storyboard_audio_mode:
                apply_storyboard_audio_mode(failed_task)
            return failed_task
        raise
    task = _register_ai_comic_task(
        remote_task_id=result.get("task_id"),
        project_id=project_id,
        task_type=task_type,
        task_name=task_name,
        target_id=target_id,
        target_type=target_type,
        model=model,
        prompt=prompt,
        params=params,
        count=count,
        billing_ctx=billing_ctx,
    )
    if minimax_h3_direct:
        task["provider"] = "minimax-direct"
        task["actual_model"] = str(result.get("actual_model") or MINIMAX_H3_PROVIDER_MODEL)
        task["actualModel"] = task["actual_model"]
        task["billing_status"] = str(result.get("billing_status") or "awaiting_actual_cost")
        task["billingStatus"] = task["billing_status"]
        task["billing_price_table_version"] = str(
            result.get("billing_price_table_version") or "minimax-h3-price-unresolved"
        )
        task["billingPriceTableVersion"] = task["billing_price_table_version"]
        _save_local_comic_state()
    if storyboard_audio_mode:
        apply_storyboard_audio_mode(task)
    return task


def _comic_storyboard_image_frame_prompts(workflow_mode, payload, prompt):
    workflow_mode = str(workflow_mode or "").strip()
    if workflow_mode == "keyframes":
        return _keyframe_prompts(payload if isinstance(payload, dict) else {}, prompt)
    if workflow_mode == "multiframe":
        return _seven_frame_prompts(prompt)
    return []


def _comic_storyboard_requested_image_frame_index(workflow_mode, payload):
    payload = payload if isinstance(payload, dict) else {}
    supplied_frame_indices = []
    for key in ("frameIndex", "frame_index"):
        if key not in payload:
            continue
        raw_frame_index = payload.get(key)
        if type(raw_frame_index) is not int or raw_frame_index not in (1, 2):
            raise ValueError("frameIndex must be 1 or 2 for keyframes")
        supplied_frame_indices.append(raw_frame_index)
    if not supplied_frame_indices:
        return None
    if str(workflow_mode or "").strip() != "keyframes" or len(set(supplied_frame_indices)) != 1:
        raise ValueError("frameIndex must be 1 or 2 for keyframes")
    return supplied_frame_indices[0]


def _comic_storyboard_batch_payload(payload):
    batch_payload = dict(payload if isinstance(payload, dict) else {})
    batch_payload.pop("frameIndex", None)
    batch_payload.pop("frame_index", None)
    return batch_payload


def _comic_storyboard_frame_prompt_source(payload=None, storyboard=None, fallback=""):
    payload = payload if isinstance(payload, dict) else {}
    storyboard = storyboard if isinstance(storyboard, dict) else {}
    candidates = []
    for source in (payload, storyboard):
        for key in (
            "description",
            "action_grid_prompt",
            "actionGridPrompt",
            "storyboard_image_prompt",
            "storyboardImagePrompt",
            "image_prompt",
            "imagePrompt",
            "final_prompt",
            "finalPrompt",
        ):
            value = str(source.get(key) or "").strip()
            if value:
                candidates.append(value)
    fallback = str(fallback or "").strip()
    if fallback:
        candidates.append(fallback)
    for text in candidates:
        if not re.search(r"七帧关键帧生成|请根据以下漫剧剧本|严格参考同一批已上传|本次画面只允许出现", text):
            return text
    return candidates[0] if candidates else ""


def _comic_image_model_reference_limit(model_id):
    model_id = _normalize_comic_model_id(model_id)
    if not model_id:
        model_id = COMIC_DEFAULT_IMAGE_MODEL
    try:
        catalog = _build_comic_model_catalog_response("image")
    except Exception:
        catalog = {"models": COMIC_LOCAL_MODEL_CATALOG.get("image") or []}
    for item in catalog.get("models") or []:
        if not isinstance(item, dict):
            continue
        if _normalize_comic_model_id(item.get("id")) != model_id:
            continue
        supports_refs = item.get("supports_reference_images")
        max_refs = item.get("max_reference_images")
        try:
            max_refs = int(max_refs)
        except Exception:
            max_refs = COMIC_FRAME_IMAGE_MIN_REFERENCE_IMAGES
        if supports_refs is False:
            max_refs = 0
        return max(0, max_refs)
    return COMIC_FRAME_IMAGE_MIN_REFERENCE_IMAGES


def _comic_video_model_reference_limit(model_id):
    model_id = _normalize_comic_model_id(model_id)
    if not model_id:
        model_id = COMIC_DEFAULT_VIDEO_MODEL
    if _is_official_ark_seedance_video_model(model_id):
        return COMIC_OFFICIAL_ARK_SEEDANCE_REFERENCE_LIMIT
    try:
        _, detail = _lk888_video_model_detail(model_id)
        if isinstance(detail.get("params"), list):
            return max(0, _lk888_video_schema_reference_limit(model_id))
    except Exception:
        pass
    try:
        catalog = _build_comic_model_catalog_response("video")
    except Exception:
        catalog = {"models": COMIC_LOCAL_MODEL_CATALOG.get("video") or []}
    for item in catalog.get("models") or []:
        if not isinstance(item, dict):
            continue
        if _normalize_comic_model_id(item.get("id")) != model_id:
            continue
        try:
            max_refs = int(item.get("max_reference_images") or 0)
        except Exception:
            max_refs = 0
        if item.get("supports_reference_images") is False:
            max_refs = 0
        return max(0, max_refs)
    return 0


def _comic_video_params_have_required_extra_inputs(params, required_fields):
    params = params if isinstance(params, dict) else {}
    aliases = {
        "sound_file": ("sound_file", "soundFile", "audio", "audio_file", "audioFile", "reference_audio_file"),
    }
    for field in required_fields or []:
        keys = aliases.get(str(field or ""), (str(field or ""),))
        if not any(params.get(key) not in (None, "", [], {}) for key in keys):
            return False
    return True


def _comic_multiframe_video_model_error(model_id, params=None):
    extra_required = _lk888_required_extra_inputs_for_storyboard_video(model_id)
    if extra_required and not _comic_video_params_have_required_extra_inputs(params, extra_required):
        return f"七帧模式不支持当前视频模型 {model_id or COMIC_DEFAULT_VIDEO_MODEL}，该模型还需要额外输入：{', '.join(extra_required)}。请切换到 Vidu Q3 参考生视频、Seedance 参考、Wanxiang 参考生视频等多参考视频模型。"
    max_refs = _comic_video_model_reference_limit(model_id)
    if max_refs >= COMIC_MULTIFRAME_VIDEO_MIN_REFERENCE_IMAGES:
        return ""
    return (
        f"七帧视频模式需要支持至少 {COMIC_MULTIFRAME_VIDEO_MIN_REFERENCE_IMAGES} 张参考图的视频模型，"
        f"当前视频模型 {model_id or COMIC_DEFAULT_VIDEO_MODEL} 只支持 {max_refs} 张。请切换到 Vidu Q3 参考生视频、Seedance 参考、Wanxiang 参考生视频等多参考视频模型。"
    )


def _comic_keyframes_video_model_error(model_id, params=None):
    extra_required = _lk888_required_extra_inputs_for_storyboard_video(model_id)
    if extra_required and not _comic_video_params_have_required_extra_inputs(params, extra_required):
        return f"首尾帧模式不支持当前视频模型 {model_id or COMIC_DEFAULT_VIDEO_MODEL}，该模型还需要额外输入：{', '.join(extra_required)}。请切换到 Sora-2、Vidu Q3、Seedance、Kling 首尾帧、PixVerse 首尾帧等图片生视频模型。"
    max_refs = _comic_video_model_reference_limit(model_id)
    if max_refs <= 0:
        return f"首尾帧模式需要支持图片参考的视频模型，当前视频模型 {model_id or COMIC_DEFAULT_VIDEO_MODEL} 不支持参考图。请切换到 Sora-2、Vidu Q3、Seedance、Kling 首尾帧、PixVerse 首尾帧等图片生视频模型。"
    return ""


