def _comic_video_model_is_reference_generation(model_id):
    raw = str(model_id or "").strip().lower()
    return any(token in raw for token in ("cankao", "cankaosheng", "参考生"))


def _comic_keyframes_limited_video_reference_limit(model_id):
    raw = str(model_id or "").strip().lower()
    if raw in COMIC_KEYFRAMES_SINGLE_IMAGE_VIDEO_MODEL_IDS:
        return 1
    max_refs = _comic_video_model_reference_limit(model_id)
    if max_refs > 0:
        return max_refs
    if raw in COMIC_KEYFRAMES_TWO_IMAGE_VIDEO_MODEL_IDS or raw.startswith("viduq3"):
        return 2
    return 0


def _comic_catalog_item_reference_limit(item):
    if not isinstance(item, dict):
        return 0
    try:
        max_refs = int(item.get("max_reference_images") or 0)
    except Exception:
        max_refs = 0
    if item.get("supports_reference_images") is False:
        max_refs = 0
    return max(0, max_refs)


def _comic_model_supports_multiframe_refs(item, kind="image"):
    min_refs = COMIC_MULTIFRAME_VIDEO_MIN_REFERENCE_IMAGES if str(kind or "") == "video" else COMIC_FRAME_IMAGE_MIN_REFERENCE_IMAGES
    return _comic_catalog_item_reference_limit(item) >= min_refs


def _comic_request_wants_multiframe_catalog(handler):
    try:
        parsed = urllib.parse.urlparse(getattr(handler, "path", "") or "")
        query = urllib.parse.parse_qs(parsed.query or "")
    except Exception:
        query = {}
    values = []
    for key in (
        "workflow_mode",
        "workflowMode",
        "storyboard_workflow_mode",
        "storyboardWorkflowMode",
        "mode",
        "frame_mode",
        "frameMode",
    ):
        values.extend(query.get(key) or [])
    text = " ".join(str(value or "") for value in values).lower()
    return any(token in text for token in ("multiframe", "multi_frame", "seven", "7frame", "7_frame", "七帧"))


def _filter_multiframe_reference_model_catalog(catalog, kind="image"):
    catalog = dict(catalog if isinstance(catalog, dict) else {})
    models = []
    for item in catalog.get("models") or []:
        if not isinstance(item, dict):
            continue
        updated = dict(item)
        updated["supports_multiframe_references"] = _comic_model_supports_multiframe_refs(updated, kind)
        if updated["supports_multiframe_references"]:
            models.append(updated)
    catalog["models"] = models
    return catalog


def _comic_frame_image_model_error(workflow_mode, model_id):
    workflow_mode = str(workflow_mode or "").strip()
    if workflow_mode not in {"keyframes", "multiframe"}:
        return ""
    max_refs = _comic_image_model_reference_limit(model_id)
    if max_refs >= COMIC_FRAME_IMAGE_MIN_REFERENCE_IMAGES:
        return ""
    return (
        f"{'七帧' if workflow_mode == 'multiframe' else '首尾帧'}参考图生成需要支持至少 "
        f"{COMIC_FRAME_IMAGE_MIN_REFERENCE_IMAGES} 张参考图的图片模型，当前图片模型 "
        f"{model_id or COMIC_DEFAULT_IMAGE_MODEL} 只支持 {max_refs} 张。请切换到 Nano Banana / GPT Image 2 Official 等多参考图模型。"
    )


def _comic_frame_image_model_or_default(workflow_mode, model_id):
    workflow_mode = str(workflow_mode or "").strip()
    model_id = _normalize_comic_model_id(model_id)
    if workflow_mode in {"keyframes", "multiframe"} and (not model_id or model_id == COMIC_DEFAULT_IMAGE_MODEL):
        return COMIC_DEFAULT_FRAME_IMAGE_MODEL
    return model_id or COMIC_DEFAULT_IMAGE_MODEL


def _apply_comic_frame_task_metadata(task, workflow_mode, frame_index):
    if not isinstance(task, dict):
        return task
    task["workflow_mode"] = str(workflow_mode or "").strip()
    task["frame_index"] = int(frame_index)
    _save_local_comic_state()
    return task


def _apply_comic_storyboard_audio_mode_metadata(task, audio_mode):
    if not isinstance(task, dict):
        return task
    normalized = str(audio_mode or "").strip().lower()
    if normalized not in {"auto", "tts"}:
        normalized = "legacy"
    existing_modes = set()
    for key in ("audio_mode", "audioMode"):
        if key not in task or not str(task.get(key) or "").strip():
            continue
        existing = str(task.get(key) or "").strip().lower()
        existing_modes.add(existing if existing in {"auto", "tts"} else "legacy")
    if existing_modes and existing_modes != {normalized}:
        return task
    if task.get("audio_mode") == normalized and task.get("audioMode") == normalized:
        return task
    task["audio_mode"] = normalized
    task["audioMode"] = normalized
    _save_local_comic_state()
    return task


def _extract_comic_gateway_task_id(payload):
    if isinstance(payload, dict):
        for key in ("task_id", "taskId", "id", "job_id", "jobId", "request_id", "requestId"):
            value = payload.get(key)
            if isinstance(value, (str, int, float)):
                text = str(value).strip()
                if text and text.lower() not in {"0", "none", "null", "undefined"}:
                    return text
        for key in ("data", "result", "response", "payload", "task", "job"):
            found = _extract_comic_gateway_task_id(payload.get(key))
            if found:
                return found
        for value in payload.values():
            found = _extract_comic_gateway_task_id(value)
            if found:
                return found
    elif isinstance(payload, list):
        for item in payload:
            found = _extract_comic_gateway_task_id(item)
            if found:
                return found
    return ""


def _comic_gateway_offpeak_disabled_payload(payload):
    payload = dict(payload if isinstance(payload, dict) else {})
    params = dict(payload.get("params") if isinstance(payload.get("params"), dict) else {})
    for key in ("off_peak", "offpeak", "offPeak", "cuofeng", "peak_mode", "peakMode"):
        if key in payload:
            payload[key] = False
        if key in params:
            params[key] = "false" if isinstance(params.get(key), str) else False
    params.setdefault("off_peak", "false")
    payload["params"] = params
    return payload


def _comic_gateway_is_offpeak_unsupported_error(error):
    text = AiApiService.sanitize_error(str(error or ""))
    return bool(re.search(r"(错峰|off[-_ ]?peak).*(不支持|unsupported)|全能版不支持错峰", text, re.IGNORECASE))


def _minimax_h3_https_url(value, label="reference URL"):
    text = str(value or "").strip()
    try:
        parsed = urllib.parse.urlparse(text)
    except Exception:
        parsed = None
    if not parsed or parsed.scheme.lower() != "https" or not parsed.netloc:
        raise ValueError(f"{label} must be a public HTTPS URL")
    host = (parsed.hostname or "").strip().lower()
    if not host or host in {"localhost", "127.0.0.1", "::1"}:
        raise ValueError(f"{label} must be a public HTTPS URL")
    try:
        address = ipaddress.ip_address(host)
        if address.is_private or address.is_loopback or address.is_link_local or address.is_reserved:
            raise ValueError(f"{label} must be a public HTTPS URL")
    except ValueError as exc:
        if "public HTTPS URL" in str(exc):
            raise
    return text


def _minimax_h3_duration(params):
    params = params if isinstance(params, dict) else {}
    for key in ("duration", "video_duration", "videoDuration", "seconds"):
        value = params.get(key)
        if value in (None, ""):
            continue
        try:
            duration = int(float(value))
        except Exception as exc:
            raise ValueError("MiniMax H3 duration must be an integer") from exc
        if MINIMAX_H3_DURATION_MIN <= duration <= MINIMAX_H3_DURATION_MAX:
            return duration
        raise ValueError("MiniMax H3 duration must be between 4 and 15 seconds")
    return MINIMAX_H3_DURATION_MIN


def _minimax_h3_resolution(params):
    params = params if isinstance(params, dict) else {}
    for key in ("resolution", "videoSize", "video_size", "size", "quality"):
        raw = str(params.get(key) or "").strip()
        if not raw:
            continue
        normalized = raw.upper()
        if normalized in {"768", "768P", "720P", "720"}:
            return "768P"
        if normalized in {"2K", "1440P", "1440"}:
            return "2K"
        raise ValueError("MiniMax H3 resolution must be 768P or 2K")
    return "768P"


def _minimax_h3_content_from_params(params):
    params = params if isinstance(params, dict) else {}
    for key in (
        "reference_image_urls",
        "referenceImageUrls",
        "image_urls",
        "imageUrls",
        "inputUrls",
        "images",
        "reference_images",
        "referenceImages",
        "subject_reference_images",
        "additional_reference_images",
        "character_reference_images",
        "scene_reference_images",
        "prop_reference_images",
        "strict_reference_image_urls",
        "storyboard_image",
        "storyboardImage",
        "end_frame_image",
        "endFrameImage",
        "first_frame",
        "firstFrameUrl",
        "last_frame",
        "lastFrameUrl",
        "image_url",
        "imageUrl",
        "url",
        "urls",
    ):
        if key not in params:
            continue
        for candidate in _minimax_h3_reference_candidates(params.get(key)):
            _minimax_h3_https_url(candidate, "content URL")
    action_refs, extra_refs, refs = _comic_collect_video_reference_urls(params)
    refs = _dedupe_urls([*action_refs, *extra_refs, *refs])[:7]
    content = []
    for ref in refs:
        content.append(
            {
                "type": "image_url",
                "image_url": {"url": _minimax_h3_https_url(ref, "content URL")},
            }
        )
    return content


def _minimax_h3_reference_candidates(value):
    if isinstance(value, str):
        text = value.strip()
        return [text] if text else []
    if isinstance(value, list):
        items = []
        for item in value:
            items.extend(_minimax_h3_reference_candidates(item))
        return items
    if isinstance(value, dict):
        items = []
        for key in (
            "url",
            "src",
            "image_url",
            "imageUrl",
            "media_url",
            "mediaUrl",
        ):
            if key in value:
                items.extend(_minimax_h3_reference_candidates(value.get(key)))
        return items
    return []


def _minimax_h3_json_request(method, path, payload=None, timeout=60):
    if not MINIMAX_ENABLED:
        raise RuntimeError("MiniMax H3 is disabled")
    if not MINIMAX_COMIC_API_KEY:
        raise RuntimeError("MiniMax comic API key is not configured")
    base = MINIMAX_COMIC_API_BASE.rstrip("/")
    parsed_base = urllib.parse.urlparse(base)
    if parsed_base.scheme.lower() != "https" or not parsed_base.netloc:
        raise RuntimeError("MiniMax comic API base must be HTTPS")
    body = None
    if payload is not None:
        body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
    request = urllib.request.Request(
        base + path,
        data=body,
        headers={
            "Authorization": "Bearer " + MINIMAX_COMIC_API_KEY,
            "Content-Type": "application/json",
            "User-Agent": "AI-CanvasPro-MiniMax-H3/1.0",
        },
        method=str(method or "GET").upper(),
    )
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            raw = response.read()
    except urllib.error.HTTPError as exc:
        detail = ""
        try:
            detail = exc.read().decode("utf-8", "replace")[:240]
        except Exception:
            detail = str(exc)
        raise RuntimeError("MiniMax H3 HTTP %s: %s" % (exc.code, detail))
    data = json.loads((raw or b"{}").decode("utf-8"))
    if not isinstance(data, dict):
        raise RuntimeError("MiniMax H3 returned invalid JSON")
    base_resp = data.get("base_resp")
    if isinstance(base_resp, dict):
        status_code = base_resp.get("status_code")
        if status_code not in (None, 0, "0"):
            raise RuntimeError(str(base_resp.get("status_msg") or "MiniMax H3 rejected request"))
    return data


def _minimax_h3_provider_result_url(payload):
    if not isinstance(payload, dict):
        return ""
    task = payload.get("task")
    if isinstance(task, dict):
        content = task.get("content")
        if isinstance(content, dict):
            url = str(content.get("url") or "").strip()
            if url:
                return _minimax_h3_https_url(url, "provider result URL")
        found = _minimax_h3_provider_result_url(task)
        if found:
            return found
    for key in (
        "result_url",
        "resultUrl",
        "video_url",
        "videoUrl",
        "url",
        "output",
        "fileUrl",
        "file_url",
        "download_url",
        "downloadUrl",
    ):
        value = payload.get(key)
        if isinstance(value, str) and value.strip():
            return _minimax_h3_https_url(value.strip(), "provider result URL")
    for key in ("data", "result", "response", "payload"):
        found = _minimax_h3_provider_result_url(payload.get(key))
        if found:
            return found
    for key in ("results", "outputs", "files", "urls"):
        value = payload.get(key)
        if isinstance(value, list):
            for item in value:
                if isinstance(item, str) and item.strip():
                    return _minimax_h3_https_url(item.strip(), "provider result URL")
                found = _minimax_h3_provider_result_url(item)
                if found:
                    return found
    return ""


def _minimax_h3_task_status_envelope(task_id):
    task_id = str(task_id or "").strip()
    if not task_id:
        raise RuntimeError("MiniMax H3 task_id is required")
    payload = _minimax_h3_json_request(
        "GET",
        "/v2/query/video_generation/" + urllib.parse.quote(task_id, safe=""),
        None,
        min(MINIMAX_TASK_TIMEOUT_SEC, 120),
    )
    raw_status = str(payload.get("status") or payload.get("state") or "").strip().lower()
    if raw_status in {"success", "succeeded", "complete", "completed"}:
        result_url = _minimax_h3_provider_result_url(payload)
        if not result_url:
            raise RuntimeError("MiniMax H3 completed without result URL")
        return {
            "status": "COMPLETED",
            "task_status": "COMPLETED",
            "state": "success",
            "is_final": True,
            "progress": "100",
            "result_url": result_url,
            "url": result_url,
            "video_url": result_url,
            "videoUrl": result_url,
            "task_id": task_id,
            "provider": "minimax-direct",
            "actual_model": MINIMAX_H3_PROVIDER_MODEL,
            "billing_status": "awaiting_actual_cost",
            "billing_price_table_version": "minimax-h3-price-unresolved",
        }
    if raw_status in {"pending", "processing", "queued", "running"}:
        return {
            "status": "RUNNING",
            "task_status": "RUNNING",
            "state": "running",
            "is_final": False,
            "progress": str(payload.get("progress") or ""),
            "task_id": task_id,
            "provider": "minimax-direct",
            "actual_model": MINIMAX_H3_PROVIDER_MODEL,
            "billing_status": "awaiting_actual_cost",
            "billing_price_table_version": "minimax-h3-price-unresolved",
        }
    if raw_status in {"fail", "failed", "failure", "cancelled", "canceled"}:
        message = (
            payload.get("error")
            or payload.get("message")
            or payload.get("status_msg")
            or "MiniMax H3 provider task failed"
        )
        return {
            "status": "FAILED",
            "task_status": "FAILED",
            "state": "failed",
            "is_final": True,
            "progress": "100",
            "error": AiApiService.sanitize_error(str(message)),
            "task_id": task_id,
            "provider": "minimax-direct",
            "actual_model": MINIMAX_H3_PROVIDER_MODEL,
            "billing_status": "awaiting_actual_cost",
            "billing_price_table_version": "minimax-h3-price-unresolved",
        }
    raise RuntimeError("MiniMax H3 returned malformed task status")


def _submit_minimax_h3_comic_video_task(prompt, params=None):
    params = params if isinstance(params, dict) else {}
    prompt = str(prompt or params.get("prompt") or "").strip()
    if not prompt:
        raise ValueError("MiniMax H3 prompt is required")
    provider_payload = {
        "model": MINIMAX_H3_PROVIDER_MODEL,
        "prompt": prompt,
        "duration": _minimax_h3_duration(params),
        "resolution": _minimax_h3_resolution(params),
    }
    content = _minimax_h3_content_from_params(params)
    if content:
        provider_payload["content"] = content
    created = _minimax_h3_json_request(
        "POST",
        "/v2/video_generation",
        provider_payload,
        min(MINIMAX_TASK_TIMEOUT_SEC, 120),
    )
    task_id = _extract_comic_gateway_task_id(created)
    if not task_id:
        raise RuntimeError("MiniMax H3 did not return task_id")
    _json_log(
        "minimax_h3_comic_submitted",
        provider="minimax-direct",
        model=MINIMAX_H3_PROVIDER_MODEL,
        task_id=task_id,
        duration=provider_payload.get("duration"),
        resolution=provider_payload.get("resolution"),
        reference_count=len(content),
    )
    return {
        "task_id": task_id,
        "actual_model": MINIMAX_H3_PROVIDER_MODEL,
        "provider": "minimax-direct",
        "billing_status": "awaiting_actual_cost",
        "billing_price_table_version": "minimax-h3-price-unresolved",
    }


def _submit_comic_gateway_video_task(model, prompt, params=None, count=1):
    cfg = _get_api_gateway_config()
    base = str(cfg.get("apiUrl") or "").strip().rstrip("/")
    api_key = str(cfg.get("apiKey") or "").strip()
    if not base or not api_key:
        raise RuntimeError("LK888 网关未配置，无法提交视频任务")
    data = dict(params if isinstance(params, dict) else {})
    action_refs, extra_refs, refs = _comic_collect_video_reference_urls(data)
    reference_limit = _comic_video_model_reference_limit(model)
    submit_limit = min(reference_limit, 9) if reference_limit > 0 else 9
    action_refs = action_refs[:min(7, submit_limit)]
    extra_refs = [ref for ref in extra_refs if ref not in action_refs]
    submit_refs = _dedupe_urls([*action_refs, *extra_refs])[:submit_limit]
    for field in (
        "reference_image_urls",
        "referenceImageUrls",
        "image_urls",
        "imageUrls",
        "inputUrls",
        "images",
        "reference_images",
        "referenceImages",
        "subject_reference_images",
        "additional_reference_images",
        "character_reference_images",
        "scene_reference_images",
        "prop_reference_images",
        "strict_reference_image_urls",
        "image_with_roles",
        "storyboard_image",
        "storyboardImage",
        "end_frame_image",
        "endFrameImage",
        "first_frame",
        "firstFrameUrl",
        "last_frame",
        "lastFrameUrl",
        "image_url",
        "imageUrl",
        "url",
        "urls",
    ):
        data.pop(field, None)
    if submit_refs:
        data["images"] = submit_refs
        data["image_urls"] = submit_refs
        data["reference_image_urls"] = submit_refs
        data["inputUrls"] = submit_refs
    if action_refs:
        data["action_flow_images"] = action_refs[:7]
    data["model"] = str(model or "").strip()
    data["prompt"] = str(prompt or "").strip()
    data["count"] = int(count or 1)
    payload = _comic_gateway_offpeak_disabled_payload(_adapt_api_gateway_video_payload(data, cfg))
    try:
        created = _apimart_json_request(base, api_key, "/v1/media/generate", payload, 60)
    except Exception as error:
        if not _comic_gateway_is_offpeak_unsupported_error(error):
            raise
        created = _apimart_json_request(base, api_key, "/v1/media/generate", _comic_gateway_offpeak_disabled_payload(payload), 60)
    try:
        code = int(created.get("code")) if isinstance(created, dict) and created.get("code") not in (None, "") else 200
    except Exception:
        code = 200
    if code >= 400:
        message = str(created.get("msg") or created.get("message") or created)[:300]
        if _comic_gateway_is_offpeak_unsupported_error(message):
            created = _apimart_json_request(base, api_key, "/v1/media/generate", _comic_gateway_offpeak_disabled_payload(payload), 60)
            try:
                code = int(created.get("code")) if isinstance(created, dict) and created.get("code") not in (None, "") else 200
            except Exception:
                code = 200
            if code >= 400:
                message = str(created.get("msg") or created.get("message") or created)[:300]
            else:
                task_id = _extract_comic_gateway_task_id(created)
                if not task_id:
                    raise RuntimeError("LK888 网关未返回有效 task_id")
                return {"task_id": task_id}
        raise RuntimeError(message)
    task_id = _extract_comic_gateway_task_id(created)
    if not task_id:
        raise RuntimeError("LK888 网关未返回有效 task_id")
    return {"task_id": task_id}


def _expand_comic_storyboard_image_submit_kwargs(base_kwargs, workflow_mode, payload, prompt):
    frame_prompt_source = str(base_kwargs.get("_frame_prompt_source") or prompt or "").strip()
    prompts = _comic_storyboard_image_frame_prompts(workflow_mode, payload, frame_prompt_source)
    if not prompts:
        return [base_kwargs]
    payload = payload if isinstance(payload, dict) else {}
    frame_style_mode = str(
        payload.get("frame_style_mode")
        or payload.get("frameStyleMode")
        or payload.get("style_mode")
        or payload.get("styleMode")
        or ""
    ).strip().lower()
    colored_pencil_mode = frame_style_mode in {
        "colored_pencil", "colored-pencil", "coloredpencil", "彩铅", "彩铅手绘"
    }
    requested_frame_index = _comic_storyboard_requested_image_frame_index(workflow_mode, payload)
    indexed_prompts = (
        [(requested_frame_index, prompts[requested_frame_index - 1])]
        if requested_frame_index is not None
        else list(enumerate(prompts, 1))
    )
    strict_refs = (base_kwargs.get("params") or {}).get("_strict_typed_reference_bundle")
    expanded = []
    for index, frame_prompt in indexed_prompts:
        kwargs = dict(base_kwargs)
        kwargs.pop("_frame_prompt_source", None)
        strict_ref_prompt = ""
        if isinstance(strict_refs, dict) and strict_refs.get("all") and not colored_pencil_mode:
            strict_ref_prompt = (
                "严格参考同一批已上传的人物、场景、道具参考图；七帧中的每一帧都必须保持角色脸型发型服装、"
                "场景空间结构光线、道具形状材质一致，不能有某一帧忽略参考图。"
                "画面风格必须锁定参考图的真实质感和摄影/影视质感；如果参考图是真人或写实风格，禁止动漫、二次元、漫画、插画、赛璐璐、Q版、卡通或手绘风格。"
            )
        kwargs["prompt"] = f"{strict_ref_prompt}{frame_prompt}" if strict_ref_prompt else frame_prompt
        params = dict(kwargs.get("params") or {})
        if isinstance(strict_refs, dict):
            params = _apply_strict_storyboard_references_to_params(params, strict_refs)
        params["storyboard_image_prompt"] = kwargs["prompt"]
        if workflow_mode == "multiframe":
            params["action_grid_prompt"] = kwargs["prompt"]
        elif workflow_mode == "keyframes":
            if index == 1:
                params["start_frame_prompt"] = kwargs["prompt"]
            elif index == 2:
                params["end_frame_prompt"] = kwargs["prompt"]
        kwargs["params"] = params
        kwargs["count"] = 1
        kwargs["task_name"] = f"{base_kwargs.get('task_name') or '生成分镜图'} 第{index}帧"
        kwargs["_task_metadata"] = {
            "workflow_mode": str(workflow_mode or "").strip(),
            "frame_index": index,
        }
        expanded.append(kwargs)
    return expanded


def _local_project_id_for_storyboard(storyboard_id):
    try:
        wanted = int(storyboard_id)
    except Exception:
        return 0
    for project_id, project in LOCAL_COMIC_PROJECTS.items():
        for storyboard in project.get("storyboards") or []:
            try:
                if int(storyboard.get("id")) == wanted:
                    return int(project_id)
            except Exception:
                continue
    if wanted > 1000:
        return max(0, wanted // 1000)
    return 0


def _ai_media_params_from_payload(payload, *, omit=()):
    payload = payload if isinstance(payload, dict) else {}
    omit_keys = {"model", "image_model", "video_model", "prompt", "quantity", "count", *omit}
    params = {}
    for key, value in payload.items():
        if key in omit_keys or value in (None, ""):
            continue
        params[key] = value
    if "action_flow_images" not in omit_keys:
        params = _merge_reference_urls_into_params(params, payload.get("action_flow_images") or [])
    return params


def _comic_collect_video_reference_urls(payload):
    payload = payload if isinstance(payload, dict) else {}
    action_refs = []
    extra_refs = []
    for key in ("action_flow_images", "actionFlowImages"):
        _extend_url_list(action_refs, payload.get(key))
    for key in (
        "storyboard_image",
        "storyboardImage",
        "end_frame_image",
        "endFrameImage",
        "first_frame",
        "firstFrameUrl",
        "last_frame",
        "lastFrameUrl",
        "reference_image_urls",
        "referenceImageUrls",
        "image_urls",
        "imageUrls",
        "images",
        "inputUrls",
        "image_with_roles",
        "reference_images",
        "referenceImages",
        "subject_reference_images",
        "additional_reference_images",
        "character_reference_images",
        "scene_reference_images",
        "prop_reference_images",
        "strict_reference_image_urls",
    ):
        _extend_url_list(extra_refs, payload.get(key))
    action_refs = _dedupe_urls(_apimart_publicize_ref(ref) for ref in action_refs if ref)
    extra_refs = _dedupe_urls(_apimart_publicize_ref(ref) for ref in extra_refs if ref)
    combined = _dedupe_urls([*action_refs, *extra_refs])
    return action_refs, extra_refs, combined


def _comic_multiframe_video_reference_error(workflow_mode, params):
    if str(workflow_mode or "").strip() != "multiframe":
        return ""
    params = params if isinstance(params, dict) else {}
    refs = _dedupe_urls(params.get("action_flow_images") or params.get("reference_image_urls") or params.get("image_urls") or params.get("images") or [])
    if len(refs) < 7:
        return f"七帧模式需要 7 张关键帧，当前只有 {len(refs)} 张"
    return ""


def _comic_keyframes_video_refs_from_params(params, storyboard=None):
    params = params if isinstance(params, dict) else {}
    storyboard = storyboard if isinstance(storyboard, dict) else {}
    first = _first_non_empty(
        params.get("storyboard_image"),
        params.get("storyboardImage"),
        params.get("first_frame"),
        params.get("firstFrameUrl"),
        storyboard.get("start_frame_url"),
        storyboard.get("startFrameUrl"),
        storyboard.get("image_url"),
        storyboard.get("imageUrl"),
    )
    last = _first_non_empty(
        params.get("end_frame_image"),
        params.get("endFrameImage"),
        params.get("last_frame"),
        params.get("lastFrameUrl"),
        storyboard.get("end_frame_url"),
        storyboard.get("endFrameUrl"),
    )
    refs = [first, last]
    for key in (
        "reference_image_urls",
        "referenceImageUrls",
        "image_urls",
        "imageUrls",
        "images",
        "inputUrls",
        "reference_images",
        "referenceImages",
        "subject_reference_images",
        "additional_reference_images",
        "character_reference_images",
        "scene_reference_images",
        "prop_reference_images",
        "strict_reference_image_urls",
    ):
        _extend_url_list(refs, params.get(key))
    return _dedupe_urls(refs)


def _comic_keyframes_video_params(workflow_mode, model_id, params, storyboard=None):
    params = dict(params if isinstance(params, dict) else {})
    if str(workflow_mode or "").strip() != "keyframes":
        return params
    max_refs = _comic_keyframes_limited_video_reference_limit(model_id)
    if max_refs <= 0:
        return params
    refs = _comic_keyframes_video_refs_from_params(params, storyboard)[:max_refs]
    if not refs:
        return params
    for key in (
        "reference_image_urls",
        "referenceImageUrls",
        "image_urls",
        "imageUrls",
        "images",
        "inputUrls",
        "reference_images",
        "referenceImages",
        "strict_reference_image_urls",
    ):
        params[key] = refs
    for key in (
        "character_reference_images",
        "scene_reference_images",
        "prop_reference_images",
        "subject_reference_images",
        "additional_reference_images",
        "image_with_roles",
        "action_flow_images",
        "actionFlowImages",
        "image_url",
        "imageUrl",
        "url",
        "urls",
    ):
        params.pop(key, None)
    params["_keyframes_limited_video_refs"] = refs
    params["storyboard_image"] = refs[0]
    params["first_frame"] = refs[0]
    params["firstFrameUrl"] = refs[0]
    if len(refs) > 1:
        params["end_frame_image"] = refs[1]
        params["last_frame"] = refs[1]
        params["lastFrameUrl"] = refs[1]
    return params


def _comic_multiframe_video_params(workflow_mode, model_id, params):
    params = dict(params if isinstance(params, dict) else {})
    if str(workflow_mode or "").strip() != "multiframe":
        return params
    action_refs, extra_refs, refs = _comic_collect_video_reference_urls(params)
    max_refs = _comic_video_model_reference_limit(model_id)
    limit = min(max_refs, 9) if max_refs > 0 else 9
    action_refs = action_refs[:7]
    extra_refs = [ref for ref in extra_refs if ref not in action_refs]
    selected_extra_refs = extra_refs[:max(0, limit - len(action_refs))]
    refs = _dedupe_urls([*action_refs, *selected_extra_refs])[:limit]
    selected_extra_set = set(selected_extra_refs)
    character_refs = [ref for ref in _dedupe_urls(params.get("character_reference_images") or []) if ref in selected_extra_set]
    scene_refs = [ref for ref in _dedupe_urls(params.get("scene_reference_images") or []) if ref in selected_extra_set]
    prop_refs = [ref for ref in _dedupe_urls(params.get("prop_reference_images") or []) if ref in selected_extra_set]
    params["action_flow_images"] = action_refs or refs
    params["actionFlowImages"] = action_refs or refs
    params["reference_image_urls"] = refs
    params["referenceImageUrls"] = refs
    params["image_urls"] = refs
    params["imageUrls"] = refs
    params["images"] = refs
    params["inputUrls"] = refs
    params["referenceImages"] = refs
    params["reference_images"] = refs
    params["subject_reference_images"] = selected_extra_refs
    params["additional_reference_images"] = selected_extra_refs
    params["character_reference_images"] = character_refs
    params["scene_reference_images"] = scene_refs
    params["prop_reference_images"] = prop_refs
    params["strict_reference_image_urls"] = refs
    for key in ("duration", "video_duration"):
        if key in params:
            params[key] = max(3, min(float(params[key]), 16))
    return params


def _comic_parse_video_duration(value):
    if value in (None, ""):
        return None
    try:
        text = str(value).strip().replace("秒", "")
        duration = float(re.sub(r"[^0-9.]", "", text) or 0)
    except (TypeError, ValueError):
        return None
    if duration <= 0:
        return None
    duration = max(1, min(duration, 16))
    return int(duration) if float(duration).is_integer() else duration


def _comic_nearest_video_duration_for_model(model, duration):
    duration = _comic_parse_video_duration(duration)
    if duration is None:
        return None
    normalized_model = _lk888_normalize_video_model(_apply_model_remap(model))
    caps = _lk888_video_caps_for_model(normalized_model)
    options = (caps.get("durations") or {}).get("options") if isinstance(caps.get("durations"), dict) else []
    if options:
        picked = _lk888_pick_numeric_option(duration, options, options[0])
        return _comic_parse_video_duration(picked)
    if _ark_should_route(normalized_model):
        return max(5, min(duration, 15))
    return duration


def _comic_storyboard_video_duration_from_payload(payload, target_id, storyboard=None, params=None, project=None):
    payload = payload if isinstance(payload, dict) else {}
    params = params if isinstance(params, dict) else {}
    durations = payload.get("storyboard_video_durations") or payload.get("storyboardVideoDurations") or {}
    values = []
    if isinstance(durations, dict):
        values.extend([durations.get(str(target_id)), durations.get(target_id)])
    values.extend([
        payload.get("duration"),
        payload.get("video_duration"),
        payload.get("videoDuration"),
        params.get("duration"),
        params.get("video_duration"),
        params.get("videoDuration"),
    ])
    if isinstance(storyboard, dict):
        values.extend([storyboard.get("video_duration"), storyboard.get("videoDuration"), storyboard.get("duration")])
    config = (project or {}).get("config") if isinstance(project, dict) and isinstance((project or {}).get("config"), dict) else {}
    values.extend([config.get("duration_per_shot"), config.get("durationPerShot")])
    for value in values:
        duration = _comic_parse_video_duration(value)
        if duration is not None:
            return duration
    return None


def _apply_comic_storyboard_video_duration(params, payload, target_id, storyboard=None, project=None, model=""):
    params = dict(params if isinstance(params, dict) else {})
    payload = payload if isinstance(payload, dict) else {}
    config = (project or {}).get("config") if isinstance(project, dict) and isinstance((project or {}).get("config"), dict) else {}
    control = str(
        payload.get("video_duration_control")
        or payload.get("videoDurationControl")
        or config.get("video_duration_control")
        or config.get("videoDurationControl")
        or ""
    ).strip().lower()
    if control == "disabled":
        return params
    duration = _comic_storyboard_video_duration_from_payload(payload, target_id, storyboard, params, project)
    duration = _comic_nearest_video_duration_for_model(model, duration)
    if duration is None:
        return params
    params["duration"] = duration
    params["video_duration"] = duration
    return params


def _comic_storyboard_video_aspect_ratio_from_payload(payload=None, storyboard=None, params=None, project=None):
    payload = payload if isinstance(payload, dict) else {}
    params = params if isinstance(params, dict) else {}
    storyboard = storyboard if isinstance(storyboard, dict) else {}
    config = (project or {}).get("config") if isinstance(project, dict) and isinstance((project or {}).get("config"), dict) else {}
    render_contract = config.get("render_contract") if isinstance(config.get("render_contract"), dict) else {}
    values = [
        payload.get("aspect_ratio"),
        payload.get("aspectRatio"),
        payload.get("ratio"),
        params.get("aspect_ratio"),
        params.get("aspectRatio"),
        params.get("ratio"),
        storyboard.get("aspect_ratio"),
        storyboard.get("aspectRatio"),
        config.get("aspect_ratio"),
        config.get("aspectRatio"),
        render_contract.get("aspect_ratio"),
        render_contract.get("aspectRatio"),
    ]
    for value in values:
        ratio = _normalize_aspect_ratio_value(value)
        if ratio:
            return ratio
    return ""


def _apply_comic_storyboard_video_aspect_ratio(params, payload=None, storyboard=None, project=None):
    params = dict(params if isinstance(params, dict) else {})
    ratio = _comic_storyboard_video_aspect_ratio_from_payload(payload, storyboard, params, project)
    if not ratio:
        return params
    params["aspect_ratio"] = ratio
    params["aspectRatio"] = ratio
    params["ratio"] = ratio
    return params


def _ai_image_params_with_size(params, payload, target_type=""):
    def _normalize_size(value):
        text = str(value or "").strip()
        if not text:
            return ""
        return {
            "1:1": "1024x1024",
            "2:3": "1024x1536",
            "3:2": "1536x1024",
            "9:16": "1024x1536",
            "16:9": "1536x1024",
            "portrait": "1024x1536",
            "landscape": "1536x1024",
            "square": "1024x1024",
        }.get(text.lower(), text)

    def _normalize_quality(value):
        text = str(value or "").strip()
        if not text:
            return ""
        return {
            "auto": "自动",
            "standard": "中",
            "medium": "中",
            "normal": "中",
            "hd": "高",
            "full_hd": "高",
            "high": "高",
            "low": "低",
        }.get(text.lower(), text)

    params = dict(params if isinstance(params, dict) else {})
    quality = _normalize_quality(params.get("quality") or (payload if isinstance(payload, dict) else {}).get("quality"))
    if quality:
        params["quality"] = quality
    if params.get("size"):
        params["size"] = _normalize_size(params.get("size"))
        params["imageSize"] = params["size"]
        return params
    payload = payload if isinstance(payload, dict) else {}
    size = _first_non_empty(
        payload.get("size"),
        payload.get("image_size"),
        payload.get("ratio"),
        payload.get("aspectRatio"),
        payload.get("aspect_ratio"),
        params.get("ratio"),
        params.get("aspectRatio"),
        params.get("aspect_ratio"),
    )
    if not size:
        # ponytail: ai media API requires size; local comic routes only need sane defaults.
        size = {
            "character": "1024x1536",
            "characters": "1024x1536",
            "scene": "1536x1024",
            "scenes": "1536x1024",
            "storyboard": "1536x1024",
            "storyboard_images": "1536x1024",
            "prop": "1024x1024",
            "props": "1024x1024",
        }.get(str(target_type or "").strip(), "1024x1024")
    params["size"] = _normalize_size(size)
    params["imageSize"] = params["size"]
    return params


def _create_local_comic_project_from_payload(payload):
    payload = payload if isinstance(payload, dict) else {}
    project_id = _take_local_comic_project_id()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()
    config = payload.get("config") if isinstance(payload.get("config"), dict) else {}
    project = {
        "id": project_id,
        "title": str(payload.get("title") or "未命名工坊工具项目"),
        "description": str(payload.get("description") or ""),
        "source_text": str(payload.get("source_text") or payload.get("script") or ""),
        "source_mode": str(payload.get("source_mode") or payload.get("sourceMode") or "local_flow"),
        "status": "pending",
        "config": config,
        "storyboards": [],
        "characters": [],
        "scenes": [],
        "props": [],
        "created_at": now,
        "updated_at": now,
    }
    if project["source_mode"] == "matrix_video_replacement":
        seeded_storyboards = payload.get("storyboards")
        if not isinstance(seeded_storyboards, list):
            seeded_storyboards = []
        try:
            requested_count = int(config.get("storyboardCount") or len(seeded_storyboards))
        except Exception:
            requested_count = len(seeded_storyboards)
        requested_count = max(0, min(requested_count, len(seeded_storyboards), 100))
        accepted_fields = (
            "description", "shot_type", "camera_angle", "camera_movement",
            "image_prompt", "storyboard_image_prompt", "video_prompt",
            "audio_prompt", "video_duration", "duration",
        )
        for index, source in enumerate(seeded_storyboards[:requested_count], start=1):
            if not isinstance(source, dict):
                continue
            item = {
                key: copy.deepcopy(source.get(key))
                for key in accepted_fields
                if source.get(key) not in (None, "")
            }
            item["id"] = project_id * 1000 + index
            item["project_id"] = project_id
            item["sequence"] = index
            item["status"] = "pending"
            item.setdefault("characters", [])
            item.setdefault("scene", None)
            item.setdefault("props", [])
            project["storyboards"].append(item)
        if project["storyboards"]:
            project["status"] = "storyboards"
    scope = _get_request_account_scope()
    if scope:
        project["account_scope"] = scope
    LOCAL_COMIC_PROJECTS[project_id] = project
    _save_local_comic_state()
    return project


def _local_comic_project_owner_scope(project):
    if not isinstance(project, dict):
        return ""
    for key in ("account_scope", "owner_scope", "storage_scope"):
        scope = _sanitize_account_scope(project.get(key))
        if scope:
            return scope
    return ""


def _local_comic_scope_allows_project(project):
    current_scope = _sanitize_account_scope(_get_request_account_scope())
    if not current_scope:
        return True
    owner_scope = _local_comic_project_owner_scope(project)
    if owner_scope:
        return owner_scope == current_scope
    return current_scope in {"local", "dev"}


def _inherit_local_comic_scope_from_persisted_project(project_id):
    current_scope = _sanitize_account_scope(_get_request_account_scope())
    if current_scope and current_scope not in {"local", "dev"}:
        return False
    persisted_project = _load_persisted_local_comic_project(project_id)
    owner_scope = _local_comic_project_owner_scope(persisted_project)
    if not owner_scope:
        return False
    if owner_scope == current_scope:
        return False
    _set_request_account_scope(owner_scope)
    return True


def _local_comic_project_for_current_scope(project_id):
    try:
        wanted_id = int(project_id or 0)
    except Exception:
        return None
    project = LOCAL_COMIC_PROJECTS.get(wanted_id)
    if _get_request_account_scope():
        if (
            isinstance(project, dict)
            and _local_comic_scope_allows_project(project)
            and str(project.get("status") or "").strip().lower() in {"pending", "analyzing"}
        ):
            return project
        persisted_project = _load_persisted_local_comic_project(wanted_id)
        if isinstance(project, dict) and _local_comic_scope_allows_project(project):
            memory_updated = str(project.get("updated_at") or "")
            persisted_updated = str((persisted_project or {}).get("updated_at") or "")
            if not isinstance(persisted_project, dict) or memory_updated >= persisted_updated:
                return project
        if isinstance(persisted_project, dict) and _local_comic_scope_allows_project(persisted_project):
            LOCAL_COMIC_PROJECTS[wanted_id] = persisted_project
            return persisted_project
    if _local_comic_scope_allows_project(project):
        return project
    persisted_project = _load_persisted_local_comic_project(wanted_id)
    if isinstance(persisted_project, dict) and _local_comic_scope_allows_project(persisted_project):
        LOCAL_COMIC_PROJECTS[wanted_id] = persisted_project
        return persisted_project
    return None


def _delete_local_comic_project_for_current_scope(project_id):
    try:
        wanted_id = int(project_id or 0)
    except Exception:
        return None, False, []
    project = _local_comic_project_for_current_scope(wanted_id)
    if not isinstance(project, dict):
        return None, False, []
    existed = LOCAL_COMIC_PROJECTS.pop(wanted_id, None) is not None
    removed_tasks = [
        task_id
        for task_id, task in list(LOCAL_COMIC_TASKS.items())
        if int(task.get("project_id") or 0) == wanted_id
        and _local_comic_scope_allows_task(task)
    ]
    for task_id in removed_tasks:
        LOCAL_COMIC_TASKS.pop(task_id, None)
        AI_COMIC_TASKS.pop(task_id, None)
    _save_local_comic_state()
    return project, existed, removed_tasks


def _delete_platform_comic_project_for_current_request(handler, project_id):
    if not _has_platform_proxy_authorization(handler):
        return {"attempted": False, "status": 0, "payload": {}, "deleted": False, "missing": False}
    status, payload = _fetch_platform_json_for_current_request(
        handler,
        f"/comic-drama/projects/{int(project_id)}",
        "DELETE",
    )
    return {
        "attempted": True,
        "status": int(status or 0),
        "payload": payload if isinstance(payload, dict) else {},
        "deleted": 200 <= int(status or 0) < 300,
        "missing": int(status or 0) == 404,
    }


def _load_persisted_local_comic_project(project_id):
    """Read one project from persisted state for editor detail responses."""
    try:
        wanted_id = int(project_id or 0)
    except Exception:
        return None
    if not wanted_id:
        return None
    path = os.path.abspath(str(_current_local_comic_state_path() or ""))
    if not path or not os.path.isfile(path):
        return None
    try:
        with open(path, "r", encoding="utf-8") as file:
            payload = json.load(file)
    except Exception as error:
        _json_log("local_comic_detail_state_load_failed", project_id=wanted_id, error=str(error))
        return None
    projects = payload.get("projects") if isinstance(payload, dict) else None
    if isinstance(projects, dict):
        project = projects.get(str(wanted_id))
        if project is None:
            project = projects.get(wanted_id)
    elif isinstance(projects, list):
        project = next(
            (item for item in projects if isinstance(item, dict) and int(item.get("id") or 0) == wanted_id),
            None,
        )
    else:
        project = None
    return copy.deepcopy(project) if isinstance(project, dict) else None


def _has_explicit_local_flow_comic_mode(project):
    if not isinstance(project, dict):
        return False
    config = project.get("config") if isinstance(project.get("config"), dict) else {}
    mode = str(
        project.get("source_mode")
        or project.get("sourceMode")
        or config.get("source_mode")
        or config.get("sourceMode")
        or ""
    ).strip()
    return mode in {"local_flow", "flowchart", "local"}


def _is_local_flow_comic_project(project):
    if not isinstance(project, dict):
        return False
    if _has_explicit_local_flow_comic_mode(project):
        return True
    created_at = str(project.get("created_at") or project.get("createdAt") or "")
    source_text = str(project.get("source_text") or project.get("sourceText") or "").strip()
    return bool(source_text and created_at >= "2026-07-13")


def _local_comic_scope_allows_task(task):
    current_scope = _sanitize_account_scope(_get_request_account_scope())
    if not current_scope:
        return True
    if not isinstance(task, dict):
        return False
    task_scope = _sanitize_account_scope(task.get("account_scope") or task.get("owner_scope") or task.get("storage_scope"))
    if task_scope:
        return task_scope == current_scope
    project_id = task.get("project_id")
    if project_id:
        return _local_comic_project_for_current_scope(project_id) is not None
    return current_scope in {"local", "dev"}


def _local_comic_task_scope_matches_current_project(task, wanted_project_id, project_scope_allowed):
    current_scope = _sanitize_account_scope(_get_request_account_scope())
    if not current_scope:
        return True
    if not isinstance(task, dict):
        return False
    task_scope = _sanitize_account_scope(task.get("account_scope") or task.get("owner_scope") or task.get("storage_scope"))
    if task_scope:
        return task_scope == current_scope
    try:
        task_project_id = int(task.get("project_id") or 0)
    except Exception:
        task_project_id = 0
    if task_project_id == int(wanted_project_id or 0):
        return bool(project_scope_allowed)
    return current_scope in {"local", "dev"}


def _local_comic_project_task_responses(project_id):
    try:
        wanted_project_id = int(project_id or 0)
    except Exception:
        wanted_project_id = 0
    project_scope_allowed = True
    if _sanitize_account_scope(_get_request_account_scope()) and wanted_project_id:
        project_scope_allowed = _local_comic_project_for_current_scope(wanted_project_id) is not None
    tasks_by_id = {}
    for source in (LOCAL_COMIC_TASKS, AI_COMIC_TASKS):
        for task_id, task in source.items():
            if not isinstance(task, dict):
                continue
            try:
                task_project_id = int(task.get("project_id") or 0)
            except Exception:
                task_project_id = 0
            if task_project_id != wanted_project_id:
                continue
            if not _local_comic_task_scope_matches_current_project(task, wanted_project_id, project_scope_allowed):
                continue
            tasks_by_id[str(task_id)] = task
    return [_ai_comic_task_response(task) for task in tasks_by_id.values()]


_AI_COMIC_PROJECT_REFRESH_TASK_TYPES = {"generate_image", "generate_video"}
_AI_COMIC_PROJECT_ASSET_TARGET_TYPES = {"character", "scene", "prop"}
_AI_COMIC_PROJECT_BACKGROUND_REFRESH_LIMIT = 1000


def _local_comic_project_has_active_ai_tasks(project_id):
    try:
        wanted_project_id = int(project_id or 0)
    except Exception:
        wanted_project_id = 0
    if not wanted_project_id:
        return False
    project_scope_allowed = True
    if _sanitize_account_scope(_get_request_account_scope()):
        project_scope_allowed = _local_comic_project_for_current_scope(wanted_project_id) is not None
    seen = set()
    for task_map in (LOCAL_COMIC_TASKS, AI_COMIC_TASKS):
        for task in list(task_map.values()):
            if not isinstance(task, dict):
                continue
            task_id = str(task.get("id") or task.get("task_id") or "")
            if task_id in seen:
                continue
            seen.add(task_id)
            try:
                task_project_id = int(task.get("project_id") or 0)
            except Exception:
                task_project_id = 0
            if task_project_id != wanted_project_id:
                continue
            if not _local_comic_task_scope_matches_current_project(task, wanted_project_id, project_scope_allowed):
                continue
            status = str(task.get("status") or task.get("state") or "").strip().lower()
            if status not in {"pending", "running", "processing", "submitted", "queued"}:
                continue
            task_type = str(task.get("task_type") or "").strip()
            target_type = str(task.get("target_type") or "").strip()
            if task_type in _AI_COMIC_PROJECT_REFRESH_TASK_TYPES or target_type in _AI_COMIC_PROJECT_ASSET_TARGET_TYPES:
                return True
    return False


def _refresh_ai_comic_project_media_tasks_async(project_id):
    try:
        wanted_project_id = int(project_id or 0)
    except Exception:
        wanted_project_id = 0
    if not wanted_project_id or not _local_comic_project_has_active_ai_tasks(wanted_project_id):
        return False
    agent_scope = _get_agent_runtime_scope()
    key = f"{agent_scope}:{wanted_project_id}" if agent_scope else str(wanted_project_id)
    with AI_COMIC_TASK_REFRESH_LOCK:
        if key in AI_COMIC_PROJECT_TASK_REFRESH_IN_FLIGHT:
            return False
        AI_COMIC_PROJECT_TASK_REFRESH_IN_FLIGHT.add(key)
    def _worker():
        if agent_scope:
            _set_request_account_scope(agent_scope)
            _activate_agent_comic_runtime(agent_scope)
        try:
            _refresh_pending_ai_comic_asset_tasks_for_project(
                wanted_project_id,
                limit=_AI_COMIC_PROJECT_BACKGROUND_REFRESH_LIMIT,
            )
            _refresh_ai_comic_tasks_for_project(
                wanted_project_id,
                only_frame_tasks=False,
                limit=_AI_COMIC_PROJECT_BACKGROUND_REFRESH_LIMIT,
                task_types=_AI_COMIC_PROJECT_REFRESH_TASK_TYPES,
            )
            _apply_completed_ai_comic_results_for_project(wanted_project_id)
        except Exception as error:
            _json_log("ai_comic_project_task_background_refresh_failed", project_id=wanted_project_id, error=repr(error))
        finally:
            with AI_COMIC_TASK_REFRESH_LOCK:
                AI_COMIC_PROJECT_TASK_REFRESH_IN_FLIGHT.discard(key)

    threading.Thread(target=_worker, daemon=True).start()
    return True


def _refresh_ai_comic_project_video_tasks_async(project_id):
    return _refresh_ai_comic_project_media_tasks_async(project_id)


def _refresh_ai_comic_project_tasks_for_response(project_id):
    refreshed = _apply_completed_ai_comic_results_for_project(project_id, task_types={"generate_video"})
    _refresh_ai_comic_project_media_tasks_async(project_id)
    return refreshed


def _sync_ai_comic_asset_task_completed_from_project_reference(task, item):
    if not isinstance(task, dict) or not isinstance(item, dict):
        return False
    result_url = str(task.get("result_url") or "").strip()
    if not result_url or result_url not in _local_comic_item_reference_urls(item):
        return False
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()
    task["status"] = "completed"
    task["state"] = "completed"
    task["progress_percent"] = 100
    task["current_step"] = "已完成"
    task["completed_at"] = task.get("completed_at") or now
    task["project_result_applied"] = True
    task["project_result_applied_at"] = task.get("project_result_applied_at") or now
    _save_local_comic_state()
    return True


def _refresh_pending_ai_comic_asset_tasks_for_project(project_id, limit=8):
    try:
        wanted_project_id = int(project_id or 0)
    except Exception:
        wanted_project_id = 0
    if not wanted_project_id:
        return 0
    project = LOCAL_COMIC_PROJECTS.get(wanted_project_id) or _local_comic_project_for_current_scope(wanted_project_id)
    refreshed = 0
    seen = set()
    active_statuses = {"pending", "running", "processing", "submitted", "queued"}
    for task_map in (LOCAL_COMIC_TASKS, AI_COMIC_TASKS):
        for task in list(task_map.values()):
            if refreshed >= int(limit or 0):
                return refreshed
            if not isinstance(task, dict):
                continue
            task_id = str(task.get("id") or task.get("task_id") or "")
            if task_id in seen:
                continue
            seen.add(task_id)
            try:
                task_project_id = int(task.get("project_id") or 0)
            except Exception:
                task_project_id = 0
            if task_project_id != wanted_project_id:
                continue
            target_type = str(task.get("target_type") or "")
            if target_type not in {"character", "scene", "prop"}:
                continue
            collection = {"character": "characters", "scene": "scenes", "prop": "props"}.get(target_type)
            item = _local_comic_find_by_id((project or {}).get(collection), task.get("target_id")) if collection else None
            if str(task.get("status") or task.get("state") or "").strip().lower() not in active_statuses:
                continue
            if not _local_comic_task_belongs_to_project_scope(task, wanted_project_id):
                continue
            if isinstance(item, dict) and _sync_ai_comic_asset_task_completed_from_project_reference(task, item):
                continue
            _refresh_ai_comic_task(task)
            refreshed += 1
    return refreshed


def _local_comic_task_belongs_to_project_scope(task, project_id):
    if not isinstance(task, dict):
        return False
    try:
        wanted_project_id = int(project_id or 0)
        task_project_id = int(task.get("project_id") or 0)
    except Exception:
        return False
    if not wanted_project_id or task_project_id != wanted_project_id:
        return False
    project = LOCAL_COMIC_PROJECTS.get(wanted_project_id)
    project_scope = _local_comic_project_owner_scope(project)
    task_scope = _sanitize_account_scope(task.get("account_scope") or task.get("owner_scope") or task.get("storage_scope"))
    if project_scope:
        return task_scope == project_scope
    return _local_comic_scope_allows_task(task)


def _local_comic_apply_scope_to_task(task, project_id=None):
    if not isinstance(task, dict):
        return task
    scope = _sanitize_account_scope(_get_request_account_scope())
    if not scope and project_id:
        project = LOCAL_COMIC_PROJECTS.get(int(project_id or 0)) if str(project_id or "").isdigit() else None
        scope = _local_comic_project_owner_scope(project)
    if scope:
        task["account_scope"] = scope
    return task


def _create_local_comic_project(handler):
    return _create_local_comic_project_from_payload(_read_json_body_object(handler))


_LOCAL_COMIC_NON_DIALOGUE_LABELS = {
    "画面",
    "画面描述",
    "画面说明",
    "景别",
    "角度",
    "音效",
    "运镜",
    "时长",
    "最终提示词",
    "镜头",
    "场景",
    "道具",
    "角色",
    "描述",
    "环境",
}


def _local_comic_extract_dialogue_text(text):
    source = str(text or "").strip()
    quoted = [m.strip() for m in re.findall(r"[“\"「『]([^”\"」』]{1,160})[”\"」』]", source) if str(m or "").strip()]
    if quoted:
        return " / ".join(quoted)
    colon_pattern = re.compile(
        r"(?:^|[\n。！？])\s*([\u4e00-\u9fa5A-Za-z0-9_]{1,12}(?:说|问|喊|低声说|说道|回答|旁白)?|旁白|[他她它我你])[:：]\s*([^。！？\n]{1,180})"
    )
    for speaker, body in colon_pattern.findall(source):
        label = re.sub(r"(说|问|喊|低声说|说道|回答)$", "", str(speaker or "").strip())
        dialogue = str(body or "").strip()
        if dialogue and label not in _LOCAL_COMIC_NON_DIALOGUE_LABELS:
            return dialogue
    return "无"


def _local_comic_extract_action_sound(text):
    source = str(text or "")
    sound_map = (
        (("雨", "雷", "风"), "环境风雨声"),
        (("脚步", "跑", "走"), "脚步声"),
        (("敲门", "开门", "关门"), "门声"),
        (("爆炸", "轰", "砰"), "爆炸冲击声"),
        (("撞", "摔", "碰", "碎"), "碰撞声"),
        (("电话", "手机", "铃"), "电话铃声"),
        (("枪", "射击"), "枪声"),
    )
    return "、".join(label for keywords, label in sound_map if any(keyword in source for keyword in keywords)) or "无"


def _local_comic_storyboard_audio_prompt(text):
    return {
        "action_sound": _local_comic_extract_action_sound(text),
        "dialogue": {
            "text": _local_comic_extract_dialogue_text(text),
            "dialogue_type": "对白",
            "emotion": "平静",
            "speed": "正常",
        },
    }


def _local_comic_clean_storyboard_text(value):
    text = re.sub(r"^[#*\-\s]+|[#*\-\s]+$", "", str(value or "").strip())
    return re.sub(r"\*+", "", text).strip()


def _local_comic_is_storyboard_metadata_text(value):
    text = _local_comic_clean_storyboard_text(value)
    if not text:
        return True
    metadata_re = re.compile(
        r"^(?:剧本标题|标题|类型|时长|主要人物|人物|剧情梗概|分镜要点|中文漫剧剧本|完)\s*(?:[:：]|$)",
        re.I,
    )
    return bool(metadata_re.match(text) or re.fullmatch(r"《[^》]{1,40}》", text))


def _local_comic_storyboards_look_like_metadata(storyboards):
    for item in storyboards or []:
        if not isinstance(item, dict):
            continue
        text = _first_non_empty(
            item.get("description"),
            item.get("image_prompt"),
            item.get("storyboard_image_prompt"),
            item.get("video_prompt"),
        )
        if not str(text or "").strip():
            continue
        return _local_comic_is_storyboard_metadata_text(text)
    return False


def _local_comic_first_storyboard(project):
    source_text = str((project or {}).get("source_text") or "").strip()
    description = ""
    for fragment in _split_comic_script_fragments(source_text):
        text = _local_comic_clean_storyboard_text(fragment)
        if len(text) >= 4 and not _local_comic_is_storyboard_metadata_text(text):
            description = text
            break
    if not description:
        description = source_text.splitlines()[0].strip() if source_text else "本地测试分镜"
    if len(description) > 120:
        description = description[:117] + "..."
    return {
        "id": int(project["id"]) * 1000 + 1,
        "sequence": 1,
        "description": description,
        "shot_type": "中景镜头",
        "camera_angle": "平视",
        "camera_movement": "静态镜头",
        "image_prompt": description,
        "storyboard_image_prompt": description,
        "video_prompt": description,
        "audio_prompt": _local_comic_storyboard_audio_prompt(description),
        "characters": [],
        "scene": None,
        "props": [],
        "status": "pending",
    }


def _local_comic_storyboard_from_description(project, index, description):
    text = str(description or "").strip() or "本地测试分镜"
    if len(text) > 180:
        text = text[:177] + "..."
    return {
        "id": int(project["id"]) * 1000 + int(index),
        "sequence": int(index),
        "description": text,
        "shot_type": "中景镜头",
        "camera_angle": "平视",
        "camera_movement": "静态镜头",
        "image_prompt": text,
        "storyboard_image_prompt": text,
        "video_prompt": text,
        "audio_prompt": _local_comic_storyboard_audio_prompt(text),
        "characters": [],
        "scene": None,
        "props": [],
        "status": "pending",
    }


def _local_comic_storyboards_from_source(project, limit=6):
    source_text = str((project or {}).get("source_text") or "").strip()
    fragments = _split_comic_script_fragments(source_text)
    candidates = []
    skip_re = re.compile(r"^(?:#+\s*)?(?:剧本标题|标题|类型|时长|主要人物|人物|场景|剧情梗概|分镜要点|中文漫剧剧本)\s*[:：]?", re.I)
    title_re = re.compile(r"^《[^》]{1,40}》$")
    role_re = re.compile(r"^(?:[-*]\s*)?[^：:（）()]{1,12}(?:[：:].*|[（(][^）)]*)?(?:岁|少年|少女|白领|父|母|学生|角色|表情|性格)")
    scene_only_re = re.compile(r"^(?:现代|古代|未来|室内|室外|深夜|白天|晚上|黄昏).{0,40}(?:客厅|浴室|房间|街道|场景|区域)[。.]?$")
    action_re = re.compile(r"[。！？!?，,]|镜头|画面|突然|出现|回头|发现|冲|跑|走|看|说|喊|捏碎|觉醒|直播|洗澡")
    for fragment in fragments:
        text = _local_comic_clean_storyboard_text(fragment)
        if (
            len(text) < 8
            or _local_comic_is_storyboard_metadata_text(text)
            or skip_re.match(text)
            or title_re.match(text)
            or role_re.match(text)
            or scene_only_re.match(text)
            or not action_re.search(text)
        ):
            continue
        candidates.append(text[:240])
        if len(candidates) >= int(limit or 6):
            break
    if not candidates:
        return [_local_comic_first_storyboard(project)]
    return [_local_comic_storyboard_from_description(project, index, text) for index, text in enumerate(candidates, start=1)]


def _local_comic_text_fingerprint(text):
    raw = str(text or "").strip().lower()
    chinese = "".join(re.findall(r"[\u4e00-\u9fff]+", raw))
    if len(chinese) == 1:
        grams = {chinese}
    else:
        grams = {chinese[i : i + 2] for i in range(max(0, len(chinese) - 1))}
    words = {word for word in re.findall(r"[a-z0-9_]{3,}", raw)}
    stopwords = {
        "画面", "镜头", "出现", "逐渐", "缓缓", "突然", "手中", "两人", "中的", "转为",
        "震惊", "眼神", "特写", "中景", "远景", "全景", "平视", "俯拍", "仰拍",
    }
    return (grams | words) - stopwords


def _local_comic_declared_character_names(text, max_items=8):
    names = []
    in_character_block = False
    heading_re = re.compile(r"^(?:#+\s*)?(?:剧本标题|标题|类型|时长|场景|剧情梗概|分镜要点|画面风格|记忆点)\s*[:：]?", re.I)
    for raw_line in str(text or "").replace("\r\n", "\n").replace("\r", "\n").splitlines():
        line = re.sub(r"[*#`]+", "", raw_line).strip()
        if not line:
            continue
        if re.search(r"(?:主要人物|人物|角色)\s*[:：]?", line):
            in_character_block = True
            line = re.sub(r"^.*?(?:主要人物|人物|角色)\s*[:：]?", "", line).strip()
        elif in_character_block and heading_re.match(line):
            break
        elif not in_character_block:
            continue
        candidates = [line]
        if "：" in line or ":" in line:
            candidates = [re.split(r"[:：]", line, 1)[0]]
        for part in re.split(r"[,，、/和与]+", "、".join(candidates)):
            name = _local_comic_clean_character_candidate(re.sub(r"^[-\d.\s]+", "", part))
            if _local_comic_is_plausible_character_name(name) and name not in names:
                names.append(name)
                if len(names) >= int(max_items or 8):
                    return names
    return names


def _local_comic_storyboards_match_source(source_text, storyboards):
    source = str(source_text or "").strip()
    if not source or not storyboards:
        return True
    board_text = "\n".join(
        " ".join(
            str(item.get(key) or "")
            for key in ("description", "image_prompt", "storyboard_image_prompt", "video_prompt")
        )
        for item in storyboards
        if isinstance(item, dict)
    )
    declared_names = _local_comic_declared_character_names(source, 8)
    if declared_names and not any(name in board_text for name in declared_names):
        return False
    source_fp = _local_comic_text_fingerprint(source)
    board_fp = _local_comic_text_fingerprint(board_text)
    if not source_fp or not board_fp:
        return True
    overlap = len(source_fp & board_fp)
    required_overlap = 3 if len(source) < 120 else 6
    return overlap >= required_overlap or (overlap >= 4 and overlap / max(1, min(len(source_fp), len(board_fp))) >= 0.08)


def _local_comic_analyze_script_with_timeout(source_text, model, project_id=0, project=None):
    if not _use_ai_api_provider():
        return {}
    billing_ctx = _charge_local_ai_model_call(
        "llm",
        model,
        {"source_text": source_text},
        project_id=project_id,
        description=f"云灵AI漫剧剧本分析：{model}",
    )
    try:
        timeout = max(1, int(os.environ.get("COMIC_ANALYZE_AI_TIMEOUT_SECONDS", "600") or "600"))
    except Exception:
        timeout = 600
    project = project if isinstance(project, dict) else {}
    config = project.get("config") if isinstance(project.get("config"), dict) else {}
    style_prompt = _local_comic_style_rule(project)
    visual_origin = _first_non_empty(config.get("visual_origin"), config.get("visualOrigin"))
    executor = concurrent.futures.ThreadPoolExecutor(max_workers=1)
    future = executor.submit(
        AI_API_SERVICE.analyze_comic_script,
        source_text,
        model=model,
        visual_origin=visual_origin,
        style_prompt=style_prompt,
    )
    try:
        result = future.result(timeout=timeout)
        _finalize_local_ai_model_call(billing_ctx, result, description=f"云灵AI漫剧剧本分析：{model}")
        return result if isinstance(result, dict) else {}
    except concurrent.futures.TimeoutError:
        future.cancel()
        _refund_canvas_model_call(billing_ctx, f"云灵AI漫剧剧本分析超时退款：{model}")
        _json_log("local_comic_analysis_ai_timeout_fallback", timeout_seconds=timeout)
        return {}
    except Exception:
        _refund_canvas_model_call(billing_ctx, f"云灵AI漫剧剧本分析失败退款：{model}")
        raise
    finally:
        executor.shutdown(wait=False, cancel_futures=True)


