def _local_comic_asset_next_id(project, collection):
    items = project.get(collection) if isinstance(project.get(collection), list) else []
    max_id = 0
    def use_id(value):
        nonlocal max_id
        try:
            max_id = max(max_id, int(value))
        except Exception:
            pass

    for item in items:
        if not isinstance(item, dict):
            continue
        use_id(item.get("id"))
    for storyboard in project.get("storyboards") or []:
        if not isinstance(storyboard, dict):
            continue
        if collection == "characters":
            for item in _local_comic_id_list(storyboard.get("character_ids") or storyboard.get("characterIds")):
                use_id(item)
            for item in storyboard.get("characters") or []:
                if isinstance(item, dict):
                    use_id(item.get("id"))
        elif collection == "scenes":
            use_id(storyboard.get("scene_id") if storyboard.get("scene_id") is not None else storyboard.get("sceneId"))
            scene = storyboard.get("scene")
            if isinstance(scene, dict):
                use_id(scene.get("id"))
        elif collection == "props":
            for item in _local_comic_id_list(storyboard.get("prop_ids") or storyboard.get("propIds")):
                use_id(item)
            for item in storyboard.get("props") or []:
                if isinstance(item, dict):
                    use_id(item.get("id"))
    return max_id + 1


def _local_comic_asset_find(project, collection, asset_id):
    wanted = str(asset_id)
    for item in project.get(collection) or []:
        if str(item.get("id")) == wanted:
            return item
    return None


def _local_comic_asset_payload(collection, payload, asset_id):
    meta = LOCAL_COMIC_ASSET_COLLECTIONS[collection]
    payload = payload if isinstance(payload, dict) else {}
    reference_images = payload.get("reference_images")
    if not isinstance(reference_images, list):
        reference_images = []
    reference_images = [str(item).strip() for item in reference_images if str(item or "").strip()]
    reference_image = _first_non_empty(payload.get("reference_image"), reference_images[0] if reference_images else "")
    item = {
        "id": int(asset_id),
        "type": meta["type"],
        "name": _first_non_empty(payload.get("name"), meta["default_name"]),
        "description": str(payload.get("description") or ""),
        "reference_image": reference_image,
        "reference_images": reference_images or ([reference_image] if reference_image else []),
        "base_prompt": str(payload.get("base_prompt") or payload.get("prompt") or ""),
        "status": str(payload.get("status") or "pending"),
    }
    source_asset_id = _first_non_empty(payload.get("source_asset_id"), payload.get("sourceAssetId"))
    if source_asset_id:
        item["source_asset_id"] = source_asset_id
        item["sourceAssetId"] = source_asset_id
    for key in (
        "tags",
        "audio_url",
        "audioUrl",
        "voice",
        "voice_name",
        "voiceName",
        "voice_model",
        "voiceModel",
        "voice_description",
        "voiceDescription",
        "other_views",
        "otherViews",
    ):
        if key in payload:
            item[key] = payload.get(key)
    if collection == "characters":
        item["gender"] = str(payload.get("gender") or "unknown")
        if isinstance(payload.get("age"), (int, float, str)):
            item["age"] = payload.get("age")
        item["appearance"] = payload.get("appearance") if isinstance(payload.get("appearance"), dict) else {}
        if isinstance(payload.get("views"), dict):
            item["views"] = payload.get("views")
    elif collection == "scenes":
        if payload.get("time_of_day"):
            item["time_of_day"] = str(payload.get("time_of_day"))
        if payload.get("atmosphere"):
            item["atmosphere"] = str(payload.get("atmosphere"))
    elif collection == "props":
        if payload.get("category"):
            item["category"] = str(payload.get("category"))
    return item


