def _local_comic_clean_character_candidate(name):
    text = re.sub(r"[（(][^）)]*[）)]", "", str(name or ""))
    text = text.strip(" \t\r\n，。！？；、：:“”\"'（）()[]【】")
    if "·" in text:
        first_name = text.split("·", 1)[0].strip(" \t\r\n，。！？；、：:“”\"'（）()[]【】")
        if first_name:
            text = first_name
    changed = True
    while changed and text:
        changed = False
        for suffix in _LOCAL_COMIC_CHARACTER_TRAILING_MODIFIERS:
            if text.endswith(suffix) and len(text) > len(suffix):
                text = text[: -len(suffix)].strip("，。！？；、 的地得")
                changed = True
    return text


def _local_comic_is_plausible_character_name(name):
    text = _local_comic_clean_character_candidate(name)
    if not text or len(text) < 2:
        return False
    english_name = bool(re.fullmatch(r"[A-Z][a-z][A-Za-z'-]{0,23}(?:\s+[A-Z][a-z][A-Za-z'-]{0,23}){0,2}", text))
    if not english_name and len(text) > 5:
        return False
    if text in _LOCAL_COMIC_CHARACTER_EXACT_NOISE_NAMES:
        return False
    blocked_terms = set(_LOCAL_COMIC_SCENE_TERMS) | set(_LOCAL_COMIC_PROP_TERMS)
    if text in blocked_terms or any(term in text for term in blocked_terms):
        return False
    if any(term in text for term in _LOCAL_COMIC_CHARACTER_NOISE_TERMS):
        return False
    if any(token in text for token in _LOCAL_COMIC_CHARACTER_BAD_PARTICLES):
        return False
    if re.search(r"(声|音|镜头|画面|场景|道具|字幕|手机|钥匙|信封|照片|门口|Kitchen|Door|Window|Room|Street|Scene|Prop)$", text):
        return False
    if english_name:
        return True
    if re.search(r"(淡|冷|热|白|黑|湿|亮|暗|近|远|里|外|前|后|上|下|左|右)$", text):
        return False
    if re.match(r"^(阿|小|老)[一-鿿]{1,3}$", text):
        return True
    if re.match(r"^(欧阳|司马|诸葛|上官|东方|南宫|慕容|令狐|皇甫|尉迟|公孙)[一-鿿]{1,2}$", text):
        return True
    if re.search(r"(哥|姐|爸|妈|叔|姨|爷|奶|师|同学|先生|小姐|白领|群演)$", text):
        return True
    return bool(re.match(r"^[一-鿿]{2,3}$", text))


def _local_comic_is_manual_reference_character_asset(item):
    if not isinstance(item, dict):
        return False
    source_asset_id = _first_non_empty(item.get("source_asset_id"), item.get("sourceAssetId"))
    if source_asset_id in (None, ""):
        return False
    reference_images = item.get("reference_images") or item.get("referenceImages") or []
    if not isinstance(reference_images, list):
        reference_images = []
    return bool(
        _first_non_empty(item.get("reference_image"), item.get("referenceImage"))
        or any(str(url or "").strip() for url in reference_images)
    )


def _local_comic_filter_valid_character_assets(characters):
    if not isinstance(characters, list):
        return []
    return [
        item
        for item in characters
        if isinstance(item, dict) and (
            _local_comic_is_plausible_character_name(item.get("name"))
            or _local_comic_is_manual_reference_character_asset(item)
        )
    ]


def _local_comic_prune_invalid_character_assets(project):
    if not isinstance(project, dict):
        return 0
    characters = project.get("characters")
    if not isinstance(characters, list):
        return 0
    valid = []
    removed_ids = set()
    removed_names = set()
    for item in characters:
        if isinstance(item, dict) and (
            _local_comic_is_plausible_character_name(item.get("name"))
            or _local_comic_is_manual_reference_character_asset(item)
        ):
            valid.append(item)
            continue
        if isinstance(item, dict):
            item_id = item.get("id")
            name = _local_comic_asset_name(item)
            if item_id is not None and str(item_id).strip():
                removed_ids.add(str(item_id))
            if name:
                removed_names.add(name)
    removed_count = len(characters) - len(valid)
    if not removed_count:
        return 0
    project["characters"] = valid

    def keep_character_ref(value):
        if isinstance(value, dict):
            item_id = value.get("id")
            name = _local_comic_asset_name(value)
            if item_id is not None and str(item_id) in removed_ids:
                return False
            if name and name in removed_names:
                return False
            return True
        text = str(value or "").strip()
        return text and text not in removed_ids and text not in removed_names

    for storyboard in project.get("storyboards") or []:
        if not isinstance(storyboard, dict):
            continue
        if isinstance(storyboard.get("characters"), list):
            storyboard["characters"] = [item for item in storyboard.get("characters") or [] if keep_character_ref(item)]
        for key in ("character_ids", "characterIds"):
            if isinstance(storyboard.get(key), list):
                storyboard[key] = [item for item in storyboard.get(key) or [] if keep_character_ref(item)]
    return removed_count


_LOCAL_COMIC_ENGLISH_NAME_RE = r"[A-Z][a-z][A-Za-z'-]{0,23}(?:\s+[A-Z][a-z][A-Za-z'-]{0,23}){0,2}"
_LOCAL_COMIC_ENGLISH_NAME_ACTION_RE = re.compile(
    rf"\b({_LOCAL_COMIC_ENGLISH_NAME_RE})(?=\s*(?:[:：]|说|问|喊|叫|哭|笑|沉默|带着|推门|走进|进入|走|跑|看|注视|拿|握|站|坐|转身|缓缓|慢慢|突然|猛地|低声|回头|"
    rf"entered|enters|entering|walked|walks|walking|ran|runs|running|looked|looks|looking|stared|stares|staring|held|holds|holding|carried|carries|carrying|said|says|asked|asks|turned|turns|turning|stood|stands|standing|sat|sits|sitting))"
)


def _local_comic_extract_english_character_candidates(text, max_items=8):
    found = []
    for match in _LOCAL_COMIC_ENGLISH_NAME_ACTION_RE.finditer(str(text or "")):
        name = _local_comic_clean_character_candidate(match.group(1))
        if _local_comic_is_plausible_character_name(name) and name not in found:
            found.append(name)
            if len(found) >= int(max_items or 8):
                break
    return found

def _local_comic_should_skip_analysis_asset(collection, name):
    text = str(name or "").strip()
    if not text:
        return True
    noise = ("BGM", "bgm", "音效", "配乐", "字幕", "花字", "旁白", "对白", "黑屏", "收尾", "标题")
    if any(token in text for token in noise):
        return True
    if collection == "characters" and not _local_comic_is_plausible_character_name(text):
        return True
    if collection == "props" and re.search(r"(音|声|乐|字幕|花字|文案|标题)", text):
        return True
    if collection == "scenes" and re.search(r"(黑屏|字幕|标题|收尾)", text):
        return True
    return False


def _merge_local_comic_analysis_assets(project, collection, raw_items):
    if not isinstance(raw_items, list) or not raw_items:
        return
    items = project.setdefault(collection, [])
    by_name = {_local_comic_asset_name(item): item for item in items if _local_comic_asset_name(item)}
    for raw in raw_items:
        payload = raw if isinstance(raw, dict) else {"name": raw}
        name = _local_comic_asset_name(payload)
        if _local_comic_should_skip_analysis_asset(collection, name):
            continue
        existing = by_name.get(name)
        if existing:
            merged = _local_comic_asset_payload(collection, {**existing, **payload}, existing.get("id"))
            for field in LOCAL_COMIC_ASSET_MEDIA_FIELDS:
                if existing.get(field):
                    merged[field] = existing.get(field)
            existing.clear()
            existing.update(merged)
            continue
        item = _local_comic_asset_payload(collection, payload, _local_comic_asset_next_id(project, collection))
        items.append(item)
        by_name[name] = item


def _local_comic_asset_lookup(project, collection):
    return {_local_comic_asset_name(item): item for item in (project.get(collection) or []) if _local_comic_asset_name(item)}


def _local_comic_storyboard_with_asset_refs(project, storyboard):
    project = _local_comic_project_with_valid_character_refs(project)
    item = dict(storyboard if isinstance(storyboard, dict) else {})
    characters = _local_comic_asset_lookup(project, "characters")
    scenes = _local_comic_asset_lookup(project, "scenes")
    props = _local_comic_asset_lookup(project, "props")

    def resolve_many(values, lookup):
        values = values if isinstance(values, list) else ([values] if values else [])
        resolved = []
        seen_ids = set()
        for value in values:
            asset = None
            if isinstance(value, dict):
                asset = _local_comic_find_by_id(lookup.values(), value.get("id"))
                if asset is None:
                    name = _local_comic_asset_name(value)
                    asset = lookup.get(name) if name else None
            else:
                raw = str(value or "").strip()
                asset = _local_comic_find_by_id(lookup.values(), raw) or (lookup.get(raw) if raw else None)
            if not isinstance(asset, dict):
                continue
            asset_id = str(asset.get("id") or _local_comic_asset_name(asset))
            if asset_id in seen_ids:
                continue
            seen_ids.add(asset_id)
            resolved.append(asset)
        return resolved

    def storyboard_text():
        return "\n".join(
            str(item.get(key) or "")
            for key in ("description", "image_prompt", "storyboard_image_prompt", "action_grid_prompt", "video_prompt")
            if str(item.get(key) or "").strip()
        )

    def infer_assets_from_text(collection, max_items=None, longest_first=True):
        text = storyboard_text()
        if not text:
            return []
        assets = [asset for asset in (project.get(collection) or []) if isinstance(asset, dict)]
        matches = []
        seen_ids = set()
        for asset in (sorted(assets, key=lambda value: len(_local_comic_asset_name(value)), reverse=True) if longest_first else assets):
            name = _local_comic_asset_name(asset)
            if not name or name not in text:
                continue
            asset_id = str(asset.get("id") or name)
            if asset_id in seen_ids:
                continue
            seen_ids.add(asset_id)
            matches.append(asset)
            if max_items and len(matches) >= max_items:
                break
        return matches

    def infer_characters_from_text():
        inferred = []
        seen = set()
        for asset in infer_assets_from_text("characters", longest_first=False):
            name = _local_comic_asset_name(asset)
            if not _local_comic_is_plausible_character_name(name):
                continue
            asset_id = str(asset.get("id") or name)
            if asset_id in seen:
                continue
            seen.add(asset_id)
            inferred.append(asset)
        return inferred

    def infer_scene_from_text():
        matches = infer_assets_from_text("scenes", 1)
        if matches:
            return matches[0]
        scene_assets = [asset for asset in (project.get("scenes") or []) if isinstance(asset, dict)]
        return scene_assets[0] if len(scene_assets) == 1 else None

    scene = item.get("scene")
    scene_name = _local_comic_asset_name(scene) if isinstance(scene, dict) else str(scene or "").strip()
    item["characters"] = resolve_many(item.get("characters"), characters)
    if not item["characters"]:
        item["characters"] = infer_characters_from_text()
    if item["characters"]:
        character_ids = [str(asset.get("id")) for asset in item["characters"] if asset.get("id") is not None]
        item["character_ids"] = character_ids
        item["characterIds"] = character_ids
    item["props"] = resolve_many(item.get("props"), props)
    if not item["props"]:
        item["props"] = infer_assets_from_text("props")
    if item["props"]:
        prop_ids = [str(asset.get("id")) for asset in item["props"] if asset.get("id") is not None]
        item["prop_ids"] = prop_ids
        item["propIds"] = prop_ids
    item["scene"] = scenes.get(scene_name) if scene_name and scenes.get(scene_name) else (scene if isinstance(scene, dict) else None)
    if item["scene"] is None:
        item["scene"] = infer_scene_from_text()
    if isinstance(item.get("scene"), dict) and item["scene"].get("id") is not None:
        scene_id = str(item["scene"].get("id"))
        item["scene_id"] = scene_id
        item["sceneId"] = scene_id
    return item


