        if method in {"PUT", "PATCH"}:
            payload = _read_json_body_object(handler)
            updated = _local_comic_asset_payload(collection, {**item, **payload}, item.get("id"))
            items = project.get(collection) or []
            project[collection] = [updated if str(existing.get("id")) == str(asset_id) else existing for existing in items]
            project["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
            _save_local_comic_state_deferred()
            _send_json_with_headers(handler, 200, {"data": _comic_display_media_payload(updated), "localDev": True})
            return True
        if method == "DELETE":
            project[collection] = [existing for existing in (project.get(collection) or []) if str(existing.get("id")) != str(asset_id)]
            _clear_local_comic_asset_refs(project, collection, asset_id)
            project["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
            _save_local_comic_state_deferred()
            _send_json_with_headers(handler, 200, {"success": True, "localDev": True})
