_AGENT_ORCHESTRATION_POLL_INTERVAL = 1   # seconds
_AGENT_ORCHESTRATION_STAGE_TIMEOUT = 600  # 10 min per stage
_AGENT_ORCHESTRATION_TOTAL_TIMEOUT = 1800  # 30 min total
_AGENT_ORCHESTRATION_SUBMIT_WORKERS = 8   # parallel task-submit workers


def _agent_task_group_cancel_requested(task_group):
    if not isinstance(task_group, dict):
        return False
    state = str(task_group.get("state") or task_group.get("status") or "").strip().lower()
    return bool(task_group.get("agent_cancel_requested")) or state in {"cancelled", "canceled"}


def _agent_mark_task_group_cancelled(task_group, message="已取消生成"):
    if not isinstance(task_group, dict):
        return
    task_group["agent_cancel_requested"] = True
    task_group["status"] = "cancelled"
    task_group["state"] = "cancelled"
    task_group["current_step"] = str(message or "已取消生成")
    task_group["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()


def _agent_global_reference_urls(project, config=None):
    return _local_comic_project_global_reference_images(project, config)


def _agent_global_reference_usage(project, config=None):
    project = project if isinstance(project, dict) else {}
    config = config if isinstance(config, dict) else {}
    project_config = project.get("config") if isinstance(project.get("config"), dict) else {}
    session = project.get("agent_session") if isinstance(project.get("agent_session"), dict) else {}
    for source in (config, project_config, session):
        reference_assets = source.get("reference_assets")
        if not isinstance(reference_assets, list):
            reference_assets = source.get("referenceAssets")
        for asset in reference_assets or []:
            if not isinstance(asset, dict):
                continue
            kind = str(asset.get("kind") or "")
            usage = str(asset.get("usage") or "").lower()
            if kind == "scene_images" or usage in {"background", "scene", "environment"}:
                return "background"
            if kind == "character_images" or usage == "character":
                return "character"
            if kind == "prop_images" or usage == "prop":
                return "prop"
    return ""


def _build_asset_submit_kwargs(project, single_type, target_id, model, aspect_ratio):
    item_prompt, item_refs = _local_comic_asset_request_context(project, single_type, target_id)
    params = _merge_reference_urls_into_params({}, item_refs)
    reference_usage = _agent_global_reference_usage(project)
    if reference_usage:
        params["_reference_usage"] = reference_usage
    collection = {"character": "characters", "scene": "scenes", "prop": "props"}.get(single_type)
    item = _local_comic_find_by_id(project.get(collection), target_id) if collection and isinstance(project, dict) else None
    params = _merge_comic_negative_prompt(params, single_type, item)
    params = _ai_image_params_with_size(params, {"size": aspect_ratio}, single_type)
    prompt = f"生成{single_type}参考图 #{target_id}"
    prompt = _compose_local_comic_asset_prompt(project, single_type, target_id, prompt)
    prompt, params = _ai_comic_strengthen_reference_request(model, prompt, params)
    return dict(
        model=model,
        prompt=prompt,
        params=params,
        count=1,
        project_id=int(project.get("id") or 0),
        task_type=f"generate_{single_type}_views" if single_type == "character" else f"generate_{single_type}_image",
        task_name=f"Agent 生成{single_type} #{target_id}",
        target_id=target_id,
        target_type=single_type,
    )


def _build_storyboard_image_submit_kwargs(project, storyboard, model, aspect_ratio, config=None):
    config = config if isinstance(config, dict) else {}
    target_id = storyboard.get("id")
    prompt = _first_non_empty(_local_comic_storyboard_prompt(storyboard, "image"), f"生成分镜图 #{target_id}")
    frame_prompt_source = _comic_storyboard_frame_prompt_source(config, storyboard, prompt)
    prompt = _compose_local_comic_storyboard_prompt(project, storyboard, prompt, "image")
    character_refs, character_names = _local_comic_storyboard_character_refs_for_prompt(project, storyboard, prompt)
    all_refs = _dedupe_urls([*_agent_global_reference_urls(project, config), *_local_comic_storyboard_reference_context(project, storyboard)])
    params = _merge_reference_urls_into_params({}, [*all_refs, *character_refs])
    typed_refs = _local_comic_storyboard_typed_reference_context(project, storyboard)
    params = _apply_strict_storyboard_references_to_params(params, typed_refs)
    reference_usage = _agent_global_reference_usage(project, config)
    if reference_usage:
        params["_reference_usage"] = reference_usage
    prompt = _with_character_binding_prompt(prompt, character_names)
    binding_prompt = _local_comic_storyboard_reference_binding_prompt(project, storyboard)
    if binding_prompt:
        prompt = f"{binding_prompt}；{prompt}"
    params = _ai_image_params_with_size(params, {"size": aspect_ratio}, "storyboard")
    prompt, params = _ai_comic_strengthen_reference_request(model, prompt, params)
    base_kwargs = dict(
        model=model,
        prompt=prompt,
        params=params,
        count=1,
        project_id=int(project.get("id") or 0),
        task_type="generate_image",
        task_name=f"Agent 生成分镜图 #{target_id}",
        target_id=target_id,
        target_type="storyboard",
    )
    base_kwargs["_frame_prompt_source"] = frame_prompt_source
    workflow_mode = _comic_storyboard_workflow_mode(project, config)
    base_kwargs["params"]["_strict_typed_reference_bundle"] = typed_refs
    return _expand_comic_storyboard_image_submit_kwargs(base_kwargs, workflow_mode, config, prompt)


_VIDEO_ASPECT_PRESETS = (
    ("21:9", 21 / 9),
    ("16:9", 16 / 9),
    ("3:2", 3 / 2),
    ("4:3", 4 / 3),
    ("1:1", 1.0),
    ("3:4", 3 / 4),
    ("2:3", 2 / 3),
    ("9:16", 9 / 16),
)


def _probe_image_dimensions(url):
    """Best-effort (w, h) probe via stdlib for PNG / JPEG / WebP. Returns (0, 0) on failure."""
    try:
        with urllib.request.urlopen(url, timeout=8) as resp:
            head = resp.read(64 * 1024)
    except Exception:
        return 0, 0
    if not head:
        return 0, 0
    # PNG
    if head[:8] == b"\x89PNG\r\n\x1a\n" and head[12:16] == b"IHDR" and len(head) >= 24:
        try:
            w, h = struct.unpack(">II", head[16:24])
            return int(w), int(h)
        except struct.error:
            pass
    # JPEG: scan SOFn markers
    if head[:2] == b"\xff\xd8":
        i = 2
        n = len(head)
        while i < n - 9:
            if head[i] != 0xFF:
                i += 1
                continue
            marker = head[i + 1]
            if marker in (0xD8, 0xD9):
                i += 2
                continue
            try:
                seg_len = struct.unpack(">H", head[i + 2:i + 4])[0]
            except struct.error:
                break
            if 0xC0 <= marker <= 0xCF and marker not in (0xC4, 0xC8, 0xCC):
                if i + 9 <= n:
                    h_px, w_px = struct.unpack(">HH", head[i + 5:i + 9])
                    return int(w_px), int(h_px)
                break
            i += 2 + seg_len
    # WebP
    if head[:4] == b"RIFF" and head[8:12] == b"WEBP" and len(head) >= 30:
        chunk = head[12:16]
        try:
            if chunk == b"VP8 " and len(head) >= 30:
                w = struct.unpack("<H", head[26:28])[0] & 0x3FFF
                h = struct.unpack("<H", head[28:30])[0] & 0x3FFF
                return int(w), int(h)
            if chunk == b"VP8L" and len(head) >= 25:
                b0, b1, b2, b3 = head[21], head[22], head[23], head[24]
                w = ((b1 & 0x3F) << 8 | b0) + 1
                h = ((b3 & 0x0F) << 10 | b2 << 2 | (b1 & 0xC0) >> 6) + 1
                return int(w), int(h)
            if chunk == b"VP8X" and len(head) >= 30:
                w = (head[24] | head[25] << 8 | head[26] << 16) + 1
                h = (head[27] | head[28] << 8 | head[29] << 16) + 1
                return int(w), int(h)
        except (struct.error, IndexError):
            pass
    return 0, 0


def _snap_to_video_aspect(width, height, fallback=""):
    """Snap (w, h) to the closest preset label the video API understands; fallback when probe fails."""
    if width and height:
        target = width / height
        label, _ = min(_VIDEO_ASPECT_PRESETS, key=lambda kv: abs(kv[1] - target))
        return label
    return str(fallback or "").strip() or "16:9"


def _build_storyboard_video_submit_kwargs(project, storyboard, model, workflow_mode, aspect_ratio="", config=None):
    target_id = storyboard.get("id")
    workflow_mode = str(workflow_mode or "").strip()
    if workflow_mode == "multiframe":
        model_error = _comic_multiframe_video_model_error(model)
        if model_error:
            _json_log("comic_storyboard_video_submit_rejected", provider="agent", model=model, storyboard_id=target_id, workflow_mode=workflow_mode, reason=model_error)
            return None
    if workflow_mode == "keyframes":
        model_error = _comic_keyframes_video_model_error(model)
        if model_error:
            _json_log("comic_storyboard_video_submit_rejected", provider="agent", model=model, storyboard_id=target_id, workflow_mode=workflow_mode, reason=model_error)
            return None
    action_frames = _dedupe_urls(storyboard.get("action_frame_urls") or storyboard.get("actionFrameUrls") or [])
    if workflow_mode == "multiframe":
        if len(action_frames) < 7:
            return None
        first_frame = action_frames[0]
    else:
        first_frame = _first_non_empty(
            storyboard.get("start_frame_url") if workflow_mode == "keyframes" else "",
            storyboard.get("image_url"),
            storyboard.get("imageUrl"),
            storyboard.get("storyboard_image"),
        )
    first_frame = _first_non_empty(
        first_frame,
    )
    if not first_frame:
        return None
    prompt = _first_non_empty(_local_comic_storyboard_prompt(storyboard, "video", workflow_mode), f"生成分镜视频 #{target_id}")
    prompt = _compose_local_comic_storyboard_prompt(project, storyboard, prompt, "video")
    project_config = project.get("config") if isinstance(project.get("config"), dict) else {}
    video_template = {}
    if isinstance(config, dict) and isinstance(config.get("video_template"), dict):
        video_template = config.get("video_template")
    elif isinstance(config, dict) and isinstance(config.get("videoTemplate"), dict):
        video_template = config.get("videoTemplate")
    elif isinstance(project_config.get("agentVideoTemplate"), dict):
        video_template = project_config.get("agentVideoTemplate")
    video_template = _normalize_agent_video_template({"video_template": video_template}) if video_template else {}
    template_video_url = _agent_video_template_url(video_template)
    template_instruction = _agent_video_template_instruction(video_template) if template_video_url else ""
    if template_instruction:
        prompt = _with_agent_instruction_prompt(prompt, template_instruction)
    prompt = _lock_storyboard_video_prompt_to_current_shot(project, storyboard, prompt)
    global_refs = _agent_global_reference_urls(project, config)
    if workflow_mode == "multiframe":
        typed_refs = _local_comic_storyboard_typed_reference_context(project, storyboard)
        params = _merge_reference_urls_into_params({}, [*action_frames[:7], *(typed_refs.get("all") or [])])
        params = _apply_strict_storyboard_references_to_params(params, typed_refs)
        params["action_flow_images"] = action_frames[:7]
        if global_refs:
            params = _merge_reference_urls_into_params(params, global_refs)
    else:
        typed_refs = _local_comic_storyboard_typed_reference_context(project, storyboard)
        params = _merge_reference_urls_into_params({}, _dedupe_urls([first_frame, *global_refs, *(typed_refs.get("all") or [])]))
        params = _apply_strict_storyboard_references_to_params(params, typed_refs)
    if template_video_url:
        params = _merge_reference_video_urls_into_params(params, [template_video_url])
        params["agent_video_template"] = video_template
    params["first_frame"] = first_frame
    params["firstFrameUrl"] = first_frame
    params = _apply_comic_storyboard_video_aspect_ratio(params, {"aspect_ratio": aspect_ratio}, storyboard, project)
    params = _comic_multiframe_video_params(workflow_mode, model, params)
    # 用首帧的真实像素比，对不上时回退到项目意图比例，避免人物被拉伸
    if not _ark_should_route(model):
        probed_w, probed_h = _probe_image_dimensions(first_frame)
        ratio = _snap_to_video_aspect(probed_w, probed_h, aspect_ratio)
        if ratio:
            params["aspect_ratio"] = ratio
            params["aspectRatio"] = ratio
            params["ratio"] = ratio
    return dict(
        model=model,
        prompt=prompt,
        params=params,
        count=1,
        project_id=int(project.get("id") or 0),
        task_type="generate_video",
        task_name=f"Agent 生成分镜视频 #{target_id}",
        target_id=target_id,
        target_type="storyboard",
    )


def _parallel_submit(submit_kwargs_list, target_type):
    """Submit tasks in parallel via thread pool. Returns list of task dicts (failures logged & skipped)."""
    submit_kwargs_list = [k for k in submit_kwargs_list if k]
    if not submit_kwargs_list:
        return []
    tasks = []
    max_workers = min(_AGENT_ORCHESTRATION_SUBMIT_WORKERS, len(submit_kwargs_list))
    agent_scope = _get_agent_runtime_scope()

    def submit_task(kwargs):
        if not agent_scope:
            return _submit_ai_comic_media_task(**kwargs)
        with _agent_comic_runtime_context(agent_scope):
            return _submit_ai_comic_media_task(**kwargs)

    with concurrent.futures.ThreadPoolExecutor(max_workers=max_workers) as executor:
        future_map = {}
        for kw in submit_kwargs_list:
            submit_kwargs = dict(kw)
            metadata = submit_kwargs.pop("_task_metadata", {}) if isinstance(submit_kwargs.get("_task_metadata"), dict) else {}
            future_map[executor.submit(submit_task, submit_kwargs)] = (kw, metadata)
        for future in concurrent.futures.as_completed(future_map):
            kw, metadata = future_map[future]
            try:
                task = future.result()
                if metadata:
                    _apply_comic_frame_task_metadata(task, metadata.get("workflow_mode"), metadata.get("frame_index"))
                tasks.append(task)
            except Exception as error:
                _json_log(
                    "agent_stage_submit_failed",
                    target_type=target_type,
                    target_id=kw.get("target_id"),
                    error=AiApiService.sanitize_error(repr(error)),
                )
    return tasks


def _agent_modify_priority_instruction(config):
    config = config if isinstance(config, dict) else {}
    if not bool(config.get("agent_modify_priority")):
        return ""
    return str(config.get("workflow_instruction") or config.get("idea") or "").strip()


def _apply_agent_modify_priority_to_kwargs(kwargs, config):
    if not isinstance(kwargs, dict):
        return kwargs
    instruction = _agent_modify_priority_instruction(config)
    if instruction:
        kwargs = dict(kwargs)
        kwargs["prompt"] = _with_agent_instruction_prompt(kwargs.get("prompt"), instruction)
    return kwargs


def _submit_stage_batch(project, target_type, config, target_ids=None):
    """Submit a batch of media tasks for a given stage. Returns list of task dicts."""
    project_config = project.get("config") if isinstance(project.get("config"), dict) else {}
    aspect_ratio = project_config.get("aspectRatio") or project_config.get("aspect_ratio") or config.get("size") or "16:9"

    if target_type in ("characters", "scenes", "props"):
        if target_type == "characters":
            _local_comic_prune_invalid_character_assets(project)
        model = _comic_media_model_for_project(project, config, "image")
        single_type = {"characters": "character", "scenes": "scene", "props": "prop"}[target_type]
        if target_ids is None:
            target_ids = [item.get("id") for item in project.get(target_type) or [] if isinstance(item, dict)]
        elif target_type == "characters":
            valid_character_ids = {str(item.get("id")) for item in project.get("characters") or [] if isinstance(item, dict)}
            target_ids = [target_id for target_id in target_ids if str(target_id) in valid_character_ids]
        submit_kwargs = [
            _apply_agent_modify_priority_to_kwargs(
                _build_asset_submit_kwargs(project, single_type, target_id, model, aspect_ratio),
                config,
            )
            for target_id in target_ids
        ]
        return _parallel_submit(submit_kwargs, target_type)

    elif target_type == "storyboard_images":
        model = _comic_media_model_for_project(project, config, "image")
        submit_kwargs = [
            _apply_agent_modify_priority_to_kwargs(kwargs, config)
            for sb in (project.get("storyboards") or [])
            if isinstance(sb, dict)
            for kwargs in _build_storyboard_image_submit_kwargs(project, sb, model, aspect_ratio, config)
        ]
        return _parallel_submit(submit_kwargs, target_type)

    elif target_type == "storyboard_videos":
        model = _comic_media_model_for_project(project, config, "video")
        workflow_mode = _comic_storyboard_workflow_mode(project, config)
        submit_kwargs = []
        for sb in (project.get("storyboards") or []):
            if not isinstance(sb, dict):
                continue
            kw = _build_storyboard_video_submit_kwargs(project, sb, model, workflow_mode, aspect_ratio, config)
            if kw is None:
                _json_log("agent_stage_submit_skipped", target_type=target_type, target_id=sb.get("id"), reason="no_image_url")
                continue
            kw = _apply_agent_modify_priority_to_kwargs(kw, config)
            submit_kwargs.append(kw)
        return _parallel_submit(submit_kwargs, target_type)

    return []


def _submit_storyboard_video_for(project, storyboard_id, config):
    """Submit the video task for a single storyboard whose image just completed. Returns task dict or None."""
    storyboard = next(
        (sb for sb in (project.get("storyboards") or [])
         if isinstance(sb, dict) and str(sb.get("id")) == str(storyboard_id)),
        None,
    )
    if not storyboard:
        return None
    model = _comic_media_model_for_project(project, config, "video")
    workflow_mode = _comic_storyboard_workflow_mode(project, config)
    aspect_ratio = (project.get("config") or {}).get("aspectRatio") or config.get("size") or "16:9"
    kw = _build_storyboard_video_submit_kwargs(project, storyboard, model, workflow_mode, aspect_ratio, config)
    kw = _apply_agent_modify_priority_to_kwargs(kw, config)
    task_name = f"Agent 生成分镜视频 #{storyboard_id}"
    if kw is None:
        reason = "视频任务缺少可用首帧图，无法提交"
        _json_log("agent_stage_submit_skipped", target_type="storyboard_videos", target_id=storyboard_id, reason="no_image_url")
        return _register_ai_comic_failed_task(
            project_id=int(project.get("id") or 0),
            task_type="generate_video",
            task_name=task_name,
            target_id=storyboard_id,
            target_type="storyboard",
            message=reason,
        )
    try:
        task = _submit_ai_comic_media_task(**kw)
        if workflow_mode == "multiframe":
            _apply_comic_frame_task_metadata(task, workflow_mode, 0)
        return task
    except Exception as error:
        message = f"视频任务提交失败：{AiApiService.sanitize_error(str(error) or repr(error))}"
        _json_log(
            "agent_stage_submit_failed",
            target_type="storyboard_videos",
            target_id=storyboard_id,
            model=model,
            workflow_mode=workflow_mode,
            error=AiApiService.sanitize_error(repr(error)),
        )
        return _register_ai_comic_failed_task(
            project_id=int(project.get("id") or 0),
            task_type="generate_video",
            task_name=task_name,
            target_id=storyboard_id,
            target_type="storyboard",
            message=message,
        )


def _poll_tasks_until_done(tasks, timeout=_AGENT_ORCHESTRATION_STAGE_TIMEOUT, on_complete=None, should_stop=None):
    """Poll task list until all are completed/failed or timeout. Returns (completed, failed) counts.

    `tasks` is mutable: callers / on_complete may append new tasks and they will be polled too.
    `on_complete(task)` fires once per task transitioning to completed (after result applied).
    """
    if not tasks:
        return 0, 0
    applied = set()
    fired = set()
    deadline = time.time() + timeout
    while time.time() < deadline:
        if should_stop is not None and should_stop():
            break
        time.sleep(_AGENT_ORCHESTRATION_POLL_INTERVAL)
        if should_stop is not None and should_stop():
            break
        all_done = True
        # Snapshot to allow on_complete to append to tasks safely
        for task in list(tasks):
            status = task.get("status")
            tid = task.get("id") or task.get("task_id")
            if status not in ("completed", "failed"):
                _refresh_ai_comic_task(task)
                status = task.get("status")
            if status == "completed" and tid and tid not in applied:
                try:
                    _apply_ai_comic_task_result_to_project(task)
                except Exception:
                    pass
                applied.add(tid)
            if status == "completed" and tid and tid not in fired:
                fired.add(tid)
                if on_complete is not None:
                    try:
                        on_complete(task)
                    except Exception as error:
                        _json_log("agent_on_complete_failed", task_id=tid, error=AiApiService.sanitize_error(repr(error)))
            if task.get("status") not in ("completed", "failed"):
                all_done = False
        if all_done:
            break
    completed = sum(1 for t in tasks if t.get("status") == "completed")
    failed = sum(1 for t in tasks if t.get("status") == "failed")
    for task in tasks:
        if task.get("status") not in ("completed", "failed"):
            task["status"] = "failed"
            task["error_message"] = "Agent 编排超时"
            failed += 1
            _save_local_comic_state()
    return completed, failed


def _agent_append_session_message(project, role, text, stage=None, status="info", images=None, videos=None):
    """Append a message to the agent session embedded in the project."""
    session = project.get("agent_session")
    if not isinstance(session, dict):
        return
    messages = session.setdefault("messages", [])
    msg = {
        "id": f"{session.get('id', '')}-{len(messages) + 1}",
        "role": str(role),
        "text": str(text),
        "stage": str(stage or ""),
        "status": str(status),
        "created_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
    }
    if images:
        msg["images"] = [str(u) for u in images if u]
    if videos:
        msg["videos"] = [str(u) for u in videos if u]
    messages.append(msg)
    session["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()



def _agent_directed_workflow_target(text, explicit_target=""):
    explicit_target = str(explicit_target or "").strip().lower()
    explicit_map = {
        "characters": "characters",
        "character": "characters",
        "character_images": "characters",
        "scenes": "scenes",
        "scene": "scenes",
        "scene_images": "scenes",
        "props": "props",
        "prop": "props",
        "prop_images": "props",
        "storyboard_images": "storyboard_images",
        "images": "storyboard_images",
        "storyboards": "storyboard_images",
        "storyboard_videos": "storyboard_videos",
        "videos": "storyboard_videos",
        "video": "storyboard_videos",
    }
    if explicit_target in explicit_map:
        return explicit_map[explicit_target]
    if explicit_target == "full_flow":
        return ""
    text = str(text or "").strip()
    if not text:
        return ""
    if re.search(r"(场景图|场景参考图|背景图|背景参考图|环境图)", text):
        return "scenes"
    if re.search(r"(角色图|人物图|角色参考图|人物参考图)", text):
        return "characters"
    if re.search(r"(道具图|道具参考图|物件图)", text):
        return "props"
    if re.search(r"(视频|分镜视频|镜头视频)", text):
        return "storyboard_videos"
    if re.search(r"(分镜图|镜头图|画面图|图片|图像)", text):
        return "storyboard_images"
    return ""


def _with_agent_instruction_prompt(prompt, instruction):
    prompt = str(prompt or "").strip()
    instruction = str(instruction or "").strip()
    if not instruction:
        return prompt
    if prompt:
        return (
            "最高优先级：严格执行用户本次修改要求。用户提出的颜色、背景、风格、构图、材质、"
            "角色/场景/道具变化、镜头变化、数量、范围和禁止项都必须优先生效；"
            f"用户本次修改要求：{instruction}；"
            f"原始描述仅用于保留主体和语义参考，不得覆盖用户本次要求：{prompt}"
        )
    return (
        "最高优先级：严格执行用户本次修改要求。用户提出的颜色、背景、风格、构图、材质、"
        "角色/场景/道具变化、镜头变化、数量、范围和禁止项都必须优先生效；"
        f"用户本次修改要求：{instruction}"
    )


def _submit_agent_directed_stage(project, target_type, config):
    project_config = project.get("config") if isinstance(project.get("config"), dict) else {}
    aspect_ratio = project_config.get("aspectRatio") or project_config.get("aspect_ratio") or config.get("size") or "16:9"
    instruction = str(config.get("idea") or config.get("workflow_instruction") or "").strip()

    if target_type in ("characters", "scenes", "props"):
        if target_type == "characters":
            _local_comic_prune_invalid_character_assets(project)
        model = _comic_media_model_for_project(project, config, "image")
        single_type = {"characters": "character", "scenes": "scene", "props": "prop"}[target_type]
        target_ids = [item.get("id") for item in project.get(target_type) or [] if isinstance(item, dict)]
        submit_kwargs = []
        for target_id in target_ids:
            kwargs = _build_asset_submit_kwargs(project, single_type, target_id, model, aspect_ratio)
            kwargs["prompt"] = _with_agent_instruction_prompt(kwargs.get("prompt"), instruction)
            submit_kwargs.append(kwargs)
        return _parallel_submit(submit_kwargs, target_type)

    if target_type == "storyboard_images":
        model = _comic_media_model_for_project(project, config, "image")
        submit_kwargs = []
        for storyboard in project.get("storyboards") or []:
            if not isinstance(storyboard, dict):
                continue
            for kwargs in _build_storyboard_image_submit_kwargs(project, storyboard, model, aspect_ratio, config):
                kwargs = dict(kwargs)
                kwargs["prompt"] = _with_agent_instruction_prompt(kwargs.get("prompt"), instruction)
                submit_kwargs.append(kwargs)
        return _parallel_submit(submit_kwargs, target_type)

    if target_type == "storyboard_videos":
        model = _comic_media_model_for_project(project, config, "video")
        workflow_mode = _comic_storyboard_workflow_mode(project, config)
        submit_kwargs = []
        for storyboard in project.get("storyboards") or []:
            if not isinstance(storyboard, dict):
                continue
            kwargs = _build_storyboard_video_submit_kwargs(project, storyboard, model, workflow_mode, aspect_ratio, config)
            if not kwargs:
                continue
            kwargs["prompt"] = _with_agent_instruction_prompt(kwargs.get("prompt"), instruction)
            submit_kwargs.append(kwargs)
        return _parallel_submit(submit_kwargs, target_type)

    return []


def _run_agent_directed_workflow_loop(project_id, task_group_id, session_id, config):
    try:
        project = LOCAL_COMIC_PROJECTS.get(int(project_id))
        task_group = LOCAL_COMIC_TASKS.get(task_group_id)
        if not project or not task_group:
            _json_log("agent_directed_workflow_abort", reason="project_or_group_missing", project_id=project_id)
            return
        should_cancel = lambda: _agent_task_group_cancel_requested(task_group)
        config = config if isinstance(config, dict) else {}
        instruction = str(config.get("idea") or config.get("workflow_instruction") or "").strip()
        explicit_target = str(config.get("workflow_target") or "").strip()
        target_type = _agent_directed_workflow_target(instruction, explicit_target)
        stage_label = {
            "characters": "角色图",
            "scenes": "场景图",
            "props": "道具图",
            "storyboard_images": "分镜图",
            "storyboard_videos": "分镜视频",
        }.get(target_type)
        if not stage_label:
            _json_log("agent_directed_workflow_fallback_full", project_id=project_id, instruction=instruction[:120])
            return _run_agent_orchestration_loop(project_id, task_group_id, session_id, config)

        task_group["stage_order"] = [stage_label]
        task_group["stage_task_ids"] = {}
        task_group["agent_directed_batch"] = True
        task_group["status"] = "running"
        task_group["state"] = "running"
        task_group["current_step"] = f"正在重新生成{stage_label}"
        task_group["progress_percent"] = max(1, int(task_group.get("progress_percent") or 1))
        _agent_append_session_message(project, "agent", f"开始按要求重新生成{stage_label}…", stage=target_type, status="running")
        _save_local_comic_state()

        if should_cancel():
            _save_local_comic_state()
            return

        tasks = _submit_agent_directed_stage(project, target_type, config)
        if should_cancel():
            _save_local_comic_state()
            return
        if tasks:
            AGENT_TASK_SERVICE.attach_stage_task(task_group, stage_label, tasks[0].get("id"))
        else:
            task_group["status"] = "failed"
            task_group["state"] = "failed"
            task_group["current_step"] = f"没有找到可生成的{stage_label}目标"
            _agent_append_session_message(project, "agent", task_group["current_step"], stage=target_type, status="failed")
            _save_local_comic_state()
            return

        def _on_directed_done(task):
            url = str(task.get("result_url") or "").strip()
            if not url:
                return
            kwargs = {"videos": [url]} if target_type == "storyboard_videos" else {"images": [url]}
            _agent_append_session_message(
                project,
                "agent",
                f"{stage_label} #{task.get('target_id') or ''} 生成完成",
                stage=target_type,
                status="completed",
                **kwargs,
            )
            _save_local_comic_state()

        completed, failed = _poll_tasks_until_done(tasks, timeout=_AGENT_ORCHESTRATION_STAGE_TIMEOUT, on_complete=_on_directed_done, should_stop=should_cancel)
        if should_cancel():
            _agent_append_session_message(project, "agent", "已取消生成，当前步骤已停止。", stage="cancelled", status="cancelled")
            _save_local_comic_state()
            _json_log("agent_directed_workflow_cancelled", project_id=project_id, target_type=target_type)
            return
        status = "completed" if completed > 0 and failed == 0 else ("failed" if completed == 0 else "completed")
        task_group["status"] = status
        task_group["state"] = status
        task_group["progress_percent"] = 100 if status == "completed" else int(task_group.get("progress_percent") or 1)
        task_group["current_step"] = f"{stage_label}重新生成完成（成功 {completed}，失败 {failed}）"
        _agent_append_session_message(project, "agent", task_group["current_step"], stage=target_type, status=status)
        _save_local_comic_state()
        _json_log("agent_directed_workflow_completed", project_id=project_id, target_type=target_type, completed=completed, failed=failed)
    except Exception as error:
        _json_log("agent_directed_workflow_error", project_id=project_id, error=repr(error))
        try:
            project = LOCAL_COMIC_PROJECTS.get(int(project_id))
            task_group = LOCAL_COMIC_TASKS.get(task_group_id)
            if project:
                _agent_append_session_message(project, "agent", f"定向生成异常：{error}", stage="error", status="failed")
            if task_group:
                task_group["status"] = "failed"
                task_group["state"] = "failed"
                task_group["current_step"] = f"定向生成异常：{AiApiService.sanitize_error(str(error))}"
            _save_local_comic_state()
        except Exception:
            pass


def _run_agent_directed_workflow_for_scope(scope, project_id, task_group_id, session_id, config):
    with _agent_comic_runtime_context(scope):
        return _run_agent_directed_workflow_loop(project_id, task_group_id, session_id, config)


def _run_agent_orchestration_loop(project_id, task_group_id, session_id, config):
    """Background thread: auto-advance Agent task chain after script analysis."""
    try:
        project = LOCAL_COMIC_PROJECTS.get(int(project_id))
        task_group = LOCAL_COMIC_TASKS.get(task_group_id)
        if not project or not task_group:
            _json_log("agent_orchestration_abort", reason="project_or_group_missing", project_id=project_id)
            return

        overall_deadline = time.time() + _AGENT_ORCHESTRATION_TOTAL_TIMEOUT
        should_cancel = lambda: _agent_task_group_cancel_requested(task_group)

        # --- Phase 1: Characters, Scenes, Props (parallel) ---
        _agent_append_session_message(project, "agent", "开始生成角色、场景和道具参考图…", stage="assets", status="running")
        _save_local_comic_state()

        if should_cancel():
            _save_local_comic_state()
            return

        char_tasks = _submit_stage_batch(project, "characters", config)
        if should_cancel():
            _save_local_comic_state()
            return
        scene_tasks = _submit_stage_batch(project, "scenes", config)
        if should_cancel():
            _save_local_comic_state()
            return
        prop_tasks = _submit_stage_batch(project, "props", config)

        if char_tasks:
            AGENT_TASK_SERVICE.attach_stage_task(task_group, "角色", char_tasks[0].get("id"))
        if scene_tasks:
            AGENT_TASK_SERVICE.attach_stage_task(task_group, "场景", scene_tasks[0].get("id"))
        if prop_tasks:
            AGENT_TASK_SERVICE.attach_stage_task(task_group, "道具", prop_tasks[0].get("id"))

        all_asset_tasks = [*(char_tasks or []), *(scene_tasks or []), *(prop_tasks or [])]

        _asset_label_map = {"character": "角色", "scene": "场景", "prop": "道具"}

        def _on_asset_done(task):
            url = str(task.get("result_url") or "").strip()
            if not url:
                return
            label = _asset_label_map.get(str(task.get("target_type") or ""), "参考图")
            _agent_append_session_message(
                project, "agent",
                f"{label}「{task.get('task_name') or ''}」生成完成",
                stage="assets", status="completed",
                images=[url],
            )
            _save_local_comic_state()

        completed, failed = _poll_tasks_until_done(all_asset_tasks, on_complete=_on_asset_done, should_stop=should_cancel)
        if should_cancel():
            _agent_append_session_message(project, "agent", "已取消生成，后续阶段不会继续提交。", stage="cancelled", status="cancelled")
            _save_local_comic_state()
            return
        _json_log("agent_orchestration_phase1_done", project_id=project_id, completed=completed, failed=failed)
        _agent_append_session_message(
            project, "agent",
            f"参考图阶段完成（成功 {completed}，失败 {failed}）",
            stage="assets", status="completed",
        )
        _save_local_comic_state()

        if time.time() > overall_deadline:
            _agent_append_session_message(project, "agent", "总超时，任务链终止", stage="timeout", status="failed")
            task_group["status"] = "failed"
            _save_local_comic_state()
            return

        # --- Phase 2 + 3 (pipelined): storyboard images → as each completes, submit its video ---
        _agent_append_session_message(project, "agent", "开始生成分镜图和视频（流水线）…", stage="storyboard", status="running")
        _save_local_comic_state()

        if should_cancel():
            _save_local_comic_state()
            return

        sb_image_tasks = _submit_stage_batch(project, "storyboard_images", config)
        if sb_image_tasks:
            AGENT_TASK_SERVICE.attach_stage_task(task_group, "分镜", sb_image_tasks[0].get("id"))

        # Combined list: poll image + video tasks together. on_complete will append video tasks here.
        pipeline_tasks = list(sb_image_tasks)
        video_task_ids = set()
        video_attached = {"flag": False}

        def _on_image_done(task):
            if task.get("target_type") != "storyboard":
                return
            if should_cancel():
                _agent_append_session_message(project, "agent", "已取消生成，跳过后续分镜视频提交。", stage="cancelled", status="cancelled")
                _save_local_comic_state()
                return
            tid = task.get("id") or task.get("task_id")
            is_video = (
                str(task.get("result_type") or "").lower() == "video"
                or "video" in str(task.get("task_type") or "").lower()
                or tid in video_task_ids
            )
            url = str(task.get("result_url") or "").strip()
            if is_video:
                if url:
                    _agent_append_session_message(
                        project, "agent",
                        f"分镜 #{task.get('target_id')} 视频生成完成",
                        stage="storyboard_videos", status="completed",
                        videos=[url],
                    )
                    _save_local_comic_state()
                return
            # image task: push one-image message, then submit its video
            if url:
                _agent_append_session_message(
                    project, "agent",
                    f"分镜 #{task.get('target_id')} 图片生成完成",
                    stage="storyboard_images", status="completed",
                    images=[url],
                )
                _save_local_comic_state()
            target_id = task.get("target_id")
            if not target_id:
                return
            if should_cancel():
                _agent_append_session_message(project, "agent", "已取消生成，图片完成后不再提交视频任务。", stage="cancelled", status="cancelled")
                _save_local_comic_state()
                return
            video_task = _submit_storyboard_video_for(project, target_id, config)
            if not video_task:
                return
            pipeline_tasks.append(video_task)
            video_task_ids.add(video_task.get("id") or video_task.get("task_id"))
            if not video_attached["flag"]:
                video_attached["flag"] = True
                AGENT_TASK_SERVICE.attach_stage_task(task_group, "视频", video_task.get("id"))

        # Use the remaining overall budget as this combined stage's timeout
        combined_timeout = max(60, int(overall_deadline - time.time()))
        completed, failed = _poll_tasks_until_done(pipeline_tasks, timeout=combined_timeout, on_complete=_on_image_done, should_stop=should_cancel)

        if should_cancel():
            _agent_append_session_message(project, "agent", "已取消生成，任务已停止在当前阶段。", stage="cancelled", status="cancelled")
            _save_local_comic_state()
            _json_log("agent_orchestration_cancelled", project_id=project_id, session_id=session_id)
            return

        image_done = sum(1 for t in pipeline_tasks if (t.get("id") or t.get("task_id")) not in video_task_ids and t.get("status") == "completed")
        image_fail = sum(1 for t in pipeline_tasks if (t.get("id") or t.get("task_id")) not in video_task_ids and t.get("status") != "completed")
        video_done = sum(
            1
            for t in pipeline_tasks
            if (t.get("id") or t.get("task_id")) in video_task_ids
            and t.get("status") == "completed"
            and str(t.get("result_url") or "").strip()
        )
        video_fail = sum(1 for t in pipeline_tasks if (t.get("id") or t.get("task_id")) in video_task_ids and t.get("status") != "completed")
        expected_videos = image_done
        if expected_videos > 0:
            video_fail += max(0, expected_videos - video_done - video_fail)
        video_stage_ok = expected_videos > 0 and video_done >= expected_videos
        video_failure_details = []
        for task in pipeline_tasks:
            if (task.get("id") or task.get("task_id")) not in video_task_ids:
                continue
            if task.get("status") == "completed":
                continue
            detail = _first_non_empty(
                task.get("error_message"),
                task.get("current_step"),
                task.get("failure_reason"),
                task.get("failReason"),
                "未知错误",
            )
            target = _first_non_empty(task.get("target_id"), task.get("task_name"), "未知分镜")
            video_failure_details.append(f"分镜 {target}: {detail}")
        _json_log(
            "agent_orchestration_phase23_done",
            project_id=project_id,
            image_done=image_done, image_fail=image_fail,
            video_done=video_done, video_fail=video_fail,
            expected_videos=expected_videos,
        )
        _agent_append_session_message(
            project, "agent",
            f"分镜图阶段完成（成功 {image_done}，失败 {image_fail}）",
            stage="storyboard_images", status="completed",
        )
        _agent_append_session_message(
            project, "agent",
            f"分镜视频阶段完成（成功 {video_done}，失败 {video_fail}）"
            + (f"\n失败原因：{'；'.join(video_failure_details[:3])}" if video_failure_details else ""),
            stage="storyboard_videos", status="completed" if video_stage_ok else "failed",
        )

        if not video_stage_ok:
            task_group["status"] = "failed"
            task_group["state"] = "failed"
            task_group["current_step"] = f"视频阶段未完成：预期 {expected_videos} 个，成功 {video_done} 个，失败 {video_fail} 个"
            _agent_append_session_message(
                project,
                "agent",
                task_group["current_step"]
                + (f"\n失败原因：{'；'.join(video_failure_details[:3])}" if video_failure_details else ""),
                stage="storyboard_videos",
                status="failed",
            )
            _save_local_comic_state()
            _json_log(
                "agent_orchestration_failed",
                project_id=project_id,
                session_id=session_id,
                reason="video_stage_incomplete",
                expected_videos=expected_videos,
                video_done=video_done,
                video_fail=video_fail,
            )
            return

        # --- Done ---
        task_group["status"] = "completed"
        task_group["state"] = "completed"
        task_group["progress_percent"] = 100
        task_group["current_step"] = "全部生成完成"
        _agent_append_session_message(project, "agent", "漫剧全流程生成完毕！", stage="done", status="completed")
        _save_local_comic_state()
        _json_log("agent_orchestration_completed", project_id=project_id, session_id=session_id)

    except Exception as error:
        _json_log("agent_orchestration_error", project_id=project_id, error=repr(error))
        try:
            project = LOCAL_COMIC_PROJECTS.get(int(project_id))
            task_group = LOCAL_COMIC_TASKS.get(task_group_id)
            if project:
                _agent_append_session_message(project, "agent", f"编排异常：{error}", stage="error", status="failed")
            if task_group:
                task_group["status"] = "failed"
                task_group["current_step"] = f"编排异常：{AiApiService.sanitize_error(str(error))}"
            _save_local_comic_state()
        except Exception:
            pass


def _run_agent_orchestration_for_scope(scope, project_id, task_group_id, session_id, config):
    with _agent_comic_runtime_context(scope):
        return _run_agent_orchestration_loop(project_id, task_group_id, session_id, config)


