def _handle_local_profile_fallback(handler, path, method):
    method = str(method or "").upper()
    path = str(path or "").split("?", 1)[0]
    if method != "GET":
        return False
    if (AICANVAS_AUTH_REQUIRED and not _has_local_password_login_session(handler)) or _has_platform_session_authorization(handler):
        return False
    if path == "/api/v1/user/info":
        _json_log("profile_local_dev_fallback", method=method, path=path)
        _send_json_with_headers(handler, 200, _local_profile_user_info_response(handler))
        return True
    if path == "/api/v1/user/membership":
        _json_log("profile_local_dev_fallback", method=method, path=path)
        _send_json_with_headers(
            handler,
            200,
            {
                "membership": None,
                "orders": [],
                "localDev": True,
                "detail": "本地免登录模式未连接平台账号，会员信息显示为空。",
            },
        )
        return True
    if path in LOCAL_PROFILE_COLLECTION_PATHS:
        _json_log("profile_local_dev_fallback", method=method, path=path)
        _send_json_with_headers(handler, 200, _local_profile_collection_response(handler))
        return True
    return False


COMIC_MODEL_CATALOG_PATHS = {
    "/api/v1/comic-drama/llm-models": ("llm", "/comic-drama/llm-models"),
    "/api/v1/comic-drama/image-models": ("image", "/comic-drama/image-models"),
    "/api/v1/comic-drama/audio-models": ("audio", "/comic-drama/audio-models"),
    "/api/v1/comic-drama/video-models": ("video", "/comic-drama/video-models"),
}


COMIC_STORYBOARD_WORKFLOW_MODES = {"action_flow", "keyframes", "multiframe"}


def _normalize_comic_storyboard_workflow_mode(value):
    mode = str(value or "").strip()
    return mode if mode in COMIC_STORYBOARD_WORKFLOW_MODES else ""


def _comic_storyboard_workflow_mode(project, payload):
    payload = payload if isinstance(payload, dict) else {}
    config = project.get("config") if isinstance(project, dict) and isinstance(project.get("config"), dict) else {}
    return _normalize_comic_storyboard_workflow_mode(
        payload.get("workflow_mode")
        or payload.get("workflowMode")
        or config.get("storyboard_workflow_mode")
        or config.get("storyboardWorkflowMode")
    )


def _comic_storyboard_image_generation_workflow_mode(project, payload, pending_workflow_mode=""):
    payload = payload if isinstance(payload, dict) else {}
    workflow_mode = _normalize_comic_storyboard_workflow_mode(
        payload.get("workflow_mode") or payload.get("workflowMode")
    )
    if workflow_mode:
        return workflow_mode
    try:
        quantity = int(payload.get("quantity") or payload.get("count") or 0)
    except Exception:
        quantity = 0
    if quantity == 7:
        return "multiframe"
    if quantity == 2:
        return "keyframes"
    workflow_mode = _normalize_comic_storyboard_workflow_mode(pending_workflow_mode)
    if workflow_mode:
        return workflow_mode
    return _comic_storyboard_workflow_mode(project, payload)


def _comic_workflow_mode_store_path():
    return os.path.join(_current_user_dir(), "comic_workflow_modes.json")


def _load_comic_workflow_modes():
    path = _comic_workflow_mode_store_path()
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except Exception:
        return {}
    if not isinstance(data, dict):
        return {}
    modes = {}
    for project_id, mode in data.items():
        normalized = _normalize_comic_storyboard_workflow_mode(mode)
        if normalized:
            modes[str(project_id)] = normalized
    return modes


def _save_comic_workflow_modes(modes):
    path = _comic_workflow_mode_store_path()
    try:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w", encoding="utf-8") as f:
            json.dump(modes, f, ensure_ascii=False, indent=2, sort_keys=True)
    except Exception as error:
        _json_log("comic_workflow_mode_store_failed", path=path, error=repr(error))


def _remember_comic_workflow_mode(project_id, mode):
    normalized = _normalize_comic_storyboard_workflow_mode(mode)
    if not project_id or not normalized:
        return
    modes = _load_comic_workflow_modes()
    modes[str(project_id)] = normalized
    _save_comic_workflow_modes(modes)
    _json_log("comic_workflow_mode_remembered", project_id=str(project_id), mode=normalized)


def _project_id_from_payload(value):
    if not isinstance(value, dict):
        return ""
    project_id = value.get("id") or value.get("project_id")
    if project_id:
        return str(project_id)
    data = value.get("data")
    if isinstance(data, dict):
        return _project_id_from_payload(data)
    return ""


def _overlay_comic_workflow_modes(payload):
    modes = _load_comic_workflow_modes()
    if not modes:
        return payload

    def overlay(value):
        if isinstance(value, list):
            for item in value:
                overlay(item)
            return
        if not isinstance(value, dict):
            return
        project_id = value.get("id") or value.get("project_id")
        config = value.get("config")
        if project_id and isinstance(config, dict):
            mode = modes.get(str(project_id))
            if mode:
                config["storyboard_workflow_mode"] = mode
        for key in ("data", "items", "projects", "results"):
            overlay(value.get(key))

    overlay(payload)
    return payload


def _remove_foreign_comic_project_records(payload):
    def clean(value):
        if isinstance(value, list):
            return [
                item
                for item in (clean(item) for item in value)
                if not _is_foreign_comic_project_record(item)
            ]
        if not isinstance(value, dict):
            return value
        for key in ("data", "items", "projects", "results"):
            child = value.get(key)
            if isinstance(child, list):
                value[key] = [
                    item
                    for item in (clean(item) for item in child)
                    if not _is_foreign_comic_project_record(item)
                ]
                if key in {"data", "items"} and "total" in value:
                    value["total"] = len(value[key])
            elif isinstance(child, dict):
                value[key] = clean(child)
        return value

    return clean(payload)


def _is_comic_generator_project_record(project):
    if not isinstance(project, dict):
        return False
    config = project.get("config") if isinstance(project.get("config"), dict) else {}
    source_mode = str(project.get("source_mode") or config.get("source_mode") or "").strip()
    if source_mode == "local_flow":
        return True
    created_at = str(project.get("created_at") or "")
    return bool(project.get("source_text") and created_at >= "2026-07-13")


def _overlay_local_comic_project_list_summary(project):
    if not isinstance(project, dict):
        return project
    try:
        project_id = int(project.get("id") or 0)
    except Exception:
        project_id = 0
    if not project_id:
        return project

    local_project = None
    persisted_project = _load_persisted_local_comic_project(project_id)
    if isinstance(persisted_project, dict) and _local_comic_scope_allows_project(persisted_project):
        local_project = persisted_project
    memory_project = LOCAL_COMIC_PROJECTS.get(project_id)
    if isinstance(memory_project, dict) and _local_comic_scope_allows_project(memory_project):
        if not local_project or (
            _local_comic_project_has_real_storyboards(memory_project)
            and not _local_comic_project_has_real_storyboards(local_project)
        ):
            local_project = memory_project
    if not isinstance(local_project, dict):
        return project

    counts = {
        "total_characters": len(local_project.get("characters") or []),
        "total_scenes": len(local_project.get("scenes") or []),
        "total_storyboards": len(local_project.get("storyboards") or []),
        "total_props": len(local_project.get("props") or []),
    }
    for key, value in counts.items():
        if value:
            project[key] = value
    project["totalCharacters"] = project.get("total_characters", 0)
    project["totalScenes"] = project.get("total_scenes", 0)
    project["totalStoryboards"] = project.get("total_storyboards", 0)
    project["totalProps"] = project.get("total_props", 0)
    if counts["total_storyboards"] and str(project.get("status") or "").lower() in {"", "pending", "analyzing"}:
        project["status"] = str(local_project.get("status") or "storyboards")
        project["progress_percent"] = max(_coerce_comic_count(project.get("progress_percent"), 0), 100)
    project.setdefault("account_scope", _local_comic_project_owner_scope(local_project))
    return project


def _filter_comic_generator_project_list(payload):
    if not isinstance(payload, dict) or not isinstance(payload.get("data"), list):
        return payload
    payload["data"] = [
        _overlay_local_comic_project_list_summary(item)
        for item in payload["data"]
        if _is_comic_generator_project_record(item)
    ]
    if "total" in payload:
        payload["total"] = len(payload["data"])
    return payload


def _rewrite_comic_workflow_request(path, method, body):
    if not body or "/api/v1/comic-drama/" not in str(path or ""):
        return body, ""
    content = None
    try:
        content = json.loads(body.decode("utf-8") if isinstance(body, (bytes, bytearray)) else body)
    except Exception:
        return body, ""
    if not isinstance(content, dict):
        return body, ""

    def rewrite_unpriced_llm_model(value):
        return _normalize_priced_comic_llm_model(value)

    if str(path or "").startswith("/api/v1/comic-drama/projects"):
        content["llm_model"] = rewrite_unpriced_llm_model(content.get("llm_model"))
        config_payload = content.get("config")
        if isinstance(config_payload, dict):
            config_payload["llm_model"] = rewrite_unpriced_llm_model(config_payload.get("llm_model"))
        if str(method or "").upper() == "POST" and str(path or "") == "/api/v1/comic-drama/projects":
            config_payload = content.setdefault("config", {})
            if isinstance(config_payload, dict):
                config_payload.setdefault("source_mode", "local_flow")

    pending_mode = ""
    config = content.get("config")
    if isinstance(config, dict):
        mode = _normalize_comic_storyboard_workflow_mode(config.get("storyboard_workflow_mode"))
        if mode:
            pending_mode = mode

    mode = _normalize_comic_storyboard_workflow_mode(content.get("workflow_mode"))

    update_match = re.fullmatch(r"/api/v1/comic-drama/projects/(\d+)", str(path or ""))
    if update_match and pending_mode:
        _remember_comic_workflow_mode(update_match.group(1), pending_mode)

    return json.dumps(content, ensure_ascii=False).encode("utf-8"), pending_mode


def _rewrite_comic_workflow_response(path, method, body, pending_mode=""):
    if not body or "/api/v1/comic-drama/projects" not in str(path or ""):
        return body
    try:
        payload = json.loads(body.decode("utf-8") if isinstance(body, (bytes, bytearray)) else body)
    except Exception:
        return body
    if not isinstance(payload, (dict, list)):
        return body

    if pending_mode:
        project_id = _project_id_from_payload(payload)
        if project_id:
            _remember_comic_workflow_mode(project_id, pending_mode)
    if str(method or "").upper() == "GET":
        payload = _remove_foreign_comic_project_records(payload)
        if str(path or "") == "/api/v1/comic-drama/projects":
            payload = _filter_comic_generator_project_list(payload)
    payload = _overlay_comic_workflow_modes(payload)
    return json.dumps(payload, ensure_ascii=False).encode("utf-8")


def _comic_proxy_task_id_from_response(payload):
    if not isinstance(payload, dict):
        return ""
    candidates = []
    data = payload.get("data")
    if isinstance(data, dict):
        candidates.append(data)
    candidates.append(payload)
    for source in candidates:
        task_id = _extract_proxy_task_id(source)
        if task_id:
            return task_id
        for key in ("task", "result", "payload"):
            value = source.get(key)
            if isinstance(value, dict):
                task_id = _extract_proxy_task_id(value)
                if task_id:
                    return task_id
    return ""


def _comic_frame_task_overlay_path():
    return os.path.join(_current_user_dir(), "comic_frame_task_overlays.json")


def _load_comic_frame_task_overlays():
    try:
        with open(_comic_frame_task_overlay_path(), "r", encoding="utf-8") as file:
            data = json.load(file)
    except Exception:
        return {}
    return data if isinstance(data, dict) else {}


def _save_comic_frame_task_overlays(overlays):
    try:
        path = _comic_frame_task_overlay_path()
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w", encoding="utf-8") as file:
            json.dump(overlays if isinstance(overlays, dict) else {}, file, ensure_ascii=False, indent=2, sort_keys=True)
    except Exception as error:
        _json_log("comic_frame_task_overlay_save_failed", error=repr(error))


def _register_comic_frame_task_overlay(task_id, storyboard_id, workflow_mode, frame_index):
    task_id = str(task_id or "").strip()
    if not task_id:
        return
    overlays = _load_comic_frame_task_overlays()
    overlays[task_id] = {
        "storyboard_id": str(storyboard_id or ""),
        "workflow_mode": str(workflow_mode or ""),
        "frame_index": int(frame_index or 0),
    }
    _save_comic_frame_task_overlays(overlays)


def _update_comic_frame_task_overlays_from_payload(payload):
    overlays = _load_comic_frame_task_overlays()
    if not overlays:
        return
    changed = False

    def visit(value):
        nonlocal changed
        if isinstance(value, list):
            for item in value:
                visit(item)
            return
        if not isinstance(value, dict):
            return
        task_id = str(value.get("id") or value.get("task_id") or value.get("taskId") or "").strip()
        overlay = overlays.get(task_id)
        if overlay:
            result_url = _extract_ai_result_url(value)
            status = str(value.get("status") or value.get("state") or "").lower()
            error_message = _first_non_empty(
                value.get("error_message"),
                value.get("errorMessage"),
                value.get("message"),
                value.get("detail"),
                value.get("current_step"),
            )
            if result_url and result_url != overlay.get("result_url"):
                overlay["result_url"] = result_url
                changed = True
                _json_log(
                    "comic_frame_task_overlay_result",
                    task_id=task_id,
                    storyboard_id=overlay.get("storyboard_id"),
                    workflow_mode=overlay.get("workflow_mode"),
                    frame_index=overlay.get("frame_index"),
                    result_url=result_url,
                )
            if status and status != overlay.get("status"):
                overlay["status"] = status
                changed = True
            if error_message and error_message != overlay.get("error_message"):
                overlay["error_message"] = error_message
                changed = True
            if overlay and status in {"failed", "error", "cancelled", "canceled"}:
                _json_log(
                    "comic_frame_task_overlay_failed",
                    task_id=task_id,
                    storyboard_id=overlay.get("storyboard_id"),
                    workflow_mode=overlay.get("workflow_mode"),
                    frame_index=overlay.get("frame_index"),
                    status=status,
                    error_message=str(error_message or overlay.get("error_message") or "")[:300],
                    model=value.get("model") or value.get("image_model") or value.get("imageModel"),
                )
        for child in value.values():
            if isinstance(child, (dict, list)):
                visit(child)

    visit(payload)
    if changed:
        _save_comic_frame_task_overlays(overlays)


def _apply_comic_frame_task_overlays(payload):
    overlays = _load_comic_frame_task_overlays()
    if not overlays:
        return payload
    by_storyboard = {}
    for overlay in overlays.values():
        result_url = str(overlay.get("result_url") or "").strip()
        storyboard_id = str(overlay.get("storyboard_id") or "").strip()
        workflow_mode = str(overlay.get("workflow_mode") or "").strip()
        try:
            frame_index = int(overlay.get("frame_index") or 0)
        except Exception:
            frame_index = 0
        if result_url and storyboard_id and frame_index > 0:
            by_storyboard.setdefault(storyboard_id, []).append((workflow_mode, frame_index, result_url))
    if not by_storyboard:
        return payload

    def visit(value):
        if isinstance(value, list):
            for item in value:
                visit(item)
            return
        if not isinstance(value, dict):
            return
        storyboard_id = str(value.get("id") or value.get("storyboard_id") or "").strip()
        frames = by_storyboard.get(storyboard_id)
        if frames:
            for workflow_mode, frame_index, result_url in frames:
                if workflow_mode == "keyframes":
                    if frame_index == 1:
                        value["start_frame_url"] = result_url
                    elif frame_index == 2:
                        value["end_frame_url"] = result_url
                    value["generatedImages"] = _set_url_at_index(value.get("generatedImages"), result_url, frame_index)
                elif workflow_mode == "multiframe":
                    value["action_frame_urls"] = _set_url_at_index(value.get("action_frame_urls"), result_url, frame_index)
                    value["generatedImages"] = list(value.get("action_frame_urls") or [])
        for child in value.values():
            if isinstance(child, (dict, list)):
                visit(child)

    visit(payload)
    return payload


def _apply_ai_comic_task_results_to_payload(payload):
    try:
        wanted_project_id = int((payload or {}).get("id") or 0)
    except Exception:
        wanted_project_id = 0
    by_storyboard = {}
    video_by_storyboard = {}
    image_by_storyboard = {}
    asset_results = {
        "character": {},
        "scene": {},
        "prop": {},
    }
    for task in list(AI_COMIC_TASKS.values()):
        if not _ai_comic_task_has_applyable_result(task):
            continue
        if wanted_project_id and not _local_comic_task_belongs_to_project_scope(task, wanted_project_id):
            continue
        result_url = str(task.get("result_url") or "").strip()
        target_id = str(task.get("target_id") or "").strip()
        target_type = str(task.get("target_type") or "").strip().lower()
        task_type = str(task.get("task_type") or "").strip().lower()
        if result_url and target_id and target_type in asset_results:
            asset_results[target_type][target_id] = result_url
            continue
        storyboard_id = target_id
        if result_url and storyboard_id and "video" in task_type:
            video_by_storyboard[storyboard_id] = result_url
            continue
        if result_url and storyboard_id and target_type == "storyboard" and "image" in task_type:
            try:
                frame_index = int(task.get("frame_index") or 0)
            except Exception:
                frame_index = 0
            if frame_index <= 0:
                image_by_storyboard[storyboard_id] = result_url
                continue
        workflow_mode = str(task.get("workflow_mode") or "").strip()
        try:
            frame_index = int(task.get("frame_index") or 0)
        except Exception:
            frame_index = 0
        if result_url and storyboard_id and frame_index > 0:
            by_storyboard.setdefault(storyboard_id, []).append((workflow_mode, frame_index, result_url))
    if not by_storyboard and not video_by_storyboard and not image_by_storyboard and not any(asset_results.values()):
        return payload

    def visit(value, collection=""):
        if isinstance(value, list):
            for item in value:
                visit(item, collection)
            return
        if not isinstance(value, dict):
            return
        item_id = str(value.get("id") or value.get("character_id") or value.get("scene_id") or value.get("prop_id") or "").strip()
        if item_id:
            for target_type, result_by_id in asset_results.items():
                result_url = result_by_id.get(item_id)
                if not result_url:
                    continue
                type_hint = " ".join(str(value.get(key) or "") for key in ("type", "asset_type", "target_type", "kind")).lower()
                collection_hint = str(value.get("_collection") or value.get("collection") or "").lower()
                context_hint = f"{collection} {collection_hint}"
                if target_type == "character" and not (
                    collection == "characters" or any(hint in type_hint or hint in context_hint for hint in ("character", "角色", "人物"))
                ):
                    continue
                if target_type == "scene" and not (
                    collection == "scenes" or any(hint in type_hint or hint in context_hint for hint in ("scene", "场景"))
                ):
                    continue
                if target_type == "prop" and not (
                    collection == "props" or any(hint in type_hint or hint in context_hint for hint in ("prop", "道具"))
                ):
                    continue
                value["reference_image"] = result_url
                value["referenceImage"] = result_url
                value["reference_images"] = _append_unique_url(value.get("reference_images"), result_url)
                value["referenceImages"] = _append_unique_url(value.get("referenceImages"), result_url)
                value["thumbnail_url"] = value.get("thumbnail_url") or result_url
                if target_type == "character":
                    views = value.get("views") if isinstance(value.get("views"), dict) else {}
                    views["front"] = result_url
                    value["views"] = views
        storyboard_id = str(value.get("id") or value.get("storyboard_id") or "").strip()
        frames = by_storyboard.get(storyboard_id)
        if frames:
            for workflow_mode, frame_index, result_url in frames:
                if workflow_mode == "keyframes":
                    if frame_index == 1:
                        value["start_frame_url"] = result_url
                    elif frame_index == 2:
                        value["end_frame_url"] = result_url
                    value["generatedImages"] = _set_url_at_index(value.get("generatedImages"), result_url, frame_index)
                elif workflow_mode == "multiframe":
                    value["action_frame_urls"] = _set_url_at_index(value.get("action_frame_urls"), result_url, frame_index)
                    value["generatedImages"] = list(value.get("action_frame_urls") or [])
                else:
                    value["generatedImages"] = _set_url_at_index(value.get("generatedImages"), result_url, frame_index)
        image_url = image_by_storyboard.get(storyboard_id)
        if image_url:
            current_image = value.get("image_url") or value.get("imageUrl")
            if current_image and current_image != image_url:
                value["generatedImages"] = _append_unique_url(value.get("generatedImages"), current_image)
            value["image_url"] = image_url
            value["imageUrl"] = image_url
            value["generatedImages"] = _append_unique_url(value.get("generatedImages"), image_url)
        video_url = video_by_storyboard.get(storyboard_id)
        if video_url:
            current_video = value.get("video_url") or value.get("videoUrl")
            history_values = value.get("video_history") or value.get("videoHistory") or []
            if isinstance(history_values, str):
                history_values = [history_values]
            history = _dedupe_urls(history_values if isinstance(history_values, list) else [])
            if current_video and current_video != video_url:
                history = _append_unique_url(history, current_video)
            value["video_url"] = video_url
            value["videoUrl"] = video_url
            value["video_history"] = [url for url in history if url != video_url]
            value["videoHistory"] = list(value["video_history"])
            value["videoStatus"] = "completed"
        for key, child in value.items():
            if isinstance(child, (dict, list)):
                child_collection = key if key in {"characters", "scenes", "props", "storyboards"} else collection
                visit(child, child_collection)

    visit(payload)
    return payload


def _merge_ai_comic_project_tasks_into_payload(payload, project_id):
    try:
        wanted_project_id = int(project_id or 0)
    except Exception:
        wanted_project_id = 0
    if not wanted_project_id:
        return payload
    local_tasks = []
    for task in list(LOCAL_COMIC_TASKS.values()):
        if not isinstance(task, dict):
            continue
        try:
            task_project_id = int(task.get("project_id") or 0)
        except Exception:
            task_project_id = 0
        if task_project_id != wanted_project_id:
            continue
        if not _local_comic_task_belongs_to_project_scope(task, wanted_project_id):
            continue
        local_tasks.append(_ai_comic_task_response(task))
    if not local_tasks:
        return payload

    def task_id_of(value):
        if not isinstance(value, dict):
            return ""
        return str(value.get("id") or value.get("task_id") or value.get("taskId") or "").strip()

    def is_final(value):
        status = str((value or {}).get("status") or (value or {}).get("state") or "").strip().lower()
        return status in {"completed", "failed", "cancelled", "canceled"}

    def merge_list(items):
        if not isinstance(items, list):
            return items
        by_id = {task_id_of(item): index for index, item in enumerate(items) if task_id_of(item)}
        for local_task in local_tasks:
            local_id = task_id_of(local_task)
            if not local_id:
                continue
            index = by_id.get(local_id)
            if index is None:
                items.append(local_task)
                by_id[local_id] = len(items) - 1
                continue
            existing = items[index] if isinstance(items[index], dict) else {}
            if is_final(existing) and not is_final(local_task):
                continue
            items[index] = {**existing, **local_task}
        return items

    if isinstance(payload, list):
        return merge_list(payload)
    if not isinstance(payload, dict):
        return payload
    data = payload.get("data")
    if isinstance(data, list):
        payload["data"] = merge_list(data)
    elif isinstance(data, dict) and isinstance(data.get("items"), list):
        data["items"] = merge_list(data.get("items"))
    elif isinstance(payload.get("items"), list):
        payload["items"] = merge_list(payload.get("items"))
    return payload


def _normalize_comic_task_identity_fields(payload):
    def visit(value):
        if isinstance(value, list):
            for item in value:
                visit(item)
            return value
        if not isinstance(value, dict):
            return value
        task_id = str(
            value.get("id")
            or value.get("task_id")
            or value.get("taskId")
            or value.get("job_id")
            or value.get("jobId")
            or ""
        ).strip()
        task_type = str(value.get("task_type") or value.get("taskType") or "").strip()
        looks_like_task = bool(task_id and (
            task_type
            or "progress_percent" in value
            or "progress" in value
            or "current_step" in value
            or "status" in value and ("target_id" in value or "targetId" in value)
        ))
        if looks_like_task:
            value.setdefault("id", task_id)
            value.setdefault("task_id", task_id)
            if "taskType" in value and "task_type" not in value:
                value["task_type"] = value.get("taskType")
            if "targetId" in value and "target_id" not in value:
                value["target_id"] = value.get("targetId")
            if "targetType" in value and "target_type" not in value:
                value["target_type"] = value.get("targetType")
            if "progress" in value and "progress_percent" not in value:
                try:
                    progress = str(value.get("progress") or "0").strip().rstrip("%")
                    value["progress_percent"] = int(float(progress))
                except Exception:
                    value["progress_percent"] = 0
        for child in list(value.values()):
            if isinstance(child, (dict, list)):
                visit(child)
        return value

    return visit(payload)


def _handle_comic_frame_generate_image_proxy(handler, path, upstream_url, body, pending_workflow_mode):
    route_path = str(path or "").split("?", 1)[0]
    if not re.fullmatch(r"/api/v1/comic-drama/storyboards/\d+/generate-image", route_path):
        return False
    try:
        payload = json.loads(body.decode("utf-8") if isinstance(body, (bytes, bytearray)) else (body or b"{}"))
    except Exception:
        return False
    if not isinstance(payload, dict):
        return False
    workflow_mode = _comic_storyboard_image_generation_workflow_mode({}, payload, pending_workflow_mode)
    try:
        requested_frame_index = _comic_storyboard_requested_image_frame_index(workflow_mode, payload)
    except ValueError as error:
        _json_log(
            "comic_generate_image_proxy_frame_rejected",
            path=path,
            workflow_mode=workflow_mode,
            reason="invalid_frame_index",
            frame_index_type=type(payload.get("frameIndex") if "frameIndex" in payload else payload.get("frame_index")).__name__,
        )
        _send_json_with_headers(handler, 400, {"detail": str(error)})
        return True
    if workflow_mode not in {"keyframes", "multiframe"}:
        _json_log(
            "comic_generate_image_proxy_frame_skip",
            path=path,
            reason="workflow_mode_not_frame",
            workflow_mode=workflow_mode,
            quantity=payload.get("quantity") or payload.get("count"),
        )
        return False
    model = _first_non_empty(payload.get("image_model"), payload.get("imageModel"), payload.get("model"), COMIC_DEFAULT_IMAGE_MODEL)
    model_error = _comic_frame_image_model_error(workflow_mode, model)
    if model_error:
        _json_log(
            "comic_generate_image_proxy_frame_rejected",
            path=path,
            workflow_mode=workflow_mode,
            model=model or COMIC_DEFAULT_IMAGE_MODEL,
            reason=model_error,
        )
        _send_json_with_headers(handler, 400, {"detail": model_error})
        return True
    prompt = _first_non_empty(
        payload.get("prompt"),
        payload.get("storyboard_image_prompt"),
        payload.get("action_grid_prompt"),
        payload.get("start_frame_prompt"),
        payload.get("end_frame_prompt"),
    )
    frame_prompt_source = _comic_storyboard_frame_prompt_source(payload, None, prompt)
    frame_prompts = _comic_storyboard_image_frame_prompts(workflow_mode, payload, frame_prompt_source)
    expected = 7 if workflow_mode == "multiframe" else 2
    if len(frame_prompts) != expected:
        _send_json_with_headers(handler, 502, {"detail": f"{workflow_mode} 提示词拆分失败：预期 {expected} 段，实际 {len(frame_prompts)} 段"})
        return True

    indexed_prompts = (
        [(requested_frame_index, frame_prompts[requested_frame_index - 1])]
        if requested_frame_index is not None
        else list(enumerate(frame_prompts, 1))
    )

    headers = _platform_api_proxy_headers(handler)
    task_ids = []
    billing_request_hashes = []
    first_payload = None
    billing_request_base = re.sub(
        r"[^a-zA-Z0-9._:-]+",
        "-",
        str(
            payload.get("billingRequestId")
            or payload.get("requestId")
            or payload.get("request_id")
            or f"aicanvas:comic-frame:{secrets.token_hex(16)}"
        ).strip(),
    )
    for index, frame_prompt in indexed_prompts:
        frame_payload = dict(payload)
        frame_payload["prompt"] = frame_prompt
        frame_payload["storyboard_image_prompt"] = frame_prompt
        if workflow_mode == "multiframe":
            frame_payload["action_grid_prompt"] = frame_prompt
        elif workflow_mode == "keyframes":
            if index == 1:
                frame_payload["start_frame_prompt"] = frame_prompt
                frame_payload["storyboard_image_prompt"] = frame_prompt
            elif index == 2:
                frame_payload["end_frame_prompt"] = frame_prompt
        frame_payload["quantity"] = 1
        frame_payload["count"] = 1
        frame_payload["workflow_mode"] = workflow_mode
        frame_payload["frame_index"] = index
        frame_payload["frameIndex"] = index
        billing_suffix = f":frame:{index}"
        frame_payload["billingRequestId"] = f"{billing_request_base[:120 - len(billing_suffix)]}{billing_suffix}"
        billing_request_hashes.append(
            hashlib.sha256(frame_payload["billingRequestId"].encode("utf-8")).hexdigest()[:12]
        )
        request_body = json.dumps(frame_payload, ensure_ascii=False).encode("utf-8")
        request = urllib.request.Request(upstream_url, data=request_body, headers=headers, method="POST")
        try:
            with urllib.request.urlopen(request, timeout=PLATFORM_API_PROXY_TIMEOUT_SECONDS) as response:
                response_body = response.read()
        except urllib.error.HTTPError as error:
            error_body = error.read()
            error_body = _rewrite_comic_display_media_proxy_response(path, error.headers, error_body)
            _json_log(
                "comic_generate_image_proxy_frame_failed",
                path=path,
                workflow_mode=workflow_mode,
                frame_index=index,
                upstream_status=int(error.code),
            )
            _send_platform_proxy_response(handler, int(error.code), error.headers, error_body)
            return True
        try:
            response_payload = json.loads(response_body.decode("utf-8"))
        except Exception:
            response_payload = {}
        task_id = _comic_proxy_task_id_from_response(response_payload)
        if not task_id:
            _json_log("comic_generate_image_proxy_frame_missing_task", path=path, workflow_mode=workflow_mode, frame_index=index)
            _send_json_with_headers(handler, 502, {"detail": f"第 {index} 帧提交后平台未返回 task_id"})
            return True
        if first_payload is None:
            first_payload = response_payload if isinstance(response_payload, dict) else {}
        task_ids.append(task_id)
        storyboard_match = re.fullmatch(r"/api/v1/comic-drama/storyboards/(\d+)/generate-image", route_path)
        _register_comic_frame_task_overlay(
            task_id,
            storyboard_match.group(1) if storyboard_match else "",
            workflow_mode,
            index,
        )

    data = dict((first_payload or {}).get("data") or {}) if isinstance((first_payload or {}).get("data"), dict) else {}
    data["task_id"] = task_ids[0]
    data["task_ids"] = task_ids
    payload_out = dict(first_payload or {})
    payload_out["data"] = data
    _json_log(
        "comic_generate_image_proxy_frame_tasks_submitted",
        path=path,
        workflow_mode=workflow_mode,
        model=model,
        task_count=len(task_ids),
        task_ids=task_ids,
        billing_request_hashes=billing_request_hashes,
        prompt_hashes=[hashlib.sha256(text.encode("utf-8")).hexdigest()[:12] for _, text in indexed_prompts],
    )
    _send_json_with_headers(handler, 200, _comic_display_media_payload(payload_out))
    return True


def _rewrite_sso_ticket_canvas_url(path, body):
    """把平台 sso-ticket 响应里的 canvas_url 改写成本机同域画布，
    让首页画布入口跳转到集成的 /canvas（而非外部独立画布域名），
    从而复用同域登录态。仅改写 canvas_url，不动票据本身。"""
    if str(path or "") != "/api/v1/aicanvas/sso-ticket":
        return body
    local_url = AICANVAS_LOCAL_CANVAS_URL or "/canvas"
    try:
        payload = json.loads(body.decode("utf-8") if isinstance(body, (bytes, bytearray)) else body)
    except Exception:
        return body
    if not isinstance(payload, dict):
        return body
    if payload.get("ticket") or (isinstance(payload.get("data"), dict) and payload["data"].get("ticket")):
        # 无论上游是否返回 canvas_url，都强制注入本地画布地址
        payload["canvas_url"] = local_url
        if isinstance(payload.get("data"), dict):
            payload["data"]["canvas_url"] = local_url
        return json.dumps(payload, ensure_ascii=False).encode("utf-8")
    return body


def _parse_json_bytes(raw):
    try:
        data = json.loads(raw.decode("utf-8") if isinstance(raw, (bytes, bytearray)) else raw or "{}")
    except Exception:
        return {}
    return data if isinstance(data, dict) else {}


def _password_login_challenge_message(payload):
    detail = ""
    if isinstance(payload, dict):
        detail = payload.get("detail") or payload.get("error") or payload.get("message") or ""
        if isinstance(detail, list):
            detail = " ".join(str(item) for item in detail)
    message = str(detail or "")
    if any(word in message for word in ("验证码", "短信", "绑定手机号", "手机号登录")):
        return message
    return ""


def _local_password_login_user(username):
    username = str(username or "").strip()
    return {
        "id": 0,
        "user_id": 0,
        "username": username or "local-dev",
        "nickname": username or "本地开发",
        "avatar": "",
        "member_level": "free",
        "memberLevel": "free",
        "is_verified": True,
        "localDev": True,
        "local_password_login": True,
    }


_CANVAS_SESSION_AUTH_PATHS = {
    "/api/v1/auth/login/password",
    "/api/v1/auth/login/phone",
    "/api/v1/auth/register/password",
}


def _nested_dict_value(payload, *keys):
    current = payload if isinstance(payload, dict) else {}
    for key in keys:
        if not isinstance(current, dict):
            return None
        current = current.get(key)
    return current


def _extract_platform_auth_token(payload):
    payload = payload if isinstance(payload, dict) else {}
    for key in ("access_token", "token", "platform_access_token", "jwt"):
        value = str(payload.get(key) or "").strip()
        if value:
            return value
    data = payload.get("data")
    if isinstance(data, dict):
        for key in ("access_token", "token", "platform_access_token", "jwt"):
            value = str(data.get(key) or "").strip()
            if value:
                return value
        auth = data.get("auth")
        if isinstance(auth, dict):
            for key in ("access_token", "token", "platform_access_token", "jwt"):
                value = str(auth.get(key) or "").strip()
                if value:
                    return value
    return ""


def _extract_platform_auth_user(payload):
    payload = payload if isinstance(payload, dict) else {}
    candidates = (
        payload.get("user"),
        _nested_dict_value(payload, "data", "user"),
        _nested_dict_value(payload, "result", "user"),
        payload.get("data"),
    )
    for candidate in candidates:
        if isinstance(candidate, dict) and (candidate.get("id") or candidate.get("user_id")):
            return candidate
    return None


def _platform_auth_expires_at(payload):
    payload = payload if isinstance(payload, dict) else {}
    data = payload.get("data") if isinstance(payload.get("data"), dict) else {}
    for key in ("expires_at", "exp"):
        value = payload.get(key) or data.get(key)
        if value:
            try:
                return int(value)
            except Exception:
                pass
    for key in ("expires_in", "ttl"):
        value = payload.get(key) or data.get(key)
        if value:
            try:
                return int(time.time()) + int(value)
            except Exception:
                pass
    return int(time.time()) + int(AICANVAS_SESSION_TTL_SECONDS)


def _canvas_session_login_payload(response_payload, token, user):
    response_payload = response_payload if isinstance(response_payload, dict) else {}
    payload = {
        "access_token": token,
        "token": token,
        "token_type": "bearer",
        "expires_in": int(AICANVAS_SESSION_TTL_SECONDS),
        "user": user,
        "authenticated": True,
        "success": True,
    }
    for key in ("message", "detail", "code"):
        value = response_payload.get(key)
        if value not in (None, ""):
            payload[key] = value
    data = response_payload.get("data")
    if isinstance(data, dict):
        safe_data = {}
        for key in ("message", "detail", "code"):
            value = data.get(key)
            if value not in (None, ""):
                safe_data[key] = value
        nested_user = data.get("user")
        if isinstance(nested_user, dict):
            safe_data["user"] = user
        if safe_data:
            payload["data"] = safe_data
    return payload


def _canvas_session_login_response_from_upstream(path, method, status_code, response_body, request_body):
    route_path = str(path or "").split("?", 1)[0]
    if route_path not in _CANVAS_SESSION_AUTH_PATHS or str(method or "").upper() != "POST":
        return None
    response_payload = _parse_json_bytes(response_body)
    if int(status_code or 0) not in range(200, 300):
        return None
    upstream_token = _extract_platform_auth_token(response_payload)
    upstream_user = _extract_platform_auth_user(response_payload)
    if not upstream_token or not isinstance(upstream_user, dict):
        return None
    try:
        user_id = int(upstream_user.get("user_id") or upstream_user.get("id"))
    except Exception:
        return None
    if user_id <= 0:
        return None
    platform_session_id = _store_platform_session_token(upstream_token, _platform_auth_expires_at(response_payload))
    user = {
        "user_id": user_id,
        "id": user_id,
        "username": str(upstream_user.get("username") or ""),
        "nickname": str(upstream_user.get("nickname") or upstream_user.get("username") or upstream_user.get("phone") or ""),
        "phone": str(upstream_user.get("phone") or ""),
        "avatar": str(upstream_user.get("avatar") or ""),
        "platform_session_id": platform_session_id,
    }
    token = _make_canvas_session_token(user)
    payload = _canvas_session_login_payload(response_payload, token, user)
    _json_log(
        "auth_login_canvas_session",
        path=route_path,
        user_id=user_id,
        platform_session=bool(platform_session_id),
    )
    return token, payload


def _local_password_login_response_from_upstream(path, method, status_code, response_body, request_body):
    if str(path or "").split("?", 1)[0] != "/api/v1/auth/login/password" or str(method or "").upper() != "POST":
        return None
    request_payload = _parse_json_bytes(request_body)
    username = str(request_payload.get("username") or "").strip()
    password = str(request_payload.get("password") or "").strip()
    if not username or not password:
        return None

    response_payload = _parse_json_bytes(response_body)
    challenge = _password_login_challenge_message(response_payload)
    if int(status_code or 0) in range(200, 300):
        canvas_session = _canvas_session_login_response_from_upstream(path, method, status_code, response_body, request_body)
        if canvas_session:
            return canvas_session
        stale_flags = any(
            key in response_payload
            for key in ("need_bind_phone", "need_sms_code", "sms_code_required", "require_sms_code", "requires_sms_code")
        )
        if not challenge and not stale_flags:
            return None
    elif int(status_code or 0) not in {400, 401, 403} or not challenge:
        return None

    if AICANVAS_AUTH_REQUIRED:
        return None

    user = _local_password_login_user(username)
    token = _make_canvas_session_token(user)
    _json_log(
        "password_login_local_session",
        path="/api/v1/auth/login/password",
        username_present=bool(username),
        upstream_status=int(status_code or 0),
    )
    return token, {
        "access_token": token,
        "token": token,
        "token_type": "bearer",
        "expires_in": int(AICANVAS_SESSION_TTL_SECONDS),
        "user": user,
        "success": True,
        "authenticated": True,
        "localDev": True,
        "message": "登录成功",
    }


def _fetch_platform_json_for_current_request(handler, target_path, method="GET"):
    upstream_url = _platform_url(target_path)
    if not upstream_url:
        return 0, {}
    request = urllib.request.Request(
        upstream_url,
        headers=_platform_api_proxy_headers(handler),
        method=str(method or "GET").upper(),
    )
    try:
        with urllib.request.urlopen(request, timeout=min(PLATFORM_API_PROXY_TIMEOUT_SECONDS, 10)) as response:
            return int(response.status), _parse_platform_json(response.read())
    except urllib.error.HTTPError as error:
        return int(error.code), _parse_platform_json(error.read())
    except Exception as error:
        _json_log(
            "comic_model_catalog_upstream_error",
            target_path=target_path,
            method=method,
            error=repr(error),
        )
        return 0, {}


def _send_platform_json_for_current_request(handler, target_path, payload=None, method="PATCH"):
    upstream_url = _platform_url(target_path)
    if not upstream_url:
        return 0, {}
    headers = _platform_api_proxy_headers(handler)
    headers["Content-Type"] = "application/json"
    data = json.dumps(payload or {}, ensure_ascii=False).encode("utf-8")
    request = urllib.request.Request(
        upstream_url,
        data=data,
        headers=headers,
        method=str(method or "PATCH").upper(),
    )
    try:
        with urllib.request.urlopen(request, timeout=min(PLATFORM_API_PROXY_TIMEOUT_SECONDS, 10)) as response:
            return int(response.status), _parse_platform_json(response.read())
    except urllib.error.HTTPError as error:
        return int(error.code), _parse_platform_json(error.read())
    except Exception as error:
        _json_log(
            "platform_json_write_error",
            target_path=target_path,
            method=method,
            error=repr(error),
        )
        return 0, {}


def _read_json_body_object(handler):
    try:
        data = json.loads(_read_body(handler) or b"{}")
    except Exception:
        data = {}
    return data if isinstance(data, dict) else {}


AGENT_ASSET_KINDS = {
    "video_templates": {"label": "视频模版", "collection": "", "media": "video"},
    "character_images": {"label": "角色图", "collection": "characters", "media": "image"},
    "scene_images": {"label": "场景图", "collection": "scenes", "media": "image"},
    "prop_images": {"label": "道具图", "collection": "props", "media": "image"},
    "storyboard_images": {"label": "分镜图", "collection": "storyboards", "media": "image"},
    "storyboard_videos": {"label": "分镜视频", "collection": "storyboards", "media": "video"},
}


def _agent_asset_key(project_id, kind, item_id):
    return f"{int(project_id)}:{kind}:{item_id}"


def _agent_parse_asset_key(asset_key):
    parts = str(asset_key or "").split(":")
    if len(parts) != 3 or parts[1] not in AGENT_ASSET_KINDS:
        return None
    try:
        return int(parts[0]), parts[1], parts[2]
    except Exception:
        return None


def _agent_storyboard_image_urls(storyboard):
    refs = []
    for key in ("storyboard_image", "storyboardImage", "image_url", "imageUrl", "result_url", "resultUrl"):
        _extend_url_list(refs, storyboard.get(key) if isinstance(storyboard, dict) else "")
    if isinstance(storyboard, dict):
        for key in ("generatedImages", "generated_images", "image_history", "imageHistory"):
            _extend_url_list(refs, storyboard.get(key))
    return _dedupe_urls(refs)


def _agent_storyboard_video_urls(storyboard):
    refs = []
    if isinstance(storyboard, dict):
        for key in ("video_url", "videoUrl", "result_video_url", "resultVideoUrl", "video_history", "videoHistory"):
            _extend_url_list(refs, storyboard.get(key))
    return _dedupe_urls(refs)


def _agent_asset_media_urls(kind, item):
    if not isinstance(item, dict):
        return []
    if kind == "video_templates":
        return _dedupe_urls([
            _agent_video_template_url(item),
            item.get("thumbnail_url"),
            item.get("thumbnailUrl"),
            item.get("preview_url"),
        ])
    if kind == "storyboard_images":
        return _agent_storyboard_image_urls(item)
    if kind == "storyboard_videos":
        return _agent_storyboard_video_urls(item)
    refs = _local_comic_item_reference_urls(item)
    for key in ("thumbnail_url", "image_url", "imageUrl", "result_url", "resultUrl"):
        _extend_url_list(refs, item.get(key))
    return _dedupe_urls(refs)


def _agent_asset_name(kind, item):
    if not isinstance(item, dict):
        return ""
    candidates = [
        item.get("name"),
        item.get("title"),
        item.get("character_name"),
        item.get("characterName"),
        item.get("scene_name"),
        item.get("sceneName"),
        item.get("prop_name"),
        item.get("propName"),
        item.get("role"),
        item.get("type_name"),
    ]
    if kind.startswith("storyboard_"):
        sequence = item.get("sequence") or item.get("shot_number") or item.get("shotNo") or item.get("order") or item.get("id") or ""
        return _first_non_empty(
            *candidates,
            f"第 {sequence} 镜" if sequence else "",
            "分镜资产",
        )
    if kind == "video_templates":
        data = item.get("asset_data") if isinstance(item.get("asset_data"), dict) else {}
        return _first_non_empty(item.get("title"), item.get("name"), data.get("title"), data.get("name"), "视频模版")
    prompt = _first_non_empty(item.get("description"), item.get("base_prompt"), item.get("prompt"))
    prompt_title = str(prompt or "").strip(" ，。,.")[:12]
    return _first_non_empty(*candidates, prompt_title, AGENT_ASSET_KINDS[kind]["label"])


def _agent_asset_description(kind, item):
    if not isinstance(item, dict):
        return ""
    if kind.startswith("storyboard_"):
        return _first_non_empty(
            item.get("description"),
            item.get("storyboard_image_prompt"),
            item.get("image_prompt"),
            item.get("video_prompt"),
        )
    if kind == "video_templates":
        data = item.get("asset_data") if isinstance(item.get("asset_data"), dict) else {}
        return _first_non_empty(item.get("description"), data.get("prompt"), data.get("video_prompt"), data.get("videoPrompt"))
    return _first_non_empty(item.get("description"), item.get("base_prompt"), item.get("prompt"))


def _agent_asset_payload(project, kind, item):
    media_urls = _agent_asset_media_urls(kind, item)
    project_id = int(project.get("id") or 0)
    item_id = item.get("id") if isinstance(item, dict) else ""
    return {
        "asset_key": _agent_asset_key(project_id, kind, item_id),
        "id": item_id,
        "project_id": project_id,
        "kind": kind,
        "label": AGENT_ASSET_KINDS[kind]["label"],
        "name": _agent_asset_name(kind, item),
        "description": _agent_asset_description(kind, item),
        "status": str((item or {}).get("status") or ""),
        "thumbnail_url": media_urls[0] if media_urls else "",
        "media_url": media_urls[0] if media_urls else "",
        "reference_urls": media_urls,
        "is_favorite": bool((item or {}).get("is_favorite")),
        "source_mode": str(project.get("source_mode") or ""),
        "project_title": str(project.get("title") or ""),
        "created_at": str((item or {}).get("created_at") or project.get("created_at") or ""),
        "updated_at": str((item or {}).get("updated_at") or project.get("updated_at") or ""),
    }


AGENT_REFERENCE_KIND_BUCKETS = {
    "character_images": "character_reference_images",
    "scene_images": "scene_reference_images",
    "prop_images": "prop_reference_images",
    "storyboard_images": "storyboard_reference_images",
    "storyboard_videos": "storyboard_reference_images",
}
AGENT_LLM_REFERENCE_KINDS = {"scene_images", "character_images", "prop_images", "storyboard_images", "reference_image"}
AGENT_LLM_REFERENCE_USAGES = {"background", "scene", "character", "prop", "style", "reference"}


def _agent_reference_kind_label(kind):
    kind = str(kind or "").strip()
    meta = AGENT_ASSET_KINDS.get(kind)
    if isinstance(meta, dict):
        return str(meta.get("label") or "参考图")
    return "参考图"


def _agent_reference_url_from_value(value):
    if isinstance(value, dict):
        for key in ("media_url", "url", "src", "thumbnail_url", "image_url", "imageUrl", "reference_image", "video_url", "videoUrl"):
            found = _agent_reference_url_from_value(value.get(key))
            if found:
                return found
        return ""
    text = str(value or "").strip()
    if not text or text.lower() in {"undefined", "null", "none", "false", "0", "about:blank"}:
        return ""
    return text


def _agent_extend_reference_urls(items, value):
    if isinstance(value, list):
        for item in value:
            url = _agent_reference_url_from_value(item)
            if url:
                items.append(url)
        return
    url = _agent_reference_url_from_value(value)
    if url:
        items.append(url)


def _agent_reference_asset_from_value(value, fallback_kind="", source="legacy_payload"):
    raw = value if isinstance(value, dict) else {"media_url": value}
    refs = []
    for key in ("reference_urls", "reference_images", "referenceImages", "image_urls", "reference_image_urls"):
        _agent_extend_reference_urls(refs, raw.get(key))
    for key in ("media_url", "url", "thumbnail_url", "image_url", "reference_image", "video_url"):
        _agent_extend_reference_urls(refs, raw.get(key))
    refs = _dedupe_urls(refs)
    media_url = _first_non_empty(raw.get("media_url"), raw.get("url"), raw.get("thumbnail_url"), refs[0] if refs else "")
    if not media_url:
        return None
    kind = _first_non_empty(raw.get("kind"), fallback_kind, "reference_image")
    name = _first_non_empty(raw.get("name"), raw.get("title"), raw.get("label"), os.path.basename(urllib.parse.urlsplit(media_url).path), "参考图")
    label = _first_non_empty(raw.get("label"), _agent_reference_kind_label(kind))
    return {
        "asset_key": str(raw.get("asset_key") or ""),
        "kind": str(kind),
        "label": str(label),
        "name": str(name),
        "description": str(raw.get("description") or ""),
        "usage": str(raw.get("usage") or ""),
        "media_url": str(media_url),
        "reference_urls": refs or [str(media_url)],
        "source": str(raw.get("source") or source),
    }


def _agent_dedupe_reference_assets(items):
    result = []
    seen = set()
    for item in items:
        if not isinstance(item, dict):
            continue
        keys = []
        for value in (
            item.get("asset_key"),
            item.get("media_url"),
            (item.get("reference_urls") or [""])[0] if isinstance(item.get("reference_urls"), list) else "",
        ):
            text = str(value or "").strip()
            if text:
                keys.append(text)
        if not keys or any(key in seen for key in keys):
            continue
        seen.update(keys)
        result.append(item)
    return result


def _agent_reference_priority(asset):
    if not isinstance(asset, dict):
        return 99
    source = str(asset.get("source") or "").lower()
    kind = str(asset.get("kind") or "").lower()
    if source == "upload":
        return 0
    if kind == "reference_image" or source == "legacy_reference_image":
        return 1
    if source == "agent_asset":
        return 2
    return 3


def _agent_reference_intent_from_text(text):
    value = str(text or "")
    if re.search(r"背景|场景|环境|地点|室内|室外|街道|房间|天空|森林|城市|作为底图|当作底图", value):
        return {
            "usage": "background",
            "kind": "scene_images",
            "label": "场景图",
            "description": "用户指定作为背景/场景参考",
        }
    if re.search(r"人物|角色|主角|脸|发型|服装|穿着|形象", value):
        return {
            "usage": "character",
            "kind": "character_images",
            "label": "角色图",
            "description": "用户指定作为角色参考",
        }
    if re.search(r"道具|物品|装备|武器|工具|拿着|佩戴", value):
        return {
            "usage": "prop",
            "kind": "prop_images",
            "label": "道具图",
            "description": "用户指定作为道具参考",
        }
    return {}


def _agent_ordinal_value(value):
    text = str(value or "").strip()
    if text.isdigit():
        return int(text)
    numbers = {"一": 1, "二": 2, "两": 2, "三": 3, "四": 4, "五": 5, "六": 6, "七": 7, "八": 8, "九": 9, "十": 10}
    if text in numbers:
        return numbers[text]
    if len(text) == 2 and text.startswith("十") and text[1] in numbers:
        return 10 + numbers[text[1]]
    if len(text) == 2 and text.endswith("十") and text[0] in numbers:
        return numbers[text[0]] * 10
    if len(text) == 3 and text[1] == "十" and text[0] in numbers and text[2] in numbers:
        return numbers[text[0]] * 10 + numbers[text[2]]
    return 0


def _agent_reference_intents_by_index(text):
    value = str(text or "")
    pattern = re.compile(r"(第\s*([一二两三四五六七八九十\d]+)\s*(?:张|个)?\s*(?:图|图片)?|(?:图|图片)\s*([一二两三四五六七八九十\d]+)|([一二两三四五六七八九十\d]+)\s*(?:号)?\s*(?:图|图片))")
    matches = []
    for match in pattern.finditer(value):
        ordinal = _agent_ordinal_value(match.group(2) or match.group(3) or match.group(4))
        if ordinal > 0:
            matches.append((ordinal, match.start(), match.end()))
    intents = {}
    for index, (ordinal, start, end) in enumerate(matches):
        next_start = matches[index + 1][1] if index + 1 < len(matches) else min(len(value), end + 32)
        intent = _agent_reference_intent_from_text(value[start:next_start])
        if intent:
            intents[ordinal - 1] = intent
    return intents


def _agent_parse_json_object(text):
    text = str(text or "").strip()
    if not text:
        return {}
    try:
        parsed = json.loads(text)
        return parsed if isinstance(parsed, dict) else {}
    except Exception:
        pass
    match = re.search(r"\{.*\}", text, flags=re.DOTALL)
    if not match:
        return {}
    try:
        parsed = json.loads(match.group(0))
        return parsed if isinstance(parsed, dict) else {}
    except Exception:
        return {}


def _agent_normalize_llm_reference_intent(item):
    if not isinstance(item, dict):
        return {}
    kind = str(item.get("kind") or "").strip()
    usage = str(item.get("usage") or "").strip().lower()
    if usage in {"background", "scene", "environment"}:
        kind = "scene_images"
        label = "场景图"
        normalized_usage = "scene" if usage == "scene" else "background"
    elif usage in {"character", "person", "role"}:
        kind = "character_images"
        label = "角色图"
        normalized_usage = "character"
    elif usage in {"prop", "object", "item"}:
        kind = "prop_images"
        label = "道具图"
        normalized_usage = "prop"
    elif kind in AGENT_REFERENCE_KIND_BUCKETS or kind == "reference_image":
        label = _agent_reference_kind_label(kind)
        normalized_usage = usage if usage in AGENT_LLM_REFERENCE_USAGES else "reference"
    else:
        return {}
    if kind not in AGENT_LLM_REFERENCE_KINDS or normalized_usage not in AGENT_LLM_REFERENCE_USAGES:
        return {}
    return {
        "kind": kind,
        "label": label,
        "usage": normalized_usage,
        "description": str(item.get("description") or item.get("instruction") or "").strip(),
    }


def _agent_llm_reference_intents_by_index(payload, assets, prompt_text):
    if not assets or not str(prompt_text or "").strip():
        return {}
    model = _comic_media_model_for_project({}, payload if isinstance(payload, dict) else {}, "llm")
    refs = []
    for index, asset in enumerate(assets, 1):
        if not isinstance(asset, dict):
            continue
        refs.append({
            "index": index,
            "name": str(asset.get("name") or f"图{index}"),
            "kind": str(asset.get("kind") or "reference_image"),
            "usage": str(asset.get("usage") or ""),
            "description": str(asset.get("description") or "")[:160],
        })
    if not refs:
        return {}
    prompt = (
        "你只负责把用户关于参考图的人话转换成 JSON，不生成图片，不扩写剧情。\n"
        "根据用户文本和参考图顺序，判断每张图的用途。只允许 kind 为 "
        "scene_images、character_images、prop_images、storyboard_images、reference_image；"
        "usage 只允许 background、scene、character、prop、style、reference。\n"
        "如果不能确定某张图，就不要输出它。只输出 JSON："
        "{\"refs\":[{\"index\":1,\"kind\":\"scene_images\",\"usage\":\"background\",\"description\":\"作为背景参考\"}]}。\n\n"
        f"用户文本：{str(prompt_text)[:1200]}\n"
        f"参考图列表：{json.dumps(refs, ensure_ascii=False)}"
    )
    try:
        result = _call_local_ai_chat_completion(
            model,
            [
                {"role": "system", "content": "你是严格的 JSON 解析器，只输出可解析 JSON。"},
                {"role": "user", "content": prompt},
            ],
            description=f"云灵AI漫剧Agent参考图意图解析：{model}",
            source_payload={"prompt": prompt, "reference_count": len(refs)},
            temperature=0,
            response_format={"type": "json_object"},
        )
        data = _agent_parse_json_object(_extract_ai_chat_text(result))
        intents = {}
        for item in data.get("refs") or []:
            if not isinstance(item, dict):
                continue
            try:
                index = int(item.get("index")) - 1
            except Exception:
                continue
            if index < 0 or index >= len(assets):
                continue
            intent = _agent_normalize_llm_reference_intent(item)
            if intent:
                intents[index] = intent
        _json_log("agent_reference_llm_parse_completed", model=model, ref_count=len(refs), intent_count=len(intents))
        return intents
    except Exception as error:
        _json_log("agent_reference_llm_parse_failed", model=model, error=AiApiService.sanitize_error(repr(error)))
        return {}


def _agent_reference_needs_intent(asset):
    if not isinstance(asset, dict):
        return False
    kind = str(asset.get("kind") or "")
    usage = str(asset.get("usage") or "").strip()
    return kind == "reference_image" or not usage


def _agent_apply_reference_intent(asset, intent):
    if not isinstance(asset, dict) or not intent:
        return asset
    kind = str(asset.get("kind") or "")
    source = str(asset.get("source") or "")
    usage = str(asset.get("usage") or "")
    if usage and kind != "reference_image":
        return asset
    if kind != "reference_image" and source not in {"upload", "legacy_reference_image"}:
        return asset
    asset = dict(asset)
    asset["kind"] = str(intent.get("kind") or asset.get("kind") or "reference_image")
    asset["label"] = str(intent.get("label") or asset.get("label") or "参考图")
    asset["usage"] = str(intent.get("usage") or asset.get("usage") or "")
    if not str(asset.get("description") or "").strip():
        asset["description"] = str(intent.get("description") or "")
    return asset


def _agent_reference_context(reference_assets):
    lines = []
    for index, asset in enumerate(reference_assets or [], 1):
        if not isinstance(asset, dict):
            continue
        name = _first_non_empty(asset.get("name"), asset.get("label"), f"参考图{index}")
        kind = _first_non_empty(asset.get("label"), _agent_reference_kind_label(asset.get("kind")))
        description = str(asset.get("description") or "").strip()
        urls = _dedupe_urls(asset.get("reference_urls") or [asset.get("media_url")])
        detail = f"{index}. [{kind}] {name}"
        if description:
            detail += f"：{description}"
        if urls:
            detail += f"；参考图：{', '.join(urls[:3])}"
        lines.append(detail)
    if not lines:
        return ""
    return "参考资产上下文：\n" + "\n".join(lines)


def _normalize_agent_generate_references(payload):
    payload = payload if isinstance(payload, dict) else {}
    video_template = _normalize_agent_video_template(payload)
    if video_template:
        payload["video_template"] = video_template
        payload["videoTemplate"] = video_template
        payload["video_template_id"] = video_template.get("id") or ""
        payload["videoTemplateId"] = video_template.get("id") or ""
    assets = []
    reference_assets = payload.get("reference_assets") if isinstance(payload.get("reference_assets"), list) else []
    if not reference_assets and isinstance(payload.get("referenceAssets"), list):
        reference_assets = payload.get("referenceAssets")
    reference_images = payload.get("reference_images") if isinstance(payload.get("reference_images"), list) else []
    if not reference_images and isinstance(payload.get("referenceImages"), list):
        reference_images = payload.get("referenceImages")
    for value in reference_assets:
        asset = _agent_reference_asset_from_value(value, source="agent_asset")
        if asset:
            assets.append(asset)
    for value in reference_images:
        asset = _agent_reference_asset_from_value(value, fallback_kind="reference_image", source="legacy_reference_image")
        if asset:
            assets.append(asset)
    for kind, bucket in AGENT_REFERENCE_KIND_BUCKETS.items():
        bucket_values = payload.get(bucket) if isinstance(payload.get(bucket), list) else []
        for value in bucket_values:
            asset = _agent_reference_asset_from_value(value, fallback_kind=kind, source="typed_reference")
            if asset:
                assets.append(asset)

    prompt_text = "\n".join(
        str(payload.get(key) or "")
        for key in ("idea", "prompt", "message", "text", "reference_context")
        if payload.get(key)
    )
    intent = _agent_reference_intent_from_text(prompt_text)
    indexed_intents = _agent_reference_intents_by_index(
        prompt_text
    )
    if indexed_intents:
        assets = [
            _agent_apply_reference_intent(asset, indexed_intents.get(index))
            for index, asset in enumerate(assets)
        ]
    needs_llm = any(_agent_reference_needs_intent(asset) for asset in assets)
    if needs_llm:
        llm_intents = _agent_llm_reference_intents_by_index(payload, assets, prompt_text)
        if llm_intents:
            assets = [
                _agent_apply_reference_intent(asset, llm_intents.get(index)) if _agent_reference_needs_intent(asset) else asset
                for index, asset in enumerate(assets)
            ]
    assets = [
        _agent_apply_reference_intent(asset, intent) if _agent_reference_needs_intent(asset) else asset
        for asset in assets
    ]
    assets = sorted(_agent_dedupe_reference_assets(assets), key=_agent_reference_priority)
    all_refs = []
    typed_refs = {bucket: [] for bucket in set(AGENT_REFERENCE_KIND_BUCKETS.values())}
    for asset in assets:
        urls = _dedupe_urls(asset.get("reference_urls") or [asset.get("media_url")])
        asset["reference_urls"] = urls
        all_refs.extend(urls)
        bucket = AGENT_REFERENCE_KIND_BUCKETS.get(str(asset.get("kind") or ""))
        if bucket:
            typed_refs[bucket].extend(urls)

    payload["reference_assets"] = assets
    payload["referenceAssets"] = assets
    payload["reference_images"] = _dedupe_urls(all_refs)
    for bucket, refs in typed_refs.items():
        existing = payload.get(bucket) if isinstance(payload.get(bucket), list) else []
        payload[bucket] = _dedupe_urls([*existing, *refs])

    context = _agent_reference_context(assets)
    if context:
        existing_context = str(payload.get("reference_context") or "").strip()
        payload["reference_context"] = f"{existing_context}\n\n{context}".strip() if existing_context else context
        idea = str(payload.get("idea") or "").strip()
        if idea and context not in idea:
            payload["idea"] = f"{idea}\n\n{context}"
    _json_log(
        "agent_generate_references_normalized",
        reference_assets_count=len(assets),
        reference_images_count=len(payload.get("reference_images") or []),
        character_reference_images_count=len(payload.get("character_reference_images") or []),
        scene_reference_images_count=len(payload.get("scene_reference_images") or []),
        prop_reference_images_count=len(payload.get("prop_reference_images") or []),
        storyboard_reference_images_count=len(payload.get("storyboard_reference_images") or []),
        has_reference_context=bool(context),
    )
    return payload


def _agent_video_template_url(value):
    if isinstance(value, dict):
        data = value.get("asset_data") if isinstance(value.get("asset_data"), dict) else {}
        for key in ("video_url", "videoUrl", "reference_video", "referenceVideo", "template_video_url", "templateVideoUrl", "url"):
            found = _agent_video_template_url(value.get(key))
            if found:
                return found
            found = _agent_video_template_url(data.get(key))
            if found:
                return found
        return ""
    text = str(value or "").strip()
    if not text or text.lower() in {"undefined", "null", "none", "false", "0", "about:blank"}:
        return ""
    return text


def _agent_video_template_from_asset(asset):
    if not isinstance(asset, dict) or str(asset.get("asset_type") or "") != "video_template":
        return None
    data = asset.get("asset_data") if isinstance(asset.get("asset_data"), dict) else {}
    video_url = _agent_video_template_url(asset)
    prompt = _first_non_empty(
        data.get("prompt"),
        data.get("video_prompt"),
        data.get("videoPrompt"),
        asset.get("description"),
    )
    return {
        "id": f"asset-video-template-{asset.get('id')}",
        "asset_id": asset.get("id"),
        "title": _first_non_empty(asset.get("name"), "未命名视频模版"),
        "category": _first_non_empty(asset.get("category"), "视频模版"),
        "type": "video_template",
        "description": str(asset.get("description") or ""),
        "prompt": str(prompt or ""),
        "video_url": video_url,
        "thumbnail_url": _first_non_empty(
            asset.get("thumbnail_url"),
            asset.get("preview_url"),
            data.get("thumbnail_url"),
            data.get("thumbnailUrl"),
            data.get("cover_url"),
            data.get("coverUrl"),
        ),
        "replace_policy": str(data.get("replace_policy") or data.get("replacePolicy") or "character_only"),
        "source": "asset_library",
    }


def _agent_video_template_assets():
    templates = []
    current_scope = _agent_current_account_scope() if "_agent_current_account_scope" in globals() else ""
    for asset in LOCAL_COMIC_ASSETS.values():
        if not isinstance(asset, dict):
            continue
        owner_scope = _sanitize_account_scope(asset.get("account_scope") or asset.get("owner_scope") or asset.get("storage_scope"))
        if current_scope and (owner_scope != current_scope if owner_scope else current_scope not in {"local", "dev"}):
            continue
        if str(asset.get("status") or "active") == "archived":
            continue
        template = _agent_video_template_from_asset(asset)
        if template:
            templates.append(template)
    templates.sort(key=lambda item: str(item.get("updated_at") or item.get("title") or ""), reverse=True)
    return templates


def _normalize_agent_video_template(payload):
    payload = payload if isinstance(payload, dict) else {}
    template = payload.get("video_template") if isinstance(payload.get("video_template"), dict) else None
    if template is None and isinstance(payload.get("videoTemplate"), dict):
        template = payload.get("videoTemplate")
    template_id = str(payload.get("video_template_id") or payload.get("videoTemplateId") or "").strip()
    if template is None and template_id:
        for item in AGENT_TEMPLATE_SERVICE.list_templates(extra_templates=_agent_video_template_assets()).get("items") or []:
            if str(item.get("id") or "") == template_id:
                template = item
                break
    if not isinstance(template, dict):
        return {}
    normalized = {
        "id": str(template.get("id") or template_id or ""),
        "asset_id": template.get("asset_id"),
        "title": _first_non_empty(template.get("title"), template.get("name"), "视频模版"),
        "type": "video_template",
        "description": str(template.get("description") or ""),
        "prompt": str(template.get("prompt") or ""),
        "video_url": _agent_video_template_url(template),
        "thumbnail_url": _first_non_empty(template.get("thumbnail_url"), template.get("thumbnailUrl"), template.get("preview_url")),
        "replace_policy": str(template.get("replace_policy") or template.get("replacePolicy") or "character_only"),
        "source": str(template.get("source") or ""),
    }
    return normalized if normalized.get("id") or normalized.get("video_url") else {}


def _agent_video_template_instruction(template):
    if not isinstance(template, dict):
        return ""
    title = _first_non_empty(template.get("title"), "视频模版")
    prompt = str(template.get("prompt") or "").strip()
    return (
        f"套用视频模版「{title}」：保持模版视频的镜头节奏、构图、动作、运镜和表演方式；"
        "只替换为当前项目角色形象与当前分镜内容，不复用模版原人物身份、服装和脸部特征。"
        + (f" 模版要求：{prompt}" if prompt else "")
    )


def _agent_iter_assets():
    for project in _agent_visible_projects():
        if not isinstance(project, dict):
            continue
        for kind, meta in AGENT_ASSET_KINDS.items():
            if not meta.get("collection"):
                continue
            items = project.get(meta["collection"]) or []
            for item in items:
                if isinstance(item, dict):
                    yield project, kind, item


def _agent_video_template_asset_payload(asset):
    asset = asset if isinstance(asset, dict) else {}
    media_urls = _agent_asset_media_urls("video_templates", asset)
    asset_id = asset.get("id") or ""
    return {
        "asset_key": _agent_asset_key(0, "video_templates", asset_id or 0),
        "id": asset_id,
        "project_id": 0,
        "kind": "video_templates",
        "label": AGENT_ASSET_KINDS["video_templates"]["label"],
        "name": _agent_asset_name("video_templates", asset),
        "description": _agent_asset_description("video_templates", asset),
        "status": str(asset.get("status") or "active"),
        "thumbnail_url": media_urls[0] if media_urls else "",
        "media_url": media_urls[0] if media_urls else "",
        "reference_urls": media_urls,
        "is_favorite": bool(asset.get("is_favorite")),
        "source_mode": "asset_library",
        "project_title": "视频模版",
        "asset_type": "video_template",
        "type": "video_template",
        "created_at": str(asset.get("created_at") or ""),
        "updated_at": str(asset.get("updated_at") or ""),
    }


def _agent_find_asset(asset_key):
    parsed = _agent_parse_asset_key(urllib.parse.unquote(asset_key or ""))
    if not parsed:
        return None, "", None, None
    project_id, kind, item_id = parsed
    if kind == "video_templates":
        item = LOCAL_COMIC_ASSETS.get(int(item_id)) if str(item_id).isdigit() else None
        if isinstance(item, dict) and str(item.get("asset_type") or "") == "video_template":
            return None, kind, item, ""
        return None, kind, None, ""
    project = LOCAL_COMIC_PROJECTS.get(project_id)
    if not isinstance(project, dict):
        return None, kind, None, None
    collection = AGENT_ASSET_KINDS[kind]["collection"]
    item = _local_comic_find_by_id(project.get(collection), item_id)
    return project, kind, item, collection


def _agent_list_assets(handler):
    query = urllib.parse.urlsplit(getattr(handler, "path", "") or "").query
    params = urllib.parse.parse_qs(query, keep_blank_values=True)
    q = str((params.get("q") or [""])[0] or "").strip().lower()
    kind_filter = str((params.get("kind") or [""])[0] or "").strip()
    favorite_raw = str((params.get("favorite") or [""])[0] or "").strip().lower()
    favorite_only = favorite_raw in {"1", "true", "yes", "on"}
    categories = {kind: [] for kind in AGENT_ASSET_KINDS}
    current_scope = _agent_current_account_scope()
    for asset in LOCAL_COMIC_ASSETS.values():
        if not isinstance(asset, dict):
            continue
        owner_scope = _sanitize_account_scope(asset.get("account_scope") or asset.get("owner_scope") or asset.get("storage_scope"))
        if current_scope and (owner_scope != current_scope if owner_scope else current_scope not in {"local", "dev"}):
            continue
        if str(asset.get("asset_type") or "") != "video_template":
            continue
        if str(asset.get("status") or "active") == "archived":
            continue
        if kind_filter and kind_filter != "video_templates":
            continue
        payload = _agent_video_template_asset_payload(asset)
        if favorite_only and not payload["is_favorite"]:
            continue
        haystack = " ".join([payload["name"], payload["description"], payload["project_title"]]).lower()
        if q and q not in haystack:
            continue
        categories["video_templates"].append(payload)
    for project, kind, item in _agent_iter_assets():
        if kind_filter and kind != kind_filter:
            continue
        payload = _agent_asset_payload(project, kind, item)
        if favorite_only and not payload["is_favorite"]:
            continue
        haystack = " ".join([payload["name"], payload["description"], payload["project_title"]]).lower()
        if q and q not in haystack:
            continue
        categories[kind].append(payload)
    items = [asset for kind in AGENT_ASSET_KINDS for asset in categories[kind]]
    _json_log("agent_assets_listed", project_count=len(LOCAL_COMIC_PROJECTS), asset_count=len(items), kind_count=len(categories))
    return {"items": items, "categories": categories, "total": len(items)}


def _agent_update_asset_media(kind, item, media_url):
    media_url = str(media_url or "").strip()
    if not media_url:
        return
    if kind == "storyboard_videos":
        item["video_url"] = media_url
        item["video_history"] = _append_unique_url(item.get("video_history"), media_url)
        item["videoHistory"] = _append_unique_url(item.get("videoHistory"), media_url)
    elif kind == "video_templates":
        data = item.get("asset_data") if isinstance(item.get("asset_data"), dict) else {}
        data["video_url"] = media_url
        item["asset_data"] = data
        item["thumbnail_url"] = media_url
    elif kind == "storyboard_images":
        item["storyboard_image"] = media_url
        item["generatedImages"] = _append_unique_url(item.get("generatedImages"), media_url)
    else:
        item["reference_image"] = media_url
        item["reference_images"] = _append_unique_url(item.get("reference_images"), media_url)
        item["referenceImages"] = _append_unique_url(item.get("referenceImages"), media_url)
        if kind == "character_images":
            views = item.get("views") if isinstance(item.get("views"), dict) else {}
            views["front"] = media_url
            item["views"] = views


def _agent_patch_asset(handler, asset_key):
    project, kind, item, _collection = _agent_find_asset(asset_key)
    if not item:
        _send_json_with_headers(handler, 404, {"detail": "资产不存在"})
        return True
    if project is not None and not _agent_scope_allows_project(project):
        _send_json_with_headers(handler, 404, {"detail": "资产不存在"})
        return True
    if project is None and not _agent_scope_allows_standalone_asset(item):
        _send_json_with_headers(handler, 404, {"detail": "资产不存在"})
        return True
    payload = _read_json_body_object(handler)
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()
    for field in ("name", "description", "status"):
        if field in payload:
            item[field] = str(payload.get(field) or "")
    _agent_update_asset_media(kind, item, _first_non_empty(payload.get("media_url"), payload.get("thumbnail_url")))
    item["updated_at"] = now
    if isinstance(project, dict):
        project["updated_at"] = now
    _save_local_comic_state()
    _json_log("agent_asset_updated", asset_key=urllib.parse.unquote(asset_key or ""), kind=kind, project_id=project.get("id") if project else 0)
    data = _agent_video_template_asset_payload(item) if kind == "video_templates" else _agent_asset_payload(project, kind, item)
    _send_json_with_headers(handler, 200, {"data": data})
    return True


def _agent_toggle_asset_favorite(handler, asset_key):
    project, kind, item, _collection = _agent_find_asset(asset_key)
    if not item:
        _send_json_with_headers(handler, 404, {"detail": "资产不存在"})
        return True
    if project is not None and not _agent_scope_allows_project(project):
        _send_json_with_headers(handler, 404, {"detail": "资产不存在"})
        return True
    if project is None and not _agent_scope_allows_standalone_asset(item):
        _send_json_with_headers(handler, 404, {"detail": "资产不存在"})
        return True
    item["is_favorite"] = not bool(item.get("is_favorite"))
    item["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    if isinstance(project, dict):
        project["updated_at"] = item["updated_at"]
    _save_local_comic_state()
    _json_log("agent_asset_favorite_toggled", asset_key=urllib.parse.unquote(asset_key or ""), kind=kind, project_id=project.get("id") if project else 0, is_favorite=bool(item.get("is_favorite")))
    data = _agent_video_template_asset_payload(item) if kind == "video_templates" else _agent_asset_payload(project, kind, item)
    _send_json_with_headers(handler, 200, {"data": data})
    return True


def _agent_delete_asset(handler, asset_key):
    project, kind, item, collection = _agent_find_asset(asset_key)
    decoded_key = urllib.parse.unquote(asset_key or "")
    if not item:
        _send_json_with_headers(handler, 404, {"detail": "资产不存在"})
        return True
    if project is not None and not _agent_scope_allows_project(project):
        _send_json_with_headers(handler, 404, {"detail": "资产不存在"})
        return True
    if project is None and not _agent_scope_allows_standalone_asset(item):
        _send_json_with_headers(handler, 404, {"detail": "资产不存在"})
        return True
    _json_log("agent_asset_delete_requested", asset_key=decoded_key, project_id=project.get("id") if project else 0, kind=kind)
    if kind == "video_templates":
        try:
            LOCAL_COMIC_ASSETS.pop(int(item.get("id")), None)
        except Exception:
            pass
        _save_local_comic_state()
        _send_json_with_headers(handler, 200, {"data": {"deleted": decoded_key}})
        return True
    wanted = str(item.get("id"))
    project[collection] = [entry for entry in (project.get(collection) or []) if not (isinstance(entry, dict) and str(entry.get("id")) == wanted)]
    project["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    _save_local_comic_state()
    _send_json_with_headers(handler, 200, {"data": {"deleted": decoded_key}})
    return True


def _agent_current_account_scope():
    return _sanitize_account_scope(_get_request_account_scope())


def _agent_owner_scope_from_project(project):
    if not isinstance(project, dict):
        return ""
    for key in ("account_scope", "owner_scope", "storage_scope"):
        scope = _sanitize_account_scope(project.get(key))
        if scope:
            return scope
    session = project.get("agent_session") if isinstance(project.get("agent_session"), dict) else {}
    for key in ("account_scope", "owner_scope", "storage_scope"):
        scope = _sanitize_account_scope(session.get(key))
        if scope:
            return scope
    task_group_id = str(project.get("agent_task_group_id") or "")
    task_group = LOCAL_COMIC_TASKS.get(task_group_id)
    if isinstance(task_group, dict):
        for key in ("account_scope", "owner_scope", "storage_scope"):
            scope = _sanitize_account_scope(task_group.get(key))
            if scope:
                return scope
    return ""


def _agent_scope_allows_project(project):
    current_scope = _agent_current_account_scope()
    if not current_scope:
        return True
    owner_scope = _agent_owner_scope_from_project(project)
    if owner_scope:
        return owner_scope == current_scope
    return current_scope in {"local", "dev"}


def _agent_scope_allows_standalone_asset(asset):
    current_scope = _agent_current_account_scope()
    if not current_scope:
        return True
    if not isinstance(asset, dict):
        return False
    owner_scope = _sanitize_account_scope(asset.get("account_scope") or asset.get("owner_scope") or asset.get("storage_scope"))
    if owner_scope:
        return owner_scope == current_scope
    return current_scope in {"local", "dev"}


def _agent_visible_projects():
    return [project for project in LOCAL_COMIC_PROJECTS.values() if _agent_scope_allows_project(project)]


def _agent_project_by_id_for_current_scope(project_id):
    try:
        project = LOCAL_COMIC_PROJECTS.get(int(project_id or 0))
    except Exception:
        project = None
    return project if _agent_scope_allows_project(project) else None


def _agent_project_by_session_for_current_scope(session_id):
    wanted = str(session_id or "")
    for project in LOCAL_COMIC_PROJECTS.values():
        if not _agent_scope_allows_project(project):
            continue
        session = project.get("agent_session") if isinstance(project, dict) else None
        if isinstance(session, dict) and str(session.get("id") or "") == wanted:
            return project
    return None


def _agent_project_by_task_group_for_current_scope(task_group_id):
    task_group = LOCAL_COMIC_TASKS.get(str(task_group_id or ""))
    if not isinstance(task_group, dict):
        return None, None
    project = _agent_project_by_id_for_current_scope(task_group.get("project_id"))
    if not isinstance(project, dict):
        return None, None
    return project, task_group


def _agent_apply_current_scope_to_project(project):
    scope = _agent_current_account_scope()
    if not scope or not isinstance(project, dict):
        return
    project["account_scope"] = scope
    session = project.get("agent_session") if isinstance(project.get("agent_session"), dict) else None
    if isinstance(session, dict):
        session["account_scope"] = scope
    task_group_id = str(project.get("agent_task_group_id") or "")
    task_group = LOCAL_COMIC_TASKS.get(task_group_id)
    if isinstance(task_group, dict):
        task_group["account_scope"] = scope


def _agent_project_by_session_or_id(payload):
    payload = payload if isinstance(payload, dict) else {}
    session_id = str(payload.get("session_id") or payload.get("sessionId") or "").strip()
    project_id = str(payload.get("project_id") or payload.get("projectId") or "").strip()
    if project_id:
        project = _agent_project_by_id_for_current_scope(project_id)
        if isinstance(project, dict):
            return project
    if session_id:
        project = _agent_project_by_session_for_current_scope(session_id)
        if isinstance(project, dict):
            return project
    input_scope = str(payload.get("input_scope") or payload.get("inputScope") or "").strip().lower()
    if input_scope == "task":
        return _agent_latest_session_project()
    return None


def _agent_latest_session_project():
    candidates = []
    for project in _agent_visible_projects():
        if not isinstance(project, dict):
            continue
        session = project.get("agent_session")
        if not isinstance(session, dict) or not session.get("id"):
            continue
        updated_at = _first_non_empty(project.get("updated_at"), session.get("updated_at"), project.get("created_at"))
        candidates.append((str(updated_at or ""), project))
    if not candidates:
        return None
    candidates.sort(key=lambda item: item[0], reverse=True)
    return candidates[0][1]


def _agent_storyboard_context(project, limit=8):
    project = project if isinstance(project, dict) else {}
    lines = []
    for index, storyboard in enumerate((project.get("storyboards") or [])[:limit], 1):
        if not isinstance(storyboard, dict):
            continue
        text = _first_non_empty(
            storyboard.get("description"),
            storyboard.get("storyboard_image_prompt"),
            storyboard.get("image_prompt"),
            storyboard.get("video_prompt"),
        )
        if text:
            lines.append(f"{index}. {str(text).strip()[:220]}")
    if not lines:
        return "当前项目还没有可整理的分镜。"
    return "当前分镜摘要：\n" + "\n".join(lines)


def _agent_local_chat_intent(text):
    text = str(text or "").strip()
    if not text:
        return "chat"
    negative_generate_patterns = (
        r"(先)?(别|不要|不用|不必|不需要|先别|暂时别|暂时不要|无需).{0,12}(生成|出图|生图|做视频|生成视频|重做|继续生成)",
        r"(不是|并不是).{0,12}(要|让你|叫你).{0,12}(生成|出图|生图|做视频|生成视频)",
        r"(只|仅).{0,8}(聊|问|解释|说明|分析|整理|总结|讨论|看看|检查).{0,20}(不要|别|无需|不用).{0,12}(生成|出图|做视频)",
    )
    for pattern in negative_generate_patterns:
        if re.search(pattern, text):
            return "chat"
    discussion_patterns = (
        r"(怎么|如何|为什么|哪里|是否|是不是|能不能|可不可以|要不要|建议|觉得|怎么看).*(分镜|镜头|角色|场景|道具|视频|图片|生成|修改|改成|换成)",
        r"(讨论|聊聊|解释|说明|分析|检查|看看|评估).*(分镜|镜头|角色|场景|道具|视频|图片|方案|问题)",
    )
    for pattern in discussion_patterns:
        if re.search(pattern, text):
            return "chat"
    organize_patterns = (
        r"(整理|总结|梳理|归纳|分析|说明|列出).*(分镜|镜头|需求|要求|问题|计划)",
        r"(分镜|镜头).*(怎么|如何|需要|要求|建议|注意|哪里|为什么)",
    )
    for pattern in organize_patterns:
        if re.search(pattern, text):
            return "chat"
    workflow_patterns = (
        r"(开始|继续|重新|再|帮我|请|直接)?(生成|出图|生图|做视频|生成视频|重做|补视频).*(分镜|镜头|角色|场景|道具|视频|图片)",
        r"(第\s*[\d一二三四五六七八九十百两]+\s*(镜|个分镜|条分镜)|最后一镜|上一镜|下一镜|这个分镜|该分镜).{0,40}(生成|出图|做视频|重做|重新|改成|改为|换成|替换|替换为|删除|删掉|增加|追加|补充|扩写|缩短)",
        r"(把|将).{0,40}(分镜|镜头|角色|场景|道具|视频|图片).{0,40}(改成|改为|换成|替换|替换为|删除|删掉|增加|追加|补充|扩写|缩短|重做|重新生成)",
        r"(改成|改为|换成|替换|替换为|删除|删掉|增加|追加|补充|扩写|缩短|重做|重新生成).{0,40}(分镜|镜头|角色|场景|道具|视频|图片)",
        r"(按|照着|根据).{0,60}(生成|做出|产出|更新|修改|应用到).*(分镜|视频|图片|角色|场景|道具)",
    )
    for pattern in workflow_patterns:
        if re.search(pattern, text):
            return "generate"
    return "chat"


def _agent_chat_reply_fallback(project, user_text):
    text = str(user_text or "").strip()
    context = _agent_storyboard_context(project, limit=6)
    if re.search(r"(整理|总结|梳理|归纳|要求|需求|分镜|镜头)", text):
        return (
            "我先按当前项目整理分镜要求：\n"
            f"{context}\n\n"
            "后续如果要继续生成，可以直接说明目标分镜、画面变化、角色/场景/道具约束，以及是否要生成视频。"
        )
    return (
        "这条内容看起来不是生成指令，我先按对话回复，不会启动新的生成任务。\n"
        "如果你想继续做分镜，请告诉我要调整哪一镜、画面动作、角色状态、场景、道具和视频风格。"
    )


def _agent_llm_chat_decision(project, payload):
    payload = payload if isinstance(payload, dict) else {}
    user_text = str(payload.get("idea") or payload.get("message") or payload.get("text") or "").strip()
    project_config = project.get("config") if isinstance(project, dict) and isinstance(project.get("config"), dict) else {}
    model_config = project_config.get("modelConfig") if isinstance(project_config.get("modelConfig"), dict) else {}
    model = _comic_media_model_for_project(project, payload, "llm")
    local_intent = _agent_local_chat_intent(user_text)
    context = _agent_storyboard_context(project, limit=8)
    prompt = (
        "你是漫剧 Agent 的会话分流器和上下文理解器。判断用户这句话是否应该调用工作流。\n"
        "默认 intent=chat。只有用户明确发布可执行任务时，才能 intent=generate。\n"
        "可执行任务包括：生成、继续生成、重做、修改、替换、删除、追加、扩写、缩短分镜/图片/视频/角色/场景/道具。\n"
        "如果用户只是闲聊、提问、解释、整理当前分镜要求、总结问题、讨论方案、询问是否可行，必须是 chat。\n"
        "如果用户没有要求改变分镜内容、生成新素材或提交视频/图片工作流，必须是 chat。\n"
        "当 intent=generate 时，必须判断 workflow_target：characters=角色图/人物参考图，scenes=场景图/背景图/环境图，"
        "props=道具图，storyboard_images=分镜图/镜头画面/图片，storyboard_videos=分镜视频/镜头视频，"
        "full_flow=从分析到资产、分镜图、视频的完整流程，none=不调用工作流。\n"
        "workflow_instruction 必须完整保留用户的所有修改要求和个性化约束，包括颜色、背景、风格、构图、材质、"
        "角色/场景/道具变化、参考图使用方式、禁止项、数量、目标分镜或目标资产；不要只输出模板化动作。\n"
        "所有修改要求的优先级都高于当前分镜摘要、旧描述、旧 prompt 和参考素材的默认解读；旧内容只能作为主体和上下文参考。\n"
        "只输出 JSON："
        "{\"intent\":\"chat|generate\",\"actionable_change\":true|false,"
        "\"workflow_target\":\"none|characters|scenes|props|storyboard_images|storyboard_videos|full_flow\","
        "\"workflow_instruction\":\"可直接交给工作流执行的中文指令，没有则为空字符串\","
        "\"reply\":\"给用户的中文回复\"}。\n"
        "当 intent=chat 时，reply 要直接回答用户；如果用户要求整理分镜，就结合当前分镜摘要整理。"
        "当 intent=generate 时，actionable_change 必须为 true，workflow_target 不能是 none，"
        "workflow_instruction 必须包含明确目标、动作和用户所有约束，reply 简短说明将在当前任务中执行。\n\n"
        f"{context}\n\n用户输入：{user_text[:1200]}"
    )
    try:
        result = _call_local_ai_chat_completion(
            model,
            [
                {"role": "system", "content": "你是严格的 JSON 输出器，只输出可解析 JSON。"},
                {"role": "user", "content": prompt},
            ],
            project_id=int((project or {}).get("id") or 0),
            description=f"云灵AI漫剧Agent会话判断：{model}",
            source_payload={"prompt": prompt, "message": user_text},
            temperature=0,
            response_format={"type": "json_object"},
        )
        data = _agent_parse_json_object(_extract_ai_chat_text(result))
        intent = str(data.get("intent") or local_intent).strip().lower()
        if intent not in {"chat", "generate"}:
            intent = local_intent
        actionable_change = bool(data.get("actionable_change"))
        workflow_instruction = str(data.get("workflow_instruction") or "").strip()
        workflow_target = str(data.get("workflow_target") or "").strip().lower()
        allowed_targets = {"none", "characters", "scenes", "props", "storyboard_images", "storyboard_videos", "full_flow"}
        if workflow_target not in allowed_targets:
            workflow_target = _agent_directed_workflow_target(workflow_instruction or user_text) or ("full_flow" if intent == "generate" else "none")
        if intent == "generate" and (
            (local_intent == "chat" and (not actionable_change or not workflow_instruction))
            or workflow_target == "none"
        ):
            intent = "chat"
            workflow_target = "none"
        reply = str(data.get("reply") or "").strip()
        if not reply:
            reply = _agent_chat_reply_fallback(project, user_text) if intent == "chat" else "已识别为生成需求，准备进入生成流程。"
        return {
            "intent": intent,
            "reply": reply,
            "model": model,
            "fallback": False,
            "actionable_change": actionable_change,
            "workflow_instruction": workflow_instruction,
            "workflow_target": workflow_target,
        }
    except Exception as error:
        _json_log("agent_chat_llm_failed", model=model, error=AiApiService.sanitize_error(repr(error)))
        workflow_target = _agent_directed_workflow_target(user_text) if local_intent == "generate" else "none"
        return {
            "intent": local_intent,
            "reply": _agent_chat_reply_fallback(project, user_text) if local_intent == "chat" else "已识别为生成需求，准备进入生成流程。",
            "model": model,
            "fallback": True,
            "actionable_change": local_intent == "generate",
            "workflow_instruction": user_text if local_intent == "generate" else "",
            "workflow_target": workflow_target or ("full_flow" if local_intent == "generate" else "none"),
        }


def _agent_handle_existing_session_message(handler, raw_payload):
    project = _agent_project_by_session_or_id(raw_payload)
    if not isinstance(project, dict):
        return False
    user_text = str((raw_payload or {}).get("idea") or (raw_payload or {}).get("message") or (raw_payload or {}).get("text") or "").strip()
    if not user_text:
        return False
    decision = _agent_llm_chat_decision(project, raw_payload)
    _agent_append_session_message(project, "user", user_text, stage="chat", status="info")
    session = project.get("agent_session") if isinstance(project.get("agent_session"), dict) else {}
    task_group_id = str(project.get("agent_task_group_id") or "")
    task_group = LOCAL_COMIC_TASKS.get(task_group_id)

    if decision.get("intent") == "generate":
        if not isinstance(session, dict) or not session.get("id") or not task_group:
            _agent_append_session_message(
                project,
                "agent",
                "我识别到这是继续生成/修改请求，但当前会话缺少可继续执行的任务组。为避免跳到新任务，我没有启动新任务。请重新载入该任务后再发送。",
                stage="chat",
                status="failed",
            )
            project["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
            _save_local_comic_state()
            _send_json_with_headers(
                handler,
                409,
                {
                    "detail": "当前会话缺少任务组，无法继续生成；已阻止新建任务。",
                    "data": {
                        "chat_only": True,
                        "blocked_new_task": True,
                        "project_id": project.get("id"),
                        "session_id": session.get("id") if isinstance(session, dict) else "",
                        "task_group_id": task_group_id,
                        "messages": list(session.get("messages") or []) if isinstance(session, dict) else [],
                    },
                },
            )
            return True
        task_group = AGENT_TASK_SERVICE.create_task_group(
            project_id=project.get("id"),
            session_id=session.get("id"),
            task_group_id=f"agent-task-group-{project.get('id')}-continue-{int(time.time() * 1000)}",
            task_name="Agent 当前会话继续生成",
            stage_order=[],
        )
        task_group_id = str(task_group.get("id") or task_group_id)
        project["agent_task_group_id"] = task_group_id
        _agent_apply_current_scope_to_project(project)
        _agent_append_session_message(project, "agent", decision.get("reply") or "已识别为生成需求，将在当前任务中继续生成。", stage="chat", status="running")
        if isinstance(task_group, dict):
            task_group["status"] = "running"
            task_group["state"] = "running"
            task_group["current_step"] = "当前会话继续生成"
            task_group["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        project["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        _save_local_comic_state()
        payload = _normalize_agent_generate_references(raw_payload)
        workflow_instruction = str(decision.get("workflow_instruction") or "").strip() or user_text
        payload["idea"] = workflow_instruction
        payload["workflow_instruction"] = workflow_instruction
        payload["workflow_target"] = str(decision.get("workflow_target") or "").strip()
        payload["agent_modify_priority"] = True
        threading.Thread(
            target=_run_agent_directed_workflow_for_scope,
            args=(_agent_current_account_scope(), project["id"], task_group_id, session["id"], payload),
            daemon=True,
            name=f"AgentOrchestration-continue-{project['id']}",
        ).start()
        _json_log(
            "agent_existing_session_continue_generate",
            project_id=project.get("id"),
            session_id=session.get("id"),
            task_group_id=task_group_id,
            model=decision.get("model"),
            fallback=bool(decision.get("fallback")),
        )
        _send_json_with_headers(
            handler,
            200,
            {
                "data": {
                    "chat_only": False,
                    "continued": True,
                    "project_id": project.get("id"),
                    "session_id": session.get("id"),
                    "task_group_id": task_group_id,
                    "task_group": AGENT_TASK_SERVICE.build_group_payload(task_group),
                    "messages": list(session.get("messages") or []),
                }
            },
        )
        return True

    _agent_append_session_message(project, "agent", decision.get("reply") or "", stage="chat", status="completed")
    project["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    _save_local_comic_state()
    _json_log(
        "agent_chat_message_replied",
        project_id=project.get("id"),
        session_id=session.get("id"),
        intent=decision.get("intent"),
        model=decision.get("model"),
        fallback=bool(decision.get("fallback")),
    )
    _send_json_with_headers(
        handler,
        200,
        {
            "data": {
                "chat_only": True,
                "project_id": project.get("id"),
                "session_id": session.get("id"),
                "task_group_id": task_group_id,
                "task_group": AGENT_TASK_SERVICE.build_group_payload(task_group) if task_group else {},
                "messages": list(session.get("messages") or []),
            }
        },
    )
    return True


def _handle_agent_api_request(handler, path, method):
    method = str(method or "").upper()
    path = str(path or "").split("?", 1)[0]

    if method == "GET" and path == "/api/v1/comic-drama/agent/assets":
        _send_json_with_headers(handler, 200, {"data": _agent_list_assets(handler)})
        return True

    asset_match = re.fullmatch(r"/api/v1/comic-drama/agent/assets/([^/]+)", path)
    if asset_match and method == "PATCH":
        return _agent_patch_asset(handler, asset_match.group(1))
    if asset_match and method == "DELETE":
        return _agent_delete_asset(handler, asset_match.group(1))

    favorite_match = re.fullmatch(r"/api/v1/comic-drama/agent/assets/([^/]+)/favorite", path)
    if favorite_match and method == "POST":
        return _agent_toggle_asset_favorite(handler, favorite_match.group(1))

    if method == "GET" and path == "/api/v1/comic-drama/agent/templates":
        _send_json_with_headers(
            handler,
            200,
            {"data": AGENT_TEMPLATE_SERVICE.list_templates(extra_templates=_agent_video_template_assets())},
        )
        return True

    if method == "GET" and path == "/api/v1/comic-drama/agent/sessions":
        _send_json_with_headers(handler, 200, {"data": AGENT_ORCHESTRATION_SERVICE.list_sessions(projects=_agent_visible_projects())})
        return True

    session_delete_match = re.fullmatch(r"/api/v1/comic-drama/agent/sessions/([^/]+)", path)
    if method == "DELETE" and session_delete_match:
        session_id = urllib.parse.unquote(session_delete_match.group(1))
        deleted = False
        for pid, project in list(LOCAL_COMIC_PROJECTS.items()):
            if not _agent_scope_allows_project(project):
                continue
            sess = project.get("agent_session")
            if isinstance(sess, dict) and str(sess.get("id")) == session_id:
                del LOCAL_COMIC_PROJECTS[pid]
                tg_id = project.get("agent_task_group_id")
                if tg_id and tg_id in LOCAL_COMIC_TASKS:
                    del LOCAL_COMIC_TASKS[tg_id]
                deleted = True
                break
        if not deleted:
            _send_json_with_headers(handler, 404, {"detail": "会话不存在"})
            return True
        _save_local_comic_state()
        _send_json_with_headers(handler, 200, {"data": {"deleted": session_id}})
        return True

    task_cancel_match = re.fullmatch(r"/api/v1/comic-drama/agent/tasks/([^/]+)/cancel", path)
    if method == "POST" and task_cancel_match:
        task_group_id = urllib.parse.unquote(task_cancel_match.group(1))
        project, task_group = _agent_project_by_task_group_for_current_scope(task_group_id)
        if not task_group:
            _send_json_with_headers(handler, 404, {"detail": "任务组不存在"})
            return True
        _agent_mark_task_group_cancelled(task_group, "已取消生成，后续步骤不会继续提交")
        try:
            project_id = int(task_group.get("project_id") or 0)
        except Exception:
            project_id = 0
        if project:
            _agent_append_session_message(project, "agent", "已取消生成，已提交的任务可能仍会返回结果，但不会继续进入下一步。", stage="cancelled", status="cancelled")
        _save_local_comic_state()
        _send_json_with_headers(handler, 200, {"data": AGENT_TASK_SERVICE.build_group_payload(task_group)})
        return True

    task_group_match = re.fullmatch(r"/api/v1/comic-drama/agent/tasks/([^/]+)", path)
    if method == "GET" and task_group_match:
        task_group_id = urllib.parse.unquote(task_group_match.group(1))
        project, task_group = _agent_project_by_task_group_for_current_scope(task_group_id)
        if not task_group:
            _send_json_with_headers(handler, 404, {"detail": "任务组不存在"})
            return True
        try:
            agent_project_id = int(task_group.get("project_id") or 0)
        except Exception:
            agent_project_id = 0
        if agent_project_id:
            _refresh_ai_comic_tasks_for_project(agent_project_id, only_frame_tasks=False)
            _apply_completed_ai_comic_results_for_project(agent_project_id)
        payload = AGENT_TASK_SERVICE.build_group_payload(task_group)
        messages = AGENT_ORCHESTRATION_SERVICE.get_session_messages(payload.get("session_id") or task_group.get("session_id"))
        has_done_message = any(
            str(message.get("stage") or "").lower() == "done"
            and str(message.get("status") or "").lower() == "completed"
            for message in messages
            if isinstance(message, dict)
        )
        if has_done_message and str(task_group.get("status") or task_group.get("state") or "").lower() not in {"running", "pending"}:
            for stage in payload.get("stages") or []:
                if stage.get("status") == "pending":
                    stage["status"] = "completed"
                    stage["current_step"] = "已完成"
                    stage["progress_percent"] = 100
            payload["status"] = "completed"
            payload["state"] = "completed"
            payload["progress_percent"] = 100
            payload["current_step"] = "任务完成"
            task_group["status"] = "completed"
            task_group["state"] = "completed"
            task_group["progress_percent"] = 100
            task_group["current_step"] = "任务完成"
            _save_local_comic_state()
        _sync_ai_comic_project_results_to_platform(handler, agent_project_id or task_group.get("project_id"))
        _send_json_with_headers(handler, 200, {"data": payload})
        return True

    session_match = re.fullmatch(r"/api/v1/comic-drama/agent/sessions/([^/]+)/messages", path)
    if method == "GET" and session_match:
        session_id = urllib.parse.unquote(session_match.group(1))
        project = _agent_project_by_session_for_current_scope(session_id)
        if not project:
            _send_json_with_headers(handler, 404, {"detail": "会话不存在"})
            return True
        session = project.get("agent_session") if isinstance(project.get("agent_session"), dict) else {}
        _send_json_with_headers(handler, 200, {"data": list(session.get("messages") or [])})
        return True

    if method == "POST" and path == "/api/v1/comic-drama/agent/generate":
        raw_payload = _read_json_body_object(handler)
        if _agent_handle_existing_session_message(handler, raw_payload):
            return True
        payload = _normalize_agent_generate_references(raw_payload)
        idea = str(payload.get("idea") or "").strip()
        if not idea:
            _send_json_with_headers(handler, 400, {"detail": "请先输入一个想法"})
            return True
        input_scope = str(raw_payload.get("input_scope") or raw_payload.get("inputScope") or "").strip().lower() if isinstance(raw_payload, dict) else ""
        if input_scope == "task":
            local_intent = _agent_local_chat_intent(idea)
            if local_intent == "chat":
                _send_json_with_headers(
                    handler,
                    200,
                    {
                        "data": {
                            "chat_only": True,
                            "blocked_new_task": True,
                            "project_id": "",
                            "session_id": "",
                            "task_group_id": "",
                            "messages": [
                                {
                                    "id": f"agent-chat-{int(time.time() * 1000)}",
                                    "role": "agent",
                                    "text": _agent_chat_reply_fallback({}, idea),
                                    "stage": "chat",
                                    "status": "completed",
                                    "created_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
                                }
                            ],
                        }
                    },
                )
                return True
            _send_json_with_headers(
                handler,
                409,
                {
                    "detail": "找不到当前任务会话，已阻止新建任务。请重新载入当前任务后再发送。",
                    "data": {
                        "chat_only": True,
                        "blocked_new_task": True,
                        "project_id": "",
                        "session_id": "",
                        "task_group_id": "",
                        "messages": [],
                    },
                },
            )
            return True
        result = AGENT_ORCHESTRATION_SERVICE.create_session(payload=payload)
        _agent_apply_current_scope_to_project(result.get("project"))
        project_config = result["project"].setdefault("config", {})
        if isinstance(project_config, dict):
            project_config["reference_images"] = _dedupe_urls(payload.get("reference_images") or [])
            project_config["reference_assets"] = payload.get("reference_assets") if isinstance(payload.get("reference_assets"), list) else []
            project_config["reference_context"] = str(payload.get("reference_context") or "")
            if isinstance(payload.get("video_template"), dict):
                project_config["agentVideoTemplate"] = payload.get("video_template")
                if isinstance(result.get("session"), dict):
                    result["session"]["video_template"] = payload.get("video_template")
            _save_local_comic_state()
        # Start background orchestration thread to auto-advance remaining stages
        threading.Thread(
            target=_run_agent_orchestration_for_scope,
            args=(_agent_current_account_scope(), result["project"]["id"], result["task_group"]["id"], result["session"]["id"], payload),
            daemon=True,
            name=f"AgentOrchestration-{result['project']['id']}",
        ).start()
        _send_json_with_headers(
            handler,
            200,
            {
                "data": {
                    "project_id": result["project"]["id"],
                    "session_id": result["session"]["id"],
                    "task_group_id": result["task_group"]["id"],
                    "project": _local_comic_project_response(result["project"], include_details=True),
                    "task_group": AGENT_TASK_SERVICE.build_group_payload(result["task_group"]),
                    "messages": list(result["session"].get("messages") or []),
                }
            },
        )
        return True

    return False


def _handle_comic_model_config_request(handler, path, method):
    method = str(method or "").upper()
    if method == "GET" and path in COMIC_MODEL_CATALOG_PATHS:
        kind, upstream_path = COMIC_MODEL_CATALOG_PATHS[path]
        multiframe_catalog = kind in {"image", "video"} and _comic_request_wants_multiframe_catalog(handler)
        if kind == "video":
            catalog = _build_comic_model_catalog_response(kind)
            catalog = _filter_priced_comic_model_catalog(catalog, kind)
            if multiframe_catalog:
                catalog = _filter_multiframe_reference_model_catalog(catalog, kind)
            _json_log(
                "comic_model_catalog_served",
                kind=kind,
                provider="ark-official-only",
                model_count=len(catalog.get("models") or []),
                multiframe=bool(multiframe_catalog),
                upstream_status="skipped",
            )
            _send_json_with_headers(handler, 200, catalog)
            return True
        if _use_ai_api_provider():
            try:
                catalog = AI_API_SERVICE.comic_model_catalog(kind)
                catalog = _merge_local_comic_models_into_catalog(catalog, kind)
                catalog = _filter_priced_comic_model_catalog(catalog, kind)
                if multiframe_catalog:
                    catalog = _filter_multiframe_reference_model_catalog(catalog, kind)
                _json_log(
                    "comic_model_catalog_served",
                    kind=kind,
                    provider="ai",
                    model_count=len(catalog.get("models") or []),
                    multiframe=bool(multiframe_catalog),
                    upstream_status=200,
                )
                _send_json_with_headers(handler, 200, catalog)
                return True
            except Exception as error:
                _json_log(
                    "ai_api_comic_model_catalog_failed",
                    kind=kind,
                    provider="ai",
                    error=AiApiService.sanitize_error(repr(error)),
                )
        status, upstream_payload = _fetch_platform_json_for_current_request(handler, upstream_path, "GET")
        catalog = _build_comic_model_catalog_response(
            kind,
            upstream_payload if status == 200 else None,
        )
        catalog = _merge_local_comic_models_into_catalog(catalog, kind)
        catalog = _filter_priced_comic_model_catalog(catalog, kind)
        if multiframe_catalog:
            catalog = _filter_multiframe_reference_model_catalog(catalog, kind)
        _json_log(
            "comic_model_catalog_served",
            kind=kind,
            model_count=len(catalog.get("models") or []),
            multiframe=bool(multiframe_catalog),
            upstream_status=status,
        )
        _send_json_with_headers(handler, 200, catalog)
        return True

    if method == "POST" and path == "/api/v1/comic-drama/model-probes":
        payload = _read_json_body_object(handler)
        model_id = _normalize_comic_model_id(payload.get("model_id") or payload.get("id") or payload.get("model"))
        model_type = str(payload.get("model_type") or payload.get("type") or "llm").strip().lower()
        kind = _normalize_comic_model_kind(model_type)
        if not model_id:
            _send_json_with_headers(handler, 400, {"success": False, "detail": "缺少 model_id", "localDev": True})
            return True
        if kind not in COMIC_LOCAL_MODEL_CATALOG:
            _send_json_with_headers(
                handler,
                400,
                {"success": False, "detail": f"不支持的模型类型：{model_type}", "localDev": True},
            )
            return True

        status = _comic_model_status(kind, model_id)
        ready = bool(status.get("executable"))
        actual_kind = status.get("actual_type")
        if ready:
            message = f"{model_id} 可执行，适配器：{status.get('adapter')}"
        elif actual_kind:
            message = (
                f"当前探测需要{_comic_model_kind_label(kind)}模型，但 {model_id} 是"
                f"{_comic_model_kind_label(actual_kind)}模型"
            )
        else:
            message = f"{model_id} 未配置在可见的{_comic_model_kind_label(kind)}模型目录中"
        _json_log(
            "comic_model_probe_served",
            kind=kind,
            model_id=model_id,
            provider="local-adapter-check",
            ready=ready,
            adapter=status.get("adapter"),
        )
        _send_json_with_headers(
            handler,
            200 if ready else 400,
            {
                "success": ready,
                "message": message,
                "detail": "" if ready else message,
                "data": {
                    "ready": ready,
                    "visible": bool(status.get("visible")),
                    "executable": ready,
                    "model_id": model_id,
                    "model_type": kind,
                    "actual_type": actual_kind,
                    "adapter": status.get("adapter"),
                    "message": message,
                },
                "localDev": True,
            },
        )
        return True

    if method == "POST" and path == "/api/v1/comic-drama/projects/readiness":
        payload = _read_json_body_object(handler)
        payload["llm_model"] = _normalize_priced_comic_llm_model(payload.get("llm_model"))
        if _use_ai_api_provider():
            try:
                readiness = _merge_local_comic_readiness(
                    AI_API_SERVICE.comic_readiness(payload),
                    payload,
                )
                readiness = _allow_comic_analysis_readiness_without_media_models(readiness)
                readiness["model_status"] = _comic_readiness_model_statuses(payload)
                _json_log(
                    "comic_model_readiness_served",
                    provider="ai",
                    ready=bool(readiness.get("ready")),
                    llm_model=readiness.get("models", {}).get("llm_model"),
                    image_model=readiness.get("models", {}).get("image_model"),
                    video_model=readiness.get("models", {}).get("video_model"),
                )
                _send_json_with_headers(
                    handler,
                    200,
                    {
                        "success": True,
                        "message": "Project readiness checked",
                        "data": readiness,
                    },
                )
                return True
            except Exception as error:
                _json_log(
                    "ai_api_comic_readiness_failed",
                    provider="ai",
                    error=AiApiService.sanitize_error(repr(error)),
                )
        upstream_catalogs = {}
        for kind, upstream_path in (
            ("llm", "/comic-drama/llm-models"),
            ("image", "/comic-drama/image-models"),
            ("video", "/comic-drama/video-models"),
        ):
            status, upstream_payload = _fetch_platform_json_for_current_request(handler, upstream_path, "GET")
            if status == 200:
                upstream_catalogs[kind] = upstream_payload
        readiness = _build_comic_model_readiness_response(payload, upstream_catalogs)
        readiness = _allow_comic_analysis_readiness_without_media_models(readiness)
        readiness["model_status"] = _comic_readiness_model_statuses(payload)
        _json_log(
            "comic_model_readiness_served",
            ready=bool(readiness.get("ready")),
            llm_model=readiness.get("models", {}).get("llm_model"),
            image_model=readiness.get("models", {}).get("image_model"),
            video_model=readiness.get("models", {}).get("video_model"),
        )
        _send_json_with_headers(
            handler,
            200,
            {
                "success": True,
                "message": "Project readiness checked",
                "data": readiness,
            },
        )
        return True

    return False


def _send_platform_proxy_response(handler, status_code, upstream_headers, body, write_body=True, content_length=None):
    body = body or b""
    handler.send_response(int(status_code))
    content_type = ""
    try:
        content_type = upstream_headers.get("Content-Type") or upstream_headers.get("content-type") or ""
    except Exception:
        content_type = ""
    handler.send_header("Content-Type", content_type or "application/octet-stream")
    handler.send_header("Content-Length", str(len(body) if content_length is None else content_length))
    _send_cors_origin_header(handler)
    try:
        header_items = upstream_headers.items()
    except Exception:
        header_items = []
    for name, value in header_items:
        lower_name = str(name).lower()
        if lower_name in _PLATFORM_PROXY_HOP_BY_HOP_HEADERS:
            continue
        if lower_name in {
            "content-type",
            "content-length",
            "content-encoding",
            "access-control-allow-origin",
            "cache-control",
            "date",
            "server",
            "set-cookie",
            "vary",
        }:
            continue
        handler.send_header(str(name), str(value))
    handler.end_headers()
    if not write_body:
        return
    try:
        handler.wfile.write(body)
    except (BrokenPipeError, ConnectionResetError):
        pass


def _is_safe_remote_media_url(url):
    try:
        parsed = urllib.parse.urlsplit(str(url or "").strip())
    except Exception:
        return False
    if parsed.scheme not in {"http", "https"} or not parsed.netloc:
        return False
    host = (parsed.hostname or "").strip().lower()
    if not host or host in {"localhost", "0.0.0.0"} or host.endswith(".local"):
        return False
    try:
        ip = ipaddress.ip_address(host)
        return not (ip.is_loopback or ip.is_private or ip.is_link_local or ip.is_multicast or ip.is_reserved)
    except Exception:
        return True


def _handle_comic_video_url_proxy(handler, path, method):
    method = str(method or "GET").upper()
    if method not in {"GET", "HEAD"}:
        return False
    if str(path or "").split("?", 1)[0] != "/api/v1/comic-drama/video-proxy":
        return False
    query = urllib.parse.parse_qs(urllib.parse.urlsplit(getattr(handler, "path", "") or "").query, keep_blank_values=True)
    target_url = (query.get("url") or [""])[0]
    if not _is_safe_remote_media_url(target_url):
        _send_json_with_headers(handler, 400, {"detail": "视频地址不可用"})
        return True

    request_headers = {
        "User-Agent": "Yunling-AIHB-VideoProxy/1.0",
        "Accept": handler.headers.get("Accept") or "video/*,*/*",
        "Accept-Encoding": "identity",
    }
    range_header = handler.headers.get("Range")
    if range_header:
        request_headers["Range"] = range_header
    elif method == "HEAD":
        # Some signed object-storage URLs reject HEAD, while GET range is allowed.
        request_headers["Range"] = "bytes=0-0"

    request = urllib.request.Request(target_url, headers=request_headers, method="GET")
    try:
        with urllib.request.urlopen(request, timeout=PLATFORM_API_PROXY_TIMEOUT_SECONDS) as response:
            response_body = response.read()
            _send_platform_proxy_response(
                handler,
                int(response.status),
                response.headers,
                response_body,
                write_body=(method != "HEAD"),
            )
            return True
    except urllib.error.HTTPError as error:
        error_body = b"" if method == "HEAD" else error.read()
        _send_platform_proxy_response(
            handler,
            int(error.code),
            error.headers,
            error_body,
            write_body=(method != "HEAD"),
        )
        return True
    except Exception as error:
        _json_log("comic_video_url_proxy_error", error=repr(error))
        _send_json_with_headers(handler, 502, {"detail": "视频文件读取失败"})
        return True


def _rewrite_comic_display_media_proxy_response(path, upstream_headers, body):
    if not str(path or "").split("?", 1)[0].startswith("/api/v1/comic-drama"):
        return body
    try:
        content_type = str(upstream_headers.get("Content-Type") or upstream_headers.get("content-type") or "")
    except Exception:
        content_type = ""
    if body is None:
        return body
    raw = bytes(body or b"")
    stripped = raw.lstrip()
    if "json" not in content_type.lower() and not stripped.startswith((b"{", b"[")):
        return body
    try:
        payload = json.loads(raw.decode("utf-8"))
        normalized = _comic_display_media_payload(payload)
        if "/api/v1/comic-drama/" in str(path or ""):
            clean_path = str(path or "").split("?", 1)[0]
            project_match = re.search(r"/api/v1/comic-drama/projects/(\d+)", clean_path)
            project_tasks_match = re.fullmatch(r"/api/v1/comic-drama/projects/(\d+)/tasks", clean_path)
            if project_match:
                _refresh_ai_comic_project_tasks_for_response(int(project_match.group(1)))
            normalized = _normalize_comic_task_identity_fields(normalized)
            if project_tasks_match:
                normalized = _merge_ai_comic_project_tasks_into_payload(normalized, int(project_tasks_match.group(1)))
            _update_comic_frame_task_overlays_from_payload(normalized)
            normalized = _apply_comic_frame_task_overlays(normalized)
            normalized = _apply_ai_comic_task_results_to_payload(normalized)
        return json.dumps(normalized, ensure_ascii=False, indent=2).encode("utf-8")
    except Exception as error:
        _json_log("comic_display_media_proxy_rewrite_failed", path=path, error=repr(error))
        return body


def _handle_platform_api_proxy(handler, path, method):
    target_path = _platform_api_proxy_target(path)
    if not target_path:
        return False
    upstream_url = _platform_url(target_path)
    if not upstream_url:
        _send_json_with_headers(handler, 500, {"detail": "AICANVAS_PLATFORM_API_BASE is not configured"})
        return True
    query = urllib.parse.urlsplit(handler.path).query
    if query:
        upstream_url = f"{upstream_url}?{query}"

    body = None
    method = str(method or "GET").upper()
    if method not in {"GET", "HEAD"}:
        body = _read_body(handler, max_bytes=100 * 1024 * 1024)
        body, pending_workflow_mode = _rewrite_comic_workflow_request(path, method, body)
    else:
        pending_workflow_mode = ""

    if method == "POST" and _handle_comic_frame_generate_image_proxy(handler, path, upstream_url, body, pending_workflow_mode):
        return True

    prefer_canvas_bearer = (
        method == "GET"
        and str(path or "").split("?", 1)[0].rstrip("/") == "/api/v1/comic-drama/projects"
    )
    request = urllib.request.Request(
        upstream_url,
        data=body,
        headers=_platform_api_proxy_headers(handler, prefer_canvas_bearer=prefer_canvas_bearer),
        method=method,
    )
    try:
        with urllib.request.urlopen(request, timeout=PLATFORM_API_PROXY_TIMEOUT_SECONDS) as response:
            response_body = response.read()
            response_body = _rewrite_comic_workflow_response(path, method, response_body, pending_workflow_mode)
            response_body = _rewrite_sso_ticket_canvas_url(path, response_body)
            response_body = _rewrite_comic_display_media_proxy_response(path, response.headers, response_body)
            if method == "POST" and re.fullmatch(r"/api/v1/comic-drama/storyboards/\d+/generate-image", str(path or "").split("?", 1)[0]):
                task_count = 0
                task_id = ""
                try:
                    payload = json.loads(bytes(response_body or b"{}").decode("utf-8"))
                    data = payload.get("data") if isinstance(payload, dict) else None
                    source = data if isinstance(data, dict) else payload
                    task_ids = source.get("task_ids") if isinstance(source, dict) else None
                    task_id = str(source.get("task_id") or "") if isinstance(source, dict) else ""
                    task_count = len(task_ids) if isinstance(task_ids, list) else (1 if task_id else 0)
                except Exception:
                    pass
                _json_log(
                    "comic_generate_image_proxy_submitted",
                    path=path,
                    upstream_status=int(response.status),
                    workflow_mode=pending_workflow_mode,
                    task_count=task_count,
                    task_id=task_id,
                )
            canvas_session_login = _canvas_session_login_response_from_upstream(
                path,
                method,
                response.status,
                response_body,
                body,
            )
            if canvas_session_login:
                token, payload = canvas_session_login
                _send_json_with_headers(handler, 200, payload, {"Set-Cookie": _session_cookie_header(token)})
                return True
            local_password_login = _local_password_login_response_from_upstream(
                path,
                method,
                response.status,
                response_body,
                body,
            )
            if local_password_login:
                token, payload = local_password_login
                _send_json_with_headers(handler, 200, payload, {"Set-Cookie": _session_cookie_header(token)})
                return True
            _send_platform_proxy_response(handler, int(response.status), response.headers, response_body)
    except urllib.error.HTTPError as error:
        error_body = error.read()
        error_body = _rewrite_comic_workflow_response(path, method, error_body, pending_workflow_mode)
        error_body = _rewrite_comic_display_media_proxy_response(path, error.headers, error_body)
        canvas_session_login = _canvas_session_login_response_from_upstream(
            path,
            method,
            error.code,
            error_body,
            body,
        )
        if canvas_session_login:
            token, payload = canvas_session_login
            _send_json_with_headers(handler, 200, payload, {"Set-Cookie": _session_cookie_header(token)})
            return True
        local_password_login = _local_password_login_response_from_upstream(
            path,
            method,
            error.code,
            error_body,
            body,
        )
        if local_password_login:
            token, payload = local_password_login
            _send_json_with_headers(handler, 200, payload, {"Set-Cookie": _session_cookie_header(token)})
            return True
        _send_platform_proxy_response(handler, int(error.code), error.headers, error_body)
    except Exception as error:
        _json_log(
            "platform_api_proxy_error",
            path=path,
            method=method,
            error=repr(error),
        )
        _send_json_with_headers(handler, 502, {"detail": "平台服务调用失败"})
    return True


def _handle_comic_analyze_stream_proxy(handler, path):
    match = re.fullmatch(r"/api/v1/comic-drama/projects/(\d+)/analyze-stream", str(path or ""))
    if not match:
        return False
    project_id = match.group(1)

    token = _assistant_session_platform_token(handler)
    token_source = "session"
    if not token:
        user_id = _assistant_resolve_user_id(handler)
        if user_id <= 0:
            _json_err(handler, _assistant_missing_user_status(), "请先登录后再分析漫剧项目")
            return True
        token_source = "internal_mint"
        token, error = _assistant_mint_user_token(user_id)
        if not token:
            _json_log(
                "comic_analyze_stream_token_missing",
                project_id=project_id,
                source=token_source,
                internal_secret_configured=bool(AICANVAS_INTERNAL_SECRET),
                platform_api_configured=bool(AICANVAS_PLATFORM_API_BASE),
                error=error or "empty token",
            )
            _json_err(handler, 502, error or "无法获取平台访问令牌")
            return True

    target_path = f"/comic-drama/projects/{project_id}/analyze-stream"
    upstream_url = _platform_url(target_path)
    if not upstream_url:
        _send_json_with_headers(handler, 500, {"detail": "AICANVAS_PLATFORM_API_BASE is not configured"})
        return True

    raw_query = urllib.parse.urlsplit(getattr(handler, "path", "") or "").query
    query_pairs = [
        (key, value)
        for key, value in urllib.parse.parse_qsl(raw_query, keep_blank_values=True)
        if key != "token"
    ]
    query_pairs.append(("token", token))
    upstream_url = f"{upstream_url}?{urllib.parse.urlencode(query_pairs)}"

    headers = {
        "Accept": "text/event-stream",
        "User-Agent": "Yunling-AIHB-ComicGenerator/1.0",
    }
    accept_language = handler.headers.get("Accept-Language")
    if accept_language:
        headers["Accept-Language"] = accept_language
    request = urllib.request.Request(upstream_url, headers=headers, method="GET")

    try:
        upstream = urllib.request.urlopen(request, timeout=600)
    except urllib.error.HTTPError as error:
        try:
            detail = _parse_platform_json(error.read())
        except Exception:
            detail = {}
        _json_err(handler, int(error.code), _platform_error_message(detail, "平台漫剧分析服务返回错误"))
        return True
    except Exception as error:
        _json_log(
            "comic_analyze_stream_proxy_error",
            project_id=project_id,
            source=token_source,
            error=repr(error),
        )
        _json_err(handler, 502, f"无法连接平台漫剧分析服务：{repr(error)}")
        return True

    _json_log("comic_analyze_stream_proxy_started", project_id=project_id, source=token_source)
    try:
        handler.send_response(200)
        handler.send_header("Content-Type", "text/event-stream; charset=utf-8")
        handler.send_header("Cache-Control", "no-cache")
        handler.send_header("Connection", "keep-alive")
        handler.send_header("X-Accel-Buffering", "no")
        _send_cors_origin_header(handler)
        handler.end_headers()
        while True:
            chunk = upstream.read(1024)
            if not chunk:
                break
            try:
                handler.wfile.write(chunk)
                handler.wfile.flush()
            except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
                break
    except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
        pass
    finally:
        try:
            upstream.close()
        except Exception:
            pass
    return True


def _handle_platform_media_proxy(handler, path, method):
    method = str(method or "GET").upper()
    if method not in {"GET", "HEAD"}:
        return False
    target_path = _platform_media_proxy_target(path)
    if not target_path:
        return False

    local_path = ""
    try:
        if target_path.startswith("/uploads/"):
            local_path = os.path.abspath(os.path.join(_current_uploads_dir(), target_path[len("/uploads/"):].lstrip("/")))
            if not _is_path_inside(local_path, _current_uploads_dir()) or not os.path.isfile(local_path):
                local_path = ""
    except Exception:
        local_path = ""
    if local_path:
        try:
            stat = os.stat(local_path)
            handler.send_response(200)
            handler.send_header("Content-Type", mimetypes.guess_type(local_path)[0] or "application/octet-stream")
            handler.send_header("Content-Length", str(stat.st_size))
            handler.send_header("Accept-Ranges", "bytes")
            _send_cors_origin_header(handler)
            handler.end_headers()
            if method != "HEAD":
                with open(local_path, "rb") as file:
                    shutil.copyfileobj(file, handler.wfile)
        except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
            pass
        except Exception as error:
            _json_log("platform_media_local_file_error", path=target_path, error=repr(error))
            _send_json_with_headers(handler, 500, {"detail": "本地媒体文件读取失败"})
        return True

    upstream_urls = _platform_media_candidate_urls(target_path)
    if not upstream_urls:
        _send_json_with_headers(handler, 500, {"detail": "AICANVAS_PLATFORM_MEDIA_BASE is not configured"})
        return True
    query = urllib.parse.urlsplit(handler.path).query

    request_headers = {
        "User-Agent": "Yunling-AIHB-MediaProxy/1.0",
        "Accept": handler.headers.get("Accept") or "*/*",
    }
    range_header = handler.headers.get("Range")
    if range_header:
        request_headers["Range"] = range_header
    last_http_error = None
    for index, upstream_url in enumerate(upstream_urls):
        request_url = f"{upstream_url}?{query}" if query else upstream_url
        request = urllib.request.Request(
            request_url,
            headers=request_headers,
            method=method,
        )
        try:
            with urllib.request.urlopen(request, timeout=PLATFORM_API_PROXY_TIMEOUT_SECONDS) as response:
                response_body = b"" if method == "HEAD" else response.read()
                if index > 0:
                    _json_log("platform_media_proxy_fallback_hit", path=target_path, upstream=urllib.parse.urlsplit(upstream_url).netloc)
                _send_platform_proxy_response(handler, int(response.status), response.headers, response_body)
                return True
        except urllib.error.HTTPError as error:
            last_http_error = error
            if int(error.code) == 404 and index < len(upstream_urls) - 1:
                try:
                    error.read()
                except Exception:
                    pass
                continue
            error_body = b"" if method == "HEAD" else error.read()
            _send_platform_proxy_response(handler, int(error.code), error.headers, error_body)
            return True
        except Exception as error:
            _json_log(
                "platform_media_proxy_error",
                path=target_path,
                method=method,
                upstream=urllib.parse.urlsplit(upstream_url).netloc,
                error=repr(error),
            )
            if index < len(upstream_urls) - 1:
                continue
            _send_json_with_headers(handler, 502, {"detail": "平台媒体文件读取失败"})
            return True
    if last_http_error is not None:
        _send_json_with_headers(handler, int(last_http_error.code), {"detail": "平台媒体文件不存在"})
    else:
        _send_json_with_headers(handler, 502, {"detail": "平台媒体文件读取失败"})
    return True


def _handle_local_aicanvas_sso_ticket(handler, path, method):
    if str(method or "").upper() != "POST" or path != "/api/v1/aicanvas/sso-ticket":
        return False
    if AICANVAS_AUTH_REQUIRED or not AICANVAS_LOCAL_CANVAS_URL:
        return False
    _send_json_with_headers(
        handler,
        200,
        {
            "ticket": "local-dev",
            "expires_in": int(AICANVAS_SESSION_TTL_SECONDS),
            "canvas_url": AICANVAS_LOCAL_CANVAS_URL,
            "local": True,
        },
    )
    return True


_AIC_PRICE_CACHE = {"ts": 0.0, "data": None}


def _fetch_platform_model_prices():
    import time as _time
    now = _time.time()
    cached = _AIC_PRICE_CACHE.get("data")
    if cached is not None and (now - _AIC_PRICE_CACHE.get("ts", 0.0)) < 60:
        return cached
    try:
        status_code, data = _platform_json_request("/aicanvas/billing/prices", payload=None, method="GET", include_internal_secret=True, timeout=15)
    except Exception:
        status_code, data = 502, {}
    prices = []
    if int(status_code) == 200 and isinstance(data, dict) and data.get("success"):
        prices = data.get("prices") or []
    if prices:
        _AIC_PRICE_CACHE["data"] = prices
        _AIC_PRICE_CACHE["ts"] = now
    return prices


def _handle_model_prices_get(handler):
    try:
        prices = _fetch_platform_model_prices()
    except Exception:
        prices = []
    _send_json_with_headers(handler, 200, {"success": True, "prices": prices})


def _get_fresh_platform_user(session_payload):
    if not isinstance(session_payload, dict) or not session_payload.get("user_id"):
        return None, None
    status_code, data = _platform_json_request(
        "/aicanvas/internal/me",
        {"user_id": int(session_payload["user_id"])},
        include_internal_secret=True,
        timeout=20,
    )
    if status_code < 200 or status_code >= 300:
        return None, _platform_error_message(data, "获取平台用户信息失败")
    user = data.get("user") if isinstance(data, dict) else None
    return user if isinstance(user, dict) else None, None


def _session_payload_to_user(session_payload):
    if not isinstance(session_payload, dict):
        return {}
    return {
        "user_id": session_payload.get("user_id"),
        "id": session_payload.get("user_id"),
        "nickname": str(session_payload.get("nickname") or ""),
        "avatar": str(session_payload.get("avatar") or ""),
    }


def _make_billing_request_id(kind, user_id, model_id, source_payload=None):
    payload = source_payload if isinstance(source_payload, dict) else {}
    explicit = (
        payload.get("billingRequestId")
        or payload.get("requestId")
        or payload.get("request_id")
    )
    if explicit:
        cleaned = re.sub(r"[^a-zA-Z0-9._:-]+", "-", str(explicit).strip())
        if cleaned:
            return cleaned[:120]
    seed = json.dumps(
        {
            "kind": kind,
            "user_id": user_id,
            "model_id": model_id,
            "time": time.time(),
            "rand": random.randint(100000, 999999),
        },
        ensure_ascii=False,
        sort_keys=True,
    )
    digest = hashlib.sha256(seed.encode("utf-8")).hexdigest()[:32]
    return f"aicanvas:{kind}:{user_id}:{digest}"[:120]


def _billing_user_id_from_scope(scope):
    match = re.fullmatch(r"user-(\d+)", _sanitize_account_scope(scope or ""))
    return int(match.group(1)) if match else 0


def _billing_user_id_for_project(project_id=0):
    try:
        project = LOCAL_COMIC_PROJECTS.get(int(project_id or 0))
    except Exception:
        project = None
    scope = _local_comic_project_owner_scope(project) if isinstance(project, dict) else ""
    return _billing_user_id_from_scope(scope or _get_request_account_scope())


def _require_canvas_billing_user(handler):
    session_payload = _get_canvas_session_payload(handler)
    if session_payload and session_payload.get("user_id"):
        return session_payload
    if _request_has_valid_local_token(handler):
        return {"user_id": 0, "local_bypass": True}
    if AICANVAS_AUTH_REQUIRED:
        _json_err(handler, 401, "请先从云灵AI平台进入画布")
        return None
    return {"user_id": 0, "dev_bypass": True}


def _extract_billing_duration(source_payload=None):
    d = source_payload if isinstance(source_payload, dict) else {}
    for k in ("duration", "seconds", "video_duration", "duration_seconds", "videoDuration", "audio_duration"):
        v = d.get(k)
        if v in (None, ""):
            continue
        try:
            num = float(str(v).strip().replace("秒", ""))
        except (ValueError, TypeError):
            continue
        if num > 0:
            return num
    return None


def _extract_billing_tiers(source_payload=None):
    d = source_payload if isinstance(source_payload, dict) else {}
    def _first(keys):
        for k in keys:
            v = d.get(k)
            if v not in (None, ""):
                return v
        return None
    tiers = {}
    rv = _first(["resolution", "definition", "clarity", "imageSize", "image_size", "size"])
    if rv is not None:
        rs = str(rv).lower()
        if ("1080" in rs) or ("2k" in rs) or ("4k" in rs):
            tiers["resolution"] = "1080p"
        elif ("540" in rs) or ("480" in rs) or ("360" in rs):
            tiers["resolution"] = "540p"
        elif "720" in rs:
            tiers["resolution"] = "720p"
    hi = False
    if d.get("hd") in (True, "true", 1, "1") or d.get("highQuality") in (True, "true", 1, "1"):
        hi = True
    qv = _first(["quality", "mode", "model_mode", "generate_mode", "generation_mode"])
    if qv is not None:
        qs = str(qv).lower()
        for tok in ("高品质", "高质量", "专家", "专业", "pro", "high", "expert", "hq"):
            if tok in qs:
                hi = True
                break
    if hi:
        tiers["quality"] = "high"
    ov = _first(["off_peak", "offPeak", "offpeak", "cuofeng"])
    if ov in (True, "true", 1, "1", "on", "yes"):
        tiers["offpeak"] = 1
    vv = _first(["model_version", "version", "model_ver"])
    if vv is not None:
        vs = str(vv).lower()
        for tok in ("mix", "全能", "plus", "quanneng"):
            if tok in vs:
                tiers["version"] = "plus"
                break
    sv = _first(["audio", "generate_audio", "sound", "with_audio", "sound_mode"])
    if sv is not None and str(sv).lower() in ("false", "0", "no", "off", "无声", "mute", "silent", "none"):
        tiers["sound"] = "off"
    lv = _first(["lip_sync", "lipSync", "lipsync", "duikouxing", "对口型"])
    if lv in (True, "true", 1, "1", "on", "yes"):
        tiers["lipsync"] = 1
    return tiers


def _extract_billing_usage(source_payload=None):
    data = source_payload if isinstance(source_payload, dict) else {}
    usage = data.get("usage") if isinstance(data.get("usage"), dict) else data

    def _int_value(*keys):
        for key in keys:
            value = usage.get(key)
            if value in (None, ""):
                continue
            try:
                return int(value)
            except (TypeError, ValueError):
                continue
        return None

    input_tokens = _int_value("input_tokens", "prompt_tokens")
    output_tokens = _int_value("output_tokens", "completion_tokens")
    total_tokens = _int_value("total_tokens")
    if total_tokens is None and (input_tokens is not None or output_tokens is not None):
        total_tokens = int(input_tokens or 0) + int(output_tokens or 0)
    result = {}
    if input_tokens is not None:
        result["input_tokens"] = input_tokens
    if output_tokens is not None:
        result["output_tokens"] = output_tokens
    if total_tokens is not None:
        result["total_tokens"] = total_tokens
    return result


def _charge_local_ai_model_call(model_type, model_id, source_payload=None, project_id=0, description="", handler=None):
    if handler is not None:
        user = _require_canvas_billing_user(handler)
        if user is None:
            return None
        user_id = int(user.get("user_id") or 0)
    else:
        user_id = _billing_user_id_for_project(project_id)
    if user_id <= 0:
        return {"request_id": "", "skipped": True}
    model_type = str(model_type or "").strip()
    model_id = str(model_id or "").strip()
    if not model_type or not model_id:
        if handler is not None:
            _json_err(handler, 400, "模型信息不完整，无法计费")
            return None
        raise RuntimeError("模型信息不完整，无法计费")
    request_id = _make_billing_request_id(model_type, user_id, model_id, source_payload)
    body = {
        "user_id": user_id,
        "model_id": model_id,
        "model_type": model_type,
        "request_id": request_id,
        "project_id": int(project_id or 0) or None,
        "description": description or f"云灵AI漫剧调用：{model_type}/{model_id}",
    }
    duration = _extract_billing_duration(source_payload)
    if duration is not None:
        body["duration"] = duration
    for key, value in _extract_billing_tiers(source_payload).items():
        body[key] = value
    for key, value in _extract_billing_usage(source_payload).items():
        body[key] = value
    status_code, data = _platform_json_request(
        "/aicanvas/billing/charge",
        body,
        include_internal_secret=True,
        timeout=30,
    )
    if status_code < 200 or status_code >= 300 or not (isinstance(data, dict) and data.get("success", True)):
        message = _platform_error_message(data, "模型调用扣费失败")
        if handler is not None:
            _json_err(handler, 400 if status_code < 500 else 502, message)
            return None
        raise RuntimeError(message)
    return {
        "request_id": request_id,
        "user_id": user_id,
        "model_id": model_id,
        "model_type": model_type,
        "project_id": int(project_id or 0) or None,
        "usage_log": copy.deepcopy(data.get("usage_log")) if isinstance(data, dict) and isinstance(data.get("usage_log"), dict) else {},
    }


def _finalize_local_ai_model_call(billing_ctx, response_payload, description=""):
    if not isinstance(billing_ctx, dict) or not billing_ctx.get("request_id"):
        return
    usage = _extract_billing_usage(response_payload)
    if not usage:
        return
    body = {
        "user_id": int(billing_ctx.get("user_id") or 0),
        "model_id": str(billing_ctx.get("model_id") or ""),
        "model_type": str(billing_ctx.get("model_type") or ""),
        "request_id": str(billing_ctx.get("request_id") or ""),
        "project_id": billing_ctx.get("project_id"),
        "description": description or f"云灵AI漫剧调用：{billing_ctx.get('model_type')}/{billing_ctx.get('model_id')}",
        **usage,
    }
    _platform_json_request("/aicanvas/billing/charge", body, include_internal_secret=True, timeout=20)


def _call_local_ai_chat_completion(model, messages, *, project_id=0, handler=None, description="", source_payload=None, **options):
    billing_ctx = _charge_local_ai_model_call(
        "llm",
        model,
        source_payload or {"messages": messages},
        project_id=project_id,
        description=description or f"云灵AI漫剧 LLM 调用：{model}",
        handler=handler,
    )
    if billing_ctx is None:
        return None
    try:
        result = AI_API_SERVICE.create_chat_completion(model, messages, **options)
        _finalize_local_ai_model_call(billing_ctx, result, description=description)
        return result
    except Exception:
        _refund_canvas_model_call(billing_ctx, f"云灵AI漫剧 LLM 调用失败退款：{description or model}")
        raise


def _charge_canvas_model_call(handler, model_type, model_id, source_payload=None):
    user = _require_canvas_billing_user(handler)
    if user is None:
        return None
    if int(user.get("user_id") or 0) <= 0:
        return {"request_id": "", "skipped": True}
    model_type = str(model_type or "").strip()
    model_id = str(model_id or "").strip()
    if not model_type or not model_id:
        _json_err(handler, 400, "模型信息不完整，无法计费")
        return None
    request_id = _make_billing_request_id(model_type, user.get("user_id"), model_id, source_payload)
    _charge_body = {
        "user_id": int(user["user_id"]),
        "model_id": model_id,
        "model_type": model_type,
        "request_id": request_id,
        "description": f"云灵AI漫剧画布调用：{model_type}/{model_id}",
    }
    _dur = _extract_billing_duration(source_payload)
    if _dur is not None:
        _charge_body["duration"] = _dur
    for _tk, _tv in _extract_billing_tiers(source_payload).items():
        _charge_body[_tk] = _tv
    status_code, data = _platform_json_request(
        "/aicanvas/billing/charge",
        _charge_body,
        include_internal_secret=True,
        timeout=30,
    )
    if status_code < 200 or status_code >= 300 or not (isinstance(data, dict) and data.get("success", True)):
        _json_err(handler, 400 if status_code < 500 else 502, _platform_error_message(data, "模型调用扣费失败"))
        return None
    return {"request_id": request_id, "user": user, "usage": data}


def _refund_canvas_model_call(billing_ctx, reason):
    if not isinstance(billing_ctx, dict) or not billing_ctx.get("request_id"):
        return
    _platform_json_request(
        "/aicanvas/billing/refund",
        {
            "request_id": billing_ctx["request_id"],
            "reason": reason or "云灵AI漫剧画布模型调用失败退款",
        },
        include_internal_secret=True,
        timeout=20,
    )


def _settle_canvas_model_actual_cost(request_id, actual_amount, reason=""):
    request_id = str(request_id or "").strip()
    try:
        amount = float(actual_amount)
    except (TypeError, ValueError):
        amount = 0.0
    if not request_id or amount <= 0:
        return None
    status_code, data = _platform_json_request(
        "/aicanvas/billing/settle-actual-cost",
        {
            "request_id": request_id,
            "actual_amount": round(amount, 6),
            "reason": reason or "漫剧生成器中转站真实消耗同步",
        },
        include_internal_secret=True,
        timeout=20,
    )
    if status_code < 200 or status_code >= 300 or not (isinstance(data, dict) and data.get("success", True)):
        raise RuntimeError(_platform_error_message(data, "中转站真实消耗同步失败"))
    return copy.deepcopy(data.get("usage_log")) if isinstance(data, dict) and isinstance(data.get("usage_log"), dict) else {}


def _infer_media_model_type(api_url, payload):
    model = str((payload or {}).get("model") or "").strip().lower()
    path = _url_path(api_url).lower()
    video_markers = (
        "video",
        "videos",
        "sora",
        "veo",
        "vidu",
        "wan",
        "seedance",
        "kling",
        "runway",
        "hailuo",
        "minimax",
    )
    if any(marker in path for marker in ("video", "videos")):
        return "video"
    if any(marker in model for marker in video_markers):
        return "video"
    if any(marker in model for marker in ("speech", "tts", "music", "suno", "doubao-tts")):
        return "tts"
    return "image"


def _handle_aicanvas_auth_get(handler, path):
    if path != "/api/v2/auth/session":
        return False
    session_token = _canvas_session_request_token(handler)
    session_payload = _get_canvas_session_payload(handler)
    if not session_payload:
        if not AICANVAS_AUTH_REQUIRED:
            _json_ok(
                handler,
                {
                    "authenticated": True,
                    "user": {
                        "user_id": 0,
                        "id": 0,
                        "nickname": "本地开发",
                        "avatar": "",
                    },
                    "localDev": True,
                    "platformUrl": AICANVAS_PLATFORM_WEB_URL,
                },
            )
            return True
        _json_ok(
            handler,
            {
                "authenticated": False,
                "platformUrl": AICANVAS_PLATFORM_WEB_URL,
            },
        )
        return True
    user, error = _get_fresh_platform_user(session_payload)
    if error:
        fallback_user = _session_payload_to_user(session_payload)
        _json_log(
            "aicanvas_session_refresh_failed",
            user_id=fallback_user.get("user_id"),
            error=error,
        )
        _json_ok(
            handler,
            {
                "authenticated": True,
                "user": fallback_user,
                "stale": True,
                "warning": error,
                "platformUrl": AICANVAS_PLATFORM_WEB_URL,
                "access_token": session_token,
                "token": session_token,
                "token_type": "bearer",
                "expires_in": int(AICANVAS_SESSION_TTL_SECONDS),
            },
        )
        return True
    _json_ok(
        handler,
        {
            "authenticated": True,
            "user": user,
            "platformUrl": AICANVAS_PLATFORM_WEB_URL,
            "access_token": session_token,
            "token": session_token,
            "token_type": "bearer",
            "expires_in": int(AICANVAS_SESSION_TTL_SECONDS),
        },
    )
    return True


def _handle_aicanvas_auth_post(handler, path):
    if path == AICANVAS_MATRIX_SSO_EXCHANGE_PATH:
        try:
            data = json.loads(_read_body(handler) or b"{}")
        except json.JSONDecodeError:
            _json_err(handler, 400, "Invalid JSON")
            return True
        ticket = str(data.get("ticket") or "").strip()
        if not ticket:
            _json_err(handler, 400, "缺少矩阵登录票据")
            return True
        try:
            token, payload, user = _exchange_matrix_sso_ticket(ticket)
        except _MatrixSsoExchangeError as exc:
            error_id = "err-" + secrets.token_hex(8)
            _json_log(
                "matrix_sso_exchange_failed",
                errorId=error_id,
                code=exc.code,
                status=exc.status,
            )
            _send_json_with_headers(
                handler,
                exc.status,
                {"success": False, "error": exc.code, "errorId": error_id},
            )
            return True
        _json_log(
            "matrix_sso_exchange_succeeded",
            user_id=user.get("user_id"),
            org_id=user.get("matrix_org_id"),
            session_ttl=int(AICANVAS_MATRIX_SESSION_TTL_SECONDS),
        )
        _send_json_with_headers(
            handler,
            200,
            payload,
            {"Set-Cookie": _session_cookie_header(token, max_age=AICANVAS_MATRIX_SESSION_TTL_SECONDS)},
        )
        return True
    if path == "/api/v2/auth/exchange-ticket":
        try:
            data = json.loads(_read_body(handler) or b"{}")
        except json.JSONDecodeError:
            _json_err(handler, 400, "Invalid JSON")
            return True
        ticket = str(data.get("ticket") or "").strip()
        if not ticket:
            _json_err(handler, 400, "缺少登录票据")
            return True
        if not AICANVAS_AUTH_REQUIRED and ticket == "local-dev":
            user = {
                "user_id": 0,
                "id": 0,
                "nickname": "本地开发",
                "avatar": "",
            }
            token = _make_canvas_session_token(user)
            _send_json_with_headers(
                handler,
                200,
                {
                    "success": True,
                    "authenticated": True,
                    "user": user,
                    "localDev": True,
                    "access_token": token,
                    "token": token,
                    "token_type": "bearer",
                    "expires_in": int(AICANVAS_SESSION_TTL_SECONDS),
                },
                {"Set-Cookie": _session_cookie_header(token)},
            )
            return True
        status_code, exchange_data = _platform_json_request(
            "/aicanvas/sso/exchange",
            {"ticket": ticket},
            include_internal_secret=False,
            timeout=30,
        )
        if status_code < 200 or status_code >= 300:
            _json_err(handler, 401, _platform_error_message(exchange_data, "画布登录票据已失效"))
            return True
        user = exchange_data.get("user") if isinstance(exchange_data, dict) else None
        if not isinstance(user, dict) or not (user.get("user_id") or user.get("id")):
            _json_err(handler, 401, "平台用户信息无效")
            return True
        for token_key in ("platform_access_token", "access_token", "token", "jwt"):
            token_value = str(exchange_data.get(token_key) or "").strip() if isinstance(exchange_data, dict) else ""
            if token_value:
                token_exp = exchange_data.get("exp") or exchange_data.get("expires_at")
                if not token_exp:
                    try:
                        token_exp = int(time.time()) + int(AICANVAS_SESSION_TTL_SECONDS)
                    except Exception:
                        token_exp = int(time.time()) + 3600
                user["platform_session_id"] = _store_platform_session_token(token_value, token_exp)
                break
        token = _make_canvas_session_token(user)
        _send_json_with_headers(
            handler,
            200,
            {
                "success": True,
                "authenticated": True,
                "user": user,
                "access_token": token,
                "token": token,
                "token_type": "bearer",
                "expires_in": int(AICANVAS_SESSION_TTL_SECONDS),
            },
            {"Set-Cookie": _session_cookie_header(token)},
        )
        return True
    if path == "/api/v2/auth/logout":
        _send_json_with_headers(
            handler,
            200,
            {"success": True},
            {"Set-Cookie": _session_cookie_header(clear=True)},
        )
        return True
    return False


ASSISTANT_STREAM_PATH = "/api/v2/assistant/chat-stream"
ASSISTANT_CHAT_PATH = "/api/v2/assistant/chat"


def _assistant_resolve_user_id(handler):
    """Resolve the canvas session cookie -> platform user_id. Returns int or 0."""
    session_payload = _get_canvas_session_payload(handler)
    try:
        user_id = int(session_payload.get("user_id") or 0) if isinstance(session_payload, dict) else 0
    except Exception:
        user_id = 0
    if user_id > 0:
        return user_id
    if not AICANVAS_AUTH_REQUIRED and AICANVAS_DEV_USER_ID > 0:
        return int(AICANVAS_DEV_USER_ID)
    return 0


def _assistant_missing_user_message():
    if not AICANVAS_AUTH_REQUIRED:
        if AICANVAS_DEV_USER_ID <= 0:
            return "本地免登录模式已启用，但 AI 漫剧助手需要在 .env 配置 AICANVAS_DEV_USER_ID"
        return "本地免登录模式已启用，但 AI 漫剧助手无法解析开发用户"
    return "请先从云灵AI平台进入画布"


def _assistant_missing_user_status():
    if not AICANVAS_AUTH_REQUIRED:
        return 501
    return 401


def _assistant_sse_write(handler, event, payload):
    data = json.dumps(payload if isinstance(payload, dict) else {}, ensure_ascii=False)
    try:
        handler.wfile.write(f"event: {event}\n".encode("utf-8"))
        handler.wfile.write(f"data: {data}\n\n".encode("utf-8"))
        handler.wfile.flush()
    except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
        raise


def _local_assistant_project_id(message):
    seed = f"{message}:{time.time()}:{random.randint(1000, 9999)}"
    digest = hashlib.sha1(seed.encode("utf-8")).hexdigest()[:12]
    return f"local-{digest}"


def _local_assistant_title(message):
    text = str(message or "").strip()
    cleaned = re.sub(r"[\r\n\t]+", " ", text)
    cleaned = re.sub(r"\s+", " ", cleaned).strip(" ：:，,。.")
    for prefix in ("创建一个", "创建", "生成一个", "生成", "分析"):
        if cleaned.startswith(prefix):
            cleaned = cleaned[len(prefix):].strip(" ：:，,。.")
    return cleaned[:28] or "本地漫剧项目"


def _local_assistant_count_script_parts(script_text):
    text = str(script_text or "")
    scenes = max(1, len(re.findall(r"(场景|地点|镜头|分镜)", text)))
    characters = max(1, len(re.findall(r"(主角|角色|人物|导师|反派|女孩|男孩|少年|少女)", text)))
    props = max(1, len(re.findall(r"(道具|手机|钥匙|剑|书|信|戒指)", text)))
    storyboards = max(3, min(12, scenes * 3))
    return {
        "characters": characters,
        "scenes": scenes,
        "props": props,
        "storyboards": storyboards,
    }


def _local_assistant_project_filename(title):
    safe = re.sub(r'[\\/:*?"<>|]', "_", str(title or "").strip()) or "本地漫剧项目"
    return safe[:80] + ".json"


def _local_assistant_persist_project(title, script_text):
    filename = _local_assistant_project_filename(title)
    now_ms = int(time.time() * 1000)
    node_id = f"local_script_{hashlib.sha1((title + script_text).encode('utf-8')).hexdigest()[:10]}"
    payload = {
        "activeCanvasId": "canvas_1",
        "canvases": [
            {
                "id": "canvas_1",
                "name": "默认画布",
                "nodes": [
                    {
                        "id": node_id,
                        "type": "comment-note",
                        "name": title,
                        "title": title,
                        "content": script_text,
                        "text": script_text,
                        "x": 120,
                        "y": 120,
                        "width": 420,
                        "height": 280,
                        "createdAt": now_ms,
                        "updatedAt": now_ms,
                    }
                ],
                "edges": [],
                "viewport": {"x": 0, "y": 0, "zoom": 1},
            }
        ],
    }
    project_path = os.path.join(_current_canvas_dir(), filename)
    os.makedirs(os.path.dirname(project_path), exist_ok=True)
    _atomic_write_json(project_path, payload)
    return filename


def _extract_chat_completion_text(payload):
    if isinstance(payload, dict):
        choices = payload.get("choices")
        if isinstance(choices, list):
            for choice in choices:
                if not isinstance(choice, dict):
                    continue
                message = choice.get("message")
                if isinstance(message, dict):
                    content = message.get("content")
                    if isinstance(content, str) and content.strip():
                        return content.strip()
                text = choice.get("text")
                if isinstance(text, str) and text.strip():
                    return text.strip()
        for key in ("text", "content", "reply", "result"):
            value = payload.get(key)
            if isinstance(value, str) and value.strip():
                return value.strip()
    return ""


def _comic_prompt_optimizer_source_text(messages):
    if not isinstance(messages, list):
        return ""
    texts = []
    for item in messages:
        if not isinstance(item, dict):
            continue
        content = item.get("content")
        if isinstance(content, str):
            texts.append(content)
        elif isinstance(content, list):
            for part in content:
                if isinstance(part, dict) and isinstance(part.get("text"), str):
                    texts.append(part.get("text"))
    joined = "\n".join(texts)
    match = re.search(r"原始提示词[：:]\s*(.+)$", joined, flags=re.S)
    if match:
        text = match.group(1).strip()
        text = re.split(r"\n\s*(?:优化方向|上下文|类型)[：:]", text, maxsplit=1)[0].strip()
        if text:
            return text
    return texts[-1].strip() if texts else ""


def _comic_prompt_optimizer_fallback(messages):
    source = _comic_prompt_optimizer_source_text(messages)
    source = re.sub(r"\s+", " ", source).strip(" ，。")
    if not source:
        source = "当前分镜画面"
    parts = [
        source,
        "真实短剧质感，主体身份、服装、发型、关键道具和场景空间严格保持一致",
        "明确前景主体、中景互动、背景环境层次，构图清晰，镜头语言自然",
        "电影级自然光影，肤色真实，材质细节清楚，画面干净稳定",
        "不要新增无关人物、无关地点或无关道具，不要出现字幕、水印、边框、分屏和畸变",
    ]
    return "，".join(part for part in parts if part)


def _clean_comic_prompt_optimizer_text(text):
    cleaned = str(text or "").strip()
    cleaned = re.sub(r"^\s*\*\*?\s*优化后(?:的)?提示词(?:（[^）]*）)?\s*[:：]?\s*\*\*?\s*", "", cleaned, flags=re.I)
    cleaned = re.sub(r"^\s*优化后(?:的)?提示词(?:（[^）]*）)?\s*[:：]?\s*", "", cleaned, flags=re.I)
    fence = re.search(r"```(?:\w+)?\s*(.*?)```", cleaned, flags=re.S)
    if fence:
        cleaned = fence.group(1)
    cleaned = cleaned.strip().strip("`").strip()
    return cleaned or str(text or "").strip()


def _handle_local_llm_chat_request(handler, path, method):
    if method != "POST" or path != "/api/v1/llm/chat":
        return False
    payload = _read_json_body_object(handler)
    try:
        requested_model = _comic_media_model_for_project({}, {"llm_model": payload.get("llm_model") or payload.get("model")}, "llm")
    except ValueError as error:
        _send_json_with_headers(handler, 400, {"detail": str(error)})
        return True
    messages = payload.get("messages") if isinstance(payload.get("messages"), list) else []
    try:
        result = _call_local_ai_chat_completion(
            requested_model,
            messages,
            handler=handler,
            description=f"云灵AI漫剧提示词优化：{requested_model}",
            source_payload={"messages": messages},
            max_tokens=payload.get("max_tokens"),
            temperature=payload.get("temperature"),
        )
        if result is None:
            return True
        content = _extract_chat_completion_text(result)
        if content:
            content = _clean_comic_prompt_optimizer_text(content)
            _send_json_with_headers(handler, 200, {"data": {"content": content, "model": requested_model}})
            return True
        raise RuntimeError("LLM 返回内容为空")
    except Exception as error:
        fallback = _comic_prompt_optimizer_fallback(messages)
        _json_log(
            "comic_llm_chat_fallback_used",
            model=requested_model,
            error=AiApiService.sanitize_error(repr(error)),
        )
        _send_json_with_headers(
            handler,
            200,
            {
                "data": {
                    "content": fallback,
                    "model": requested_model,
                    "fallback": True,
                    "warning": "LLM 调用失败，已使用本地提示词优化兜底。",
                }
            },
        )
        return True


def _sanitize_assistant_error_message(message):
    text = str(message or "")
    text = re.sub(r"sk-[A-Za-z0-9._-]{8,}", lambda m: f"{m.group(0)[:5]}***{m.group(0)[-4:]}", text)
    return text


def _local_assistant_call_llm(message):
    if _use_ai_api_provider():
        try:
            catalog = AI_API_SERVICE.comic_model_catalog("llm")
            model = str(catalog.get("defaultModelId") or catalog.get("default_model") or "gpt-5.4-mini").strip()
        except Exception:
            model = "gpt-5.4-mini"
        prompt = (
            "你是云灵AI漫剧助手。请根据用户想法生成一个可用于短漫剧项目创建和分镜拆解的中文剧本。"
            "输出包含标题、主要人物、场景、剧情梗概和不少于3个分镜要点。\n\n"
            f"用户想法：{message}"
        )
        try:
            payload = _call_local_ai_chat_completion(
                model,
                [
                    {"role": "system", "content": "你只输出中文剧本内容，不要输出代码块。"},
                    {"role": "user", "content": prompt},
                ],
                description=f"云灵AI漫剧助手剧本生成：{model}",
                source_payload={"message": message, "prompt": prompt},
                temperature=0.7,
            )
        except Exception as e:
            raise RuntimeError(AiApiService.sanitize_error(f"本地剧本分析调用失败：{repr(e)}"))
        text = _extract_chat_completion_text(payload)
        if not text:
            raise RuntimeError("本地剧本分析未返回文本内容")
        return text

    cfg = CONFIG_ROUTE_SERVICE.get_api_gateway_config()
    api_url = str(cfg.get("apiUrl") or "").strip().rstrip("/")
    api_key = str(cfg.get("apiKey") or "").strip()
    model = str(cfg.get("llmModel") or "gpt-5.4-mini").strip()
    if not api_url or not api_key:
        raise RuntimeError("缺少 API_GATEWAY_BASE_URL 或 API_GATEWAY_API_KEY，无法本地分析剧本")
    endpoint = _join_versioned_api_path(api_url, "/v1/chat/completions")
    prompt = (
        "你是云灵AI漫剧助手。请根据用户想法生成一个可用于短漫剧项目创建和分镜拆解的中文剧本。"
        "输出包含标题、主要人物、场景、剧情梗概和不少于3个分镜要点。\n\n"
        f"用户想法：{message}"
    )
    req_body = json.dumps(
        {
            "model": model,
            "messages": [
                {"role": "system", "content": "你只输出中文剧本内容，不要输出代码块。"},
                {"role": "user", "content": prompt},
            ],
            "temperature": 0.7,
        },
        ensure_ascii=False,
    ).encode("utf-8")
    req = urllib.request.Request(
        endpoint,
        data=req_body,
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
            "User-Agent": "Yunling-AI-CanvasPro/1.0",
        },
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=60) as resp:
            payload = _parse_platform_json(resp.read())
    except urllib.error.HTTPError as e:
        detail = _parse_platform_json(e.read())
        raise RuntimeError(_sanitize_assistant_error_message(_platform_error_message(detail, f"本地剧本分析调用失败：HTTP {e.code}")))
    except Exception as e:
        raise RuntimeError(_sanitize_assistant_error_message(f"本地剧本分析调用失败：{repr(e)}"))
    text = _extract_chat_completion_text(payload)
    if not text:
        raise RuntimeError("本地剧本分析未返回文本内容")
    return text


def _handle_local_assistant_chat_stream(handler, message):
    title = _local_assistant_title(message)
    project_id = _local_assistant_project_id(message)
    handler.send_response(200)
    handler.send_header("Content-Type", "text/event-stream; charset=utf-8")
    handler.send_header("Cache-Control", "no-cache")
    handler.send_header("Connection", "keep-alive")
    handler.send_header("X-Accel-Buffering", "no")
    _send_cors_origin_header(handler)
    handler.end_headers()
    try:
        _assistant_sse_write(handler, "start", {"mode": "local", "project_id": project_id})
        _assistant_sse_write(handler, "tool_call", {"tool": "create_project", "args": {"title": title}})
        _assistant_sse_write(handler, "tool_progress", {"tool": "create_project", "step": "准备创建本地项目", "progress": 6})
        _assistant_sse_write(
            handler,
            "tool_result",
            {"tool": "create_project", "status": "ok", "result": {"project_id": project_id, "title": title, "local": True}},
        )
        _assistant_sse_write(handler, "tool_call", {"tool": "generate_script", "args": {"title": title}})
        _assistant_sse_write(handler, "tool_progress", {"tool": "generate_script", "step": "正在调用 LLM 生成剧本", "progress": 18})
        script_text = _local_assistant_call_llm(message)
        _assistant_sse_write(handler, "tool_progress", {"tool": "generate_script", "step": "剧本已返回,正在整理内容", "progress": 44})
        _assistant_sse_write(
            handler,
            "tool_result",
            {
                "tool": "generate_script",
                "status": "ok",
                "result": {
                    "project_id": project_id,
                    "title": title,
                    "script": script_text,
                    "script_length": len(script_text),
                },
            },
        )
        _assistant_sse_write(handler, "canvas_node", {"kind": "script", "title": title, "text": script_text})
        _assistant_sse_write(handler, "tool_progress", {"tool": "analyze_project", "step": "正在写入项目并统计角色、场景、道具、分镜", "progress": 58})
        project_filename = _local_assistant_persist_project(title, script_text)
        analysis = _local_assistant_count_script_parts(script_text)
        _assistant_sse_write(handler, "tool_call", {"tool": "analyze_project", "args": {"project_id": project_id}})
        _assistant_sse_write(handler, "tool_progress", {"tool": "analyze_project", "step": "正在生成分析摘要", "progress": 72})
        _assistant_sse_write(
            handler,
            "tool_result",
            {
                "tool": "analyze_project",
                "status": "ok",
                "result": {"project_id": project_id, **analysis, "local": True},
            },
        )
        _assistant_sse_write(
            handler,
            "done",
            {
                "project_id": project_id,
                "reply": f"已在本地创建项目《{title}》，并完成剧本分析。",
                "local": True,
                "project_filename": project_filename,
            },
        )
    except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
        pass
    except Exception as e:
        try:
            _assistant_sse_write(handler, "error", {"error": str(e)})
        except Exception:
            pass
    return True


def _assistant_mint_user_token(user_id):
    """Exchange a user_id for a short-lived platform JWT via the internal mint endpoint."""
    status_code, data = _platform_json_request(
        "/aicanvas/internal/mint-user-token",
        {"user_id": int(user_id)},
        include_internal_secret=True,
        timeout=15,
    )
    if status_code < 200 or status_code >= 300 or not isinstance(data, dict):
        _json_log(
            "aicanvas_assistant_token_mint_failed",
            user_id=int(user_id),
            status=status_code,
            internal_secret_configured=bool(AICANVAS_INTERNAL_SECRET),
            platform_api_configured=bool(AICANVAS_PLATFORM_API_BASE),
        )
        return None, _platform_error_message(data, "无法获取平台访问令牌")
    token = str(data.get("token") or "").strip()
    if not token:
        _json_log(
            "aicanvas_assistant_token_mint_failed",
            user_id=int(user_id),
            status=status_code,
            internal_secret_configured=bool(AICANVAS_INTERNAL_SECRET),
            platform_api_configured=bool(AICANVAS_PLATFORM_API_BASE),
            reason="empty_token",
        )
        return None, "平台未返回访问令牌"
    _json_log(
        "aicanvas_assistant_token_resolved",
        user_id=int(user_id),
        source="internal_mint",
        internal_secret_configured=bool(AICANVAS_INTERNAL_SECRET),
    )
    return token, None


def _assistant_session_platform_token(handler, prefer_bearer=False):
    headers = getattr(handler, "headers", {})
    bearer = _bearer_token_from_authorization(headers.get("Authorization"))
    cookies = _parse_cookie_header(handler)
    cookie_token = _canvas_session_cookie_token(cookies)
    tokens = (bearer, cookie_token) if prefer_bearer else (cookie_token, bearer)
    for token in tokens:
        payload = _decode_canvas_session_token(token)
        if not isinstance(payload, dict):
            continue
        platform_session_id = str(payload.get("platform_session_id") or "").strip()
        platform_token = _load_platform_session_token(platform_session_id)
        if platform_token:
            return platform_token
        try:
            user_id = int(payload.get("user_id") or 0)
        except Exception:
            user_id = 0
        if user_id > 0:
            minted_token, _ = _assistant_mint_user_token(user_id)
            if minted_token:
                exp = int(payload.get("exp") or (int(time.time()) + int(AICANVAS_SESSION_TTL_SECONDS)))
                _store_platform_session_token(minted_token, exp, platform_session_id or None)
                _json_log(
                    "aicanvas_platform_session_restored",
                    user_id=user_id,
                    reused_session_id=bool(platform_session_id),
                )
                return minted_token
    return ""


def _assistant_collect_query(handler, token):
    """Build the upstream query dict, passing through message/project_id/auto_generate_media/model."""
    raw_qs = handler.path.split("?", 1)[1] if "?" in handler.path else ""
    incoming = urllib.parse.parse_qs(raw_qs, keep_blank_values=True)

    def _first(name, default=""):
        vals = incoming.get(name)
        return vals[0] if vals else default

    out_params = {"token": token, "message": _first("message")}
    project_id = _first("project_id")
    if project_id != "":
        out_params["project_id"] = project_id
    auto_gen = _first("auto_generate_media")
    if auto_gen != "":
        out_params["auto_generate_media"] = auto_gen
    model = _first("model")
    if model != "":
        out_params["model"] = model
    return out_params


def _handle_assistant_chat_stream(handler, path):
    """Same-origin SSE proxy: canvas client -> platform comic-drama assistant chat-stream.

    (a) validate canvas session -> user_id (401 if none)
    (b) mint a platform JWT for that user (internal secret)
    (c) open the platform SSE and stream bytes through verbatim.
    """
    if path != ASSISTANT_STREAM_PATH:
        return False

    user_id = _assistant_resolve_user_id(handler)
    if user_id <= 0:
        if not AICANVAS_AUTH_REQUIRED:
            raw_qs = handler.path.split("?", 1)[1] if "?" in handler.path else ""
            incoming = urllib.parse.parse_qs(raw_qs, keep_blank_values=True)
            message = (incoming.get("message") or [""])[0]
            return _handle_local_assistant_chat_stream(handler, message)
        _json_err(handler, _assistant_missing_user_status(), _assistant_missing_user_message())
        return True

    token = _assistant_session_platform_token(handler)
    err = None
    token_source = "session"
    if not token:
        token_source = "internal_mint"
        token, err = _assistant_mint_user_token(user_id)
    if not token:
        _json_log(
            "aicanvas_assistant_token_missing",
            user_id=user_id,
            path=ASSISTANT_STREAM_PATH,
            source=token_source,
            internal_secret_configured=bool(AICANVAS_INTERNAL_SECRET),
            platform_api_configured=bool(AICANVAS_PLATFORM_API_BASE),
            error=err or "empty token",
        )
        _json_err(handler, 502, err or "无法获取平台访问令牌")
        return True
    if token_source == "session":
        _json_log("aicanvas_assistant_token_resolved", user_id=user_id, path=ASSISTANT_STREAM_PATH, source="session")

    out_params = _assistant_collect_query(handler, token)
    upstream_url = _platform_url("/comic-drama/assistant/chat-stream") + "?" + urllib.parse.urlencode(out_params)
    req = urllib.request.Request(
        upstream_url,
        headers={
            "Accept": "text/event-stream",
            "User-Agent": "Yunling-AI-CanvasPro/1.0",
        },
        method="GET",
    )

    try:
        upstream = urllib.request.urlopen(req, timeout=600)
    except urllib.error.HTTPError as e:
        try:
            detail = _parse_platform_json(e.read())
        except Exception:
            detail = {}
        _json_err(handler, int(e.code), _platform_error_message(detail, "平台助手服务返回错误"))
        return True
    except Exception as e:
        _json_err(handler, 502, f"无法连接平台助手服务：{repr(e)}")
        return True

    try:
        handler.send_response(200)
        handler.send_header("Content-Type", "text/event-stream; charset=utf-8")
        handler.send_header("Cache-Control", "no-cache")
        handler.send_header("Connection", "keep-alive")
        handler.send_header("X-Accel-Buffering", "no")
        _send_cors_origin_header(handler)
        handler.end_headers()
        while True:
            chunk = upstream.read(1024)
            if not chunk:
                break
            try:
                handler.wfile.write(chunk)
                handler.wfile.flush()
            except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
                break
    except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
        pass
    finally:
        try:
            upstream.close()
        except Exception:
            pass
    return True


def _handle_assistant_chat(handler, path):
    """Same-origin non-streaming proxy: canvas client -> platform assistant POST /chat.

    Mints a per-user JWT from the canvas session and calls the platform with a Bearer token.
    """
    if path != ASSISTANT_CHAT_PATH:
        return False

    user_id = _assistant_resolve_user_id(handler)
    if user_id <= 0:
        _json_err(handler, _assistant_missing_user_status(), _assistant_missing_user_message())
        return True

    token = _assistant_session_platform_token(handler)
    err = None
    token_source = "session"
    if not token:
        token_source = "internal_mint"
        token, err = _assistant_mint_user_token(user_id)
    if not token:
        _json_log(
            "aicanvas_assistant_token_missing",
            user_id=user_id,
            path=ASSISTANT_CHAT_PATH,
            source=token_source,
            internal_secret_configured=bool(AICANVAS_INTERNAL_SECRET),
            platform_api_configured=bool(AICANVAS_PLATFORM_API_BASE),
            error=err or "empty token",
        )
        _json_err(handler, 502, err or "无法获取平台访问令牌")
        return True
    if token_source == "session":
        _json_log("aicanvas_assistant_token_resolved", user_id=user_id, path=ASSISTANT_CHAT_PATH, source="session")

    try:
        body = json.loads(_read_body(handler) or b"{}")
    except json.JSONDecodeError:
        _json_err(handler, 400, "Invalid JSON")
        return True

    upstream_url = _platform_url("/comic-drama/assistant/chat")
    data = json.dumps(body, ensure_ascii=False).encode("utf-8")
    req = urllib.request.Request(
        upstream_url,
        data=data,
        headers={
            "Authorization": f"Bearer {token}",
            "Content-Type": "application/json",
            "User-Agent": "Yunling-AI-CanvasPro/1.0",
        },
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=600) as resp:
            payload = _parse_platform_json(resp.read())
            _json_ok(handler, payload if isinstance(payload, dict) else {"data": payload})
    except urllib.error.HTTPError as e:
        detail = _parse_platform_json(e.read())
        _json_err(handler, int(e.code), _platform_error_message(detail, "平台助手服务返回错误"))
    except Exception as e:
        _json_err(handler, 502, f"无法连接平台助手服务：{repr(e)}")
    return True


