def _is_sensitive_api_path(path):
    clean_path = str(path or "").split("?", 1)[0].rstrip("/") or "/"
    return any(
        clean_path == prefix or clean_path.startswith(prefix + "/")
        for prefix in _SENSITIVE_API_PREFIXES
    )


def _is_account_scoped_path(path):
    clean_path = str(path or "").split("?", 1)[0].replace("\\", "/")
    clean_api_path = clean_path.rstrip("/") or "/"
    if any(
        clean_api_path == prefix or clean_api_path.startswith(prefix + "/")
        for prefix in _ACCOUNT_SCOPED_PREFIXES
    ):
        return True
    return any(clean_path == prefix[:-1] or clean_path.startswith(prefix) for prefix in _ACCOUNT_SCOPED_STATIC_PREFIXES)


def _is_local_comic_projects_fallback_path(path):
    clean_path = str(path or "").split("?", 1)[0].rstrip("/") or "/"
    if clean_path == "/comic-drama/projects" or clean_path.startswith("/comic-drama/projects/"):
        clean_path = "/api/v1" + clean_path
    if clean_path in {
        "/api/v1/comic-drama/projects",
        "/api/v1/comic-drama/upload-reference-image",
        "/api/v2/comic-drama/compose-video",
    }:
        return True
    patterns = (
        r"/api/v1/comic-drama/projects/\d+",
        r"/api/v1/comic-drama/projects/\d+/analyze",
        r"/api/v1/comic-drama/projects/\d+/auto-edit",
        r"/api/v1/comic-drama/projects/\d+/merge-videos",
        r"/api/v1/comic-drama/projects/\d+/tasks",
        r"/api/v1/comic-drama/tasks/[^/]+",
        r"/api/v1/comic-drama/storyboards/\d+",
        r"/api/v1/comic-drama/storyboards/\d+/characters",
        r"/api/v1/comic-drama/storyboards/\d+/scene",
        r"/api/v1/comic-drama/projects/\d+/(characters|scenes|props)",
        r"/api/v1/comic-drama/projects/\d+/characters/batch",
        r"/api/v1/comic-drama/projects/\d+/(characters|scenes|props)/[^/]+",
    )
    return any(re.fullmatch(pattern, clean_path) for pattern in patterns)


def _is_local_comic_assets_fallback_path(path):
    clean_path = str(path or "").split("?", 1)[0].rstrip("/") or "/"
    asset_paths = {
        "/api/v1/assets",
        "/api/v1/assets/stats",
        "/api/v1/assets/favorites",
        "/api/v1/assets/batch",
        "/api/v1/collections",
        "/api/v1/presets",
    }
    if clean_path in asset_paths:
        return True
    patterns = (
        r"/api/v1/assets/\d+",
        r"/api/v1/assets/\d+/use",
        r"/api/v1/assets/\d+/usage-history",
        r"/api/v1/assets/\d+/favorite",
        r"/api/v1/assets/\d+/duplicate",
        r"/api/v1/assets/extract-from-project/\d+",
        r"/api/v1/collections/\d+",
        r"/api/v1/collections/\d+/assets(?:/\d+)?",
    )
    return any(re.fullmatch(pattern, clean_path) for pattern in patterns)


def _prepare_request_storage_context(handler, path):
    _set_request_account_scope("")
    _set_agent_runtime_scope("")

    clean_path = str(path or "").split("?", 1)[0]
    if clean_path.startswith("/api/v1/comic-drama/agent/"):
        session_payload = _get_canvas_session_payload(handler)
        try:
            platform_session_id = str(session_payload.get("platform_session_id") or "").strip()
            platform_user_id = int(session_payload.get("user_id") or 0)
        except Exception:
            platform_session_id = ""
            platform_user_id = 0
        if not platform_session_id:
            platform_user_id = _platform_authorization_user_id(handler)
        if platform_user_id <= 0:
            _json_err(handler, 401, "请先登录云灵AI平台后使用 Agent")
            return False
        scope = f"user-{platform_user_id}"
        _set_request_account_scope(scope)
        _activate_agent_comic_runtime(scope)
        _ensure_current_storage_dirs()
        return True

    # NEW: Check Referer header for API calls
    try:
        ref = handler.headers.get("Referer", "") or ""
        if ref:
            ru = urllib.parse.urlparse(ref)
            rp = urllib.parse.parse_qs(ru.query)
            rid = (rp.get("id") or [None])[0]
            if rid:
                if rid.startswith("user_"):
                    parts = rid.split("_")
                    if len(parts) >= 2 and parts[1].isdigit():
                        _set_request_account_scope("user-" + parts[1])
                        _ensure_current_storage_dirs()
                        return True
                elif rid.startswith("session_"):
                    _set_request_account_scope("local")
                    _ensure_current_storage_dirs()
                    return True
    except Exception:
        pass

    # Check ?id= in request URL
    try:
        raw = str(path or "")
        qp = raw.find("?")
        if qp >= 0:
            pms = urllib.parse.parse_qs(raw[qp+1:])
            idv = (pms.get("id") or [None])[0]
            if idv:
                if idv.startswith("user_"):
                    parts = idv.split("_")
                    if len(parts) >= 2 and parts[1].isdigit():
                        _set_request_account_scope("user-" + parts[1])
                        _ensure_current_storage_dirs()
                        return True
                elif idv.startswith("session_"):
                    _set_request_account_scope("local")
                    _ensure_current_storage_dirs()
                    return True
    except Exception:
        pass


    if not _is_account_scoped_path(path):
        return True

    session_payload = _get_canvas_session_payload(handler)
    try:
        user_id = int(session_payload.get("user_id") or 0) if isinstance(session_payload, dict) else 0
    except Exception:
        user_id = 0
    if user_id > 0:
        _set_request_account_scope(f"user-{user_id}")
        _ensure_current_storage_dirs()
        return True

    if str(path or "").split("?", 1)[0].startswith("/api/v1/comic-drama/agent/"):
        platform_user_id = _platform_authorization_user_id(handler)
        if platform_user_id > 0:
            _set_request_account_scope(f"user-{platform_user_id}")
            _ensure_current_storage_dirs()
            return True

    if _request_has_valid_local_token(handler):
        _set_request_account_scope("local")
        _ensure_current_storage_dirs()
        return True

    if (
        _use_ai_api_provider()
        and not _has_platform_session_authorization(handler)
        and (
            _is_local_comic_projects_fallback_path(path)
            or _is_local_comic_assets_fallback_path(path)
            or str(path or "").split("?", 1)[0] in COMIC_MODEL_CATALOG_PATHS
        )
    ):
        _set_request_account_scope("local")
        _ensure_current_storage_dirs()
        return True

    if AICANVAS_AUTH_REQUIRED:
        _json_err(handler, 401, "请先从云灵AI平台进入画布")
        return False

    _set_request_account_scope("dev")
    _ensure_current_storage_dirs()
    return True


def _request_passes_local_security(handler, path):
    if not _is_sensitive_api_path(path):
        return True
    # AIC_PUBLIC_CANVAS_ORIGIN_ORDER: the deployed canvas page must be able to call its own APIs.
    origin = handler.headers.get("Origin", "")
    if origin and _is_allowed_origin(handler, origin):
        return True
    host_origin = _request_host_origin(handler)
    if host_origin and _is_allowed_origin(handler, host_origin):
        return True
    if LOCAL_ACCESS_TOKEN and _request_has_valid_local_token(handler):
        return True
    return _client_is_loopback(handler)


def _enforce_local_api_access(handler, path):
    if _request_passes_local_security(handler, path):
        return True
    _json_err(handler, 403, "Forbidden: request origin is not allowed")
    return False


def _extract_install_id_from_request(handler, payload=None):
    return SUBSCRIPTION_GATE_SERVICE.extract_install_id_from_request(handler, payload)


def _enforce_vip_subscription_gate(handler, payload=None, required_model_id=""):
    decision = SUBSCRIPTION_GATE_SERVICE.check_vip_subscription_gate(
        handler,
        payload,
        required_model_id=required_model_id,
    )
    if bool(decision.get("allowed")):
        return True
    _json_ok(handler, SUBSCRIPTION_GATE_SERVICE.build_subscription_denial_payload(decision))
    return False


def _json_ok(handler, data):
    body = json.dumps(data, ensure_ascii=False, indent=2).encode()
    handler.send_response(200)
    handler.send_header("Content-Type", "application/json; charset=utf-8")
    handler.send_header("Content-Length", str(len(body)))
    _send_cors_origin_header(handler)
    handler.end_headers()
    try:
        handler.wfile.write(body)
    except (BrokenPipeError, ConnectionResetError):
        pass

def _json_err(handler, code, msg):
    body = json.dumps({"error": msg}, ensure_ascii=False, indent=2).encode()
    handler.send_response(code)
    handler.send_header("Content-Type", "application/json; charset=utf-8")
    handler.send_header("Content-Length", str(len(body)))
    _send_cors_origin_header(handler)
    handler.end_headers()
    try:
        handler.wfile.write(body)
    except (BrokenPipeError, ConnectionResetError):
        pass


def _send_route_response(handler, response):
    if not isinstance(response, dict):
        raise ValueError("Route response must be a dict")
    kind = str(response.get("kind") or "").strip()
    if kind == "json_ok":
        _json_ok(handler, response.get("data"))
        return
    if kind == "json_err":
        _json_err(
            handler,
            int(response.get("code") or 500),
            response.get("message") or "Unknown error",
        )
        return
    if kind == "binary":
        body = response.get("body") or b""
        if isinstance(body, str):
            body = body.encode("utf-8")
        else:
            body = bytes(body)
        handler.send_response(int(response.get("status") or 200))
        handler.send_header(
            "Content-Type",
            str(response.get("contentType") or "application/octet-stream"),
        )
        headers = response.get("headers") if isinstance(response.get("headers"), dict) else {}
        for name, value in headers.items():
            if str(name).lower() == "access-control-allow-origin":
                continue
            handler.send_header(str(name), str(value))
        handler.send_header("Content-Length", str(len(body)))
        handler.end_headers()
        try:
            handler.wfile.write(body)
        except (BrokenPipeError, ConnectionResetError):
            pass
        return
    raise ValueError(f"Unknown route response kind: {kind}")

def _read_body(handler, max_bytes=None):
    te = (handler.headers.get("Transfer-Encoding", "") or "").lower()
    if "chunked" in te:
        chunks = []
        total = 0
        while True:
            line = handler.rfile.readline()
            if not line:
                break
            size_hex = line.split(b";", 1)[0].strip()
            try:
                size = int(size_hex, 16)
            except Exception:
                break
            if size == 0:
                handler.rfile.readline()
                break
            chunk = handler.rfile.read(size)
            total += len(chunk)
            if max_bytes is not None and total > max_bytes:
                raise ValueError("REQUEST_BODY_TOO_LARGE")
            chunks.append(chunk)
            handler.rfile.read(2)
        return b"".join(chunks)
    length = int(handler.headers.get("Content-Length", 0))
    if max_bytes is not None and length > max_bytes:
        raise ValueError("REQUEST_BODY_TOO_LARGE")
    return handler.rfile.read(length) if length > 0 else b""


