class Handler(http.server.SimpleHTTPRequestHandler):

    def __init__(self, *args, **kwargs):
        super().__init__(*args, directory=DIRECTORY, **kwargs)

    def translate_path(self, path):
        raw_path = urllib.parse.urlsplit(path).path
        decoded_path = urllib.parse.unquote(raw_path).replace("\\", "/")
        if ".." in [part for part in decoded_path.split("/") if part]:
            return os.path.join(DIRECTORY, "__aic_404__")
        if decoded_path in ("/canvas", "/canvas/"):
            return os.path.join(DIRECTORY, "index.html")
        platform_index_path = os.path.join(DIRECTORY, "platform-index.html")
        platform_spa_roots = (
            "/",
            "/login",
            "/test-login",
            "/courses",
            "/live",
            "/profile",
            "/orders",
            "/pricing",
            "/recharge",
            "/billing",
            "/team",
            "/invoices",
            "/tickets",
            "/help",
            "/legal",
            "/notifications",
            "/comic-tool",
            "/comic-drama",
            "/assets",
        )
        if os.path.exists(platform_index_path):
            if decoded_path in ("", "/") or decoded_path in platform_spa_roots or decoded_path in {f"{root}/" for root in platform_spa_roots if root != "/"}:
                return platform_index_path
            if any(decoded_path.startswith(f"{root}/") for root in platform_spa_roots if root != "/"):
                if not os.path.exists(os.path.join(DIRECTORY, decoded_path.lstrip("/"))):
                    return platform_index_path
        virtual_roots = (
            ("/output/", _current_output_dir()),
            ("/data/uploads/", _current_uploads_dir()),
            ("/data/assets/", _current_assets_dir()),
            ("/user/prompt/_thumbs/", os.path.join(_current_user_dir(), "prompt", "_thumbs")),
            ("/data/workflows/", _current_workflows_dir()),
        )
        media_path = _resolve_local_virtual_path(decoded_path)
        if media_path:
            return media_path
        for prefix, root_dir in virtual_roots:
            if decoded_path == prefix[:-1] or decoded_path.startswith(prefix):
                rel = decoded_path[len(prefix):].lstrip("/")
                rel = os.path.normpath(rel)
                if rel in ("", "."):
                    return os.path.abspath(root_dir)
                if rel.startswith(".."):
                    return os.path.abspath(root_dir)
                return os.path.abspath(os.path.join(root_dir, rel))
        return super().translate_path(path)

    # 屏蔽日志噪音（按霢注释掉）
    def log_message(self, fmt, *args):
        pass

    def send_head(self):
        path = self.translate_path(self.path)
        f = None
        raw_request_path = urllib.parse.urlsplit(self.path).path
        if _is_path_inside(path, AICANVAS_ACCOUNT_STORAGE_ROOT) and not _is_account_scoped_path(raw_request_path):
            self.send_error(404, "File not found")
            return None
        if os.path.isdir(path):
            parts = urllib.parse.urlsplit(self.path)
            if not parts.path.endswith('/'):
                self.send_response(301)
                new_parts = (parts[0], parts[1], parts[2] + '/', parts[3], parts[4])
                new_url = urllib.parse.urlunsplit(new_parts)
                self.send_header("Location", new_url)
                self.end_headers()
                return None
            for index in ("index.html", "index.htm"):
                index_path = os.path.join(path, index)
                if os.path.exists(index_path):
                    path = index_path
                    break
            else:
                return self.list_directory(path)
        ctype = self.guess_type(path)
        try:
            f = open(path, 'rb')
        except OSError:
            self.send_error(404, "File not found")
            return None

        fs = os.fstat(f.fileno())
        size = fs.st_size
        range_header = self.headers.get("Range", "")
        self._range = None

        if range_header.startswith("bytes="):
            spec = range_header[6:].strip()
            if "," not in spec:
                start_s, dash, end_s = spec.partition("-")
                try:
                    if start_s == "":
                        suffix_len = int(end_s)
                        if suffix_len <= 0:
                            raise ValueError()
                        start = max(0, size - suffix_len)
                        end = size - 1
                    else:
                        start = int(start_s)
                        end = int(end_s) if end_s else size - 1
                    if start < 0 or start >= size:
                        raise ValueError()
                    end = min(end, size - 1)
                    if end < start:
                        raise ValueError()
                    self._range = (start, end)
                except Exception:
                    f.close()
                    self.send_response(416)
                    self.send_header("Content-Range", f"bytes */{size}")
                    self.end_headers()
                    return None

        if self._range:
            start, end = self._range
            self.send_response(206)
            self.send_header("Content-Type", ctype)
            self.send_header("Accept-Ranges", "bytes")
            self.send_header("Content-Range", f"bytes {start}-{end}/{size}")
            self.send_header("Content-Length", str(end - start + 1))
            self.send_header("Last-Modified", self.date_time_string(fs.st_mtime))
            self.end_headers()
            f.seek(start)
            return f

        self.send_response(200)
        self.send_header("Content-Type", ctype)
        self.send_header("Accept-Ranges", "bytes")
        self.send_header("Content-Length", str(size))
        self.send_header("Last-Modified", self.date_time_string(fs.st_mtime))
        self.end_headers()
        return f

    def copyfile(self, source, outputfile):
        rng = getattr(self, "_range", None)
        if not rng:
            return super().copyfile(source, outputfile)
        start, end = rng
        remaining = end - start + 1
        bufsize = 64 * 1024
        while remaining > 0:
            chunk = source.read(min(bufsize, remaining))
            if not chunk:
                break
            outputfile.write(chunk)
            remaining -= len(chunk)

    # ┢┢ OPTIONS 预检（CORS）─┢┢┢┢┢┢┢┢┢┢┢┢┢┢┢┢┢┢┢┢┢┢┢┢┢┢┢┢┢
    def do_OPTIONS(self):
        path = self.path.split("?")[0]
        if not _enforce_local_api_access(self, path):
            return
        self.send_response(204)
        self.send_header("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, PATCH, OPTIONS")
        self.send_header(
            "Access-Control-Allow-Headers",
            "Content-Type, Authorization, X-AIC-Install-Id, X-AIC-Local-Token",
        )
        self.end_headers()

