        if _handle_agent_api_request(self, path, "DELETE"):
            return
        if _handle_local_comic_projects_fallback(self, path, "DELETE"):
            return
        if _handle_local_comic_assets_fallback(self, path, "DELETE"):
            return
        if _handle_platform_api_proxy(self, path, "DELETE"):
            return
        if HTTP_ROUTE_DISPATCHER.handle_delete(self, path):
            return

        _json_err(self, 400, "Invalid request")

